def apply_settings(d):
    pots = d.get("potions")
    if isinstance(pots, dict) and isinstance(pots.get("16"), list) and pots["16"] and pots["16"][0] == "Flügel":
        pots["16"][0] = "Flügeltrank"                     # Paket 4: "Flügeltrank" statt "Flügel"
    """Uebernimmt Klassen-/Trank-/Album-Einstellungen aus der Config in die Modul-Variablen."""
    global CLASSES, POTIONS, EXTRA_POTIONS, ALBUM_MAX, HP_PORTAL, HP_RUNE, HP_POTION, HP_POTION_BONUS, HP_PER_PLAYER
    try:
        cl = dict(DEFAULT_CLASSES)                         # neue Klassen (z. B. Blutweber) auch bei alter Einstellungsdatei
        cl.update(d.get("classes") or {})
        CLASSES = {int(k): (str(v[0]), float(v[1]), str(v[2]).strip().upper()) for k, v in cl.items()}
    except Exception:
        CLASSES = {int(k): tuple(v) for k, v in DEFAULT_CLASSES.items()}
    POTIONS = {int(k): tuple(v) for k, v in DEFAULT_POTIONS.items()}      # feste Spielwerte (grosse Traenke)
    EXTRA_POTIONS = ["A", "F"]                                            # "Alle Traenke" = Haupttrank + Ausdauer + Fluegel
    try:
        ALBUM_MAX = max(1, int(d.get("album_max", DEFAULT_ALBUM_MAX)))
    except Exception:
        ALBUM_MAX = DEFAULT_ALBUM_MAX
    HP_PORTAL, HP_RUNE, HP_POTION, HP_POTION_BONUS = 50.0, 15.0, "F", 25.0   # nur noch Ersatz, wenn der Scan nichts liefert
    HP_PER_PLAYER = True


POT_ATTRS = ["staerke", "geschick", "intelligenz", "ausdauer", "glueck"]       # Reihenfolge wie im Scan (Typ 1-5)
POT_SIZES = ["klein", "mittel", "gross"]                                        # Typ 1-5 / 6-10 / 11-15
POT_LETTERS = ["S", "G", "I", "A", "Gl"]


def potion_key(t):
    """Trank-Typ aus dem Scan -> Bildname ohne 'trank_' (z. B. 13 -> 'intelligenz_gross', 16 -> 'fluegel')."""
    t = int(t or 0)
    if t == 16:
        return "fluegel"
    if 1 <= t <= 15:
        return "%s_%s" % (POT_ATTRS[(t - 1) % 5], POT_SIZES[(t - 1) // 5])
    return None


def potion_short(t):
    """Kuerzel eines Tranks: grosse Traenke wie in den Einstellungen (S, G, I, A, F), sonst z. B. S15 (mittel), A10 (klein)."""
    t = int(t or 0)
    if t in POTIONS:
        return POTIONS[t][1]
    if 1 <= t <= 15:
        size = (t - 1) // 5
        return POT_LETTERS[(t - 1) % 5] + ("" if size == 2 else ("10", "15")[size])
    return ""


