# ======================================================================================
#  1.4 Server: Namen, Reihenfolge, Server-Gruppen
# ======================================================================================
def short_server(s):
    s = re.sub(r"\s+", " ", str(s or "").replace("\xa0", " ")).strip()
    s = re.sub(r"\.sfgame\.\w+$", "", s, flags=re.I)
    s = re.sub(r"\s*\.(net|eu|com|de)$", "", s, flags=re.I)
    return s.strip()


SRV_ABBR = {"stumblesteppe": "ST", "gnarogrim": "GN", "blackforest": "BF", "maerwynn": "MA"}   # Namenswelten: kurz anzeigen
SRV_ABBR_KEY = {v.lower(): k for k, v in SRV_ABBR.items()}                                       # "st" -> "stumblesteppe"


def srv_display(disp, raw=""):
    """Anzeigename eines Servers: EU-Server heissen EU5, EU6 ... (intern bleibt die Kennung s5, s6 ...);
    Namenswelten werden abgekuerzt (Stumblesteppe = ST, Gnarogrim = GN, Blackforest = BF, Maerwynn = MA)."""
    m = re.match(r"^s(\d+)$", str(disp or ""), re.I)
    if m and not re.search(r"\.(de|net|com|us|pl|cz)\b|_(net|de|us)$", str(raw or ""), re.I):
        return "EU%d" % int(m.group(1))
    return SRV_ABBR.get(str(disp or "").lower(), disp)


def fusion_table(plan, merges):
    """Fuer die Seite (Eigene Scans): {"m": [[neue Welt, [alte Server]]], "g": [[Server einer Halbjahres-Gruppe]]} - nur Kennungen."""
    m = {}
    for x in merges or []:
        new = srv_key_of(x.get("new", "")) if x.get("new") else ""
        olds = {srv_key_of(o) for o in (x.get("old") or []) if o}
        for o_srv, _on, n_srv, _nn in x.get("players", []) or []:
            if o_srv and n_srv:
                m.setdefault(str(n_srv).lower(), set()).add(str(o_srv).lower())
        if new:
            m.setdefault(new, set()).update(o for o in olds if o and o != new)
    groups = {}
    for k, info in (plan or {}).items():
        groups.setdefault(info.get("group"), []).append(str(k).lower())
    out = {}
    if m:
        out["m"] = [[k, sorted(v, key=natural_key)] for k, v in sorted(m.items()) if v]
    g = [sorted(v, key=natural_key) for v in groups.values() if len(v) >= 2]
    if g:
        out["g"] = sorted(g)
    return out


def srv_with_predecessors(sel, merges):
    """Server-Auswahl (interne Kennungen) + alle Vorgaenger-Server laut gespeicherter Zusammenlegung
    (z. B. f29 -> s5, s6, s7, s8), damit aeltere Scans vor der Fusion dieselben Spieler enthalten."""
    prev = {}
    for m in merges or []:
        new = srv_key_of(m.get("new", "")) if m.get("new") else ""
        olds = {srv_key_of(o) for o in (m.get("old") or []) if o}
        for o_srv, _on, n_srv, _nn in m.get("players", []) or []:
            if o_srv and n_srv:
                prev.setdefault(str(n_srv).lower(), set()).add(str(o_srv).lower())
        if new:
            prev.setdefault(new, set()).update(o for o in olds if o != new)
    out, todo = set(sel), list(sel)
    while todo:
        k = todo.pop()
        for o in prev.get(k, ()):
            if o not in out:
                out.add(o)
                todo.append(o)
    return out


def srv_key_of(text):
    """Eingabe eines Servers -> interne Kennung: 'EU5' / 'eu05' / 's5.sfgame.eu' -> 's5', 'F8' -> 'f8', 'ST' -> 'stumblesteppe'."""
    t = short_server(text).lower().replace(" ", "")
    m = re.match(r"^eu0*(\d+)$", t)
    return "s%d" % int(m.group(1)) if m else SRV_ABBR_KEY.get(t, t)


def srv_sort_key(d):
    """Server-Reihenfolge: EU5, EU6 … bzw. F8, F9 … zuerst (nach Nummer), danach AM1 und benannte Welten."""
    return (0 if re.match(r"^(EU|F)\d+$", str(d or ""), re.I) else 1, natural_key(str(d or "")))


def eu_names(txt):
    """'EU5–EU8' -> 'EU5–EU8' (EU-Server ohne fuehrende Null)."""
    return re.sub(r"\bEU0+(\d)", r"EU\1", str(txt or ""))


def natural_key(s):
    return [int(t) if t.isdigit() else t.lower() for t in re.split(r"(\d+)", s)]


DEFAULT_SERVER_GROUPS = [["EU-Server", "eu*, am1"], ["Fusionsserver", "f*, blackforest, gnarogrim, stumblesteppe, maerwynn"]]
OLD_SERVER_GROUPS = [["Fusions-Server", "f*"], ["EU-Server", "eu*"], ["AM1", "am1*"], ["Zukünftige Fusions-Server", ""]]


def server_pattern_match(pattern, *names):
    """Passt ein Server zu einem Muster wie "f*, eu5-8, maerwynn"? (Komma-Liste; * = beliebig; eu5-8 = eu5 bis eu8)."""
    import fnmatch
    lows = [str(n or "").lower().replace(" ", "") for n in names if n]
    for tok in re.split(r"[,;\s]+", str(pattern or "").lower()):
        if not tok:
            continue
        m = re.match(r"^([a-z_]*?)(\d+)-([a-z_]*?)(\d+)$", tok)
        if m:
            pre, lo, hi = m.group(1), int(m.group(2)), int(m.group(4))
            for n in lows:
                mm = re.match(r"^([a-z_]*?)0*(\d+)$", n)
                if mm and mm.group(1) == pre and lo <= int(mm.group(2)) <= hi:
                    return True
            continue
        for n in lows:
            if fnmatch.fnmatchcase(n, tok) or re.sub(r"(?<=[a-z])0+(?=\d)", "", n) == tok:
                return True
    return False


def server_from_prefix(prefix):
    """'f8_net' -> 'F8' ; 'maerwynn_net' -> 'Maerwynn' (angezeigt als MA, siehe srv_display) ; 'eu5_eu' -> 'EU5'"""
    base = str(prefix or "").split("_")[0]
    if re.match(r"^[a-z]{1,3}\d+$", base, re.I):
        return base.upper()
    return base[:1].upper() + base[1:]


# ======================================================================================
#  1.5 Zahlen, Zeiten und Texte: aus den Dateien lesen und fuer die Anzeige formatieren
# ======================================================================================
_WS_BETWEEN_DIGITS = re.compile(r"(?<=\d)[\s   ]+(?=\d)")
_THOUSANDS = re.compile(r"^-?\d{1,3}(?:\.\d{3}){2,}|^-?\d{1,3}(?:,\d{3})+(?!\d)")
_NUM = re.compile(r"-?\d+(?:[.,]\d+)?")
_RATIO = re.compile(r"(\d+(?:[.,]\d+)?)\s*[:/]\s*(\d+(?:[.,]\d+)?)")


def parse_num(s):
    """'1 082\xa0284\xa0869' -> 1082284869.0 ; '536 583 +3024' -> 536583.0 ; '?' -> None"""
    if s is None:
        return None
    if isinstance(s, bool):
        return 1.0 if s else 0.0
    if isinstance(s, (int, float)):
        return float(s)
    s = str(s).strip()
    if not s or s in ("?", "-", "–"):
        return None
    s = _WS_BETWEEN_DIGITS.sub("", s)
    m = _THOUSANDS.match(s)
    if m:
        return float(m.group(0).replace(".", "").replace(",", ""))
    m = _NUM.search(s)
    if not m:
        return None
    return float(m.group(0).replace(",", "."))


def parse_ratio(s):
    """'68:32' -> (68.0, '68:32')  (Main-Anteil, Originaltext)"""
    if s is None:
        return None, ""
    if isinstance(s, (int, float)) and not isinstance(s, bool):
        x = float(s)
        if 0 <= x <= 1:
            x *= 100
        return x, "%d:%d" % (round(x), 100 - round(x))
    m = _RATIO.search(str(s))
    if not m:
        return None, ""
    a = float(m.group(1).replace(",", "."))
    return a, "%s:%s" % (m.group(1), m.group(2))


def parse_flag(s):
    if isinstance(s, bool):
        return s
    if isinstance(s, (int, float)):
        return s != 0
    return str(s or "").strip().lower() in ("ja", "yes", "true", "1", "y", "x", "wahr", "j")


def parse_dhm(s):
    if s is None:
        return None
    parts = re.findall(r"\d+", str(s))
    if not parts:
        return None
    nums = [int(p) for p in parts][-3:]
    while len(nums) < 3:
        nums.insert(0, 0)
    return float(nums[0] * 1440 + nums[1] * 60 + nums[2])


def parse_date(s):
    if s is None or s == "":
        return None
    if isinstance(s, (int, float)) and not isinstance(s, bool):
        try:  # unix timestamp (s oder ms)
            t = float(s)
            if t > 1e11:
                t /= 1000.0
            return float(datetime.datetime.utcfromtimestamp(t).date().toordinal())
        except Exception:
            return None
    t = str(s).strip()
    for fmt in ("%d.%m.%Y", "%Y-%m-%d", "%d.%m.%Y %H:%M", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%d/%m/%Y"):
        try:
            return float(datetime.datetime.strptime(t, fmt).date().toordinal())
        except ValueError:
            continue
    m = re.match(r"(\d{4})-(\d{2})-(\d{2})", t)
    if m:
        return float(datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3))).toordinal())
    return None


def _ratio_txt(main, total):
    if not total:
        return None, ""
    x = main * 100.0 / total
    return x, "%d:%d" % (round(x), 100 - round(x))


def _group(n):
    return "{:,}".format(n).replace(",", ".")


def fmt_num(x, signed=False):
    if x is None:
        return "–"
    sign = "+" if (signed and x > 0) else ""
    if abs(x - round(x)) < 1e-9:
        return sign + _group(int(round(x)))
    s = "%.2f" % x
    ip, dp = s.split(".")
    dp = dp.rstrip("0")
    neg = ip.startswith("-")
    ip = _group(int(ip.lstrip("-") or 0))
    return sign + ("-" if neg else "") + ip + ("," + dp if dp else "")


def fmt_thr(t):
    """Schwellenwert kurz: 750000 -> 750k, 1600000 -> 1,6M, 800 -> 800"""
    if t >= 1e6:
        return ("%.2f" % (t / 1e6)).rstrip("0").rstrip(".").replace(".", ",") + "M"
    if t >= 1000 and t % 1000 == 0:
        return "%dk" % (t // 1000)
    return fmt_num(t)


def parse_threshold(tok):
    tok = tok.strip()
    m = re.match(r"^(-?\d+(?:[.,]\d+)?)\s*([kKmM]?)$", tok)
    if m:
        v = float(m.group(1).replace(",", "."))
        mult = {"": 1, "k": 1e3, "m": 1e6}[m.group(2).lower()]
        return v * mult
    v = parse_num(tok)
    if v is None:
        raise ValueError("Schwellenwert nicht lesbar: '%s'" % tok)
    return v


def split_thresholds(s):
    parts = re.split(r"\s*;\s*|\s*,\s+|\s+|\n", str(s).strip())
    return [p for p in parts if p]


POT_KEYS = ("pot_min", "pot_main", "pot_con", "pot_life")


def fmt_potleft(key, rec):
    """Trank-Laufzeit: Datum und Resttage ab dem Scan, z. B. "10.12.2026 (81 T)"; abgelaufen / unter 3 Tagen markiert."""
    v, at = rec.get(key), rec.get(key + "_at")
    if v is None:
        return "–"
    d = fmt_ts(at, False) if at else "?"
    if v < 0:
        return "abgelaufen (%s)" % d
    n = int(v)
    if v < 3:
        return "%s (nur noch %s)" % (d, "%d T" % n if n >= 1 else "%d h" % max(1, int(v * 24)))
    return "%s (%s T)" % (d, _group(n))


def is_avatar(r):
    """Spieler mit Avatar-Bild (Spezial-Bild statt Gesicht): letzter Gesichtswert negativ, z. B. -404."""
    f = r.get("_face")
    return bool(f) and isinstance(f[-1], (int, float)) and f[-1] < 0


def is_special(r):
    """Spezial-Bild: Content Creator oder Avatar-Bild (zaehlt bei "Gleiches Aussehen" nur mit Haken)."""
    return r.get("creator") is True or is_avatar(r)


def special_counts(recs):
    """Verschiedene Spezial-Bilder: (CC-Bilder, CC-Spieler, Avatar-Bilder ohne CC, Avatar-Spieler).
    Ein Bild = Avatar-Nummer (letzter Gesichtswert negativ), sonst das ganze Aussehen."""
    cc, av, seen = {}, {}, set()
    for r in recs or []:
        if not is_special(r):
            continue
        if r.get("_srv") is not None and r.get("name"):
            ck = (r.get("_srv"), str(r.get("name")).lower())
            if ck in seen:
                continue
            seen.add(ck)
        f = r.get("_face") or ()
        k = ("a", f[-1]) if f and isinstance(f[-1], (int, float)) and f[-1] < 0 else face_key(r)
        if k is None:
            continue
        d = cc if r.get("creator") is True else av
        d[k] = d.get(k, 0) + 1
    return len(cc), sum(cc.values()), len(av), sum(av.values())


def special_counts_text(recs):
    a, b, c, d = special_counts(recs)
    return ("Gefunden (alle geladenen Spieler): %s verschiedene Spezial-Bilder – CC: %s Bilder (%s Spieler) · "
            "Avatar-Bild (A, ohne CC): %s Bilder (%s Spieler)" % (_group(a + c), _group(a), _group(b), _group(c), _group(d)))


def fmt_value(key, rec):
    f = FIELD_MAP.get(key)
    if f is None:
        return str(rec.get(key, ""))
    if key in POT_KEYS:
        return fmt_potleft(key, rec)
    v = rec.get(key)
    delta = rec.get("_delta")
    if key == "server":
        return rec.get("_srv_disp", "?")
    if key.startswith("gd_") and key not in ("gd_joined", "gd_left"):
        return "–" if v is None else fmt_num(v, signed=True)
    if key in SIGNED_KEYS and not delta:
        return "–" if v is None else fmt_num(v, signed=True)
    if key == "level_k" and v is not None and not delta:
        return fmt_num(round(v))
    if key == "mount" and v is not None and not delta:
        return "kein" if not v else "%s %%%s" % (fmt_num(v), (" " + rec["_mount_name"]) if rec.get("_mount_name") else "")
    if key in ("rune_dmg", "rune_dmg2") and v and not delta:
        return "%s%s%%" % ((rec.get(key + "_el") + " ") if rec.get(key + "_el") else "", fmt_num(v))
    if f.kind == "text":
        return v or ""
    if f.kind == "flag":
        if v is None:
            return "–"
        if delta:
            return "neu" if v else "–"
        return "Ja" if v else "Nein"
    if v is None:
        return "–"
    if f.kind == "ts" and not delta:
        return fmt_ts(v, bool(rec.get("_seen_time", True)))
    if delta:
        return fmt_num(v, signed=True) + (" %" if f.kind == "pct" else "")
    if f.kind == "ratio":
        return rec.get(key + "_txt") or fmt_num(v)
    if f.kind == "pct":
        return fmt_num(v) + "%"
    if f.kind == "dhm":
        m = int(v)
        return "%02d:%02d:%02d" % (m // 1440, (m % 1440) // 60, m % 60)
    if f.kind == "date":
        try:
            return datetime.date.fromordinal(int(v)).strftime("%d.%m.%Y")
        except Exception:
            return "–"
    return fmt_num(v)


def cell_text(key, rec):
    """Text einer Tabellenzelle. Bei "Bester Spieler der Gilde" steht der Name vor dem Wert: "Name - Summe"."""
    if key in SQ_GROUPS:
        return sq_text(key, rec)
    t = fmt_value(key, rec)
    if key.startswith("gm_") and rec.get(key) is not None:
        n = rec.get(key + "_n")
        if n:
            return "%s - %s" % (n, t)
    return t


def parse_terms(s):
    """Suchtext in mehrere Begriffe zerlegen (Trennzeichen: Komma, Semikolon, Zeilenumbruch)."""
    return [t.strip().lower() for t in re.split(r"[,;\n]+", s or "") if t.strip()]


def match_terms(terms, *texts):
    """True, wenn (ohne Begriffe) immer, sonst wenn irgendein Begriff in irgendeinem Text vorkommt."""
    if not terms:
        return True
    lows = [str(t or "").lower() for t in texts]
    return any(tm in t for tm in terms for t in lows)


def fmt_ts(ms, with_time=True):
    if not ms:
        return "?"
    try:
        dt = datetime.datetime.fromtimestamp(ms / 1000.0)
    except Exception:
        return "?"
    return dt.strftime("%d.%m.%Y %H:%M" if with_time else "%d.%m.%Y")


