        self.d = {}
        try:
            with open(CONFIG_PATH, "r", encoding="utf-8") as fh:
                self.d = json.load(fh)
        except Exception:
            self.d = {}
        d = self.d
        ver = d.get("rules_version")
        if ver != RULES_VERSION:
            if ver == 3 and isinstance(d.get("rules"), list):
                # eigene Einstellungen behalten, nur den neuen Eintrag "Lebensenergie" ergaenzen
                pos = max([i for i, r in enumerate(d["rules"]) if r.get("type") == "top"] + [-1]) + 1
