def komp_key_of(name):
    """'EU5' -> 's5' (Server-Kuerzel im Programm), 'AM1' -> 'am1'."""
    m = re.match(r"^\s*EU\s*0*(\d+)\s*$", str(name or ""), re.I)
    if m:
        return "s%d" % int(m.group(1))
    return re.sub(r"\s+", "", str(name or "")).lower()


def default_komp_servers():
    out = []
    for name, start in DEFAULT_KOMP_SERVERS:
        out.append({"name": name, "key": komp_key_of(name), "start": start, "origin": DEFAULT_KOMP_ORIGINS.get(name),
                    "fused": name in KOMP_ALREADY_FUSED})
    return out


def parse_day(txt):
    """'07.07.2023' / '07-07-2023' / '2023-07-07' -> datetime.date (sonst None)."""
    t = str(txt or "").strip()
    m = re.match(r"^(\d{1,2})[.\-/](\d{1,2})[.\-/](\d{4})$", t)
    try:
        if m:
            return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
        m = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})$", t)
        if m:
            return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        return None
    return None


def komp_group_of(day):
    return (day.year, 1 if day.month <= 6 else 2)


def komp_group_label(g):
    """Halbjahr als Text: (2023, 2) -> '2. Halbjahr 2023'."""
    return "%d. Halbjahr %d" % (g[1], g[0])


def komp_range_label(names):
    """Server einer Fusionsgruppe als Bereich: ['EU5', 'EU6', 'EU7', 'EU8'] -> 'EU5–EU8' (andere Namen mit +)."""
    eu = sorted([n for n in names if re.match(r"^EU\d+$", n, re.I)], key=natural_key)
    other = [n for n in names if n not in eu]
    txt = (eu[0] if len(eu) == 1 else "%s–%s" % (eu[0], eu[-1])) if eu else ""
    if other:
        txt = (txt + " + " if txt else "") + ", ".join(other)
    return txt


def komp_plan(servers, mode="round", cycle=True, ref=None):
    """Serverliste -> {Kuerzel: Info} mit Gruppe, Bezugsserver und Monaten (gerundet auf 0,5 oder exakt).
    cycle=False: kein Halbjahres-Zyklus - alle ungefusionierten Server ab dem Bezugsserver (ref) bilden eine Gruppe,
    aeltere ungefusionierte Server bekommen nichts; bereits fusionierte Server bleiben wie bisher (Halbjahr)."""
    rows = []
    for sv in servers or []:
        day = parse_day(sv.get("start"))
        if day is None:
            continue
        rows.append(dict(sv, day=day, group=komp_group_of(day)))
    if not cycle:
        live = [r for r in rows if not r.get("fused")]
        rk = str(ref or "").strip().lower()
        rr = next((r for r in live if rk and rk in (str(r.get("key") or komp_key_of(r["name"])).lower(),
                                                    eu_names(r["name"]).lower(), str(r["name"]).lower())), None)
        if rr is None and live:
            rr = min(live, key=lambda r: r["day"])
        if rr is not None:
            g0 = (rr["day"].year, 0)                       # eigene Gruppe "ab <Bezug>"
            keep = []
            for r in rows:
                if not r.get("fused"):
                    if r["day"] < rr["day"]:
                        continue
                    r["group"] = g0
                keep.append(r)
            rows = keep
    first, members = {}, {}
    for r in rows:
        g = r["group"]
        members.setdefault(g, []).append(r["name"])
        if g not in first or r["day"] < first[g]["day"]:
            first[g] = r
    plan = {}
    for r in rows:
        ref = first[r["group"]]
        exact = (r["day"] - ref["day"]).days / DAYS_PER_MONTH
        months = math.floor(exact * 2 + 0.5) / 2.0 if mode != "exact" else round(exact, 2)
        plan[str(r.get("key") or komp_key_of(r["name"])).lower()] = dict(
            name=eu_names(r["name"]), group=r["group"], group_label=komp_range_label([eu_names(n) for n in members[r["group"]]]),
            half_label=komp_group_label(r["group"]) if r["group"][1] else "ab %s (ohne Zyklus)" % eu_names(ref["name"]),
            ref=eu_names(ref["name"]),
            months=months, months_exact=exact, fused=bool(r.get("fused")), origin=r.get("origin"))
    return plan


def komp_bonus(level, months, curve="new"):
    """Base-Bonus = floor(Goldkurve[Level] / 60,38647 x (1+2+1+0,5) x 1,1 x (1+1) x 4/5 x 16/10.000.000 x 25 x Monate).
    Neue Kurve (seit F28): ab Level 557 kommen je Level nur noch 12,8 Stats x Monate / 1,5 dazu
    (geprueft: Reckless EU8 Level 572 -> 12.109, Vaaz F28/EU4 Level 572 hat hoechstens 12.129,9 bekommen)."""
    if level is None or not months:
        return 0
    lv = max(0, int(level))
    if curve != "old" and lv > KOMP_FLAT_FROM:
        base = GOLD_CURVE[KOMP_FLAT_FROM] / KOMP_DIVISOR * KOMP_FACTOR * months
        return int(math.floor(base + (lv - KOMP_FLAT_FROM) * KOMP_FLAT_STEP * months / 1.5 + 1e-9))
    lv = min(lv, len(GOLD_CURVE) - 1)
    return int(math.floor(GOLD_CURVE[lv] / KOMP_DIVISOR * KOMP_FACTOR * months))


def learn_origins(recs, plan):
    """Herkunfts-Nummer je ungefusioniertem Server aus dem Scan lernen: {Nummer: Kuerzel}."""
    by = {}
    for r in recs or []:
        k, o = r.get("_srv"), r.get("origin_id")
        if k in plan and not plan[k]["fused"] and o:
            by.setdefault(k, Counter())[int(o)] += 1
    out = {}
    for k, cnt in by.items():
        o, n = cnt.most_common(1)[0]
        if n >= 0.9 * sum(cnt.values()):
            out[o] = k
    return out


def apply_komp(recs, plan, origins, level_per_month=2.0, curve="new"):
    """Setzt je Spieler die Kompensationsfelder. Ungefusionierte Server direkt; fusionierte Server ueber den
    Herkunftsserver - aber nur nach der ersten Fusion (stammen die Spieler aus mehreren Halbjahren, gibt es keine
    Kompensation mehr)."""
    by_origin = {}
    for k, info in plan.items():
        if info.get("origin"):
            by_origin[int(info["origin"])] = k
    for o, k in (origins or {}).items():
        if k in plan:
            by_origin.setdefault(int(o), k)
    names = {k: info["name"] for k, info in plan.items()}
    fused_ok = {}                                  # fusionierter Server -> nur eine Herkunfts-Gruppe?
    for r in recs or []:
        k = r.get("_srv")
        if k in plan and not plan[k]["fused"]:
            continue
        o = r.get("origin_id")
        src = by_origin.get(int(o)) if o else None
        if src:
            fused_ok.setdefault(k, set()).add(plan[src]["group"])
    for r in recs or []:
        for f in ("komp_server", "komp_group", "komp_months", "level_k", "base_k", "komp_bonus", "komp_lvb"):
            r[f] = "" if f in ("komp_server", "komp_group") else None
        o = r.get("origin_id")
        if o and int(o) in by_origin:
            r["origin"] = names.get(by_origin[int(o)], "")
        k = r.get("_srv")
        src = None
        if k in plan and not plan[k]["fused"]:
            src = k
        elif o and len(fused_ok.get(k, ())) == 1:
            src = by_origin.get(int(o))
        if not src:
            continue
        info = plan[src]
        lv, bs = r.get("level"), r.get("base_sum")
        if lv is None:
            continue
        m = info["months"]
        bonus = komp_bonus(lv, m, curve)
        r["komp_server"] = info["name"]
        r["komp_group"] = info["group_label"]
        r["_komp_g"] = info["group"]
        r["komp_months"] = float(m)
        lvb = math.floor(m * level_per_month + 1e-9)        # wie die Formel: ganze Level, Rest abgerundet
        r["level_k"] = float(lv + lvb)
        r["komp_lvb"] = float(lvb)
        r["komp_bonus"] = float(bonus)
        if bs is not None:
            r["base_k"] = float(bs + bonus)


def komp_guilds(recs):
    """Gilden-Zusammenfassung der kompensierten Spieler (je Server und Gilde)."""
    groups = {}
    for r in recs or []:
        if r.get("komp_bonus") is None or not r.get("guild"):
            continue
        groups.setdefault((r["_srv"], r["guild"].lower()), []).append(r)
    out = []
    for (srv, _low), mem in groups.items():
        n = len(mem)
        r0 = mem[0]
        lv = [m["level"] for m in mem if m.get("level") is not None]
        lk = [m["level_k"] for m in mem if m.get("level_k") is not None]
        bs = [m["base_sum"] for m in mem if m.get("base_sum") is not None]
        bk = [m["base_k"] for m in mem if m.get("base_k") is not None]
        bo = [m["komp_bonus"] for m in mem]
        grp = sorted({m["komp_group"] for m in mem})
        srvs = sorted({m["komp_server"] for m in mem}, key=natural_key)
        out.append({
            "name": r0["guild"], "guild": r0["guild"], "_srv": srv, "_srv_disp": r0.get("_srv_disp", srv),
            "server": r0.get("server", ""), "g_server": r0.get("_srv_disp", srv), "g_name": r0["guild"],
            "_ts": max((m.get("_ts") or 0) for m in mem), "_members": mem,
            "komp_group": ", ".join(grp), "komp_server": ", ".join(srvs),
            "_komp_g": min(m.get("_komp_g") or (9999, 9) for m in mem),
            "kg_members": float(n),
            "kg_level_avg": round(sum(lv) / len(lv), 1) if lv else None,
            "kg_level_k_avg": round(sum(lk) / len(lk), 1) if lk else None,
            "kg_base_sum": float(sum(bs)) if bs else None,
            "kg_base_k_sum": float(sum(bk)) if bk else None,
            "kg_bonus_sum": float(sum(bo)),
            "kg_bonus_avg": round(sum(bo) / n, 1) if n else None,
        })
    return out


