def open_file(path):
    """Datei mit dem Standard-Programm oeffnen (Bildbetrachter)."""
    try:
        if sys.platform.startswith("win"):
            os.startfile(path)                          # noqa
        elif sys.platform == "darwin":
            subprocess.Popen(["open", path])
        else:
            subprocess.Popen(["xdg-open", path])
        return True
    except Exception:
        return False


def copy_image_to_clipboard(path):
    """PNG als Bild in die Windows-Zwischenablage (zum Einfuegen in Discord) - ohne Zusatzpakete. True = geklappt."""
    if not sys.platform.startswith("win"):
        return False
    try:
        import ctypes
        from ctypes import wintypes
        from PIL import Image
        with Image.open(path) as im:
            bio = io.BytesIO()
            im.convert("RGB").save(bio, "BMP")
        data = bio.getvalue()[14:]                      # ohne Datei-Kopf = CF_DIB
        k32, u32 = ctypes.windll.kernel32, ctypes.windll.user32
        k32.GlobalAlloc.restype, k32.GlobalAlloc.argtypes = wintypes.HGLOBAL, [wintypes.UINT, ctypes.c_size_t]
        k32.GlobalLock.restype, k32.GlobalLock.argtypes = wintypes.LPVOID, [wintypes.HGLOBAL]
        k32.GlobalUnlock.argtypes = [wintypes.HGLOBAL]
        u32.OpenClipboard.argtypes = [wintypes.HWND]
        u32.SetClipboardData.restype, u32.SetClipboardData.argtypes = wintypes.HANDLE, [wintypes.UINT, wintypes.HANDLE]
        h = k32.GlobalAlloc(0x0002, len(data))
        p = k32.GlobalLock(h)
        ctypes.memmove(p, data, len(data))
        k32.GlobalUnlock(h)
        if not u32.OpenClipboard(None):
            return False
        try:
            u32.EmptyClipboard()
            return bool(u32.SetClipboardData(8, h))
        finally:
            u32.CloseClipboard()
    except Exception:
        return False


def split_discord(text, limit=2000):
    """Teilt die Liste in Nachrichten mit hoechstens `limit` Zeichen. Bevorzugt Schnitte an Leerzeilen,
    sonst zwischen zwei Zeilen; nur extrem lange Einzelzeilen werden hart getrennt."""
    if not text:
        return []
    if not limit or limit < 50 or len(text) <= limit:
        return [text]
    if "```" in text:
        limit -= 8                                         # Platz fuer ``` beim Teilen eines Codeblocks
    lines = text.split("\n")
    parts, start = [], 0
    while start < len(lines):
        total, end, last_blank = 0, start, None
        while end < len(lines):
            add = len(lines[end]) + (1 if end > start else 0)
            if total + add > limit:
                break
            total += add
            if end > start and not lines[end].strip():
                last_blank = end
            end += 1
        if end >= len(lines):
            parts.append("\n".join(lines[start:]).strip("\n"))
            break
        if end == start:                                   # einzelne Zeile ist laenger als das Limit
            parts.append(lines[start][:limit])
            lines[start] = lines[start][limit:]
            continue
        cut = last_blank if last_blank is not None else end
        parts.append("\n".join(lines[start:cut]).strip("\n"))
        start = cut
        while start < len(lines) and not lines[start].strip():
            start += 1
    parts = [x for x in parts if x.strip()]
    for i in range(len(parts) - 1):                       # Schnitt mitten in einem Codeblock (Tabelle): schliessen / neu oeffnen
        if sum(1 for ln in parts[i].split("\n") if ln.strip().startswith("```")) % 2 == 1:
            parts[i] += "\n```"
            parts[i + 1] = "```\n" + parts[i + 1]
    return parts


_PH = re.compile(r"\{(\w+(?:-\d+)?)\}")

# ---- Bild-Formatierung: Farben und Marken wirken nur im Bild ("Als Bild speichern"); im Discord-Text werden sie entfernt
IMG_COLORS = {"gold": "#f0b232", "gelb": "#ffd166", "orange": "#ff9f43", "rot": "#ff6b6b", "rosa": "#ff7bb0",
              "lila": "#c79bff", "blau": "#7fb8ff", "türkis": "#5ad1e8", "grün": "#57d98b", "hellgrün": "#b5e655",
              "hellblau": "#c9cdfb", "silber": "#c0c4cc", "bronze": "#cd8a4f", "weiß": "#ffffff"}
_IMG_COL_ALIAS = {"tuerkis": "türkis", "gruen": "grün", "hellgruen": "hellgrün", "weiss": "weiß"}
_COLTAG = r"(?:%s|#[0-9a-fA-F]{6}|#[0-9a-fA-F]{3})" % "|".join(
    sorted(list(IMG_COLORS) + list(_IMG_COL_ALIAS), key=len, reverse=True))
_MARK_RE = re.compile(r"\[(?:%s|/|rahmen(?:=%s)?|nichtfett|trenn|icon:[a-z]\d+)\]" % (_COLTAG, _COLTAG), re.I)
_ICON_RE = re.compile(r"\[icon:([a-z])(\d+)\]", re.I)      # Symbol im Bild (z.B. [icon:c3] = Klasse 3), im Text entfernt
_ICON_HOOK = [None]                                          # (Art, Nr), Groesse -> Pillow-Bild (setzt das Programm)


def set_icon_hook(fn):
    _ICON_HOOK[0] = fn
_HEAD_MARK_RE = re.compile(r"\[(rahmen(?:=(%s))?|nichtfett|(%s))\]\s*" % (_COLTAG, _COLTAG), re.I)


def img_color(name):
    """Farbname (gold, grün …) oder #rrggbb / #rgb -> #rrggbb; sonst None."""
    n = str(name or "").strip().lower()
    n = _IMG_COL_ALIAS.get(n, n)
    if n in IMG_COLORS:
        return IMG_COLORS[n]
    if re.fullmatch(r"#[0-9a-f]{6}", n):
        return n
    if re.fullmatch(r"#[0-9a-f]{3}", n):
        return "#" + "".join(c * 2 for c in n[1:])
    return None


_TBL_SEP_RE = re.compile(r"^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$")
_NUMCELL_RE = re.compile(r"^[★☆✦]?\s*[+\-−±]?\s*#?[\d.,]+\s*(%|[kKMB]|Mio\.?)?\s*([▲▼]\s*\d*)?$|^[–—\-]$")
_FMT_RE = re.compile(r"\*\*|__|~~|`")


def is_table_line(ln):
    """Tabellen-Zeile: beginnt mit | und endet mit | (| a | b |) - auch eine Spalte (| a |)."""
    t = str(ln).strip()
    return t.startswith("|") and (t.count("|") >= 3 or (len(t) > 2 and t.endswith("|")))


def table_cells(line):
    t = str(line).strip()
    if t.startswith("|"):
        t = t[1:]
    if t.endswith("|"):
        t = t[:-1]
    return [c.strip() for c in t.split("|")]


def _plain_cell(c):
    return _FMT_RE.sub("", _MARK_RE.sub("", c)).strip()


def parse_table(lines):
    """'|'-Zeilen -> (Zeilen [[Zelle]], Ausrichtung je Spalte 'l'/'c'/'r', Zeilen ohne Marken). Erste Zeile = Kopf.
    Ausrichtung aus einer Trennzeile (|:--|:-:|--:|), sonst: nur Zahlen = mittig, Text = links."""
    rows, sep = [], None
    for ln in lines:
        if "-" in ln and _TBL_SEP_RE.match(ln):
            if sep is None:
                sep = table_cells(ln)
            continue
        rows.append(table_cells(ln))
    n = max([len(r) for r in rows] or [0])
    rows = [r + [""] * (n - len(r)) for r in rows]
    plain = [[_plain_cell(c) for c in r] for r in rows]
    al = []
    for i in range(n):
        sp = sep[i].strip() if sep and i < len(sep) else ""
        if sp.startswith(":") and sp.endswith(":"):
            al.append("c")
        elif sp.endswith(":"):
            al.append("r")
        elif sp.startswith(":"):
            al.append("l")
        else:
            vals = [r[i] for r in plain[1:] if r[i]]
            al.append("c" if vals and all(_NUMCELL_RE.match(v) for v in vals) else "l")
    return rows, al, plain


def table_box(lines):
    """Tabelle fuer Discord: Codeblock mit Rahmen aus Linien-Zeichen, Spalten buendig (Zahlen mittig)."""
    rows, al, plain = parse_table(lines)
    if not rows or not rows[0]:
        return []
    n = len(rows[0])
    wd = [max(len(r[i]) for r in plain) for i in range(n)]

    def cell(t, i, head):
        if head or al[i] == "c":
            return t.center(wd[i])
        return t.rjust(wd[i]) if al[i] == "r" else t.ljust(wd[i])

    def line(r, head=False):
        return "│" + "│".join(" " + cell(r[i], i, head) + " " for i in range(n)) + "│"

    def edge(a, b, c):
        return a + b.join("─" * (w + 2) for w in wd) + c
    seps = {ri for ri, r in enumerate(rows) if ri > 1 and r and "[trenn]" in r[0].lower()}   # Trennlinie (z. B. neuer Server)
    out = ["```", edge("┌", "┬", "┐"), line(plain[0], True)]
    if len(plain) > 1:
        out.append(edge("├", "┼", "┤"))
        for ri, r in enumerate(plain[1:], 1):
            if ri in seps:
                out.append(edge("├", "┼", "┤"))
            out.append(line(r))
    return out + [edge("└", "┴", "┘"), "```"]


def table_box_rows(head, body):
    """Kopf + Zeilen (Texte) -> Discord-Codeblock mit Rahmen."""
    return table_box(["| " + " | ".join(_tcl(c) for c in head) + " |"] + ["| " + " | ".join(_tcl(c) for c in r) + " |" for r in body])


def _balance_parts(parts):
    """Fett / unterstrichen ueber einen Zeilenumbruch (/n): am Zeilenende schliessen, in der naechsten Zeile wieder oeffnen."""
    for mk in ("**", "__"):
        op = False
        for i, p in enumerate(parts):
            if op:
                p = mk + p
            op = p.count(mk) % 2 == 1
            if op and i < len(parts) - 1:
                p = p + mk
            parts[i] = p.replace(mk + mk, "")
    for i, p in enumerate(parts):                         # "**Keltic  **" -> "**Keltic**" (sonst zeigt Discord kein Fett)
        p = re.sub(r"[ 	]+((?:\*\*|__)+)$", r"\1", p.rstrip())
        parts[i] = re.sub(r"^((?:\*\*|__)+)[ 	]+", r"\1", p)
    return parts


def strip_marks(text):
    """Bild-Marken ([gold] … [/], [rahmen], [nichtfett] …) entfernen - fuer Discord, .txt und die Text-Vorschau.
    Discord-Formatierung (**fett**, *kursiv*, __unterstrichen__, `hervorgehoben`) bleibt; Codebloecke bleiben unberuehrt.
    Tabellen (Zeilen mit | … | …) werden ein Codeblock mit Rahmen."""
    out, code = [], False
    lines = str(text).split("\n")
    k = 0
    while k < len(lines):
        ln = lines[k]
        k += 1
        if not code and is_table_line(ln):
            blk = [ln]
            while k < len(lines) and is_table_line(lines[k]):
                blk.append(lines[k])
                k += 1
            out += table_box(blk)
            continue
        if ln.strip().startswith("```"):
            code = not code
            out.append(ln)
            continue
        if code:
            out.append(ln)
            continue
        if _NEWPIC_RE.search(ln):
            ln = _NEWPIC_RE.sub("", ln).lstrip(" ")
            if not _MARK_RE.sub("", ln).strip():
                continue                                    # Zeile nur mit [neues Bild]: faellt im Text weg
        ln = _MARK_RE.sub("", ln)
        if "\u2028" in ln:                                 # Zeilenumbruch aus der Vorlage
            m = re.match(r"^(-#|#+)\s*", ln)
            pre = m.group(1) + " " if m else ""
            parts = [ln.split("\u2028")[0].rstrip()] + [p.strip(" ") for p in ln.split("\u2028")[1:]]
            parts = _balance_parts(parts)
            out.append(parts[0].rstrip())
            for p in parts[1:]:
                p = p.strip()
                if _FMT_RE.sub("", p).strip():              # leere Teilzeile (z.B. {guild} ohne Gilde) faellt weg
                    out.append(pre + p if pre else p)
            continue
        out.append(ln)
    return "\n".join(out)


def wo_text(rec, extra):
    """{wo}: "Gilde X" (wenn Gilden gewaehlt sind; gleicher Gildenname auf zwei Servern -> Server in Klammern), sonst "Server Y"."""
    if rec is None:
        return str(extra.get("_wo_scope", ""))
    srv = rec.get("_srv_disp") or rec.get("server") or ""
    g = rec.get("guild")
    if extra.get("_wo_kind") != "guild" and extra.get("_wo_g") and g:
        if str(g).lower() in (extra.get("_wo_dup") or ()):
            return "Gilde %s (%s)" % (g, srv)
        return "Gilde %s" % g
    return "Server %s" % srv


def _wo_list(word1, wordn, names):
    names = [n for n in names if n]
    if not names:
        return ""
    if len(names) == 1:
        return "%s %s" % (word1, names[0])
    if len(names) <= 4:
        return "%s %s" % (wordn, ", ".join(names))
    return "%s %s" % (_group(len(names)), wordn + ("n" if wordn == "Server" else ""))


def wo_ctx(ctx, recs, gmode=False, kind="player"):
    """Angaben fuer {wo} in den Kontext schreiben (gmode = Gilden-Auswahl aktiv)."""
    ctx["_wo_g"], ctx["_wo_kind"] = bool(gmode), kind
    srvs, by = set(), {}
    for p in recs or ():
        srvs.add(p.get("_srv_disp") or p.get("server") or "")
        g = p.get("guild") if kind != "guild" else None
        if g:
            by.setdefault(str(g).lower(), {}).setdefault(p.get("_srv"), (g, p.get("_srv_disp") or ""))
    dup = {k for k, v in by.items() if len(v) > 1}
    ctx["_wo_dup"] = dup
    if gmode and by and kind != "guild":
        names = []
        for k, v in sorted(by.items()):
            for g, sd in sorted(v.values()):
                names.append("%s (%s)" % (g, sd) if k in dup else g)
        ctx["_wo_scope"] = _wo_list("Gilde", "Gilden", names)
    else:
        ctx["_wo_scope"] = _wo_list("Server", "Server", sorted(srvs, key=str.lower))
    return ctx


_BR_RE = re.compile(r"\\n|/n(?![a-zäöüß])")      # Zeilenumbruch in Vorlagen: \n oder /n (nicht /neu, /nicht ...)
_NEWPIC_RE = re.compile(r"\[neues\s*bild\]", re.I)    # [neues Bild]: hier beginnt im Bild ein neues Bild


def fill(template, rec, extra):
    template = _BR_RE.sub("\u2028", str(template))   # Umbruch innerhalb der Zeile (eine Ueberschrift bleibt eine, mit Rahmen)

    def repl(m):
        k = m.group(1)
        if k in extra:
            return str(extra[k])
        if k == "wo":
            return wo_text(rec, extra)
        if rec is not None:
            if k == "server_full":
                return rec.get("server", "")
            base, src = k, rec
            if k.endswith("_new") or k.endswith("_old"):
                base = k[:-4]
                if rec.get("_delta"):
                    src = rec["_new"] if k.endswith("_new") else rec["_old"]
            if base in FIELD_MAP:
                return fmt_value(base, src)
        return m.group(0)
    return _PH.sub(repl, template)


def new_rule(t):
    if t == "bestval":
        return {"type": "bestval", "enabled": True, "fields": list(BESTVAL_DEF), "tcols": ["_n", "name", "server", "guild"],
                "title": "## Bester Spieler je Wert", "blank_after": 0}
    if t == "threshold":
        return {"type": "threshold", "enabled": True, "field": "level", "values": "800; 790; 780",
                "op": ">=", "label": "Level", "template": "- {count} Spieler sind über **{label} {value}**",
                "blank_after": 0}
    if t == "top":
        return {"type": "top", "enabled": True, "field": "level", "direction": "max", "n": 1, "tiebreak": "",
                "min_value": "", "template": "Bester Spieler: **{name}** von {server} ({value})",
                "title": "Top {n} ({label}):", "template_multi": "{rank}. **{name}** von {server} – {value}",
                "blank_after": 0}
    if t == "flagcount":
        return {"type": "flagcount", "enabled": True, "field": "gold_frame", "label": "Gold Frame",
                "template": "- {count} Spieler haben einen **{label}**", "blank_after": 0}
    if t == "classpotions":
        return {"type": "classpotions", "enabled": True, "field": "level", "tiebreak": "xp", "tops": "1000",
                "sort": "count", "title": "**Klassen in den Top {x}:**",
                "template": "- {klasse}: {count} Spieler ({pct}%), davon {full} mit allen Tränken ({full_pct}%)",
                "template_total": "- Alle Klassen: {full_total} von {n} Spielern haben alle Tränke ({full_total_pct}%)",
                "blank_after": 0}
    if t == "guildavg":
        return {"type": "guildavg", "enabled": True, "field": "base_sum", "x": 10, "n": 3, "min_members": 15, "label": "",
                "title": "## Ø der Top {x} je Gilde ({label})",
                "template": "- **{guild}** ({server}): Ø {avg} – die Top {x} liegen {abstand} dem Ø der übrigen {rest_n} Mitglieder ({rest})",
                "blank_after": 0}
    if t == "classsrv":
        return {"type": "classsrv", "enabled": True, "field": "level", "n": 1, "tiebreak": "xp", "label": "", "sort": "count",
                "title": "## Beste je Klasse je Server ({label})", "template_srv": "### {server} – {count} Spieler",
                "template": "- {klasse} ({count}): **{name}** – {label} {value}", "total": True,
                "template_total": "-# Alle Server: {klassen}", "blank_after": 0}
    if t == "classbest":
        return {"type": "classbest", "enabled": True, "field": "level", "n": 1, "tiebreak": "xp", "label": "",
                "title": "## Höchstes {label} nach Klassen",
                "template": "- **{klasse}** – {name} von {wo} mit {label} **{value}**", "blank_after": 0}
    return {"type": "text", "enabled": True, "text": "", "blank_after": 0}


def _thr(field, values, label, template, blank=1, op=">="):
    r = new_rule("threshold")
    r.update(field=field, values=values, label=label, template=template, blank_after=blank, op=op)
    return r


def _top(field, template, direction="max", n=1, tiebreak="", blank=0, min_value="", title=None, tmulti=None):
    r = new_rule("top")
    r.update(field=field, template=template, direction=direction, n=n, tiebreak=tiebreak, blank_after=blank,
             min_value=min_value)
    if title is not None:
        r["title"] = title
    if tmulti is not None:
        r["template_multi"] = tmulti
    return r


def _flag(field, label, template, blank=0):
    r = new_rule("flagcount")
    r.update(field=field, label=label, template=template, blank_after=blank)
    return r


def _text(text, blank=0):
    r = new_rule("text")
    r.update(text=text, blank_after=blank)
    return r


