def _min_members(r, players, cache):
    """Gilden-Regeln: Gilden mit weniger als 'min_members' Mitgliedern ignorieren. Gibt (Liste, Schluessel) zurueck."""
    try:
        mm = int(r.get("min_members") or 0)
    except (TypeError, ValueError):
        mm = 0
    if mm <= 0:
        return players, None
    key = ("mm", mm)
    if key not in cache:
        cache[key] = [p for p in players if (p.get("g_members") or p.get("g_scanned") or 0) >= mm]
    return cache[key], mm


def _sorted_vals(cache, players, field, tag=None):
    key = ("sorted", field, tag)
    if key not in cache:
        cache[key] = sorted(v for v in (p.get(field) for p in players) if v is not None)
    return cache[key]


def ev_text(r, players, ctx, cache):
    txt = _BR_RE.sub("\n", str(r.get("text", "")))       # Text-Eintrag: \n oder /n = neue Zeile
    return fill(txt, None, ctx).split("\n")


_NX = re.compile(r"\{n-(\d+)\}")


def _nx_name(p, dup):
    nm = str(p.get("name") or "")
    return "%s (%s)" % (nm, p.get("_srv_disp") or "") if nm.lower() in dup else nm


def _nx_list(recs, x, dup, more_on=True):
    """{n-x}: bis zu x Namen, danach "+N weitere" (abschaltbar); leer = "–"."""
    x = max(1, int(x))
    shown = [_nx_name(p, dup) for p in recs[:x]]
    more = len(recs) - len(shown)
    txt = ", ".join(shown) if shown else "–"
    if more > 0 and more_on:
        txt += " +%s weitere" % _group(more)
    return txt


def _names_n(r):
    """Schwellen-Zaehler (Tabelle): wie viele Namen je Zeile (Vorgabe 5)."""
    try:
        return max(1, int(r.get("names_n", 5) or 5))
    except (TypeError, ValueError):
        return 5


def _nx_dup(recs):
    cnt = Counter(str(p.get("name") or "").lower() for p in recs)
    return {k for k, v in cnt.items() if v > 1}


def ev_threshold(r, players, ctx, cache):
    f = r["field"]
    players, mm = _min_members(r, players, cache)
    vals = _sorted_vals(cache, players, f, mm)
    n = len(vals)
    if n == 0:
        raise ValueError("Feld '%s' ist in den geladenen Daten nicht vorhanden" % label_of(f))
    out = []
    tpl = r.get("template", "")
    gt = r.get("op", ">=") == ">"
    toks = [parse_threshold(tok) for tok in split_thresholds(r.get("values", ""))]
    if _table_on(r):                                    # Tabelle: eine Zeile je Schwelle
        guild = _is_g(players)
        cols = table_cols(r, guild)
        meets = (lambda v, t: v > t) if gt else (lambda v, t: v >= t)
        pool = sorted((p for p in players if p.get(f) is not None and toks and meets(p[f], min(toks))),
                      key=lambda p: (-p[f], str(p.get("name") or p.get("g_name") or "").lower())) if "names" in cols else []
        dup = _nx_dup(pool) if pool else set()
        out = []
        if r.get("title"):
            e0 = dict(ctx)
            e0.update(label=r.get("label") or label_of(f), total=_group(n))
            out.append(fill(r["title"], None, e0))
        rows = []
        for t in toks:
            cnt = n - (bisect_right(vals, t) if gt else bisect_left(vals, t))
            ex = {"_thr": "**%s %s**" % ("über" if gt else "ab", fmt_thr(t)), "count": "[blau]**%s**[/]" % _group(cnt),
                  "_pct": "%s %%" % _pct(cnt, n)}
            if "names" in cols:
                hi = [u for u in toks if u > t]
                nxt = min(hi) if hi else None
                band = [p for p in pool if meets(p[f], t) and (nxt is None or not meets(p[f], nxt))]
                ex["names"] = _tcl(_nx_list(band, _names_n(r), dup, r.get("names_more", True) is not False))
            rows.append([ex.get(k, "") for k in cols])
        return out + _tlines([table_col_label(k, r, guild) for k in cols], rows)
    nx = sorted({int(x) for x in _NX.findall(tpl)})
    if nx:                                              # Namen: jeder nur in der hoechsten Stufe, die er erreicht
        meets = (lambda v, t: v > t) if gt else (lambda v, t: v >= t)
        pool = sorted((p for p in players if p.get(f) is not None and toks and meets(p[f], min(toks))),
                      key=lambda p: (-p[f], str(p.get("name") or "").lower()))
        dup = _nx_dup(pool)
    for t in toks:
        if gt:
            cnt = n - bisect_right(vals, t)
        else:
            cnt = n - bisect_left(vals, t)
        extra = dict(ctx)
        extra.update(count=_group(cnt), value=fmt_thr(t), label=r.get("label") or label_of(f),
                     total=_group(n), op=r.get("op", ">="))
        if nx:
            hi = [u for u in toks if u > t]
            nxt = min(hi) if hi else None
            band = [p for p in pool if meets(p[f], t) and (nxt is None or not meets(p[f], nxt))]
            for x in nx:
                extra["n-%d" % x] = _nx_list(band, x, dup, r.get("names_more", True) is not False)
        out.append(fill(tpl, None, extra))
    return out


def ev_top(r, players, ctx, cache):
    f = r["field"]
    players, _mm = _min_members(r, players, cache)
    n = max(1, int(r.get("n", 1) or 1))
    desc = r.get("direction", "max") == "max"
    tb = r.get("tiebreak") or None
    mv = r.get("min_value", "")
    minv = parse_num(mv) if str(mv).strip() != "" else None
    items = []
    for idx, p in enumerate(players):
        v = p.get(f)
        if v is None or (minv is not None and v < minv):
            continue
        t = p.get(tb) if tb else None
        t = -1e18 if t is None else t
        items.append(((-v if desc else v), -t, idx, p))
    if not items:
        raise ValueError("Keine %s mit Wert für '%s'" % ("Gilden" if _mm else "Spieler", label_of(f)))
    top = heapq.nsmallest(n, items, key=lambda x: (x[0], x[1], x[2]))
    label = r.get("label") or label_of(f)
    out = []
    if _table_on(r):                                    # Tabelle: eine Zeile je Platz
        guild = _is_g(players)
        cols = table_cols(r, guild)
        if r.get("title"):
            e0 = dict(ctx)
            e0.update(n=n, label=label)
            out.append(fill(r["title"], None, e0))
        rows = [_trow(cols, it[3], f, {"_n": "[silber]%d[/]" % i}) for i, it in enumerate(top, 1)]
        if r.get("cls_icon_top") and not guild and "name" in cols:          # Klassen-Symbol hinter dem Namen (nur im Bild)
            ni = cols.index("name")
            for row, it in zip(rows, top):
                if it[3].get("_cls"):
                    row[ni] += " [icon:c%d]" % int(it[3]["_cls"])
        return out + _tlines([table_col_label(k, r, guild) for k in cols], rows)
    if n == 1:
        p = top[0][3]
        v1 = p.get(f)
        ties = sum(1 for it in items if it[3].get(f) == v1) - 1
        extra = dict(ctx)
        extra.update(label=label, value=fmt_value(f, p), rank=1, ties=ties, n=1)
        out.append(fill(r.get("template", ""), p, extra))
    else:
        title = r.get("title", "")
        if title:
            e0 = dict(ctx)
            e0.update(n=n, label=label)
            out.append(fill(title, None, e0))
        for i, it in enumerate(top, 1):
            p = it[3]
            extra = dict(ctx)
            extra.update(label=label, value=fmt_value(f, p), rank=i, n=n)
            out.append(fill(r.get("template_multi", ""), p, extra))
    return out


def ev_flagcount(r, players, ctx, cache):
    f = r["field"]
    if all(p.get(f) is None for p in players):
        raise ValueError("Feld '%s' ist in den geladenen Daten nicht vorhanden (nur in der CSV)" % label_of(f))
    cnt = sum(1 for p in players if p.get(f))
    extra = dict(ctx)
    extra.update(count=_group(cnt), label=r.get("label") or label_of(f), total=_group(len(players)))
    if _table_on(r):
        cols = table_cols(r)
        ex = {"label": "**%s**" % _tcl(extra["label"]), "count": "[blau]**%s**[/]" % extra["count"], "total": extra["total"],
              "_pct": "%s %%" % _pct(cnt, len(players))}
        head = [fill(r["title"], None, extra)] if r.get("title") else []
        return head + _tlines([table_col_label(k, r) for k in cols], [[ex.get(k, "") for k in cols]])
    return [fill(r.get("template", ""), None, extra)]


def _pct(a, b):
    return fmt_num(round(a * 100.0 / b, 1)) if b else "0"


def ev_classpotions(r, players, ctx, cache):
    """Klassenverteilung in den Top X (nach Ranking-Feld) und wie viele davon alle Traenke haben."""
    rf = r.get("field") or "level"
    tb = r.get("tiebreak") or None
    if not any(p.get("klasse") for p in players):
        raise ValueError("Keine Klassen-Daten vorhanden (nur in den JSON-Rohdaten)")
    pool = [p for p in players if p.get(rf) is not None]
    pool.sort(key=lambda p: (-p[rf], -(p.get(tb) or 0) if tb else 0))
    out = []
    xs = [int(parse_threshold(tok)) for tok in split_thresholds(r.get("tops", "1000"))]
    nx = sorted({int(k) for k in _NX.findall(r.get("template", ""))})
    table = _table_on(r)
    tcols = table_cols(r) if table else []
    dup = _nx_dup(pool[:max(xs)]) if ((nx or "names" in tcols) and xs) else set()
    for x in xs:
        lo = max([u for u in xs if u < x] or [0])         # {n-x}: nur die Plaetze lo+1 … x (hoechste Stufe)
        top = [p for p in pool[:x] if p.get("klasse")]
        n = len(top)
        groups = {}
        for p in top:
            g = groups.setdefault(p["klasse"], [0, 0, p.get("_cls") or 0])
            g[0] += 1
            g[1] += 1 if p.get("tranke_voll") else 0
        if r.get("sort", "count") == "count":
            order = sorted(groups.items(), key=lambda kv: (-kv[1][0], kv[0]))
        else:
            order = sorted(groups.items(), key=lambda kv: (kv[1][2], kv[0]))
        base = dict(ctx)
        base.update(x=_group(x), n=_group(n))
        if r.get("title"):
            out.append(fill(r["title"], None, base))
        if table:                                       # Tabelle: eine Zeile je Klasse
            rows = []
            for name, (cnt, full, cid) in order:
                c = CLASSES.get(cid)
                ex = {"klasse": "[grün]**%s**[/]" % _tcl(name), "count": "[blau]**%s**[/]" % _group(cnt), "_pct": "%s %%" % _pct(cnt, n),
                      "full": _group(full), "full_pct": "%s %%" % _pct(full, cnt), "mult": fmt_num(c[1]) if c else "",
                      "letter": c[2] if c else ""}
                if "names" in tcols:
                    ex["names"] = _tcl(_nx_list([p for p in pool[lo:x] if p.get("klasse") == name], 5, dup))
                rows.append([ex.get(k, "") for k in tcols])
            out += _tlines([table_col_label(k, r, x=_group(x)) for k in tcols], rows)
            if r.get("template_total"):
                ft = sum(g[1] for g in groups.values())
                e = dict(base)
                e.update(full_total=_group(ft), full_total_pct=_pct(ft, n))
                out.append(fill(r["template_total"], None, e))
            continue
        for name, (cnt, full, cid) in order:
            c = CLASSES.get(cid)
            e = dict(base)
            e.update(klasse=name, count=_group(cnt), pct=_pct(cnt, n), full=_group(full), full_pct=_pct(full, cnt),
                     mult=fmt_num(c[1]) if c else "", letter=c[2] if c else "")
            if nx:
                band = [p for p in pool[lo:x] if p.get("klasse") == name]
                for k in nx:
                    e["n-%d" % k] = _nx_list(band, k, dup)
            out.append(fill(r.get("template", ""), None, e))
        if r.get("template_total"):
            ft = sum(g[1] for g in groups.values())
            e = dict(base)
            e.update(full_total=_group(ft), full_total_pct=_pct(ft, n))
            out.append(fill(r["template_total"], None, e))
    return out


def _fmt_avg(f, v, ints):
    if v is None:
        return "–"
    return fmt_value(f, {f: int(round(v)) if ints else round(v, 1)})


def ev_guildavg(r, players, ctx, cache):
    """Gilden: Durchschnitt der besten X Mitglieder und Abstand zum Durchschnitt der uebrigen Mitglieder."""
    f = r.get("field") or "base_sum"
    try:
        x = max(1, int(r.get("x", 10) or 10))
        n = max(1, int(r.get("n", 3) or 3))
        mm = max(0, int(r.get("min_members") or 0))
    except (TypeError, ValueError):
        x, n, mm = 10, 3, 0
    by = {}
    for p in players:
        g, v = p.get("guild"), p.get(f)
        if g and v is not None:
            by.setdefault(cgk(p["_srv"], g), []).append(p)
    rows = []
    ints = True
    for k, ps in by.items():
        if len(ps) < max(mm, 1):
            continue
        vals = sorted((p[f] for p in ps), reverse=True)
        ints = ints and all(isinstance(v, int) or float(v).is_integer() for v in vals)
        top, rest = vals[:x], vals[x:]
        rows.append((sum(top) / len(top), (sum(rest) / len(rest)) if rest else None, len(ps), len(top), ps[0]))
    if not rows:
        raise ValueError("Keine Gilden mit Wert für '%s'%s" % (label_of(f), " und mind. %d Mitgliedern im Scan" % mm if mm else ""))
    rows.sort(key=lambda t: (-t[0], str(t[4].get("guild") or "").lower()))
    label = r.get("label") or label_of(f)
    out = []
    if r.get("title"):
        e0 = dict(ctx)
        e0.update(x=_group(x), n=n, label=label)
        out.append(fill(r["title"], None, e0))
    table = _table_on(r)
    tcols = table_cols(r) if table else []
    trows = []
    for i, (avg, ravg, cnt, ntop, p0) in enumerate(rows[:n], 1):
        if ravg:
            pct = round((avg / ravg - 1) * 100)
            abst = "%s %% %s" % (_group(abs(pct)), "unter" if pct < 0 else "über")
        else:
            abst = "–"
        if table:
            ex = {"_n": "[silber]%d[/]" % i, "guild": "**%s**" % _tcl(p0.get("guild") or ""), "server": _tcl(p0.get("_srv_disp") or ""),
                  "avg": "[blau]**%s**[/]" % _fmt_avg(f, avg, ints), "rest": _fmt_avg(f, ravg, ints), "abstand": abst,
                  "members": _group(cnt), "rest_n": _group(cnt - ntop)}
            trows.append([ex.get(k, "") for k in tcols])
            continue
        e = dict(ctx)
        e.update(guild=p0.get("guild") or "", name=p0.get("guild") or "", server=p0.get("_srv_disp") or "",
                 wo="Server %s" % (p0.get("_srv_disp") or ""), x=_group(x), n=n, label=label, rank=i,
                 avg=_fmt_avg(f, avg, ints), rest=_fmt_avg(f, ravg, ints), abstand=abst,
                 rest_n=_group(cnt - ntop), members=_group(cnt))
        out.append(fill(r.get("template", ""), None, e))
    if table:
        out += _tlines([table_col_label(k, r, x=_group(x)) for k in tcols], trows)
    return out


def ev_classbest(r, players, ctx, cache):
    """Beste je Klasse: die besten N Spieler jeder Klasse im gewaehlten Feld."""
    f = r.get("field") or "level"
    tb = r.get("tiebreak") or None
    try:
        n = max(1, int(r.get("n", 1) or 1))
    except (TypeError, ValueError):
        n = 1
    if not any(p.get("klasse") for p in players):
        raise ValueError("Keine Klassen-Daten vorhanden (nur in den JSON-Rohdaten)")
    by = {}
    for p in players:
        if p.get("klasse") and p.get(f) is not None:
            by.setdefault((p.get("_cls") or 0, p["klasse"]), []).append(p)
    if not by:
        raise ValueError("Keine Spieler mit Wert für '%s'" % label_of(f))
    label = r.get("label") or label_of(f)
    out = []
    if r.get("title"):
        e0 = dict(ctx)
        e0.update(n=n, label=label)
        out.append(fill(r["title"], None, e0))
    table = _table_on(r)
    tcols = table_cols(r) if table else []
    trows = []
    cls_all = {}
    if table:                                           # alle Spieler je Klasse (fuer "bester Wert der Klasse" in jeder Spalte)
        for p in players:
            if p.get("klasse"):
                cls_all.setdefault(p["klasse"], []).append(p)
    for (cid, kl), ps in sorted(by.items()):
        ps.sort(key=lambda p: (-p[f], -(p.get(tb) or 0) if tb else 0, str(p.get("name") or "").lower()))
        c = CLASSES.get(cid)
        for i, p in enumerate(ps[:n], 1):
            if table:
                ex = {"_n": "[silber]%d[/]" % (len(trows) + 1), "klasse": "[grün]**%s**[/]" % _tcl(kl) if i == 1 else "",
                      "mult": fmt_num(c[1]) if c else "", "letter": c[2] if c else ""}
                ex.update(_cls_best_cells(tcols, p, f, cls_all.get(kl, ps)))
                trows.append(_trow(tcols, p, f, ex))
                continue
            e = dict(ctx)
            e.update(klasse=kl, label=label, value=fmt_value(f, p), rank=i, n=n,
                     mult=fmt_num(c[1]) if c else "", letter=c[2] if c else "")
            out.append(fill(r.get("template", ""), p, e))
    if table:
        out += _tlines([table_col_label(k, r) for k in tcols], trows)
    return out


