def set_server_starts(servers):
    """Startdaten der Server (aus der Kompensations-Serverliste) und der Fusionswelten fuer {sstart}."""
    _SERVER_STARTS.clear()
    for k, d in FUSION_STARTS.items():
        _SERVER_STARTS[k] = parse_day(d)
    for sv in servers or []:
        day = parse_day(sv.get("start"))
        if day is not None:
            _SERVER_STARTS[str(sv.get("key") or komp_key_of(sv.get("name"))).lower()] = day


def sstart_text(srv):
    """{sstart}: Serverstart mit Tagen bis heute (Starttag und heute zaehlen mit), z.B. "07.07.2023 (1.189 Tage)" - leer, wenn unbekannt."""
    if not _SERVER_STARTS:
        set_server_starts(default_komp_servers())
    day = _SERVER_STARTS.get(str(srv or "").lower())
    if day is None:
        return ""
    n = (datetime.date.today() - day).days + 1               # Starttag und heute zaehlen beide mit
    if n <= 0:
        return "%s (in %s %s)" % (day.strftime("%d.%m.%Y"), _group(1 - n), "Tag" if n == 0 else "Tagen")
    return "%s (%s %s)" % (day.strftime("%d.%m.%Y"), _group(n), "Tag" if n == 1 else "Tage")


def short_label(k):
    """Kurzer Name eines Feldes fuer Listen (ohne "(Gilde gesamt)" / "(je Spieler)")."""
    return label_of(k).replace(" (Gilde gesamt)", "").replace(" (je Spieler)", "").replace("ø", "Ø")


def _srv_groups(items):
    """[(Anzeige-Name, [Eintraege])] je Server, in Server-Reihenfolge."""
    by = {}
    for x in items:
        by.setdefault(x.get("_srv"), []).append(x)
    out = [(xs[0].get("_srv_disp") or xs[0].get("g_server") or str(k), xs) for k, xs in by.items()]
    out.sort(key=lambda t: srv_sort_key(str(t[0])))
    return out


TABLE_TYPES = ("threshold", "top", "flagcount", "classpotions", "guildavg", "classbest", "classsrv", "srvbest")
# je Art: (besondere Spalten, Zahlenwerte der Spieler/Gilden waehlbar?, Vorgabe)
_TSPEC = {
    "threshold": ([("_thr", "Schwelle"), ("count", "Anzahl"), ("_pct", "Anteil (%)"), ("names", "Namen (bis zu X, siehe „Namen bis zu“)")],
                  False, ["_thr", "count", "names"]),
    "flagcount": ([("label", "Bezeichnung"), ("count", "Anzahl"), ("total", "von (gesamt)"), ("_pct", "Anteil (%)")],
                  False, ["label", "count", "_pct"]),
    "top": ([("_n", "# (Nummerierung 1, 2, 3 …)"), ("name", "Name"), ("server", "Server"), ("guild", "Gilde (nur Spieler)"),
             ("_value", "Gewählter Wert (Feld oben)")], True, ["_n", "name", "server", "guild", "_value"]),
    "classpotions": ([("klasse", "Klasse"), ("count", "Anzahl in den Top X"), ("_pct", "Anteil (%)"), ("full", "mit allen Tränken"),
                      ("full_pct", "Anteil mit allen Tränken (%)"), ("names", "Namen (bis zu 5)"), ("mult", "Faktor"),
                      ("letter", "Kürzel")], False, ["klasse", "count", "_pct", "full", "full_pct"]),
    "guildavg": ([("_n", "# (Platz)"), ("guild", "Gilde"), ("server", "Server"), ("avg", "Ø der Top X"), ("rest", "Ø der übrigen"),
                  ("abstand", "Abstand"), ("members", "Mitglieder"), ("rest_n", "Anzahl übrige")], False,
                 ["_n", "guild", "server", "avg", "rest", "abstand"]),
    "classbest": ([("_n", "# (Nummerierung 1, 2, 3 …)"), ("klasse", "Klasse"), ("name", "Spieler"), ("server", "Server"),
                   ("guild", "Gilde"), ("_value", "Gewählter Wert (Feld oben)"), ("mult", "Faktor"), ("letter", "Kürzel")], True,
                  ["_n", "klasse", "name", "server", "_value"]),
    "srvbest": ([("_n", "# (Nummerierung 1, 2, 3 …)"), ("label", "Wertung"), ("_rank", "Platz"), ("name", "Gilde"),
                 ("server", "Server"), ("_value", "Wert")], True, ["label", "name", "_value"]),
}
_TCOL_NAMES = {"_n": "#", "klasse": "Klasse", "server": "Server", "guild": "Gilde", "_count": "Anzahl", "count": "Anzahl",
               "_pct": "Anteil", "full": "alle Tränke", "full_pct": "Anteil alle Tränke", "names": "Namen", "mult": "Faktor",
               "letter": "Kürzel", "rest": "Ø übrige", "abstand": "Abstand", "members": "Mitglieder", "rest_n": "übrige",
               "label": "Wertung", "_rank": "Platz", "total": "von"}


def _is_g(items):
    """Liste aus Gilden (Gilden-Bestenliste)?"""
    return bool(items) and isinstance(items[0], dict) and "g_name" in items[0]


def table_col_opts(t, guild, fields=()):
    """Waehlbare Spalten einer Art (fuer "Spalten wählen …")."""
    if t == "classsrv":
        spec, recs = list(CLASSSRV_COLS), True
    else:
        spec, recs, _d = _TSPEC[t]
        spec = [(k, l) for k, l in spec if not (guild and k == "guild" and t == "top")]
    if recs:
        spec = spec + [(k, short_label(k)) for k in fields if k in FIELD_MAP]
    return spec


def table_default(r, guild=False):
    t = r.get("type")
    if t == "classsrv":
        f = r.get("field") or "level"
        return ["_n", "klasse", "name", "_value", "level" if f != "level" else "base_sum"]
    d = list(_TSPEC[t][2])
    if t == "srvbest" and r.get("one_table"):
        return ["_n", "name", "server", "_value"]
    if t == "top" and guild:
        d.remove("guild")
    if t == "srvbest" and int(r.get("n", 1) or 1) > 1:
        d.insert(1, "_rank")
    return d


def table_cols(r, guild=False):
    """Gewaehlte Spalten der Tabelle eines Eintrags (sonst die Vorgabe der Art)."""
    t = r.get("type")
    if t == "classsrv":
        return classsrv_cols(r)
    spec, recs, _d = _TSPEC[t]
    keys = dict(spec)
    cols = [k for k in (r.get("tcols") or []) if k in keys or (recs and k in FIELD_MAP)]
    return cols or table_default(r, guild)


def table_col_label(k, r, guild=False, x=None):
    t = r.get("type")
    f = r.get("field") or "level"
    lab = r.get("label") or label_of(f)
    if k in ("_value", "_thr"):
        return "Wert" if t == "srvbest" else lab
    if k == "name":
        return "Gilde" if (guild or t == "srvbest") else "Spieler"
    if k == "count":
        if t == "threshold":
            return "Gilden" if guild else "Spieler"
        if t == "classpotions":
            return "in Top %s" % (x or "X")
        return "Anzahl"
    if k == "avg":
        return "Ø Top %s" % (x or r.get("x", 10))
    if k == "label" and t == "flagcount":
        return "Eigenschaft"
    if k in _TCOL_NAMES:
        return _TCOL_NAMES[k]
    return short_label(k) if k in FIELD_MAP else k


def _tcl(t):
    return str(t).replace("|", "¦")


_SCAN_CTX = {"scan1": "", "scan2": ""}                      # Datum Scan / Vergleichs-Scan der gerade erstellten Liste


def _tcell(k, p, f):
    """Zelle fuer einen Spieler / eine Gilde (mit Bild-Farben; im Discord-Text werden die Marken entfernt)."""
    if k in ("scan1", "scan2") and p.get(k) is None:          # 1st / 2nd Scan: Datum des Scans bzw. des Vergleichs-Scans
        return _tcl(_SCAN_CTX.get(k) or "")
    if k.startswith("gm_") and p.get(k) is not None and p.get(k + "_n"):    # Bester Spieler der Gilde: "Name – Wert"
        return "%s – [gelb]**%s**[/]" % (_tcl(p.get(k + "_n")), fmt_value(k, p))
    if k == "name":
        return "**%s**" % _tcl(p.get("name") or p.get("g_name") or "")
    if k == "server":
        return _tcl(p.get("_srv_disp") or p.get("g_server") or "")
    if k == "guild":
        return _tcl(p.get("guild") or "–")
    if k == "_value":
        return "[blau]**%s**[/]" % fmt_value(f, p)
    if k in FIELD_MAP:
        return "[gelb]**%s**[/]" % fmt_value(k, p)
    return ""


def _cls_best_cells(cols, p, f, grp):
    """Wert-Zellen: blau, wenn der Spieler in seiner Klasse (grp) den hoechsten Wert dieser Spalte hat, sonst gelb."""
    out = {}
    for k in cols:
        kk = f if k == "_value" else k
        if k != "_value" and (k not in FIELD_MAP or FIELD_MAP[k].kind not in NUMERIC_KINDS):
            continue
        v = p.get(kk)
        if v is None:
            out[k] = "–"
            continue
        mx = max((x.get(kk) for x in grp if x.get(kk) is not None), default=None)
        out[k] = "[%s]**%s**[/]" % ("blau" if mx is not None and v >= mx else "gelb", fmt_value(kk, p))
    return out


def _trow(cols, p, f, extra):
    return [extra[k] if k in extra else _tcell(k, p, f) for k in cols]


def _tlines(head, rows):
    """Tabelle als |-Zeilen (Kopf + Zeilen) und eine Leerzeile danach."""
    if not rows:
        return []
    return ["| " + " | ".join(head) + " |"] + ["| " + " | ".join(r) + " |" for r in rows] + [""]


def _table_on(r):
    return r.get("display") == "table" and r.get("type") in TABLE_TYPES


CLASSSRV_COLS = [("_n", "# (Nummerierung 1, 2, 3 …)"), ("klasse", "Klasse"), ("name", "Spieler"),
                 ("_value", "Gewählter Wert (Feld oben)"), ("_count", "Anzahl Spieler der Klasse"), ("guild", "Gilde"),
                 ("server", "Server")]


def classsrv_cols(r):
    """Spalten der Tabelle bei "Beste je Klasse je Server" (Vorgabe: #, Klasse, Spieler, Wert, Level bzw. Base Sum)."""
    f = r.get("field") or "level"
    cols = [k for k in (r.get("tcols") or []) if k in dict(CLASSSRV_COLS) or k in FIELD_MAP]
    return cols or ["_n", "klasse", "name", "_value", "level" if f != "level" else "base_sum"]


def classsrv_col_label(k, label):
    if k == "_value":
        return label
    return {"_n": "#", "klasse": "Klasse", "name": "Spieler", "_count": "Anzahl", "guild": "Gilde", "server": "Server"}.get(
        k, short_label(k) if k in FIELD_MAP else k)


def _classsrv_row(tcols, f, p, kl, cnt, disp, no, grp=None):
    """Eine Tabellen-Zeile (Zellen mit Bild-Farben; im Discord-Text werden die Marken entfernt).
    grp = Spieler der Klasse auf dem Server: bester Wert der Klasse = blau, sonst gelb."""
    def cl(t):
        return str(t).replace("|", "¦")
    best = _cls_best_cells(tcols, p, f, grp) if grp else {}
    out = []
    for k in tcols:
        if k in best:
            out.append(best[k])
            continue
        if k == "_n":
            out.append("[silber]%d[/]" % no)
        elif k == "klasse":
            out.append("[grün]**%s**[/]" % cl(kl) if kl else "")
        elif k == "name":
            out.append("**%s**" % cl(p.get("name") or ""))
        elif k == "_count":
            out.append(_group(cnt) if kl else "")
        elif k == "guild":
            out.append(cl(p.get("guild") or "–"))
        elif k == "server":
            out.append(cl(disp))
        elif k == "_value":
            out.append("[blau]**%s**[/]" % fmt_value(f, p))
        else:
            out.append("[gelb]**%s**[/]" % fmt_value(k, p))
    return out


BESTVAL_COLS = [("_n", "# (Nummerierung 1, 2, 3 …)"), ("name", "Name"), ("server", "Server (ohne Überschrift)"),
                ("guild", "Gilde (nur Spieler)")]


def bestval_cols(r, guild=False):
    keys = [k for k, _l in BESTVAL_COLS if not (guild and k == "guild")]
    cols = [k for k in (r.get("tcols") or []) if k in keys]
    return cols if r.get("tcols") is not None else [k for k in ("_n", "name", "server", "guild") if k in keys]


def ev_bestval(r, items, ctx, cache):
    """Bester Spieler / beste Gilde je Wert: je Wert-Spalte eine Zeile (in Spalten-Reihenfolge) mit dem Besten, der noch nicht
    in der Tabelle steht. Blau = bester Wert der Spalte ueberhaupt (ein Spieler kann mehrere haben), hellblau = der Wert,
    fuer den die Zeile steht, wenn der Beste dieser Spalte schon weiter oben steht. Gleichstand: mehr Base Sum zuerst."""
    guild = _is_g(items)
    dflt = BESTVAL_DEF_G if guild else BESTVAL_DEF
    fields = [k for k in (r.get("fields") or dflt) if k in FIELD_MAP and any(p.get(k) is not None for p in items)]
    if not fields:
        raise ValueError("Keine der gewählten Werte ist in den geladenen Daten vorhanden")
    tb = "gs_base_sum" if guild else "base_sum"
    nm = lambda p: str(p.get("name") or p.get("g_name") or "").lower()
    best, used, rows = {}, set(), []
    for f in fields:
        cand = sorted((p for p in items if p.get(f) is not None), key=lambda p: (-p[f], -(p.get(tb) or 0), nm(p)))
        if not cand:
            continue
        best[f] = id(cand[0])
        pick = next((p for p in cand if id(p) not in used), None)
        if pick is not None:
            used.add(id(pick))
            rows.append((pick, f))
    cols = bestval_cols(r, guild)
    head = [{"_n": "#", "name": "Gilde" if guild else "Spieler", "server": "", "guild": "Gilde"}[k] for k in cols] + \
           [short_label(f) for f in fields]
    trows = []
    icon_on = not guild and r.get("cls_icon", True) is not False
    for i, (p, own) in enumerate(rows, 1):
        cells = ["[silber]%d[/]" % i if k == "_n" else _tcell(k, p, own) for k in cols]
        if icon_on and "name" in cols and p.get("_cls"):
            cells[cols.index("name")] += " [icon:c%d]" % int(p["_cls"])
        for f in fields:
            v = fmt_value(f, p)
            if best.get(f) == id(p):
                cells.append("[blau]**%s**[/]" % v)
            elif f == own:
                cells.append("[hellblau]**%s**[/]" % v)
            else:
                cells.append("[gelb]**%s**[/]" % v)
        trows.append(cells)
    out = []
    if r.get("title"):
        e0 = dict(ctx)
        e0.update(n=len(rows))
        out.append(fill(r["title"], None, e0))
    return out + _tlines(head, trows)


def _one_sort_rows(rows, srt, f):
    """Alle Server in einer Tabelle: [(Server-Nr., Platz im Server, Datensatz)] - nach Server (Trennlinie) oder nach Wert."""
    if srt == "value":
        rows = sorted(rows, key=lambda t: (-(t[2].get(f) if t[2].get(f) is not None else -1e18), t[0], t[1]))
    return rows


def ev_classsrv(r, players, ctx, cache):
    """Beste je Klasse je Server: je Server die Spielerzahl, je Klasse die Anzahl und der/die Besten im gewaehlten Feld."""
    f = r.get("field") or "level"
    tb = r.get("tiebreak") or None
    try:
        n = max(1, int(r.get("n", 1) or 1))
    except (TypeError, ValueError):
        n = 1
    ps = [p for p in players if p.get("klasse")]
    if not ps:
        raise ValueError("Keine Klassen-Daten vorhanden (nur in den JSON-Rohdaten)")
    label = r.get("label") or label_of(f)
    out, tot = [], Counter()
    if r.get("title"):
        e0 = dict(ctx)
        e0.update(n=n, label=label)
        out.append(fill(r["title"], None, e0))
    srt = r.get("sort") or "count"
    one = bool(r.get("one_table"))                       # alle Server in einer Tabelle
    table = r.get("display") == "table" or one
    tcols = classsrv_cols(r)
    if one and "server" not in tcols:
        tcols = list(tcols)
        tcols.insert(1 if tcols and tcols[0] == "_n" else 0, "server")
    one_rows = []

    def _best(cl):
        vals = [p[f] for p in cl if p.get(f) is not None]
        return -max(vals) if vals else float("inf")
    for disp, lst in _srv_groups(ps):
        e1 = dict(ctx)
        gn = sorted({str(p.get("guild")) for p in lst if p.get("guild")}, key=str.lower) if ctx.get("_wo_g") else []
        e1.update(server=disp, wo=disp, count=_group(len(lst)), label=label, n=n, guild=", ".join(gn),
                  sstart=sstart_text(lst[0].get("_srv")))
        if r.get("template_srv") and not one:
            out.append(fill(r["template_srv"], None, e1))
        cls = {}
        for p in lst:
            cls.setdefault((p.get("_cls") or 0, p["klasse"]), []).append(p)
        if srt == "name":
            order = sorted(cls.items(), key=lambda kv: kv[0][1].lower())
        elif srt == "value":                                # nach Wert: Klasse mit dem besten Spieler zuerst
            order = sorted(cls.items(), key=lambda kv: (_best(kv[1]), -len(kv[1]), kv[0][1].lower()))
        else:
            order = sorted(cls.items(), key=lambda kv: (-len(kv[1]), kv[0][1].lower()))
        trows = []
        for (cid, kl), cl in order:
            tot[kl] += len(cl)
            cand = [p for p in cl if p.get(f) is not None]
            cand.sort(key=lambda p: (-p[f], -(p.get(tb) or 0) if tb else 0, str(p.get("name") or "").lower()))
            c = CLASSES.get(cid)
            for i, p in enumerate(cand[:n], 1):
                if one:
                    one_rows.append((len(one_rows), disp, p, kl if i == 1 else "", len(cl), cl, kl))
                    continue
                if table:
                    trows.append(_classsrv_row(tcols, f, p, kl if i == 1 else "", len(cl), disp, len(trows) + 1, cl))
                    continue
                e = dict(ctx)
                e.update(klasse=kl, count=_group(len(cl)), label=label, value=fmt_value(f, p), rank=i, n=n, server=disp,
                         mult=fmt_num(c[1]) if c else "", letter=c[2] if c else "")
                out.append(fill(r.get("template", ""), p, e))
        if table and trows:
            out.append("| " + " | ".join(classsrv_col_label(k, label) for k in tcols) + " |")
            out += ["| " + " | ".join(row) + " |" for row in trows]
            out.append("")
    if one and one_rows:                                  # eine Tabelle: nach Server (Trennlinie) oder nach Wert
        osrt = r.get("one_sort") or "server"
        if osrt == "value":
            one_rows.sort(key=lambda t: (-(t[2].get(f) if t[2].get(f) is not None else -1e18), t[0]))
        out.append("| " + " | ".join(classsrv_col_label(k, label) for k in tcols) + " |")
        prev, no = None, 0
        for _i, disp, p, kl, cnt, cl, kl0 in one_rows:
            no = no + 1 if (osrt == "value" or disp == prev) else 1
            row = _classsrv_row(tcols, f, p, kl if osrt != "value" else kl0, cnt, disp, no, cl)
            if osrt != "value" and prev is not None and disp != prev and row:
                row[0] = "[trenn]" + row[0]
            prev = disp
            out.append("| " + " | ".join(row) + " |")
        out.append("")
    if r.get("total", True) and r.get("template_total"):
        e = dict(ctx)
        e.update(klassen=" · ".join("%s %s" % (k, _group(v)) for k, v in sorted(tot.items(), key=lambda kv: (-kv[1], kv[0]))),
                 count=_group(sum(tot.values())), label=label)
        out.append(fill(r["template_total"], None, e))
    return out


def ev_srvbest(r, guilds, ctx, cache):
    """Beste Gilde je Server: je Server die Gildenzahl und je gewaehltem Wert die beste(n) Gilde(n)."""
    fields = [k for k in (r.get("fields") or []) if k in FIELD_MAP] or ["g_level_avg"]
    try:
        n = max(1, int(r.get("n", 1) or 1))
        mm = max(0, int(r.get("min_members") or 0))
    except (TypeError, ValueError):
        n, mm = 1, 0
    gs = [g for g in guilds if (g.get("g_members") or g.get("g_scanned") or 0) >= mm]
    if not gs:
        raise ValueError("Keine Gilden mit mindestens %d Mitgliedern" % mm)
    out = []
    if r.get("title"):
        e0 = dict(ctx)
        e0.update(n=n)
        out.append(fill(r["title"], None, e0))
    if r.get("one_table"):                                # alle Server in einer Tabelle (je Wert eine Tabelle)
        tcols = list(table_cols(r, True))
        if "server" not in tcols:
            tcols.insert(tcols.index("name") + 1 if "name" in tcols else len(tcols), "server")
        osrt = r.get("one_sort") or "server"
        groups = _srv_groups(gs)
        for f in fields:
            rows = []
            for si, (disp, lst) in enumerate(groups):
                cand = sorted((g for g in lst if g.get(f) is not None), key=lambda g: (-g[f], str(g.get("name") or "").lower()))
                rows += [(si, i, g) for i, g in enumerate(cand[:n], 1)]
            rows = _one_sort_rows(rows, osrt, f)
            trows, prev = [], None
            for k, (si, i, g) in enumerate(rows, 1):
                cells = _trow(tcols, g, f, {"_n": "[silber]%d[/]" % (k if osrt == "value" else i), "_rank": str(i),
                                            "label": "**%s**" % _tcl(short_label(f))})
                if osrt != "value" and prev is not None and si != prev and cells:
                    cells[0] = "[trenn]" + cells[0]
                prev = si
                trows.append(cells)
            if len(fields) > 1:
                out.append("**%s**" % short_label(f))
            out += _tlines([table_col_label(k, r, True) if k != "_value" else short_label(f) for k in tcols], trows)
        return out
    for disp, lst in _srv_groups(gs):
        e1 = dict(ctx)
        e1.update(server=disp, count=_group(len(lst)), n=n, sstart=sstart_text(lst[0].get("_srv")))
        if r.get("template_srv"):
            out.append(fill(r["template_srv"], None, e1))
        table = _table_on(r)
        tcols = table_cols(r, True) if table else []
        trows = []
        for f in fields:
            cand = [g for g in lst if g.get(f) is not None]
            cand.sort(key=lambda g: (-g[f], str(g.get("name") or "").lower()))
            for i, g in enumerate(cand[:n], 1):
                if table:
                    trows.append(_trow(tcols, g, f, {"label": "**%s**" % _tcl(short_label(f)) if i == 1 else "", "_rank": str(i)}))
                    continue
                e = dict(ctx)
                e.update(label=short_label(f), value=fmt_value(f, g), rank=i, n=n, name=g.get("name") or g.get("g_name") or "",
                         server=disp)
                out.append(fill(r.get("template", ""), g, e))
        if table:
            out += _tlines([table_col_label(k, r, True) for k in tcols], trows)
    return out


EVALUATORS = {"text": ev_text, "threshold": ev_threshold, "top": ev_top, "flagcount": ev_flagcount,
              "classpotions": ev_classpotions, "guildavg": ev_guildavg, "classbest": ev_classbest,
              "classsrv": ev_classsrv, "srvbest": ev_srvbest, "bestval": ev_bestval}


def eval_rules(rules, players, ctx):
    lines, errors, cache = [], [], {}
    _SCAN_CTX.update(scan1=str((ctx or {}).get("scan1") or ""), scan2=str((ctx or {}).get("scan2") or ""))
    for i, r in enumerate(rules):
        if not r.get("enabled", True):
            continue
        try:
            out = EVALUATORS[r["type"]](r, players, ctx, cache)
        except Exception as e:
            errors.append((i, str(e)))
            out = []
        lines.extend(out)
        lines.extend([""] * int(r.get("blank_after", 0) or 0))
    while lines and lines[-1] == "":
        lines.pop()
    return lines, errors


def make_ctx(players, extra=None):
    ctx = {"players": _group(len(players)),
           "servers": _group(len({p["_srv"] for p in players})),
           "guilds": _group(len({(p["_srv"], p["guild"]) for p in players if p["guild"]})),
           "date": datetime.date.today().strftime("%d.%m.%Y")}
    wo_ctx(ctx, players)
    if extra:
        ctx.update(extra)
    return ctx


def make_guild_ctx(guilds):
    members = sum(int(g["g_members"]) for g in guilds if g.get("g_members"))
    ctx = make_ctx(guilds)
    ctx.update(players=_group(members), members=_group(members), guilds=_group(len(guilds)),
               _info="%s Gilden" % _group(len(guilds)))
    wo_ctx(ctx, guilds, False, "guild")
    return ctx


