GRID_COLOR = "#4b4e58"                    # feine Trennlinien zwischen den Tabellenspalten (heller als beide Zeilenfarben)
PNG_MAX_BYTES = 50 * 1024 * 1024          # groesser darf eine Bilddatei nicht werden - sonst wird die Liste auf mehrere Bilder verteilt
PNG_MAX_PIXELS = 60 * 1000 * 1000         # Speicherbremse je Bild
PNG_MAX_HEIGHT = 30000


def _png_font_paths():
    win = os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts")
    reg = [os.path.join(win, n) for n in ("segoeui.ttf", "arial.ttf", "calibri.ttf")] + [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", "/usr/share/fonts/TTF/DejaVuSans.ttf",
        "/System/Library/Fonts/Supplemental/Arial.ttf", "/Library/Fonts/Arial.ttf"]
    bold = [os.path.join(win, n) for n in ("segoeuib.ttf", "arialbd.ttf", "calibrib.ttf")] + [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", "/usr/share/fonts/TTF/DejaVuSans-Bold.ttf",
        "/System/Library/Fonts/Supplemental/Arial Bold.ttf", "/Library/Fonts/Arial Bold.ttf"]
    return reg, bold


def _png_font_paths_it():
    win = os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts")
    it = [os.path.join(win, n) for n in ("segoeuii.ttf", "ariali.ttf", "calibrii.ttf")] + [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Oblique.ttf", "/usr/share/fonts/TTF/DejaVuSans-Oblique.ttf",
        "/System/Library/Fonts/Supplemental/Arial Italic.ttf", "/Library/Fonts/Arial Italic.ttf"]
    bit = [os.path.join(win, n) for n in ("segoeuiz.ttf", "arialbi.ttf", "calibriz.ttf")] + [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-BoldOblique.ttf", "/usr/share/fonts/TTF/DejaVuSans-BoldOblique.ttf",
        "/System/Library/Fonts/Supplemental/Arial Bold Italic.ttf", "/Library/Fonts/Arial Bold Italic.ttf"]
    return it, bit


def png_fonts(ImageFont, size):
    """(normal, fett) als Pillow-Schriften - Segoe UI wie im Programm, sonst Arial / DejaVu."""
    reg_p, bold_p = _png_font_paths()

    def first(paths):
        for p in paths:
            try:
                return ImageFont.truetype(p, size)
            except Exception:
                continue
        return None
    reg, bold = first(reg_p), first(bold_p)
    if reg is None:
        try:
            reg = ImageFont.load_default(size)
        except TypeError:
            reg = ImageFont.load_default()
    return reg, (bold or reg)


# ---- Besucher-Statistik der Online-Liste (GoatCounter: kostenlos, ohne Cookies, keine Namen oder IP-Adressen der Besucher)
GC_BASE = "https://%s.goatcounter.com"          # %s = Konto-Name (z. B. nachbar -> https://nachbar.goatcounter.com)


def gc_account(v):
    """Konto-Name pruefen: "nachbar", auch aus "https://nachbar.goatcounter.com" - sonst ""."""
    v = str(v or "").strip().lower()
    m = re.match(r"^(?:https?://)?([a-z0-9][a-z0-9-]{0,49})(?:\.goatcounter\.com)?/?$", v)
    return m.group(1) if m else ""


def gc_api(account, key, path, params, timeout=20):
    """GET /api/v0/<path> mit dem geheimen Schluessel (Bearer). Fehler -> RuntimeError mit verstaendlichem Text."""
    import urllib.request
    import urllib.parse
    import urllib.error
    url = (GC_BASE % account) + "/api/v0/" + path + "?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers={"Authorization": "Bearer " + str(key).strip(),
                                               "Content-Type": "application/json", "User-Agent": APP_NAME})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as ex:
        msg = {401: "Schlüssel falsch oder abgelaufen (401).", 403: "Der Schlüssel darf die Statistik nicht lesen (403) – "
               "beim Schlüssel „Read statistics“ anhaken.", 404: "Konto „%s“ nicht gefunden (404) – Konto-Name prüfen." % account,
               429: "Zu viele Anfragen (429) – einen Moment warten."}.get(ex.code, "Fehler %s vom Server." % ex.code)
        raise RuntimeError(msg)
    except urllib.error.URLError as ex:
        raise RuntimeError("Keine Verbindung zu %s (%s)." % ((GC_BASE % account).split("//")[-1], getattr(ex, "reason", ex)))
    except ValueError:
        raise RuntimeError("Unerwartete Antwort vom Server.")


def gc_range(days, now=None):
    """(start, end) als UTC-Zeitpunkte auf volle Stunden: heute (days=1) oder die letzten X Tage ab Mitternacht (Ortszeit)."""
    now = (now or datetime.datetime.now()).astimezone()
    start = (now.replace(hour=0, minute=0, second=0, microsecond=0) - datetime.timedelta(days=max(1, days) - 1))
    end = now.replace(minute=0, second=0, microsecond=0) + datetime.timedelta(hours=1)
    f = lambda t: t.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:00:00Z")
    return f(start), f(end)


def gc_fetch(account, key, days, pause=0.3):
    """Alle Zahlen fuer den Reiter "Besucher": Summe, Seiten/Links und Klicks (Ereignisse) samt Stunden und Tagen."""
    start, end = gc_range(days)
    tot = gc_api(account, key, "stats/total", {"start": start, "end": end})
    hits, ids = [], []
    for _page in range(6):                                  # je Abruf hoechstens 100 Pfade
        time.sleep(pause)
        p = {"start": start, "end": end, "limit": 100}
        if ids:
            p["exclude_paths"] = ",".join(str(i) for i in ids)
        res = gc_api(account, key, "stats/hits", p)
        got = res.get("hits") or []
        hits.extend(got)
        ids.extend(h.get("path_id") for h in got if h.get("path_id") is not None)
        if not res.get("more") or not got:
            break
    return summarize_gc(tot, hits, days)


def summarize_gc(tot, hits, days):
    hourly, daily = [0] * 24, {}
    pages, events = [], []
    for h in hits:
        cnt = int(h.get("count") or 0)
        (events if h.get("event") else pages).append((str(h.get("path") or ""), cnt))
        if h.get("event"):
            continue
        for st in h.get("stats") or []:
            day = str(st.get("day") or "")[:10]
            daily[day] = daily.get(day, 0) + int(st.get("daily") or 0)
            for i, v in enumerate((st.get("hourly") or [])[:24]):
                hourly[i] += int(v or 0)
    total = int(tot.get("total") or 0)
    ev = int(tot.get("total_events") or 0)
    today = datetime.date.today().strftime("%Y-%m-%d")
    peak = max(range(24), key=lambda i: hourly[i]) if any(hourly) else None
    return {"visitors": max(0, total - ev), "events": ev, "today": daily.get(today, 0), "peak": peak,
            "hourly": hourly, "daily": daily, "days": days,
            "pages": sorted(pages, key=lambda x: (-x[1], x[0])), "events_list": sorted(events, key=lambda x: (-x[1], x[0]))}


def load_pillow(parent=None):
    """(Image, ImageDraw, ImageFont) von Pillow; fehlt das Paket, wird angeboten, es mit pip zu installieren."""
    def imp():
        from PIL import Image, ImageDraw, ImageFont
        return Image, ImageDraw, ImageFont
    try:
        return imp()
    except ImportError:
        pass
    if parent is None:
        return None
    if not messagebox.askyesno(APP_NAME, "Für den Bild-Export wird das kostenlose Python-Paket „Pillow“ benötigt.\n\n"
                               "Jetzt automatisch installieren? (pip install pillow – dauert ca. 10–30 Sekunden, Internet nötig)",
                               parent=parent):
        return None
    err = ""
    try:
        parent.config(cursor="watch")
        parent.update_idletasks()
        flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        for extra in ([], ["--user"]):
            r = subprocess.run([sys.executable, "-m", "pip", "install", "pillow"] + extra, capture_output=True, text=True,
                               timeout=900, creationflags=flags)
            if r.returncode == 0:
                err = ""
                break
            err = (r.stderr or r.stdout or "").strip()[-600:]
    except Exception as ex:
        err = str(ex)
    finally:
        parent.config(cursor="")
    if not err:
        try:
            import importlib
            importlib.invalidate_caches()
            import site
            try:
                if site.getusersitepackages() not in sys.path:
                    sys.path.append(site.getusersitepackages())
            except Exception:
                pass
            return imp()
        except ImportError:
            err = "Pillow wurde installiert, ist aber erst nach einem Neustart des Programms verfügbar."
    messagebox.showerror(APP_NAME, "Pillow konnte nicht installiert werden.\n\n%s\n\nManuell: in der Eingabeaufforderung "
                         "\"pip install pillow\" ausführen und das Programm neu starten." % err, parent=parent)
    return None


def _hex(c):
    return tuple(int(c[i:i + 2], 16) for i in (1, 3, 5))


PNG_ICON_SIZE = 22           # Kantenlaenge der Klassen-/Reittier-Symbole im Bild (Zeilenhoehe 26 bei Schriftgroesse 15)


def render_table_png(pil, path, title, sub, head, align, data, bold_i=None, tint_i=None, sort_i=None, sort_desc=True,
                     medals=(), progress=None, max_bytes=PNG_MAX_BYTES, size=15, icons=None, icon_i=None, lead_icons=None):
    """Tabelle als PNG. data = [(Zellen, Medaille|None)] (Medaille = Index in medals = [(Vordergrund, Hintergrund)]).
    Wird eine Datei groesser als max_bytes (oder zu gross fuer den Speicher), verteilt sich die Liste auf mehrere nummerierte
    Bilder (Name_1.png, Name_2.png ...). Rueckgabe: Liste der geschriebenen Dateien; None bei Abbruch."""
    Image, ImageDraw, ImageFont = pil
    f, fb = png_fonts(ImageFont, size)
    ftb = png_fonts(ImageFont, size + 4)[1]
    BG, ALT, HEAD = _hex(C["panel"]), _hex("#33353b"), _hex(C["panel2"])
    FG, DIM, ACC = _hex(C["fg"]), _hex(C["dim"]), _hex(C["accent"])
    GRID = _hex(GRID_COLOR)
    tint = lambda base: tuple(int(round(a + (b - a) * 0.11)) for a, b in zip(base, ACC))
    PAD, M = 10, 14
    nrow = len(data)
    bb = f.getbbox("Ag")
    text_h, text_top = bb[3] - bb[1], bb[1]
    row_h, head_h, top_h = size + 11, size + 17, 2 * size + 30
    # Spaltenbreiten aus dem Inhalt (mit Obergrenze)
    widths = []
    for j, h in enumerate(head):
        fj = fb if j == bold_i else f
        cells = {r[0][j] for r in data}
        w = max([fb.getlength(h) + 26] + [fj.getlength(c) for c in cells]) if cells else fb.getlength(h) + 26
        widths.append(int(math.ceil(min(max(w + 2 * PAD + 2, 52), 460 if j else 80))))
    icon_room = 0
    if (icons or lead_icons) and icon_i is not None and icon_i < len(widths):
        n_ic = max((len(x) for x in (icons or []) if x), default=0)
        n_ld = max((len(x) for x in (lead_icons or []) if x), default=0)
        if n_ic or n_ld:
            icon_room = (n_ic + n_ld) * (PNG_ICON_SIZE + 3) + 4
            widths[icon_i] += icon_room
    offs = [0]
    for w in widths:
        offs.append(offs[-1] + w)
    TW = offs[-1]
    W = TW + 2 * M
    max_h = max(2000, min(PNG_MAX_HEIGHT, int(PNG_MAX_PIXELS / max(W, 1))))
    per = max(1, (max_h - top_h - head_h - 24) // row_h)
    parts = max(1, -(-nrow // per))
    step = -(-max(nrow, 1) // parts)
    queue = [(a, min(nrow, a + step)) for a in range(0, max(nrow, 1), step)]

    def clip(t, w, font):
        if font.getlength(t) <= w:
            return t
        while len(t) > 1 and font.getlength(t + "…") > w:
            t = t[:-1]
        return t + "…"

    def render(a, b, tmp):
        n = b - a
        H = top_h + head_h + n * row_h + 12
        img = Image.new("RGB", (W, H), BG)
        d = ImageDraw.Draw(img)
        d.text((M, 8), title, font=ftb, fill=FG)
        d.text((M, 8 + size + 10), "%s  ·  Zeilen %s–%s von %s" % (sub, _group(a + 1), _group(b), _group(nrow)) if sub else
               "Zeilen %s–%s von %s" % (_group(a + 1), _group(b), _group(nrow)), font=f, fill=DIM)
        y0 = top_h
        d.rectangle([M, y0, M + TW - 1, y0 + head_h - 1], fill=HEAD)
        ty = lambda y, h: y + (h - text_h) // 2 - text_top
        for j, h in enumerate(head):
            x, w = M + offs[j], widths[j]
            col = FG
            room = w - 2 * PAD - (14 if j == sort_i else 0)
            h = clip(h, room, fb)
            tw = fb.getlength(h)
            a_ = align[j]
            tx = x + PAD if a_ == "w" else (x + w - PAD - tw - (14 if j == sort_i else 0) if a_ == "e" else x + (w - tw) / 2 - (7 if j == sort_i else 0))
            d.text((tx, ty(y0, head_h)), h, font=fb, fill=col)
            if j == sort_i:
                cx, cy = tx + tw + 9, y0 + head_h / 2
                tri = [(cx - 4, cy - 2), (cx + 4, cy - 2), (cx, cy + 3)] if sort_desc else [(cx - 4, cy + 2), (cx + 4, cy + 2), (cx, cy - 3)]
                d.polygon(tri, fill=ACC)
        ybase = y0 + head_h
        for i in range(a, b):
            cells, md = data[i]
            y = ybase + (i - a) * row_h
            fg, base = FG, (ALT if i % 2 else BG)
            if md is not None and 0 <= md < len(medals):
                fg, base = _hex(medals[md][0]), _hex(medals[md][1])
            if base != BG:
                d.rectangle([M, y, M + TW - 1, y + row_h - 1], fill=base)
            if tint_i is not None:
                d.rectangle([M + offs[tint_i], y, M + offs[tint_i + 1] - 1, y + row_h - 1], fill=tint(base))
            if icon_room and icons and icons[i]:
                xr = M + offs[icon_i] + widths[icon_i] - PAD
                for ic in reversed(icons[i]):
                    xr -= ic.width
                    img.paste(ic, (int(xr), int(y + (row_h - ic.height) / 2)), ic)
                    xr -= 3
            for j, t in enumerate(cells):
                if not t:
                    continue
                x, w = M + offs[j], widths[j]
                if j == icon_i and icon_room:
                    w -= icon_room
                fj = fb if j == bold_i else f
                t = clip(t, w - 2 * PAD, fj)
                a_ = align[j]
                tw = fj.getlength(t)
                tx = x + PAD if a_ == "w" else (x + w - PAD - tw if a_ == "e" else x + (w - tw) / 2)
                d.text((tx, ty(y, row_h)), t, font=fj, fill=fg)
                if j == icon_i and icon_room and lead_icons and lead_icons[i]:      # CC direkt hinter dem Namen
                    xl = tx + tw + 5
                    for ic in lead_icons[i]:
                        img.paste(ic, (int(xl), int(y + (row_h - ic.height) / 2)), ic)
                        xl += ic.width + 3
            if progress and (i - a) % 250 == 0:
                if progress(i, nrow) is False:
                    return False
        yend = ybase + n * row_h
        for j in range(len(widths) + 1):
            x = M + offs[j] - (1 if j == len(widths) else 0)
            d.line([(x, y0), (x, yend)], fill=GRID)
        d.line([(M, y0), (M + TW - 1, y0)], fill=GRID)
        d.line([(M, yend), (M + TW - 1, yend)], fill=GRID)
        img.save(tmp, "PNG", compress_level=6)
        img.close()
        return True

    done, tmps = [], []
    try:
        while queue:
            a, b = queue.pop(0)
            tmp = "%s.teil%d.tmp" % (path, len(tmps))
            ok = render(a, b, tmp)
            if ok is False:
                raise KeyboardInterrupt
            tmps.append(tmp)
            if os.path.getsize(tmp) > max_bytes and b - a > 1:          # zu gross: Bereich halbieren
                os.remove(tmp)
                tmps.pop()
                mid = (a + b) // 2
                queue[0:0] = [(a, mid), (mid, b)]
                continue
            done.append((a, b, tmp))
            if progress and progress(b, nrow) is False:
                raise KeyboardInterrupt
    except KeyboardInterrupt:
        for t in tmps:
            try:
                os.remove(t)
            except OSError:
                pass
        return None
    stem, ext = os.path.splitext(path)
    ext = ext or ".png"
    out = []
    if len(done) == 1:
        os.replace(done[0][2], stem + ext)
        out.append(stem + ext)
    else:
        pad = len(str(len(done)))
        for k, (_a, _b, tmp) in enumerate(done, 1):
            fn = "%s_%0*d%s" % (stem, pad, k, ext)
            os.replace(tmp, fn)
            out.append(fn)
    return out


_EMOJI_RE = re.compile("([\U0001F000-\U0001FAFF\u2600-\u27BF\u2B00-\u2BFF\u2300-\u23FF\uFE0F\u200D]+)")


class _TextPainter:
    """Misst und zeichnet Text mit Pillow; Emoji und Sonderzeichen (falls vorhanden) mit Segoe UI Emoji."""

    def __init__(self, ImageFont):
        self.IF, self._f, self._e = ImageFont, {}, {}

    def font(self, size, bold):
        if (size, bold) not in self._f:
            reg, bld = png_fonts(self.IF, size)
            self._f[(size, False)], self._f[(size, True)] = reg, bld
        return self._f[(size, bold)]

    def emoji_font(self, size):
        if size not in self._e:
            try:
                self._e[size] = self.IF.truetype(os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts", "seguiemj.ttf"), size)
            except Exception:
                self._e[size] = None
        return self._e[size]

    @staticmethod
    def pieces(text):
        return [(t, i % 2 == 1) for i, t in enumerate(_EMOJI_RE.split(text)) if t]

    def width(self, text, size, bold):
        w = 0.0
        for t, emo in self.pieces(text):
            f = (self.emoji_font(size) if emo else None) or self.font(size, bold)
            w += f.getlength(t)
        return w

    def mono(self, size):
        key = ("mono", size)
        if key not in self._f:
            f = None
            wd = os.environ.get("WINDIR", r"C:\Windows")
            for p in (os.path.join(wd, "Fonts", "consola.ttf"), os.path.join(wd, "Fonts", "cour.ttf"),
                      "/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf", "DejaVuSansMono.ttf", "Menlo.ttc"):
                try:
                    f = self.IF.truetype(p, size)
                    break
                except Exception:
                    continue
            self._f[key] = f or self.font(size, False)
        return self._f[key]

    def ifont(self, size, bold):
        """Kursive Schrift (fett oder normal); fehlt sie, die normale."""
        key = ("it", size, bold)
        if key not in self._f:
            f = None
            for p in _png_font_paths_it()[1 if bold else 0]:
                try:
                    f = self.IF.truetype(p, size)
                    break
                except Exception:
                    continue
            self._f[key] = f or self.font(size, bold)
        return self._f[key]

    def sfont(self, size, st):
        """Schrift zu einem Stil (fett, kursiv, unterstrichen, hervorgehoben, durchgestrichen, Farbe)."""
        if st[3]:
            return self.mono(max(8, int(size * 0.9)))
        if st[1]:
            return self.ifont(size, st[0])
        return self.font(size, st[0])

    def swidth(self, text, size, st):
        w = 0.0
        for t, emo in self.pieces(text):
            f = (self.emoji_font(size) if emo else None) or self.sfont(size, st)
            w += f.getlength(t)
        return w

    def sdraw(self, d, x, base, text, size, st, fill):
        for t, emo in self.pieces(text):
            ef = self.emoji_font(size) if emo else None
            f = ef or self.sfont(size, st)
            kw = {"embedded_color": True} if ef else {}
            try:
                d.text((x, base), t, font=f, fill=fill, anchor="ls", **kw)
            except Exception:
                try:
                    d.text((x, base - size), t, font=f, fill=fill)
                except Exception:
                    pass
            x += f.getlength(t)

    def draw(self, d, x, base, text, size, bold, fill):
        for t, emo in self.pieces(text):
            ef = self.emoji_font(size) if emo else None
            f = ef or self.font(size, bold)
            kw = {"embedded_color": True} if ef else {}
            try:
                d.text((x, base), t, font=f, fill=fill, anchor="ls", **kw)
            except Exception:
                try:
                    d.text((x, base - size), t, font=f, fill=fill)
                except Exception:
                    pass
            x += f.getlength(t)


_ST0 = (False, False, False, False, False, None)        # fett, kursiv, unterstrichen, hervorgehoben, durchgestrichen, Farbe
_INL = (("code", re.compile(r"`([^`]+)`")),
        ("b", re.compile(r"\*\*(.+?)\*\*")),
        ("u", re.compile(r"__(.+?)__")),
        ("s", re.compile(r"~~(.+?)~~")),
        ("i", re.compile(r"\*(?![\s*])((?:\*\*.+?\*\*|[^*])+?)(?<!\s)\*")),
        ("i", re.compile(r"(?<![\w_])_(?![\s_])(.+?)(?<![\s_])_(?![\w_])")),
        ("c", re.compile(r"\[(%s)\](.*?)(?:\[/\]|$)" % _COLTAG, re.I)))


def _inline_runs(s, st, out):
    """Discord-Formatierung + Farb-Marken einer Zeile in Stuecke [(Text, Stil)] zerlegen (verschachtelt moeglich)."""
    pos, ln = 0, len(s)
    while pos < ln:
        best = None
        for kind, rx in _INL:
            m = rx.search(s, pos)
            if m and (best is None or m.start() < best[1].start()):
                best = (kind, m)
        if best is None:
            break
        kind, m = best
        if m.start() > pos:
            _emit_run(s[pos:m.start()], st, out)
        b, i, u, c, k, col = st
        if kind == "code":
            _emit_run(m.group(1), (b, i, u, True, k, col), out)
        elif kind == "c":
            _inline_runs(m.group(2), (b, i, u, c, k, img_color(m.group(1)) or col), out)
        else:
            nst = (b or kind == "b", i or kind == "i", u or kind == "u", c, k or kind == "s", col)
            _inline_runs(m.group(1), nst, out)
        pos = m.end()
    if pos < ln:
        _emit_run(s[pos:], st, out)
    return out


def _emit_run(t, st, out):
    t = t.replace("[/]", "")
    if t:
        out.append((t, st))


def _lead_ws(line):
    """Einrueckung am Zeilenanfang aus Alt 0160 / Tab: (Anzahl Leerzeichen-Breiten, Rest der Zeile).
    Normale Leerzeichen allein zaehlen nicht (wie bisher)."""
    m = re.match("[\u00a0\t ]*", line)
    pre = m.group(0)
    if "\u00a0" not in pre and "\t" not in pre:
        return 0, line
    return len(pre.replace("\t", "    ")), line[len(pre):]


def render_text_png(pil, path, text, size=16, max_bytes=PNG_MAX_BYTES, max_h=None, text_max=1000, images=None):
    """Discord-Text (Ueberschriften #, -#, **fett**, *kursiv*, __unterstrichen__, `hervorgehoben`, Listenpunkte) als PNG -
    dazu Farben [gold]…[/] und Ueberschriften-Marken [rahmen] [rahmen=farbe] [farbe] [nichtfett].
    Zu hohe oder zu grosse (max_bytes) Listen werden an Leerzeilen auf mehrere nummerierte Bilder verteilt.
    Rueckgabe: Liste der geschriebenen Dateien - oder, mit images=[], die Bilder selbst (fuer die Vorschau)."""
    Image, ImageDraw, ImageFont = pil
    T = _TextPainter(ImageFont)
    BG, FG, DIM = _hex(C["panel"]), _hex(C["fg"]), _hex(C["dim"])
    HEADC, BOLDC, GRID = _hex(C["warn"]), _hex("#c9cdfb"), _hex(GRID_COLOR)
    CODEBG = _hex(C["bg"])
    TBODY = tuple((x + y) // 2 for x, y in zip(BG, CODEBG))         # Tabelle: etwas dunkler als der Hintergrund
    THEAD, THL = _hex(C["panel2"]), (50, 58, 90)                     # Kopfzeile / hervorgehobene Zeile (★)
    GAINC, LOSSC = _hex("#57d98b"), _hex("#ff6b6b")
    M = 22
    FPAD = 9                                          # Abstand Text - Rahmen bei [rahmen]
    items = []
    in_code = False
    src, cd = [], False
    for raw0 in str(text).split("\n"):                 # [neues Bild] (auch mitten in der Zeile) = Trennstelle
        if raw0.strip().startswith("```"):
            cd = not cd
        if not cd and is_table_line(raw0):                  # Tabellen-Zeilen sammeln
            if src and isinstance(src[-1], tuple):
                src[-1][1].append(raw0)
            else:
                src.append(("table", [raw0]))
            continue
        if cd or not _NEWPIC_RE.search(raw0):
            src.append(raw0)
            continue
        for i0, p0 in enumerate(_NEWPIC_RE.split(raw0)):
            if i0:
                src.append(None)
                p0 = p0.lstrip(" ")
            if p0.strip():
                src.append(p0)
    for raw in src:
        if raw is None:
            items.append({"kind": "break", "h": 0})
            continue
        if isinstance(raw, tuple):                          # Tabelle: Kopf fett in Goldfarbe, Zeilen mit Linien
            rows, al, plain = parse_table(raw[1])
            seps = [ri for ri, r in enumerate(rows) if ri > 1 and r and "[trenn]" in r[0].lower()]   # Trennlinie (neuer Server)
            rows = [[re.sub(r"\[trenn\]", "", c, flags=re.I) for c in r] for r in rows]
            icons = [[[(m.group(1).lower(), int(m.group(2))) for m in _ICON_RE.finditer(c)] for c in r] for r in rows]
            cells = [[[(t, (st[0] or ri == 0,) + st[1:5] + ((_hex(st[5]) if st[5] else None),))
                       for t, st in _inline_runs(_ICON_RE.sub("", c).rstrip(), _ST0, [])] for c in r] for ri, r in enumerate(rows)]
            hl = [ri for ri, r in enumerate(plain) if ri and r and r[0].startswith("★")]
            for ri in hl:                                   # ★ nur in Discord - im Bild genuegt die hinterlegte Zeile
                runs = cells[ri][0]
                for j0, (t0, st0) in enumerate(runs):
                    if t0.strip():
                        runs[j0] = (t0.lstrip().lstrip("★").lstrip(), st0)
                        break
            ics = []
            for r_ in icons:
                row_ = []
                for keys in r_:
                    ims = []
                    for k_ in keys:
                        try:
                            im_ = _ICON_HOOK[0](k_, int(size * 1.25)) if _ICON_HOOK[0] else None
                        except Exception:
                            im_ = None
                        if im_ is not None:
                            ims.append(im_)
                    row_.append(ims)
                ics.append(row_)
            items.append({"kind": "table", "fs": size, "rows": cells, "align": al, "hl": hl, "icons": ics, "sep": seps})
            continue
        line = raw.rstrip()
        if "[icon:" in line.lower():
            line = _ICON_RE.sub("", line)                   # Symbole gibt es nur in Tabellen
        if line.strip().startswith("```"):                  # Codeblock: Zeilen in fester Schriftbreite, die ``` selbst nicht
            in_code = not in_code
            continue
        if in_code:
            items.append({"kind": "code", "fs": size - 1, "col": FG, "bullet": False, "runs": [(line, _ST0)], "raw": line})
            continue
        if not _MARK_RE.sub("", line).strip():
            items.append({"kind": "blank"})
            continue
        fs, col, kind, bullet, all_bold, frame = size, FG, "text", False, False, None
        lead = 0
        if line.startswith("-#"):
            line, fs, col, kind = line[2:].lstrip(" ").rstrip(), size - 3, DIM, "dim"
        elif line.startswith("#"):
            hashes = len(line) - len(line.lstrip("#"))
            line, fs, col, kind, all_bold = line.lstrip("#").lstrip(" ").rstrip(), size + {1: 10, 2: 6}.get(hashes, 3), HEADC, "head", True
            while True:                                     # Marken am Zeilenanfang: [rahmen] [rahmen=farbe] [nichtfett] [farbe]
                l0, line = _lead_ws(line)                   # Einrueckung (Alt 0160 / Tab) vor, zwischen oder hinter den Marken
                lead += l0
                m = _HEAD_MARK_RE.match(line)
                if not m:
                    break
                tok = m.group(1).lower()
                if tok.startswith("rahmen"):
                    frame = img_color(m.group(2)) if m.group(2) else "head"
                elif tok == "nichtfett":
                    all_bold = False
                else:
                    col = _hex(img_color(m.group(3)))
                ws = m.group(0)[m.group(0).index("]") + 1:]
                line = (ws if ("\u00a0" in ws or "\t" in ws) else "") + line[m.end():]
            if frame == "head":
                frame = col
            elif frame:
                frame = _hex(frame)
        elif re.match(r"^\s*[-*]\s+", line):
            line, bullet = re.sub(r"^\s*[-*]\s+", "", line), True
        if kind != "head" and not bullet:
            lead, line = _lead_ws(line)
        runs = [(t, (st[0] or all_bold,) + st[1:5] + ((_hex(st[5]) if st[5] else None),))
                for t, st in _inline_runs(line, _ST0, [])]
        items.append({"kind": kind, "fs": fs, "col": col, "bullet": bullet, "runs": runs, "frame": frame, "lead": lead})

    def _runs_w(it):
        """Breite der Zeile - bei Umbruechen (\\n, /n) die breiteste Teilzeile."""
        segs, w = [], 0.0
        for t, st in it["runs"]:
            for i0, p0 in enumerate(t.split("\u2028")):
                if i0:
                    segs.append(w)
                    w = 0.0
                if p0:
                    w += T.swidth(p0, it["fs"], st)
        segs.append(w)
        return max(segs)

    TP = 10                                          # Innenabstand der Tabellen-Zellen

    def _tbl_measure(it):
        fs = it["fs"]
        n = max([len(r) for r in it["rows"]] or [0])
        cw = [0.0] * n
        for ri, r in enumerate(it["rows"]):
            for i, runs in enumerate(r):
                ims = it.get("icons", [])[ri][i] if it.get("icons") else []
                cw[i] = max(cw[i], sum(T.swidth(t, fs, st) for t, st in runs) + sum(im.width + 4 for im in ims))
        it["cw"] = [int(math.ceil(w)) + 2 * TP for w in cw]
        return sum(it["cw"]) + 2

    def natural(it):
        if it["kind"] == "table":
            return _tbl_measure(it)
        if it["kind"] == "code":
            return T.mono(it["fs"]).getlength(it["raw"]) + 16
        return (_runs_w(it) + (int(it["fs"] * 1.3) if it["bullet"] else 0)
                + (2 * FPAD + 4 if it.get("frame") else 0) + _lead_px(it))

    def _lead_px(it):
        return int(round(it.get("lead", 0) * T.swidth(" ", it["fs"], _ST0))) if it.get("lead") else 0

    maxw = int(min(text_max, max([natural(it) for it in items if it["kind"] not in ("blank", "break")] or [200]) + 6))
    for it in items:
        if it["kind"] == "break":
            continue
        if it["kind"] == "table":
            _tbl_measure(it)
            it["rh"] = int(it["fs"] * 1.45) + 10
            it["h"] = it["rh"] * len(it["rows"]) + 10
            it["w"] = sum(it["cw"]) + 2
            continue
        if it["kind"] == "blank":
            it["h"] = int(size * 0.85)
            continue
        fs = it["fs"]
        if it["kind"] == "code":
            it["indent"], it["lines"], it["lh"] = 8, [[(it["raw"], _ST0)]], int(fs * 1.35) + 3
            it["h"], it["w"] = it["lh"], natural(it)
            continue
        fr = 2 * FPAD + 4 if it.get("frame") else 0
        it["indent"] = (int(fs * 1.3) if it["bullet"] else 0) + _lead_px(it)
        avail = maxw - it["indent"] - fr
        toks = [(tok, st) for t, st in it["runs"] for tok in re.findall("\u2028|[^\\s\u2028]+[^\\S\u2028]*|[^\\S\u2028]+", t)]
        lines, cur, curw, nl = [], [], 0.0, False
        for tok, st in toks:
            if tok == "\u2028":                             # Zeilenumbruch aus der Vorlage (\n oder /n)
                lines.append(cur or [("", _ST0)])
                cur, curw, nl = [], 0.0, True
                continue
            if nl and not cur and not tok.strip(" "):
                continue                                    # Leerzeichen direkt hinter dem Umbruch
            nl = False
            if cur and curw + T.swidth(tok.rstrip(), fs, st) > avail:
                lines.append(cur)
                cur, curw = [], 0.0
                if not tok.strip():
                    continue
            cur.append((tok, st))
            curw += T.swidth(tok, fs, st)
        if cur:
            lines.append(cur)
        if len(lines) > 1:                                  # Teilzeile nur aus Fett-Zeichen (z.B. "**" hinter /n) weglassen
            lines = [ln for ln in lines if re.sub(r"[*_~`\s]", "", "".join(t for t, _st in ln))] or lines[:1]
        it["lines"] = lines or [[("", _ST0)]]
        it["lh"] = int(fs * 1.45) + 4
        it["h"] = it["lh"] * len(it["lines"]) + (int(fs * 0.35) if it["kind"] == "head" else 0) + (10 if fr else 0)
        it["tw"] = max(sum(T.swidth(t.rstrip() if j == len(ln) - 1 else t, fs, st) for j, (t, st) in enumerate(ln))
                       for ln in it["lines"])
        it["w"] = it["indent"] + max(sum(T.swidth(t, fs, st) for t, st in ln) for ln in it["lines"]) + fr
    W = int(math.ceil(max([it.get("w", 0) for it in items] + [380]))) + 2 * M
    n = len(items)
    limit = (max_h or max(2000, min(PNG_MAX_HEIGHT, int(PNG_MAX_PIXELS / max(W, 1))))) - 2 * M

    def pack(a, b, lim):
        """Bereich [a, b) in Stuecke bis lim Pixel Hoehe teilen - bevorzugt an Leerzeilen, nie direkt hinter einer Ueberschrift."""
        out = []
        while a < b and items[a]["kind"] == "blank":
            a += 1
        while a < b:
            tot, k = 0, a
            while k < b and (k == a or tot + items[k]["h"] <= lim):
                tot += items[k]["h"]
                k += 1
            c = k
            if k < b:
                lo = a + max(1, (k - a) // 2)
                # zuerst: Leerzeile vor einer Ueberschrift (neues Bild beginnt mit der Ueberschrift)
                pick = next((j for j in range(k, a, -1) if items[j]["kind"] == "head" and items[j - 1]["kind"] == "blank"), None)
                if pick is None:
                    pick = next((j for j in range(k, lo - 1, -1) if items[j - 1]["kind"] == "blank" or items[j]["kind"] == "blank"), None)
                if pick is None:
                    pick = next((j for j in range(k, a, -1) if items[j - 1]["kind"] != "head"), k)
                c = pick
            e = c
            while e > a and items[e - 1]["kind"] == "blank":
                e -= 1
            if e > a:
                out.append((a, e))
            a = c
            while a < b and items[a]["kind"] == "blank":
                a += 1
        return out

    def run_col(it, st):
        if st[5]:
            return st[5]
        return BOLDC if (st[0] and it["kind"] == "text") else it["col"]

    def make(a, b):
        H = 2 * M + sum(it["h"] for it in items[a:b])
        img = Image.new("RGB", (W, H), BG)
        d = ImageDraw.Draw(img)
        y = M
        for it in items[a:b]:
            if it["kind"] == "blank":
                y += it["h"]
                continue
            fs = it["fs"]
            if it["kind"] == "table":
                rh, cw = it["rh"], it["cw"]
                tw, y0, nr = sum(cw), y + 5, len(it["rows"])
                d.rectangle([M, y0, M + tw, y0 + rh * nr], fill=TBODY)
                d.rectangle([M, y0, M + tw, y0 + rh], fill=THEAD)
                for ri in it["hl"]:
                    d.rectangle([M, y0 + ri * rh, M + tw, y0 + (ri + 1) * rh], fill=THL)
                for ri in range(nr + 1):
                    d.line([(M, y0 + ri * rh), (M + tw, y0 + ri * rh)], fill=GRID, width=1)
                for ri in it.get("sep") or ():                 # goldene Trennlinie (z. B. zwischen zwei Servern)
                    d.line([(M, y0 + ri * rh), (M + tw, y0 + ri * rh)], fill=HEADC, width=3)
                xx = M
                for w in cw + [0]:
                    d.line([(xx, y0), (xx, y0 + rh * nr)], fill=GRID, width=1)
                    xx += w
                for ri, row in enumerate(it["rows"]):
                    base = y0 + ri * rh + rh // 2 + int(fs * 0.36)
                    xx = M
                    for ci, runs in enumerate(row):
                        ims = it["icons"][ri][ci] if it.get("icons") else []
                        w = sum(T.swidth(t, fs, st) for t, st in runs) + sum(im.width + 4 for im in ims)
                        al = "c" if ri == 0 else it["align"][ci]
                        x = xx + TP if al == "l" else (xx + cw[ci] - TP - w if al == "r" else xx + (cw[ci] - w) / 2.0)
                        pc = "".join(t for t, _st in runs).strip()
                        dcol = HEADC if ri == 0 else (GAINC if re.match(r"^\+\s*\d", pc) else
                                                      (LOSSC if re.match(r"^[−\-]\s*\d", pc) else FG))   # +Zuwachs gruen, −Verlust rot
                        for t, st in runs:
                            fill = st[5] or dcol
                            if st[:5] in (_ST0[:5], (True, False, False, False, False)):
                                T.draw(d, x, base, t, fs, st[0], fill)
                            else:
                                T.sdraw(d, x, base, t, fs, st, fill)
                            x += T.swidth(t, fs, st)
                        for im in ims:                          # Symbol hinter dem Text (z.B. Klasse)
                            x += 4
                            try:
                                img.paste(im, (int(x), int(y0 + ri * rh + (rh - im.height) // 2)), im if im.mode == "RGBA" else None)
                            except Exception:
                                pass
                            x += im.width
                        xx += cw[ci]
                y += it["h"]
                continue
            if it["kind"] == "code":
                d.rectangle([M - 4, y, W - M + 4, y + it["lh"]], fill=_hex(C["panel2"]))
                try:
                    d.text((M + 4, y + it["lh"] // 2 + int(fs * 0.36)), it["raw"], font=T.mono(fs), fill=it["col"], anchor="ls")
                except Exception:
                    d.text((M + 4, y), it["raw"], font=T.mono(fs), fill=it["col"])
                y += it["lh"]
                continue
            if it["kind"] == "head":
                y += int(fs * 0.35)
            frame = it.get("frame")
            x0 = M
            if frame:                                       # mit Rahmen: der ganze Rahmen rueckt ein
                ftop = y + 1
                y += 5
                x0 = M + FPAD + _lead_px(it)
            for li, ln in enumerate(it["lines"]):
                base = y + it["lh"] // 2 + int(fs * 0.36)
                x = x0
                if it["bullet"]:
                    if li == 0:
                        T.draw(d, x + int(fs * 0.2), base, "•", fs, False, DIM)
                    x += it["indent"]
                elif not frame:
                    x += _lead_px(it)                       # Einrueckung (Alt 0160 / Tab)
                for j, (t, st) in enumerate(ln):
                    if not t:
                        continue
                    w = T.swidth(t, fs, st)
                    fill = run_col(it, st)
                    if st == _ST0 or st[:5] == (True, False, False, False, False) or st[:5] == _ST0[:5]:
                        T.draw(d, x, base, t, fs, st[0], fill)
                    else:
                        wl = T.swidth(t.rstrip(), fs, st) if j == len(ln) - 1 else w
                        if st[3]:                             # hervorgehoben: dunkler Hintergrund
                            try:
                                d.rounded_rectangle([x - 2, base - int(fs * 0.95), x + wl + 2, base + int(fs * 0.32)],
                                                    radius=3, fill=CODEBG)
                            except Exception:
                                d.rectangle([x - 2, base - int(fs * 0.95), x + wl + 2, base + int(fs * 0.32)], fill=CODEBG)
                        T.sdraw(d, x, base, t, fs, st, fill)
                        lw = max(1, int(round(fs / 14.0)))
                        if st[2]:
                            d.line([(x, base + 2 + lw // 2), (x + wl, base + 2 + lw // 2)], fill=fill, width=lw)
                        if st[4]:
                            yy = base - int(fs * 0.3)
                            d.line([(x, yy), (x + wl, yy)], fill=fill, width=lw)
                    x += w
                y += it["lh"]
            if frame:
                y += 3
                box = [M - 1 + _lead_px(it), ftop, M + it["tw"] + it["indent"] + 2 * FPAD + 1, y]
                try:
                    d.rounded_rectangle(box, radius=7, outline=frame, width=2)
                except Exception:
                    d.rectangle(box, outline=frame, width=2)
                y += 2
        d.rectangle([0, 0, W - 1, H - 1], outline=GRID)
        return img

    def render(a, b, tmp):
        img = make(a, b)
        img.save(tmp, "PNG", compress_level=6)
        img.close()

    queue, a0 = [], 0
    for c0 in [i for i, it in enumerate(items) if it["kind"] == "break"] + [n]:     # [neues Bild] trennt immer
        queue += pack(a0, c0, limit)
        a0 = c0 + 1
    if not queue:
        raise ValueError("Die Liste ist leer.")
    if images is not None:                          # Vorschau: Bilder zurueckgeben statt Dateien
        for a, b in queue:
            images.append(make(a, b))
        return images
    done, cnt, tmp = [], 0, None
    try:
        while queue:
            a, b = queue.pop(0)
            cnt += 1
            tmp = "%s.teil%d.tmp" % (path, cnt)
            render(a, b, tmp)
            if os.path.getsize(tmp) > max_bytes and b - a > 1:              # zu gross: neu, mit halber Hoehe, aufteilen
                os.remove(tmp)
                half = max(60, sum(it["h"] for it in items[a:b]) // 2)
                sub = pack(a, b, half)
                queue[0:0] = sub if len(sub) > 1 else [(a, (a + b) // 2), ((a + b) // 2, b)]
                continue
            done.append(tmp)
    except BaseException:
        for t in done + ([tmp] if tmp else []):
            try:
                os.remove(t)
            except OSError:
                pass
        raise
    stem, ext = os.path.splitext(path)
    ext = ext or ".png"
    out = []
    if len(done) == 1:
        os.replace(done[0], stem + ext)
        out.append(stem + ext)
    else:
        pad = len(str(len(done)))
        for k, tmp in enumerate(done, 1):
            fn = "%s_%0*d%s" % (stem, pad, k, ext)
            os.replace(tmp, fn)
            out.append(fn)
    return out


