class IconSet:
    """Klassen- und Reittier-Symbole aus einem Ordner (z. B. 1_warrior_icon_large.png ... / mount01_icon.png ...).
    Klasse = Zahl am Anfang des Dateinamens; Reittier = mount01-04 (gute Rassen: 10/20/30/50 %), mount05-08 (böse Rassen)."""

    def __init__(self, app):
        self.app = app
        self._files = None
        self._dir = None
        self._ph = {}
        self._pil = {}
        self._folder = (None, None)           # (icon_dir aus den Einstellungen, gefundener Ordner) - nicht bei jedem Aufruf pruefen
        self._rc = {}                         # Symbole je Datensatz (fuer schnelles Scrollen)
        self.gen = 0

    def candidates(self):
        home = os.path.expanduser("~")
        return [os.path.join(app_dir(), "icons"), os.path.join(app_dir(), "Klassen-Mount"),
                os.path.join(home, "Downloads", "Klassen-Mount"), os.path.join(home, "Desktop", "Klassen-Mount")]

    def folder(self):
        d = str(self.app.cfg.d.get("icon_dir") or "").strip()
        if self._folder[0] == d and self._files is not None:
            return self._folder[1]
        found = None
        if d and os.path.isdir(d):
            found = d
        else:
            for c in self.candidates():
                if os.path.isdir(c):
                    found = c
                    break
        self._folder = (d, found)
        return found

    def reset(self):
        self._files = None
        self._folder = (None, None)
        self._ph.clear()
        self._pil.clear()
        self.bump()

    def bump(self):
        """Einstellungen der Symbole geaendert: gemerkte Symbole je Zeile verwerfen."""
        self.gen += 1
        self._rc.clear()

    def strip(self, keys, size):
        """Mehrere Symbole als EIN Bild (mit Pillow) - weniger Zeichenarbeit beim Scrollen. None ohne Pillow."""
        ck = ("strip", tuple(keys), size)
        if ck in self._ph:
            return self._ph[ck]
        ph = None
        ims = [im for im in (self._pil_img(k, size) for k in keys) if im is not None]
        if len(ims) > 1:
            try:
                from PIL import Image, ImageTk
                w = sum(im.width for im in ims) + 3 * (len(ims) - 1)
                h = max(im.height for im in ims)
                out = Image.new("RGBA", (w, h), (0, 0, 0, 0))
                x = 0
                for im in ims:
                    out.paste(im, (x, (h - im.height) // 2), im)
                    x += im.width + 3
                ph = ImageTk.PhotoImage(out, master=self.app)
            except Exception:
                ph = None
        self._ph[ck] = ph
        return ph

    def row_icons(self, rec, size):
        """(Symbole rechts, Symbole direkt hinter dem Namen) einer Zeile - gemerkt, damit Scrollen nichts neu berechnet."""
        c = self._rc.get(id(rec))
        if c is not None and c[0] is rec and c[1] == size and c[2] == self.gen:
            return c[3], c[4]
        keys = self.keys_for(rec)
        st = self.strip(keys, size) if len(keys) > 1 else None
        tail = [st] if st is not None else self.photos_for(rec, size)
        lead = self.lead_photos(rec, size)
        if len(self._rc) > 30000:
            self._rc.clear()
        self._rc[id(rec)] = (rec, size, self.gen, tail, lead)
        return tail, lead

    SUB = "Symbole"                    # Unterordner fuer Traenke, CC, Pfeile (auch direkt im Ordner moeglich)
    _RX_POT = re.compile(r"^trank_(staerke|geschick|intelligenz|ausdauer|glueck)_(klein|mittel|gross)\.")
    _RX_KOMBI = re.compile(r"^trank_kombi_(staerke|geschick|intelligenz)\.")
    _RX_MISC = re.compile(r"^(cc|pfeil_hoch|pfeil_runter|stein)\.")

    def files(self):
        d = self.folder()
        if self._files is None or d != self._dir:
            self._dir, self._files = d, {}
            self._ph.clear()
            self._pil.clear()
            for sub in ([d, os.path.join(d, self.SUB)] if d else []):
                try:
                    names = os.listdir(sub)
                except OSError:
                    continue
                for fn in names:
                    low = fn.lower()
                    if not low.endswith((".png", ".gif")):
                        continue
                    path = os.path.join(sub, fn)
                    m = self._RX_POT.match(low)
                    if m:
                        self._files[("p", "%s_%s" % m.groups())] = path
                        continue
                    if low.startswith("trank_fluegel."):
                        self._files[("p", "fluegel")] = path
                        continue
                    m = self._RX_KOMBI.match(low)
                    if m:
                        self._files[("k", m.group(1))] = path
                        continue
                    m = self._RX_MISC.match(low)
                    if m:
                        self._files[("x", m.group(1))] = path
                        continue
                    m = re.match(r"^mount0*(\d+)", low)
                    if m:
                        self._files[("m", int(m.group(1)))] = path
                        continue
                    m = re.match(r"^(\d+)[_\-. ]", low)
                    if m:
                        self._files[("c", int(m.group(1)))] = path
        return self._files

    def counts(self):
        f = self.files()
        return sum(1 for k in f if k[0] == "c"), sum(1 for k in f if k[0] == "m")

    def extra_counts(self):
        """(Traenke, Kombi-Bilder, CC vorhanden?) - fuer die Anzeige in den Einstellungen."""
        f = self.files()
        nk = sum(1 for a in ("staerke", "geschick", "intelligenz")
                 if ("k", a) in f or (self._combo_parts(a) is not None and self.have_pil()))   # auch selbst zusammengesetzte
        return sum(1 for k in f if k[0] == "p"), nk, ("x", "cc") in f

    def enabled(self):
        return bool(self.app.cfg.d.get("icons_on", True)) and bool(self.files())

    @staticmethod
    def kstr(k):
        """Schluessel als Text (fuer die Web-Seite): ('c', 1) -> 'c1', ('p', 'staerke_gross') -> 'pstaerke_gross'."""
        return "%s%s" % (k[0], k[1])

    def keys_for(self, rec):
        """Symbole hinter dem Namen (rechtsbuendig): Klasse, Reittier, Traenke."""
        out = []
        cls = rec.get("_cls")
        if cls:
            out.append(("c", int(cls)))
        m = rec.get("_mount")
        if m:
            out.append(("m", min(int(m), 4) + (4 if (rec.get("_race") or 0) >= 5 else 0)))
        if self.app.cfg.d.get("icons_potions", True):
            out.extend(self.potion_keys(rec))
        return out

    def potion_keys(self, rec):
        """Alle drei Traenke (Hauptattribut + Ausdauer + Fluegel) -> ein Kombi-Bild, sonst je Trank ein Bild
        (die Form zeigt die Groesse: duenn = klein, rund = mittel, eckig = gross)."""
        pot = [int(t) for t in (rec.get("_pot") or ()) if t]
        if not pot:
            return []
        f = self.files()
        if rec.get("tranke_voll"):
            c = CLASSES.get(rec.get("_cls"))
            attr = {"S": "staerke", "G": "geschick", "I": "intelligenz"}.get(str(c[2]).upper() if c else "")
            if attr is None:
                mi = CLASS_MAIN.get(rec.get("_cls"))
                attr = POT_ATTRS[mi] if mi is not None else None
            if attr and (("k", attr) in f or (self._combo_parts(attr) is not None and self.have_pil())):
                return [("k", attr)]
        # Reihenfolge von links nach rechts: Glueck, Haupttrank bzw. andere Attribute (zeigen nach links),
        # Fluegel (gerade), Ausdauer (zeigt nach rechts)
        def pos(t):
            if t == 16:
                return (2, 0)
            a = (t - 1) % 5
            return ({4: 0, 3: 3}.get(a, 1), a, -t)
        order = sorted(pot, key=pos)
        out = []
        for t in order:
            k = potion_key(t)
            if k and ("p", k) in f:
                out.append(("p", k))
        return out

    def lead_keys(self, rec):
        """Symbole direkt hinter dem Namen: CC-Zeichen fuer offizielle Content Creator, (A) fuer Avatar-Bilder (ohne CC),
        Schloss fuer vermutlich gesperrte Spieler (die beiden letzten zeichnet das Programm selbst, Pillow noetig)."""
        out = []
        d = self.app.cfg.d
        if rec.get("creator") is True:
            if d.get("icons_cc", True) and ("x", "cc") in self.files():
                out.append(("x", "cc"))
        elif d.get("icons_av", True) and is_avatar(rec) and self.have_pil():
            out.append(("s", "av"))
        if rec.get("locked") and d.get("icons_lock", True) and self.have_pil():
            out.append(("s", "lock"))
        return out

    @staticmethod
    def _synth(v):
        """Selbst gezeichnete Zeichen: ('s', 'av') = A im Kaestchen, ('s', 'lock') = Schloss."""
        from PIL import Image, ImageDraw, ImageFont
        W = 64
        im = Image.new("RGBA", (W, W), (0, 0, 0, 0))
        d = ImageDraw.Draw(im)
        if v == "av":
            col = (127, 184, 255, 255)
            d.rounded_rectangle([4, 6, W - 5, W - 7], radius=12, outline=col, width=6)
            f = png_fonts(ImageFont, 40)[1]
            bb = d.textbbox((0, 0), "A", font=f)
            d.text(((W - (bb[2] - bb[0])) / 2 - bb[0], (W - (bb[3] - bb[1])) / 2 - bb[1]), "A", font=f, fill=col)
        else:
            col = (240, 178, 50, 255)
            d.arc([16, 4, W - 17, 40], 180, 360, fill=col, width=7)
            d.line([(19, 22), (19, 30)], fill=col, width=7)
            d.line([(W - 20, 22), (W - 20, 30)], fill=col, width=7)
            d.rounded_rectangle([8, 28, W - 9, W - 4], radius=8, fill=col)
            d.ellipse([W / 2 - 6, 38, W / 2 + 6, 50], fill=(40, 30, 10, 255))
        return im

    @staticmethod
    def title(k, lang="de"):
        """Kurzer Hinweistext zu einem Symbol (Maus darueber auf der Web-Seite), in der Sprache lang (de, en, pl, cs)."""
        L = ICON_TXT.get(lang) or ICON_TXT["de"]
        t, v = k
        if t == "s":
            return {"av": {"de": "Avatar-Bild (kein CC)", "en": "Avatar picture (no CC)", "pl": "Awatar (nie CC)",
                           "cs": "Avatar (ne CC)"}, "lock": {"de": "vermutlich gesperrt (zuletzt online unbekannt)",
                                                            "en": "probably banned (last online unknown)",
                                                            "pl": "prawdopodobnie zablokowany", "cs": "pravděpodobně zablokován"}
                    }.get(v, {}).get(lang) or ""
        if t == "c":
            v = int(v)
            if lang == "de" or v not in L["cls"]:
                c = CLASSES.get(v)
                return c[0] if c else "%s %s" % (L["class"], v)
            return L["cls"][v]
        if t == "m":
            v = int(v)
            lvl = ((v - 1) % 4) + 1
            return L["mount_t"] % (L["mounts"][v > 4].get(lvl, ""), MOUNT_PCT.get(lvl, 0))
        if t == "k":
            return L["all_pot"] % L["attr"].get(v, v)
        if t == "p":
            if v == "fluegel":
                return L["wings"]
            a, sz = str(v).split("_", 1)
            return L["pot_t"] % (L["attr"].get(a, a), L["size"].get(sz, sz),
                                 {"klein": "10 %", "mittel": "15 %", "gross": "25 %"}.get(sz, ""))
        if t == "x" and v == "cc":
            return "Content Creator"
        return ""

    def lead_photos(self, rec, size):
        return [p for p in (self.photo(k, size) for k in self.lead_keys(rec)) if p is not None]

    def pil_lead(self, rec, size):
        return [p for p in (self._pil_img(k, size) for k in self.lead_keys(rec)) if p is not None]

    _pil_ok = None

    @classmethod
    def have_pil(cls):
        if cls._pil_ok is None:
            try:
                import PIL.Image  # noqa: F401
                cls._pil_ok = True
            except Exception:
                cls._pil_ok = False
        return cls._pil_ok

    LEFT_POTIONS = ("staerke_", "geschick_", "intelligenz_", "glueck_")   # zeigen nach links (gespiegelt); Fluegel gerade; Ausdauer nach rechts

    def _combo_parts(self, attr):
        """Die drei grossen Traenke fuer das Kombi-Bild (Ausdauer, Fluegel, Haupttrank) - None, wenn einer fehlt."""
        f = self.files()
        keys = [("p", "ausdauer_gross"), ("p", "fluegel"), ("p", "%s_gross" % attr)]
        return keys if all(k in f for k in keys) else None

    @staticmethod
    def _upright(im):
        """Fluegeltrank gerade stellen (die Bilder liegen schraeg, Hals nach rechts oben)."""
        from PIL import Image
        r = im.rotate(45, resample=Image.BICUBIC, expand=True)
        bb = r.getbbox()
        if bb:
            r = r.crop(bb)
        s = max(r.size)
        c = Image.new("RGBA", (s, s), (0, 0, 0, 0))
        c.paste(r, ((s - r.width) // 2, (s - r.height) // 2), r)
        return c

    def _oriented(self, key):
        """Bild in voller Groesse, schon passend ausgerichtet (Pillow noetig)."""
        from PIL import Image, ImageOps
        t, v = key
        if t == "s":
            return self._synth(v)
        if t == "k":
            parts = self._combo_parts(v)
            if parts is None:
                path = self.files().get(key)
                return Image.open(path).convert("RGBA") if path else None
            W = 176
            c = Image.new("RGBA", (W, W), (0, 0, 0, 0))

            def put(im, cx, cy, size):
                f = size / float(max(im.size))
                im = im.resize((max(1, round(im.width * f)), max(1, round(im.height * f))), Image.LANCZOS)
                c.alpha_composite(im, (round(cx - im.width / 2), round(cy - im.height / 2)))
            put(self._oriented(("p", "fluegel")), W * 0.5, W * 0.40, W * 0.66)       # Fluegel hinten in der Mitte
            put(self._oriented(("p", "%s_gross" % v)), W * 0.26, W * 0.60, W * 0.62)    # Haupttrank links
            put(self._oriented(("p", "ausdauer_gross")), W * 0.74, W * 0.60, W * 0.62)  # Ausdauer rechts
            return c
        path = self.files().get(key)
        if not path:
            return None
        im = Image.open(path).convert("RGBA")
        if t == "p":
            if str(v).startswith(self.LEFT_POTIONS):
                im = ImageOps.mirror(im)
            elif v == "fluegel":
                im = self._upright(im)
        return im

    def _pil_img(self, key, size):
        ck = (key, size)
        if ck not in self._pil:
            im = None
            try:
                from PIL import Image
                im = self._oriented(key)
                if im is not None:
                    im = im.copy()
                    im.thumbnail((size, size), Image.LANCZOS)
            except Exception:
                im = None
            self._pil[ck] = im
        return self._pil[ck]

    def photo(self, key, size):
        ck = (key, size)
        if ck in self._ph:
            return self._ph[ck]
        ph = None
        path = self.files().get(key)
        if path or key[0] in ("k", "s"):                # Kombi-Bild / eigene Zeichen entstehen mit Pillow
            im = self._pil_img(key, size)
            if im is not None:
                try:
                    from PIL import ImageTk
                    ph = ImageTk.PhotoImage(im, master=self.app)
                except Exception:
                    ph = None
            if ph is None and path:                     # ohne Pillow: Tk verkleinert nur ganzzahlig
                try:
                    big = tk.PhotoImage(file=path, master=self.app)
                    f = max(1, int(math.ceil(max(big.width(), big.height()) / float(size))))
                    if key[0] == "p" and str(key[1]).startswith(self.LEFT_POTIONS):
                        ph = tk.PhotoImage(master=self.app)             # gespiegelt: Ausdauer/Glueck zeigen nach links
                        ph.tk.call(ph, "copy", big, "-subsample", -f, f)
                    else:
                        ph = big.subsample(f, f)
                except Exception:
                    ph = None
        self._ph[ck] = ph
        return ph

    def photos_for(self, rec, size):
        return [p for p in (self.photo(k, size) for k in self.keys_for(rec)) if p is not None]

    def pil_for(self, rec, size):
        return [p for p in (self._pil_img(k, size) for k in self.keys_for(rec)) if p is not None]

    def data_uri(self, key, size=48):
        """Symbol als data:-URI fuer die Web-Seite (mit Pillow verkleinert, sonst die Originaldatei)."""
        path = self.files().get(key)
        if not path and key[0] != "k":
            return None
        import base64
        im = self._pil_img(key, size)
        if im is not None:
            buf = io.BytesIO()
            im.save(buf, "PNG", optimize=True)
            raw = buf.getvalue()
        elif path:
            with open(path, "rb") as fh:
                raw = fh.read()
        else:
            return None
        return "data:image/png;base64," + base64.b64encode(raw).decode("ascii")


