def _snap_fz(v, lo=60, hi=160):
    """Größe (%) der Online-Liste: 60 bis 160 in 5er-Schritten."""
    try:
        v = float(str(v).strip().rstrip("%"))
    except (TypeError, ValueError):
        return 100
    return int(max(lo, min(hi, round(v / 5.0) * 5)))


