def _jnum(v):
    if v is None or isinstance(v, bool):
        return None if v is None else int(v)
    try:
        f = float(v)
    except (TypeError, ValueError):
        return None
    if f != f or f in (float("inf"), float("-inf")):
        return None
    return int(round(f)) if abs(f - round(f)) < 1e-9 else round(f, 2)


