def sq_pack(key, rec):
    """Kaestchen-Spalte fuer die Seite: "Stufe.Stufe…|Extra" (Extra = Element der Schadensrune bzw. aktueller Rahmen).
    Die Seite rechnet Farben und Tooltips selbst (gleiche Regeln wie sq_cells)."""
    grp = SQ_GROUPS.get(key)
    if not grp or not sq_cells(key, rec):
        return None
    vals = []
    for k, _n, _m, _l in grp:
        if k == "_hell":
            continue
        v = rec.get(k)
        vals.append("" if v is None else str(int(v)))
    ex = ""
    if key == "sq_rune":
        ex = str(rec.get("rune_dmg_el") or "")
    elif key == "sq_frame":
        ex = str(rec.get("frame") or "")
    return ".".join(vals) + ("|" + ex.replace("|", "/") if ex else "")


def html_col(key, label):
    f = FIELD_MAP[key]
    c = {"id": key, "label": label, "grp": web_col_group(key)}
    if key in SQ_GROUPS:                                 # Kaestchen: Sortierwert + Stufen, die Seite malt die Kaestchen
        c["type"] = "numtxt"
        c["sq"] = 1
        c["nd"] = c["nr"] = 1
        if f.label != label:
            c["tip"] = f.label
        return c
    if key.startswith("gm_") and f.kind in ("num", "pct"):
        c["type"] = "numtxt"                             # bester Spieler der Gilde: Wert + Name (klein darunter)
        c["fmt"] = "best"
    elif key in HTML_NUMTXT or f.kind in ("ratio", "ts", "date", "dhm"):
        c["type"] = "numtxt"
    elif f.kind in ("num", "pct"):
        c["type"] = "num"
        if f.kind == "pct":
            c["fmt"] = "pct"
        elif key in SIGNED_KEYS or (key.startswith("gd_") and key not in ("gd_joined", "gd_left")):
            c["fmt"] = "signed"
        elif key == "level_k":
            c["fmt"] = "int"
    else:
        c["type"] = "text"
        c["search"] = True
        if f.kind == "flag":
            c["fmt"] = "flag"
        elif key == "klasse":
            c["fmt"] = "cls"
    if f.kind == "dhm":
        c["fmt"] = "ago"                                 # Last Active: "4 h 2 min" statt 00:04:02
    if key in GAIN_KEYS or (key.startswith("gd_") and key not in ("gd_members", "gd_joined", "gd_left")):
        c["gain"] = 1                                    # Umschalter gesamt / pro Tag / pro Woche / pro X Tage
    if key == "xp":
        c["nr"] = c["nd"] = 1                            # XP: keine Rang-Marke, kein Zuwachs darunter (1,5 Mrd je Level)
    if f.kind in ("dhm", "ts", "date") or key in ("rank", "g_rank"):
        c["nd"] = 1                                      # Zeiten und Platz: kein Zuwachs darunter
    if key in ("g_raids", "gd_raids"):
        c["nd"] = c["ng"] = 1                            # Raids: kein Zuwachs (nicht berechenbar), auch nicht pro Tag
        c.pop("gain", None)
    if key in WEB_RATE:
        c["rate"] = WEB_RATE[key]                        # im Vergleich Alt -> Neu rechnet die Seite selbst
    if key in WEB_RATE_G:
        c["gday"] = 1                                    # Gilden-Zuwachs: pro Tag / pro Woche / pro X Tage (Zuwachs-Knopf)
    if f.label != label:
        c["tip"] = f.label
    if key in ("base_xd", "xp_xd"):
        c["xd"] = GAIN_X                                 # Werte gelten fuer X Tage; die Seite rechnet auf das X des Betrachters um
        c["tip"] = "Δ %s pro X Tage" % ("Base" if key == "base_xd" else "XP")
    return c


def html_val(col, rec):
    key = col["id"]
    if col.get("sq"):
        t = sq_pack(key, rec)
        return None if t is None else [_jnum(rec.get(key)), t]
    if col["type"] == "num":
        return _jnum(rec.get(key))
    if col.get("fmt") == "best":
        v = rec.get(key)
        return None if v is None else [_jnum(v), str(rec.get(key + "_n") or "")]
    t = cell_text(key, rec)
    if col["type"] == "numtxt":
        v = rec.get(key)
        return None if v is None and t in ("", "–") else [_jnum(v), t]
    return t


MG_DK = tuple([k for g in ("sq_fort", "sq_rune") for k, _n, _m, _l in SQ_GROUPS[g]] + ["rune_dmg_el"] +
              [k for g in ("sq_pet", "sq_portal") for k, _n, _m, _l in SQ_GROUPS[g]] +
              ["gold_frame", "silver_frame", "twitch_frame", "ff_frame", "frame", "_pot", "pot_main", "pot_con", "pot_life",
               "tranke_voll", "_att", "eq_total", "eq_parts", "eq_smith", "eq_gems", "upgrade", "petb_main", "petb_con",
               "potb_main", "potb_con", "rank", "album", "g_joined"])


def _mg_v(v):
    """Wert fuer die Seite: Zahl (ganz wenn moeglich), Text, Liste; True/False als 1/0."""
    if v is None:
        return None
    if isinstance(v, bool):
        return 1 if v else 0
    if isinstance(v, (list, tuple)):
        return [_mg_v(x) for x in v]
    if isinstance(v, (int, float)):
        return _jnum(v)
    return str(v)


def _mg_trim(row):
    while row and row[-1] is None:
        row.pop()
    return row


def mg_members(gl, recs, pkey, gkey):
    """Mitglieder je Gilde eines Scans: {Gilden-Kennung: (Gildensatz, [(Spieler-Kennung, Name, Datensatz|None)])}.
    Mit Namensliste der Ehrenhalle: genau diese Namen (auch nicht gescannte, Datensatz None), sonst die Spieler mit dieser Gilde."""
    idx = {pkey(p["_srv"], p["name"]): p for p in recs if p.get("name")}
    by = {}
    for p in recs:
        if p.get("guild") and p.get("name"):
            by.setdefault(gkey(p["_srv"], p["guild"]), []).append(p)
    out = {}
    for g in gl:
        k = gkey(g["_srv"], g["name"])
        if k in out:
            continue
        if g.get("_names"):
            mem = []
            for n in g["_names"]:
                pk = pkey(g["_srv"], n)
                mem.append((pk, idx.get(pk, {}).get("name") or str(n), idx.get(pk)))
        else:
            mem = [(pkey(p["_srv"], p["name"]), p["name"], p) for p in by.get(k, [])]
        out[k] = (g, mem)
    for k, ps in by.items():
        if k in out:
            continue
        p0 = ps[0]
        g = {"name": p0["guild"], "_srv": p0["_srv"], "_srv_disp": p0.get("_srv_disp"), "g_members": None}
        out[k] = (g, [(pkey(p["_srv"], p["name"]), p["name"], p) for p in ps])
    return out


def mg_build(scans, keep=None, dscope=None, days=35, canon=True, dskip=None):
    """Daten des Reiters "Meine Gilde" der Online-Liste.
    scans = [{"ts", "recs", "groups"}] (aelteste zuerst; recs mit derive, groups = Gildensaetze des Scans).
    keep = Menge der Gilden-Kennungen, die hinein duerfen (None = alle), dscope = Gilden mit Details (Kaestchen, Werte,
    Traenke; None = alle). Mitglieder nur aus den Scans der letzten `days` Tage (mindestens die zwei neuesten).
    Kennungen "server|name klein" ueber die Zusammenlegungen (canon) - ein umbenannter Spieler bleibt derselbe."""
    if canon:
        gkey = lambda srv, nm: "|".join(cgk(srv, nm))
        pkey = lambda srv, nm: "|".join(_canon("p", srv, str(nm).lower()))
    else:
        gkey = lambda srv, nm: srv + "|" + str(nm).lower()
        pkey = lambda srv, nm: srv + "|" + str(nm).lower()
    scans = sorted([sc for sc in scans if sc.get("ts")], key=lambda sc: sc["ts"])
    if not scans:
        return None
    G, GI, P, PI = [], {}, [], {}

    def gi(k, name):
        i = GI.get(k)
        if i is None:
            i = GI[k] = len(G)
            G.append([str(name), k])
        else:
            G[i][0] = str(name)                          # neuester Name gewinnt (Scans aufsteigend)
        return i

    def pi(k, name, disp):
        i = PI.get(k)
        if i is None:
            i = PI[k] = len(P)
            P.append([str(name), str(disp or "")])
        else:
            P[i][0] = str(name)
            if disp:
                P[i][1] = str(disp)
        return i
    newest = scans[-1]["ts"]
    m_from = min(len(scans) - 2, next((i for i, sc in enumerate(scans) if sc["ts"] >= newest - days * 86400000.0), len(scans) - 1))
    m_from = max(0, m_from)
    out_ts, out_gs, out_m, det = [], [], [], {}
    last = len(scans) - 1
    for si, sc in enumerate(scans):
        gl = newest_groups(sc["groups"] or [], canon)
        mm = mg_members(gl, sc["recs"], pkey, gkey)
        gs_rows, m_rows = [], []
        for k in sorted(mm):
            if keep is not None and k not in keep:
                continue
            g, mem = mm[k]
            got = [p for _k, _n, p in mem if p is not None]
            n_mem = g.get("g_members")
            lv = [p["level"] for p in got if p.get("level") is not None]
            bs = [p["base_sum"] for p in got if p.get("base_sum") is not None]
            ts = [p["total_sum"] for p in got if p.get("total_sum") is not None]
            lva = g.get("g_level_avg") if g.get("g_level_avg") is not None else (round(sum(lv) / len(lv), 1) if lv else None)
            row = [gi(k, g["name"]), _mg_v(n_mem if n_mem is not None else len(mem)), len(got), _mg_v(lva),
                   _mg_v(round(sum(bs) / len(bs)) if bs else None), _mg_v(sum(bs) if bs else None), _mg_v(sum(ts) if ts else None),
                   _mg_v(g.get("g_raids")), _mg_v(g.get("g_rank")), _mg_v(g.get("g_honor")), str(g.get("_srv_disp") or "")]
            gs_rows.append(row)
            if si < m_from:
                continue
            mrows, few = [], len(got) * 2 < len(mem)        # kaum gescannt: nicht gescannte Namen weglassen
            for pk, nm, p in mem:
                if p is None and few:
                    continue
                i = pi(pk, nm, g.get("_srv_disp"))
                if p is None:
                    mrows.append([i])
                    continue
                m = p.get("_mount") or 0
                mv = (min(int(m), 4) + (4 if (p.get("_race") or 0) >= 5 else 0)) if m else 0
                la = p.get("last_active")
                gj = p.get("g_joined")
                r = [i, _mg_v(p.get("level")), _mg_v(p.get("base_sum")), _mg_v(p.get("total_sum")),
                     None if la is None else int(la), _mg_v(p.get("_cls")), mv, None if not gj else int(gj // 60000), None]
                mrows.append(r)
                if si == last and (dscope is None or k in dscope) and not (dskip and pk in dskip):
                    det[i] = _mg_trim([_mg_v(p.get(x)) for x in MG_DK])
            m_rows.append([gs_rows[-1][0], mrows])
        out_ts.append(int(sc["ts"]))
        out_gs.append(gs_rows)
        out_m.append(m_rows if si >= m_from else None)
    # Umbenennungen: Name je Scan (nur wenn anders als der neueste)
    pk_of = [None] * len(P)
    for k, i in PI.items():
        pk_of[i] = k
    for si, rows in enumerate(out_m):
        if rows is None:
            continue
        nm_si = {}
        for p in scans[si]["recs"]:
            if p.get("name"):
                nm_si[pkey(p["_srv"], p["name"])] = p["name"]
        for _g, mrows in rows:
            for r in mrows:
                if len(r) > 1:
                    old = nm_si.get(pk_of[r[0]])
                    if old and old != P[r[0]][0]:
                        while len(r) < 9:
                            r.append(None)
                        r[8] = old
    for rows in out_m:
        for _g, mrows in rows or ():
            for r in mrows:
                _mg_trim(r)
    return {"v": 1, "ts": out_ts, "G": G, "P": P, "gs": out_gs, "m": out_m, "mf": m_from,
            "dk": list(MG_DK), "d": [[i] + det[i] for i in sorted(det)]}


MG_DC_DEFAULT = ("Krieger = :playaWarrior:\nMagier = :playaMage:\nKundschafter = :playaScout:\nAssassine = :playaAssassin:\n"
                 "Kampfmagier = :playaBattleMage:\nBerserker = :berserker:\nDämonenjäger = :demonhunter:\nDruide = :playaDruid:\n"
                 "Barde = :playaBard:\nNekromant = :necro:\nPaladin = :paladin:\nPestdoktor = :playaPlagueDoctor:\nBlutweber = \n"
                 "Platz verbessert = :arrow_up:\nPlatz 1 = :first_place:\nPlatz 2 = :second_place:\nPlatz 3 = :third_place:\n"
                 "Kuh = \nPferd = \nSäbelzahntiger = \nGreif = \nSchwein = \nWolf = \nRaptor = \nDrache = ")


def mg_discord_codes(text):
    """Zeilen "Name = :code:" -> {c<Klasse>, up, g1-g3, m1-m8: Code} (leere Codes fehlen; die Seite schreibt dann den Namen)."""
    names = {}
    for k, v in CLASSES.items():
        names[str(v[0]).lower()] = "c%d" % k
    names.update({"platz verbessert": "up", "platz 1": "g1", "platz 2": "g2", "platz 3": "g3"})
    for i, n in enumerate(["Kuh", "Pferd", "Säbelzahntiger", "Greif", "Schwein", "Wolf", "Raptor", "Drache"]):
        names[n.lower()] = "m%d" % (i + 1)
    out = {}
    for line in str(text if text is not None else MG_DC_DEFAULT).splitlines():
        if "=" not in line:
            continue
        a, b = line.split("=", 1)
        k = names.get(a.strip().lower())
        b = b.strip().replace(" ", "")
        if k and b:
            out[k] = b[:60]
    return out


def html_ranks(rows, keys):
    """Platz je Spalte (1 = bester; gleiche Werte = gleicher Platz) ueber alle uebergebenen Zeilen."""
    out = [[None] * len(keys) for _ in rows]
    for j, k in enumerate(keys):
        neg = sorted(-r[k] for r in rows if r.get(k) is not None)
        for i, r in enumerate(rows):
            v = r.get(k)
            if v is not None:
                out[i][j] = bisect_left(neg, -v) + 1
    return out


def _html_chain_keys(scans):
    """Schluessel je Datensatz ueber mehrere Scans: derselbe Spieler behaelt seinen Schluessel auch nach einer Umbenennung
    (Zuordnung Scan fuer Scan ueber match_pairs). -> [ {id(Datensatz): Schluessel} je Scan ]"""
    out, prev = [], None
    for sc in scans:
        basis = sc["basis"]
        km, used = {}, set()
        if prev is not None:
            pairs, _n, _g = match_pairs(prev[0], basis)
            for a, b in pairs:
                k = prev[1].get(id(a))
                if k is not None and k not in used:
                    km[id(b)] = k
                    used.add(k)
        for i, r in enumerate(basis):
            if id(r) in km:
                continue
            k = "|".join(str(x) for x in cp(r)) if r.get("_srv") is not None and r.get("name") else str(i)
            base, n = k, 1
            while k in used:
                n += 1
                k = "%s#%d" % (base, n)
            km[id(r)] = k
            used.add(k)
        out.append(km)
        prev = (basis, km)
    return out


def html_spec(title, sub, cols, scans, metrics=(), top_n=0, presets=(), icons=None, defaults=None, hidden=(),
              phone_hidden=(), unit="Spieler", foot="", sort=None, mine=None, inactive_days=None, note="", period=None,
              groups=None, created=None, tp_factor=None, top_ids=None, profile=None, twins=None, locked_on=True):
    """Daten der Web-Seite. cols = [(Feld, Spaltenname)], scans = [{label, basis: [Datensaetze]}] (aelteste zuerst),
    metrics = [(Feld, Name)] fuer Top X (Vereinigung: wer in mindestens einer Spalte unter den Top X ist)."""
    ccols = [html_col(k, lab) for k, lab in cols]
    mk = [k for k, _l in metrics]
    for c in ccols:
        c["m"] = mk.index(c["id"]) if c["id"] in mk else -1
    icon_keys, out, mine_keys, gks_page = {}, [], set(), set()
    use_icons = icons is not None and icons.enabled()
    chain = _html_chain_keys(scans) if len(scans) > 1 else None
    ids = [c["id"] for c in ccols]
    srv_i = next((ids.index(k) for k in ("komp_server", "server", "g_server") if k in ids), None)
    gld_i = ids.index("guild") if "guild" in ids else None
    arrow_m = [j for j, k in enumerate(mk) if k not in DELTA_KEYS and not k.startswith("gd_")]
    pdays = (period or {}).get("days")
    last_keys = {}
    rate_m = {k: (WEB_RATE_SCANS.get(k) or WEB_RATE.get(k)) for k in mk if chain is not None and (k in WEB_RATE_SCANS or k in WEB_RATE)}
    pf_later = None                                      # je Scan: Spieler, die in einem spaeteren Scan stehen (die haben dort ihr Profil)
    if profile is not None and len(scans) > 1:
        pf_later, acc = [None] * len(scans), set()
        for j in range(len(scans) - 1, -1, -1):
            pf_later[j] = set(acc)
            acc |= {cp(r) for r in scans[j]["basis"] if r.get("_srv") is not None and r.get("name")}
    for si, sc in enumerate(scans):
        basis = list(sc["basis"])
        rbase = basis
        if rate_m and si > 0:                            # Zuwachs rechnet die Seite selbst - fuer Top X und Plaetze: zum Scan davor
            pv = {chain[si - 1][id(r)]: r for r in scans[si - 1]["basis"] if id(r) in chain[si - 1]}
            rbase = []
            for r in basis:
                q = {k: r.get(k) for k in mk}
                o = pv.get(chain[si].get(id(r)))
                if o is not None and r.get("_srv") == o.get("_srv"):
                    dd = ((r.get("_ts") or 0) - (o.get("_ts") or 0)) / 86400000.0
                    for k, (src, per) in rate_m.items():
                        a, b = o.get(src), r.get(src)
                        if a is None or b is None or q.get(k) is not None:
                            continue
                        if per == "d":
                            q[k] = b - a
                        elif dd >= 0.25:
                            q[k] = (b - a) / dd * (per or 30)
                rbase.append(q)
        ranks = html_ranks(rbase, mk) if mk else [None] * len(basis)
        pick = range(len(basis))
        tmask = [top_ids is None or k in top_ids for k in mk]
        if mk and top_n and any(tmask):
            pick = [i for i in pick if any(x is not None and x <= top_n and tmask[j] for j, x in enumerate(ranks[i]))]
        rows, keys, rks, ics, ina, avs, lks, cvs = [], [], [], [], [], [], [], {}
        ina_min = float(inactive_days) * 1440.0 if inactive_days else None
        # Pfeile: Plaetze gut gemacht (netto) unter den Eintraegen, die es in beiden Scans gibt (je Top-Liste)
        moves = {}
        has_prev = chain is None and any(r.get("_prev") is not None for r in basis)
        if has_prev and arrow_m:
            both = [i for i, r in enumerate(basis) if r.get("_prev") is not None and not r.get("_fus")]
            for j in arrow_m:
                k = mk[j]
                its = [i for i in both if basis[i].get(k) is not None and basis[i]["_prev"].get(k) is not None]
                for i, d in rank_moves(its, lambda i: basis[i][k], lambda i: basis[i]["_prev"][k]):
                    moves.setdefault(i, [None] * len(mk))[j] = d
        mvs, ovs, fus, onm, bgs, dds = [], [], [], {}, [], []
        pfs = [] if profile is not None and (si == len(scans) - 1 or pf_later is not None) else None
        for i in pick:
            r = basis[i]
            rows.append([html_val(c, r) for c in ccols])
            keys.append(chain[si][id(r)] if chain is not None else
                        ("|".join(str(x) for x in cp(r)) if r.get("_srv") is not None and r.get("name") else str(i)))
            rks.append(ranks[i])
            if si == len(scans) - 1:
                last_keys[id(r)] = keys[-1]
                if r.get("_srv") is not None and r.get("name"):
                    last_keys.setdefault(cp(r), keys[-1])
            n = len(rows) - 1
            if has_prev:
                pv = r.get("_prev")
                mvs.append(moves.get(i))
                ovs.append([_jnum(pv.get(mk[j])) if (pv is not None and j in arrow_m) else None for j in range(len(mk))]
                           if pv is not None and arrow_m else None)
                if r.get("_fus"):
                    fus.append(n)
                if r.get("_oldname"):
                    onm[str(n)] = r["_oldname"]
            bgs.append(_jnum(r.get("delta_base")))
            if si == len(scans) - 1 and r.get("guild") and r.get("_srv") is not None:
                gks_page.add("|".join(cgk(r["_srv"], r["guild"])))
            if pfs is not None:
                last = si == len(scans) - 1
                pfs.append(profile_row(r, profile) if last or (r.get("_srv") is not None and r.get("name") and cp(r) not in pf_later[si]) else None)
                if last and pfs[-1] and len(pfs[-1]) > PF_KEYS.index("dt") and pfs[-1][PF_KEYS.index("dt")] and r.get("_srv") is not None and r.get("name"):
                    profile.setdefault("_pfk", set()).add("|".join(cp(r)))
            dd = r.get("_days") or pdays
            dds.append(round(dd, 1) if dd else None)
            if mine is not None and mine(r):
                mine_keys.add(keys[-1])
            if ina_min is not None and (r.get("last_active") or 0) >= ina_min:
                ina.append(len(rows) - 1)
            if r.get("name") is not None and r.get("creator") is not True and is_avatar(r):
                avs.append(len(rows) - 1)                    # (A): Avatar-Bild, kein CC
            if r.get("locked") and locked_on:
                lks.append(len(rows) - 1)                    # vermutlich gesperrt
            if r.get("_cov"):
                cvs[str(len(rows) - 1)] = list(r["_cov"])     # Gilde nur teilweise gescannt
            if use_icons:
                kk = [k for k in icons.lead_keys(r) if k[0] != "s"] + icons.keys_for(r)   # CC, dann Klasse, Reittier, Traenke
                ks = [IconSet.kstr(k) for k in kk]
                for k, s in zip(kk, ks):
                    icon_keys[s] = k
                ics.append(ks)
        d = {"label": sc["label"], "rows": rows, "keys": keys, "n_total": len(basis)}
        if sc.get("ts"):
            d["ts"] = int(sc["ts"])
        if has_prev:
            if any(m is not None for m in mvs):
                d["mv"] = mvs
            if any(o is not None for o in ovs):
                d["ov"] = ovs
            if fus:
                d["fu"] = fus
            if onm:
                d["on"] = onm
        if any(x is not None for x in bgs):
            d["bg"] = bgs
            if tp_factor:                            # Durchschnitt des Base Gain (aktive Spieler): alle, je Server, je Gilde
                acc = {"all": [0.0, 0], "srv": {}, "g": {}}
                for r in basis:
                    g = r.get("delta_base")
                    if g is None or (ina_min is not None and (r.get("last_active") or 0) >= ina_min):
                        continue
                    acc["all"][0] += g
                    acc["all"][1] += 1
                    if srv_i is not None:
                        sv = html_val(ccols[srv_i], r)
                        a = acc["srv"].setdefault(sv, [0.0, 0]); a[0] += g; a[1] += 1
                    if gld_i is not None and r.get("guild"):
                        a = acc["g"].setdefault(r["guild"], [0.0, 0]); a[0] += g; a[1] += 1
                avg = lambda a: round(a[0] / a[1], 1) if a[1] >= 3 else None
                d["tp"] = {"all": avg(acc["all"]), "srv": {k: avg(v) for k, v in acc["srv"].items() if avg(v)},
                           "g": {k: avg(v) for k, v in acc["g"].items() if avg(v)}}
        if any(x is not None for x in dds):
            if len(set(dds)) == 1:
                d["days"] = dds[0]
            else:
                d["dd"] = dds
        if ina:
            d["ina"] = ina
        if avs:
            d["av"] = avs
        if lks:
            d["lk"] = lks
        if cvs:
            d["cv"] = cvs
        if mk:
            d["ranks"] = rks
        if use_icons:
            d["ic"] = ics
        if pfs is not None and any(x is not None for x in pfs):
            d["pf"] = pfs
        out.append(d)
    spec = {"title": title, "sub": sub, "foot": foot, "unit": unit, "cols": ccols,
            "metrics": [dict({"id": k, "label": lab}, **({} if top_ids is None or k in top_ids else {"top": False}))
                        for k, lab in metrics], "top_n": int(top_n or 0),
            "presets": [{"label": a, "q": b} for a, b in presets], "scans": out,
            "hidden": list(hidden), "phone_hidden": list(phone_hidden), "defaults": dict(defaults or {})}
    if sort:
        spec["sort"] = sort
    if mine_keys:
        spec["mine"] = sorted(mine_keys)
    if note:
        spec["note"] = str(note)
    if period:
        spec["period"] = dict(period)
    spec["stamp"] = (period or {}).get("b") or (out[-1]["label"] if out else "")
    if groups:
        spec["groups"] = groups
    if inactive_days:
        spec["inactive_days"] = inactive_days
    if tp_factor:
        spec["tp_f"] = tp_factor
    if twins:                                          # Gleiches Aussehen: Gruppen mit mindestens einem Spieler der Seite
        tw = []
        for g in twin_groups(twins):
            mem = []
            for r in sorted(g, key=lambda r: -(r.get("level") or 0)):
                k = last_keys.get(id(r))
                if k is None and r.get("_srv") is not None and r.get("name"):
                    k = last_keys.get(cp(r))
                mem.append([str(r.get("name") or ""), str(r.get("_srv_disp") or ""), int(r.get("level") or 0), k,
                            1 if r.get("creator") is True else (2 if is_avatar(r) else 0)])
            if any(m[3] is not None for m in mem):
                tw.append(mem)
        if tw:
            spec["tw"] = tw
            spec["twsp"] = list(special_counts(twins))
    spec["created"] = int(created if created is not None else time.time() * 1000)
    spec["_gk"] = gks_page                                 # nur fuer "Meine Gilde" (kommt nicht in die Seite)
    if profile is not None:
        spec["pf_keys"] = list(PF_KEYS)
        spec["_pfk"] = profile.pop("_pfk", set())          # nur fuer "Meine Gilde" (kommt nicht in die Seite)
        spec["wr_n"] = int(profile.get("n") or 0)
    if use_icons and icon_keys:
        spec["icons"], spec["icon_t"] = {}, {lang: {} for lang in WEB_LANGS}
        for s in sorted(icon_keys):
            uri = icons.data_uri(icon_keys[s])
            if uri:
                spec["icons"][s] = uri
                for lang in WEB_LANGS:
                    spec["icon_t"][lang][s] = IconSet.title(icon_keys[s], lang)
        if not IconSet.have_pil():                      # ohne Pillow spiegelt der Browser Ausdauer/Glueck
            spec["flip"] = [s for s in spec["icons"] if icon_keys[s][0] == "p"
                            and str(icon_keys[s][1]).startswith(IconSet.LEFT_POTIONS)]
    return spec


def _static_cell(c, v):
    if v is None or v == "":
        return "" if c["type"] == "text" else "–"
    if c["type"] == "numtxt":
        return v[1]
    if c["type"] == "num":
        if c.get("fmt") == "pct":
            return fmt_num(v) + " %"
        if c.get("fmt") == "signed":
            return fmt_num(v, signed=True)
        if c.get("fmt") == "int":
            return fmt_num(round(v))
        return fmt_num(v)
    return str(v)


def html_static(spec, limit=1000):
    """Einfache Tabelle ohne JavaScript - sichtbar, wenn die Datei in einer Vorschau ohne JavaScript geoeffnet wird."""
    import html as _html
    sc = spec["scans"][-1]
    hid = set(spec.get("hidden") or ())
    cols = [(i, c) for i, c in enumerate(spec["cols"]) if c["id"] not in hid]
    order = list(range(len(sc["rows"])))
    mets = [i for i, c in enumerate(spec["cols"]) if c.get("m", -1) >= 0]
    if mets:
        m0 = spec["cols"][mets[0]]["m"]
        order.sort(key=lambda j: (sc["ranks"][j][m0] is None, sc["ranks"][j][m0] or 0))
    out = ['<div class="static" id="static"><table><thead><tr><th class="r">#</th>']
    for _i, c in cols:
        out.append('<th%s>%s</th>' % (' class="r"' if c["type"] != "text" else "", _html.escape(c["label"].replace("{x}", gain_x_text()))))
    out.append("</tr></thead><tbody>")
    for n, j in enumerate(order[:limit], 1):
        row = sc["rows"][j]
        out.append('<tr><td class="r">%d</td>' % n)
        for i, c in cols:
            txt = _html.escape(_static_cell(c, row[i]))
            if c.get("m", -1) >= 0 and sc.get("ranks") and sc["ranks"][j][c["m"]] is not None:
                txt += "<small>#%s</small>" % _group(sc["ranks"][j][c["m"]])
            out.append('<td%s>%s</td>' % (' class="r"' if c["type"] != "text" else "", txt))
        out.append("</tr>")
    out.append("</tbody></table>")
    if len(order) > limit:
        out.append('<div class="more">… und %s weitere Zeilen – vollständig, sortier- und durchsuchbar nur im Browser.</div>'
                   % _group(len(order) - limit))
    out.append("</div>")
    return "".join(out)


# Profil der Online-Liste: Werte je Spieler (nur im neuesten Scan der Datei), Reihenfolge = PF_KEYS
PF_KEYS = ("lv", "bs", "ts", "hp", "hof", "alb", "arm", "wd", "iq", "upg", "gem", "mt", "md", "rg", "re", "rq", "rx", "rh", "rd",
           "ph", "pg", "wl", "wb", "wt", "pl", "pb", "pts", "la", "cts", "pm", "pc", "pw", "dt")
_PF_FIELDS = {"lv": "level", "bs": "base_sum", "ts": "total_sum", "hp": "hp", "hof": "rank", "alb": "album", "arm": "armor",
              "wd": "weapon_dmg", "iq": "item_quality", "upg": "upgrade", "gem": "gem_avg", "mt": "mount", "md": "mount_days",
              "rg": "rune_gold", "re": "rune_epic", "rq": "rune_quality", "rx": "rune_xp", "rh": "rune_hp", "rd": "rune_dmg",
              "ph": "portal_hp", "pg": "portal_guild", "la": "last_active", "cts": "_ts", "pm": "pot_main", "pc": "pot_con",
              "pw": "pot_life"}


def world_ranks(pool):
    """{(Server, Name klein): (Platz Level, Platz Base Sum, Platz Total Sum)} ueber alle Spieler des Scans (Worldrank)."""
    import bisect
    keys = ("level", "base_sum", "total_sum")
    negs = {k: sorted(-float(r[k]) for r in pool if r.get(k) is not None) for k in keys}
    out = {}
    for r in pool:
        rk = []
        for k in keys:
            v = r.get(k)
            rk.append(bisect.bisect_left(negs[k], -float(v)) + 1 if v is not None else None)
        try:
            out[cp(r)] = tuple(rk)
        except Exception:
            pass
    return out


def profile_row(r, profile):
    """Eine Zeile Profil-Daten (Liste in der Reihenfolge PF_KEYS)."""
    row = []
    wr = (profile.get("wr") or {}).get(cp(r)) if r.get("_srv") is not None and r.get("name") else None
    pv = r.get("_prev")
    for k in PF_KEYS:
        if k in _PF_FIELDS:
            v = r.get(_PF_FIELDS[k])
        elif k in ("wl", "wb", "wt"):
            v = wr[("wl", "wb", "wt").index(k)] if wr else None
        elif k == "pl":
            v = pv.get("level") if pv is not None else None
        elif k == "pb":
            v = pv.get("base_sum") if pv is not None else None
        elif k == "pts":
            v = pv.get("_ts") if pv is not None else None
        elif k == "dt":                                  # Festung, Runen, Pets, Portal, Rahmen, Traenke, Werte wie im Spiel
            dts = profile.get("dts", None)
            ok = dts is None or (r.get("guild") and r.get("_srv") is not None and "|".join(cgk(r["_srv"], r["guild"])) in dts)
            row.append(_mg_trim([_mg_v(r.get(x)) for x in MG_DK]) or None if ok else None)
            continue
        else:
            v = None
        row.append(_jnum(v))
    while row and row[-1] is None:
        row.pop()
    return row or None


PACK_MIN = 1500000        # ab so vielen Zeichen Seitendaten wird gepackt (kleine Seiten bleiben lesbar)
WEB_WARN_MB = 20.0        # ab dieser Groesse fragt das Programm vor dem Speichern nach


def _pack_num(v):
    """Zahl einer Zelle fuer die Plaetze (Wert oder erster Teil von [Zahl, Text])."""
    if isinstance(v, list):
        v = v[0] if v else None
    return v if isinstance(v, (int, float)) and not isinstance(v, bool) else None


def html_pack(spec, far=None, only=None):
    """Seitendaten fuer grosse Dateien: jede Spalte als eigene Liste, Spieler (Schluessel + Name), Texte und
    Symbol-Kombinationen je einmal in einer Tabelle, Plaetze weg, wenn die Seite sie selbst ausrechnen kann
    (alle Spieler des Scans in der Seite). Die Seite baut daraus wieder genau dieselben Daten.
    far = Scans (Nummern), die nur als Platzhalter hineinkommen (Online: Verlauf in eigener Datei);
    only = nur diese Scans (Online: Inhalt einer Verlaufs-Datei, {Nummer: Scan})."""
    S, Si, PL, Pi, IC, ICi = [], {}, [], {}, [], {}

    def sid(x):
        i = Si.get(x)
        if i is None:
            i = Si[x] = len(S)
            S.append(x)
        return i

    def pid(k, n):
        i = Pi.get((k, n))
        if i is None:
            i = Pi[(k, n)] = len(PL)
            PL.append([k, n])
        return i

    def icid(lst):
        t = tuple(lst or ())
        i = ICi.get(t)
        if i is None:
            i = ICi[t] = len(IC)
            IC.append(list(t))
        return i

    def ranks_auto(sp, sc, mcol, nm):
        rk, rows = sc.get("ranks"), sc["rows"]
        if (not rk or nm == 0 or any(m not in mcol for m in range(nm)) or sc.get("n_total") != len(rows)
                or any(r is None or len(r) != nm for r in rk)):
            return False
        n = len(rows)
        for m in range(nm):
            j = mcol[m]
            vals = [_pack_num(r[j]) for r in rows]
            if any(vals[i] is None and rk[i][m] is not None for i in range(n)):
                return False                             # Plaetze ohne Wert (z. B. Zuwachs, den die Seite selbst rechnet)
            if all(v is None or type(v) is int for v in vals):
                continue                                 # ganze Zahlen: genau die Werte, aus denen das Programm die Plaetze rechnet
            idx = sorted((i for i in range(n) if vals[i] is not None), key=vals.__getitem__, reverse=True)
            start, prev = 0, None
            for p, i in enumerate(idx):              # Platz = Position des ersten gleichen Werts + 1
                v = vals[i]
                if p == 0 or v != prev:
                    start, prev = p, v
                if rk[i][m] != start + 1:
                    return False
        return True

    def pack(sp, top=False):
        sp = dict(sp)
        cols = sp["cols"]
        ids = [c["id"] for c in cols]
        nci = next((ids.index(k) for k in ("name", "g_name") if k in ids), None)
        nm = len(sp.get("metrics") or [])
        mcol = {c["m"]: j for j, c in enumerate(cols) if c.get("m", -1) >= 0}
        out, idx = [], []
        for si, sc in enumerate(sp["scans"]):
            if top and only is not None and si not in only:
                continue
            if top and far and si in far:                        # Online: Scan steht in einer Verlaufs-Datei
                out.append({"far": 1, "label": sc.get("label"), "ts": sc.get("ts"), "n_total": sc.get("n_total"), "n": len(sc["rows"])})
                idx.append(si)
                continue
            idx.append(si)
            rows, q = sc["rows"], {}
            for k, v in sc.items():
                if k not in ("rows", "keys", "ranks", "ic", "pf"):
                    q[k] = v
            q["n"] = len(rows)
            keys = sc.get("keys")
            if keys is not None:
                q["p"] = [pid(k, rows[i][nci] if nci is not None else None) for i, k in enumerate(keys)]
            cc = []
            for j, c in enumerate(cols):
                col = [r[j] for r in rows]
                if j == nci and keys is not None:
                    cc.append(0)                                   # Name kommt aus der Spieler-Tabelle
                elif c["type"] == "text" and all(v is None or isinstance(v, str) for v in col):
                    cc.append({"s": [None if v is None else sid(v) for v in col]})
                elif c["type"] == "numtxt" and all(v is None or (isinstance(v, list) and len(v) == 2 and
                                                                 (v[1] is None or isinstance(v[1], str))) for v in col):
                    cc.append({"n": [None if v is None else v[0] for v in col],
                               "t": [None if v is None else (-1 if v[1] is None else sid(v[1])) for v in col]})
                else:
                    cc.append(col)
            q["c"] = cc
            if sc.get("ranks") is not None:
                if ranks_auto(sp, sc, mcol, nm):
                    q["ra"] = 1                                     # Plaetze rechnet die Seite selbst
                else:
                    w = max([len(r) for r in sc["ranks"] if r] or [0])
                    q["r"] = [[(r[m] if r is not None and m < len(r) else None) for r in sc["ranks"]] for m in range(w)]
                    q["rz"] = [i for i, r in enumerate(sc["ranks"]) if r is None]
            if sc.get("ic") is not None:
                q["ic"] = [icid(x) for x in sc["ic"]]
            if sc.get("pf") is not None:
                pf = sc["pf"]
                w = max([len(x) for x in pf if x] or [0])
                q["pf"] = [[(x[m] if x and m < len(x) else None) for x in pf] for m in range(w)]
                q["pz"] = [i for i, x in enumerate(pf) if not x]
            out.append(q)
        sp["scans"] = {str(i): q for i, q in zip(idx, out)} if (top and only is not None) else out
        if isinstance(sp.get("gv"), dict) and not (top and only is not None):
            sp["gv"] = pack(sp["gv"])
        return sp

    body = pack(spec, True)
    if only is not None:
        return {"v": 1, "S": S, "P": PL, "IC": IC, "scans": body["scans"]}
    return {"v": 1, "S": S, "P": PL, "IC": IC, "spec": body}


def _page_marks(page, spec):
    """Fuer "Fehler melden" (auch wenn die Daten nicht laden): Erstellungszeit der Seite und Ansprechpartner."""
    cl = lambda t: re.sub(r"[\\\"<>\r\n]", "", str(t or ""))[:80]
    made = fmt_ts(spec.get("created")) if spec.get("created") else datetime.datetime.now().strftime("%d.%m.%Y %H:%M")
    return page.replace("__MADE__", cl(made)).replace("__CONTACT__", cl(spec.get("contact") or "Deinnachbar (Discord)"))


def guild_cover(gl, players, prev=None, min_mem=45, have_extra=()):
    """Luecken im Scan je Gilde (wie die Scan-Pruefung): Mitgliederliste der Gilde gegen die gescannten Spieler desselben Servers.
    Setzt g["_cov"] = [gescannt, Mitglieder, "n" | "p", [fehlende Namen, hoechstens 12], Anzahl fehlender] bei Gilden ab min_mem Mitgliedern mit Luecke:
    "n" = neue Luecke (vorher vollstaendig) oder Gilde neu im Scan, "p" = fehlte schon im vorigen Scan.
    prev = (Spieler, Gilden) des vorigen Scans oder None."""
    have = {cp(p) for p in players or () if p.get("_srv") is not None and p.get("name")}
    have.update(have_extra or ())                               # ausgeblendete Spieler wurden gescannt
    pdone = {}
    if prev:
        ph = {cp(p) for p in prev[0] or () if p.get("_srv") is not None and p.get("name")}
        for g in newest_groups(list(prev[1] or [])):
            nm = list(g.get("_names") or [])
            if nm:
                pdone[_canon("g", g["_srv"], str(g.get("name") or "").lower())] = all(_canon("p", g["_srv"], str(n).lower()) in ph for n in nm)
    for g in gl or ():
        try:
            g.pop("_cov", None)
        except Exception:
            pass
        names = list(g.get("_names") or [])
        try:
            mem = int(g.get("g_members") or len(names) or 0)
        except (TypeError, ValueError):
            mem = len(names)
        if mem < min_mem or not names or g.get("_srv") is None:
            continue
        srv = g["_srv"]
        miss = [str(n) for n in names if _canon("p", srv, str(n).lower()) not in have]
        if not miss:
            continue
        before = pdone.get(_canon("g", srv, str(g.get("name") or g.get("g_name") or "").lower()))
        g["_cov"] = [max(0, len(names) - len(miss)), mem, "p" if before is False else "n", miss[:12], len(miss)]


def html_page(spec, pack=None, level=5):
    """Fertige Seite. Grosse Seitendaten werden gepackt (gzip, base64) - die Seite entpackt sie beim Oeffnen.
    Die Symbole (Bilder) bleiben ungepackt daneben stehen (sie sind schon gepackt)."""
    import html as _html
    import gzip as _gzip
    import base64 as _b64
    data = json.dumps(spec, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    page = _page_marks(HTML_TEMPLATE.replace("__TITLE__", _html.escape(spec.get("title") or "Topliste")), spec)
    icons = spec.get("icons")
    if pack is None:
        pack = len(data) - len(json.dumps(icons or {}, separators=(",", ":"))) >= PACK_MIN
    page = page.replace("__SUB__", spec.get("sub") or "").replace("<!--__STATIC__-->", html_static(spec, 200 if pack else 1000))
    if pack:
        body = {k: (None if k == "icons" else v) for k, v in spec.items()}   # Platz bleibt, Inhalt steht daneben
        raw = json.dumps(html_pack(body), ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        blob = _b64.b64encode(_gzip.compress(raw, level, mtime=0)).decode("ascii")
        side = json.dumps({"icons": icons} if icons is not None else None, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
        return page.replace("/*__ONLINE__*/", "").replace("/*__DATA__*/null", side).replace("/*__PACK__*/", blob)
    return page.replace("/*__ONLINE__*/", "").replace("/*__DATA__*/null", data).replace("/*__PACK__*/", "")


ONLINE_MAX_MB = 20.0         # Online: hoechstens so gross je Datei (GitHub nimmt beim Hochladen im Browser bis 25 MB)
ONLINE_ROWS = 200000         # Online: so viele Zeilen je Verlaufs-Datei (danach die naechste)
ONLINE_FILE_RE = re.compile(r"^(index\.html|daten-aktuell\.dat|daten-verlauf-\d+\.dat)$", re.I)


def html_online(spec, level=5):
    """Online-Version fuer GitHub Pages: index.html (die Seite ohne Scans) + daten-aktuell.dat (die zwei neuesten Scans,
    Gilden, Profil) + daten-verlauf-N.dat (aeltere Scans, laedt die Seite erst, wenn sie gebraucht werden).
    -> [(Dateiname, Bytes)]. Es kommen nur die Spalten der Seite hinein - nie Roh-Scans."""
    import gzip as _gzip
    import hashlib as _hl
    import html as _html
    dump = lambda o: json.dumps(o, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    scans = spec["scans"]
    far = list(range(0, max(0, len(scans) - 2)))
    files, hist, groups, cur, rows = [], [], [], [], 0
    for i in far:
        k = len(scans[i]["rows"])
        if cur and rows + k > ONLINE_ROWS:
            groups.append(cur)
            cur, rows = [], 0
        cur.append(i)
        rows += k
    if cur:
        groups.append(cur)
    def seal(pk):                                  # Kennung (Pruefsumme des Inhalts): die Seite erkennt so einen alten Stand
        pk["id"] = _hl.sha1(dump(pk)).hexdigest()[:10]
        return pk["id"], _gzip.compress(dump(pk), level, mtime=0)
    gi = 0
    while gi < len(groups):
        g = groups[gi]
        hid, blob = seal(html_pack(spec, only=set(g)))
        if len(blob) > ONLINE_MAX_MB * 1048576 and len(g) > 1:     # zu gross: Gruppe teilen
            groups[gi:gi + 1] = [g[:len(g) // 2], g[len(g) // 2:]]
            continue
        name = "daten-verlauf-%d.dat" % (len(hist) + 1)
        hist.append({"f": name, "h": hid, "s": g})
        files.append((name, blob))
        gi += 1
    body = {k: (None if k == "icons" else v) for k, v in spec.items()}
    pk = html_pack(body, far=set(far))
    pk["h"] = hist
    aid, blob = seal(pk)
    files.insert(0, ("daten-aktuell.dat", blob))
    icons = spec.get("icons")
    side = json.dumps({"icons": icons} if icons is not None else None, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    page = _page_marks(HTML_TEMPLATE.replace("__TITLE__", _html.escape(spec.get("title") or "Topliste")), spec)
    page = page.replace("__SUB__", spec.get("sub") or "").replace("<!--__STATIC__-->", html_static(spec, 50))
    cfg = json.dumps({"a": "daten-aktuell.dat", "v": aid})
    page = page.replace("/*__ONLINE__*/null", cfg).replace("/*__DATA__*/null", side).replace("/*__PACK__*/", "")
    files.insert(0, ("index.html", page.encode("utf-8")))
    return files


def parse_presets(text):
    """Zeilen 'Name = Suchbegriffe' -> [(Name, Begriffe)] (ohne '=' ist die Zeile beides)."""
    out = []
    for line in str(text or "").splitlines():
        line = line.strip()
        if not line:
            continue
        if "=" in line:
            a, b = line.split("=", 1)
            a, b = a.strip(), b.strip()
        else:
            a = b = line
        if a and b:
            out.append((a, b))
    return out


