C = dict(bg="#1e1f22", panel="#2b2d31", panel2="#313338", field="#383a40", fg="#dbdee1", dim="#949ba4",
         accent="#5865f2", accent_h="#4752c4", ok="#23a559", warn="#f0b232", err="#f23f43", sel="#404249")
MARK_UP, MARK_DOWN, MARK_TP = "#57d98b", "#ff6b6b", "#c79bff"     # Pfeile (Platz gut gemacht / verloren), Top-Performer
TP_SIGN = "\u2726"                                              # Zeichen fuer Top-Performer
DEFAULT_FONT_SIZE = 10
FONT = MONO = FONT_HEAD = MONO_B = None
FONT_T = HEAD_T = ("Segoe UI", DEFAULT_FONT_SIZE)   # Tupel-Varianten fuer ttk-Styles (reagieren sicher auf Aenderungen)
_FONT_ROOT = None
FAM = ["Segoe UI", "Consolas"]


def init_fonts(root, size):
    """Benannte Schriftarten: Aendert man ihre Groesse, passen sich alle Widgets sofort an."""
    global FONT, MONO, FONT_HEAD, MONO_B, _FONT_ROOT, FONT_T, HEAD_T
    import tkinter.font as tkfont
    try:
        size = max(7, min(28, int(size)))
    except (TypeError, ValueError):
        size = DEFAULT_FONT_SIZE
    if FONT is None or _FONT_ROOT is not root:
        try:
            have = set(tkfont.families(root))
        except Exception:
            have = set()

        def pick(*names):
            for n in names:
                if n in have:
                    return n
            return names[0] if not have else tkfont.nametofont("TkDefaultFont", root=root).actual("family")
        sans = pick("Segoe UI", "Helvetica Neue", "DejaVu Sans", "Arial")
        mono = pick("Consolas", "Menlo", "DejaVu Sans Mono", "Courier New")
        FAM[0], FAM[1] = sans, mono
        FONT = tkfont.Font(root=root, family=sans, size=size)
        MONO = tkfont.Font(root=root, family=mono, size=size)
        FONT_HEAD = tkfont.Font(root=root, family=sans, size=size + 1, weight="bold")
        MONO_B = tkfont.Font(root=root, family=mono, size=size, weight="bold")
        _FONT_ROOT = root
    else:
        FONT.configure(size=size)
        MONO.configure(size=size)
        FONT_HEAD.configure(size=size + 1)
        MONO_B.configure(size=size)
    FONT_T = (FAM[0], size)
    HEAD_T = (FAM[0], size + 1, "bold")
    for nm in ("TkDefaultFont", "TkTextFont", "TkMenuFont", "TkHeadingFont", "TkFixedFont"):
        try:
            tkfont.nametofont(nm, root=root).configure(size=size)
        except Exception:
            pass
    return size


def set_font_size(root, size):
    size = init_fonts(root, size)
    try:
        st = ttk.Style(root)
        st.configure(".", font=FONT_T)
        for nm in ("TEntry", "TCombobox", "TSpinbox"):
            st.configure(nm, font=FONT_T)
        st.configure("Head.TLabel", font=HEAD_T)
        st.configure("Treeview", font=FONT_T, rowheight=max(22, int(size * 2.2)))
        st.configure("Treeview.Heading", font=FONT_T)
        root.update_idletasks()
    except Exception:
        pass
    return size


def tkstr(s):
    """Zeichen ausserhalb der BMP (z.B. viele Emojis) koennen aeltere Tk-Versionen abstuerzen lassen."""
    return "".join(ch if ord(ch) <= 0xFFFF else "?" for ch in str(s))


