def attach_scroll(parent, widget, horizontal=False):
    vs = ttk.Scrollbar(parent, orient="vertical", command=widget.yview)
    widget.configure(yscrollcommand=vs.set)
    vs.pack(side="right", fill="y")
    hs = None
    if horizontal:
        hs = ttk.Scrollbar(parent, orient="horizontal", command=widget.xview)
        widget.configure(xscrollcommand=hs.set)
        hs.pack(side="bottom", fill="x")
    return vs, hs


if HAVE_TK:


    # ==================================================================================
    #  4.2 Grundbausteine: Scrollen, Mausrad, Tabellen-Linien und -Overlays, Hinweise, Scan-Leiste, Editoren
    # ==================================================================================
    SCROLLERS = []

    class ScrollFrame(ttk.Frame):
        """Scrollbarer Bereich: Inhalt in self.inner. Das Mausrad scrollt, wenn der Zeiger darueber steht."""

        def __init__(self, master, fill=True, **kw):
            super().__init__(master, **kw)
            self.fill = fill
            self.canvas = tk.Canvas(self, bg=C["bg"], highlightthickness=0, borderwidth=0, yscrollincrement=18)
            self.vs = ttk.Scrollbar(self, orient="vertical", command=self.canvas.yview)
            self.canvas.configure(yscrollcommand=self.vs.set)
            self.vs.pack(side="right", fill="y")
            self.canvas.pack(side="left", fill="both", expand=True)
            self.inner = ttk.Frame(self.canvas)
            self.win = self.canvas.create_window(0, 0, window=self.inner, anchor="nw")
            self.canvas.bind("<Configure>", self._fit, add="+")
            self.inner.bind("<Configure>", self._fit)
            SCROLLERS.append(self)
            self.bind("<Destroy>", self._gone)

        def _gone(self, e):
            if e.widget is self and self in SCROLLERS:
                SCROLLERS.remove(self)

        def _fit(self, _e=None):
            cw, ch = self.canvas.winfo_width(), self.canvas.winfo_height()
            rh = self.inner.winfo_reqheight()
            h = max(ch, rh) if self.fill else rh
            self.canvas.itemconfigure(self.win, width=cw, height=h)
            self.canvas.configure(scrollregion=(0, 0, cw, h))

        def can_scroll(self):
            return self.inner.winfo_reqheight() > self.canvas.winfo_height() + 1

    def _wheel_dispatch(e):
        """Ein Handler fuer alle ScrollFrames: scrollt den Bereich unter dem Mauszeiger."""
        try:
            w = e.widget.winfo_containing(e.x_root, e.y_root)
        except Exception:
            return False
        if w is None:
            return False
        try:
            if w.winfo_class() in ("Text", "Treeview", "Listbox"):
                return False                                   # scrollen selbst
        except Exception:
            return False
        p = w
        while p is not None:
            for sf in SCROLLERS:
                if p is sf.canvas:
                    if sf.can_scroll():
                        up = (getattr(e, "num", 0) == 4) or (getattr(e, "delta", 0) > 0)
                        sf.canvas.yview_scroll(-3 if up else 3, "units")
                    return True
            p = getattr(p, "master", None)
        return False

    def install_wheel(root):
        root.bind_all("<MouseWheel>", _wheel_dispatch, add="+")
        root.bind_all("<Button-4>", _wheel_dispatch, add="+")
        root.bind_all("<Button-5>", _wheel_dispatch, add="+")
        for cls in ("TCombobox", "TSpinbox"):                 # Mausrad soll dort nichts versehentlich umstellen
            for ev in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
                root.bind_class(cls, ev, lambda e: (_wheel_dispatch(e), "break")[1])


    def flow_row(frame, widgets, gap=6):
        """Knopfreihe, die bei schmalem Fenster automatisch auf zwei oder mehr Zeilen umbricht statt abgeschnitten zu werden."""
        state = {"pos": None}
        n = len(widgets)

        def relayout(_e=None):
            width = frame.winfo_width()
            if width <= 1:
                return
            req = [w.winfo_reqwidth() for w in widgets]
            for rows in range(1, n + 1):
                per = -(-n // rows)                                  # Knoepfe je Zeile
                cols = [max(req[i] for i in range(c, n, per)) for c in range(per)]     # Spaltenbreite = breitester Knopf darin
                if sum(cols) + gap * (per - 1) <= width or rows == n:
                    break
            pos = [(i // per, i % per) for i in range(n)]
            if pos != state["pos"]:
                state["pos"] = pos
                for w, (rr, cc) in zip(widgets, pos):
                    w.grid(row=rr, column=cc, sticky="w", padx=(0, gap), pady=(3, 0) if rr else 0)
        for i, w in enumerate(widgets):
            w.grid(row=0, column=i, sticky="w", padx=(0, gap))
        frame.bind("<Configure>", relayout, add="+")
        return relayout


    class GridLines:
        """Feine senkrechte Trennlinien zwischen den Spalten eines Treeviews (dezente Farbe, nur im Datenbereich)."""
        COLOR = GRID_COLOR         # heller als beide Zeilenfarben (#2b2d31 / #33353b), aber nicht grell

        def __init__(self, tree, hscroll=None, on_change=None):
            self.tree, self.lines, self._pending, self.on_change = tree, [], False, on_change
            for ev in ("<Configure>", "<B1-Motion>", "<ButtonRelease-1>", "<Map>"):
                tree.bind(ev, self.schedule, add="+")
            if hscroll is not None:                       # beim Seitwaertsscrollen mitwandern
                def xs(a, b):
                    hscroll.set(a, b)
                    self.schedule()
                tree.configure(xscrollcommand=xs)

        def schedule(self, _e=None):
            if self.on_change:
                self.on_change()
            if not self._pending:
                self._pending = True
                self.tree.after_idle(self.place)

        def place(self):
            self._pending = False
            tree = self.tree
            try:
                cols = list(tree["displaycolumns"])
                if not cols or cols[0] == "#all":
                    cols = list(tree["columns"])
                kids = tree.get_children()
                H, W = tree.winfo_height(), tree.winfo_width()
                if not cols or not kids or H < 30:
                    xs = []
                else:
                    widths = [int(tree.column(c, "width")) for c in cols]
                    off = tree.xview()[0] * sum(widths)
                    hh = _header_h(tree)
                    try:
                        rowh = int(ttk.Style().lookup("Treeview", "rowheight") or 22)
                    except (TypeError, ValueError):
                        rowh = 22
                    end = min(H, hh + len(kids) * rowh)
                    xs, acc = [], 0
                    for w in widths:
                        acc += w
                        x = int(acc - off) - 1
                        if 0 < x < W - 2:
                            xs.append(x)
            except tk.TclError:
                return
            while len(self.lines) < len(xs):
                self.lines.append(tk.Frame(tree, bg=self.COLOR, width=1, bd=0, highlightthickness=0))
            for i, fr in enumerate(self.lines):
                if i < len(xs):
                    fr.place(x=xs[i], y=hh, width=1, height=max(1, end - hh))
                else:
                    fr.place_forget()

    class Tip:
        """Kleiner Hinweistext, wenn die Maus kurz ueber einem Widget verweilt."""

        def __init__(self, w, text, delay=450):
            self.w, self.text, self.delay, self._id, self.tw = w, text, delay, None, None
            w.bind("<Enter>", self._enter, add="+")
            w.bind("<Leave>", self._leave, add="+")
            w.bind("<ButtonPress>", self._leave, add="+")

        def _enter(self, _e=None):
            self._leave()
            self._id = self.w.after(self.delay, self._show)

        def _leave(self, _e=None):
            if self._id:
                try:
                    self.w.after_cancel(self._id)
                except tk.TclError:
                    pass
                self._id = None
            if self.tw is not None:
                try:
                    self.tw.destroy()
                except tk.TclError:
                    pass
                self.tw = None

        def _show(self):
            self._id = None
            try:
                x, y = self.w.winfo_rootx() + 14, self.w.winfo_rooty() + self.w.winfo_height() + 4
                self.tw = tw = tk.Toplevel(self.w)
                tw.wm_overrideredirect(True)
                tw.wm_geometry("+%d+%d" % (x, y))
                tk.Label(tw, text=tkstr(self.text), justify="left", wraplength=360, bg=C["panel2"], fg=C["fg"], font=FONT,
                         relief="solid", bd=1, padx=8, pady=5).pack()
            except tk.TclError:
                self.tw = None


    PICK_SORTS = [("name", "Name"), ("level", "Ø Level"), ("base", "Ø Base Sum"), ("n", "Spieler")]

    def _pick_sort_bar(parent, var, command):
        """Knopfreihe 'Sortieren: Name | Ø Level | Ø Base Sum | Spieler' fuer die Auswahl-Fenster."""
        fr = ttk.Frame(parent)
        ttk.Label(fr, text="Sortieren:").pack(side="left")
        btns = {}

        def upd():
            for k, b in btns.items():
                b.configure(style="Accent.TButton" if var.get() == k else "TButton")
        for k, t in PICK_SORTS:
            b = ttk.Button(fr, text=t, command=lambda kk=k: (var.set(kk), upd(), command()))
            b.pack(side="left", padx=(6 if k == "name" else 3, 0))
            btns[k] = b
        upd()
        return fr

    def _avg_txt(s_, n_, big=False):
        if not n_:
            return "–"
        v = s_ / n_
        return _group(int(round(v))) if big else fmt_num(round(v, 1))


    _HH_CACHE = {}

    def _header_h(tree):
        """Hoehe der Ueberschriftenzeile eines Treeviews (erste Zeile, die keine Ueberschrift mehr ist).
        Gemerkt je Tabelle und Schriftgroesse - sonst kostet das Nachmessen bei jedem Scrollschritt Zeit."""
        try:
            key = (str(tree), FONT.actual("size"))
            if key in _HH_CACHE:
                return _HH_CACHE[key]
            H = tree.winfo_height()
            W = max(tree.winfo_width(), 10)
            xs = (5, 20, W // 3, W // 2)
            ys = [y for y in range(0, min(H, 90), 2) if any(tree.identify_region(x, y) == "heading" for x in xs)]
            if ys and H > 60:
                _HH_CACHE[key] = max(ys) + 2
            return (max(ys) + 2) if ys else 26
        except tk.TclError:
            return 26

    def _blend(c1, c2, t):
        a = [int(c1[i:i + 2], 16) for i in (1, 3, 5)]
        b = [int(c2[i:i + 2], 16) for i in (1, 3, 5)]
        return "#%02x%02x%02x" % tuple(int(round(x + (y - x) * t)) for x, y in zip(a, b))

    class OvHost:
        """Minimaler Ersatz fuer eine TableTab-Umgebung, damit ColOverlay auch bei anderen Tabellen funktioniert."""
        MEDALS = ()
        grid = None

        def __init__(self, tree, on_dbl=None, on_ctx=None):
            self.tree, self._dbl, self._ctx = tree, on_dbl, on_ctx

        def _open_detail(self, e):
            if self._dbl and self.tree.identify_region(e.x, e.y) == "cell":
                self._dbl(e)

        def _context(self, e):
            if self._ctx:
                self._ctx(e)

    class ColOverlay(tk.Canvas):
        """Zeichnet EINE Spalte eines Treeviews neu (fett und/oder leicht getoent) - ttk kann Schrift und Hintergrund nicht je Spalte.
        Mausklicks werden an den Treeview weitergereicht."""
        _fonts = {}

        def __init__(self, table):
            super().__init__(table.tree, highlightthickness=0, bd=0, bg=C["panel"], cursor="arrow")
            self.table, self.tree = table, table.tree
            self.key, self.bold, self.tint = None, False, False
            self._x0 = self._y0 = 0
            self._last = None
            self.bind("<ButtonPress-1>", self._press)
            for ev in ("<B1-Motion>", "<ButtonRelease-1>"):
                self.bind(ev, lambda e, ev=ev: self._fwd(ev, e))
            for ev in ("<Button-3>", "<Button-2>"):
                self.bind(ev, lambda e: table._context(self._fake(e)))
            for ev in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
                self.bind(ev, self._wheel)
            self._pend = False

        def watch(self, vs, hs=None):
            """Fuer Tabellen ohne eigene Trennlinien: bei Scrollen, Groessenaenderung und Auswahl neu zeichnen."""
            def ys(a, b):
                vs.set(a, b)
                self.schedule()
            self.tree.configure(yscrollcommand=ys)
            if hs is not None:
                def xs(a, b):
                    hs.set(a, b)
                    self.schedule()
                self.tree.configure(xscrollcommand=xs)
            for ev in ("<Configure>", "<Map>", "<<TreeviewSelect>>", "<B1-Motion>", "<ButtonRelease-1>"):
                self.tree.bind(ev, self.schedule, add="+")

        def schedule(self, _e=None):
            if not self._pend:
                self._pend = True
                self.after_idle(self._go)

        def _go(self):
            self._pend = False
            self.layout()

        def _fake(self, e):
            class _E:
                pass
            f = _E()
            f.x, f.y, f.x_root, f.y_root = self._x0 + e.x, self._y0 + e.y, e.x_root, e.y_root
            return f

        def _press(self, e):
            """Klick an den Treeview weiterreichen; einen Doppelklick erkennen wir selbst (weitergereichte Ereignisse
            wuerden Tks eigene Doppelklick-Erkennung stoeren)."""
            t = getattr(e, "time", 0) or 0
            last = self._last
            dbl = last is not None and 0 <= t - last[0] < 450 and abs(e.x - last[1]) < 6 and abs(e.y - last[2]) < 6
            self._last = None if dbl else (t, e.x, e.y)
            if dbl:
                self.table._open_detail(self._fake(e))
                return "break"
            return self._fwd("<ButtonPress-1>", e)

        def _fwd(self, ev, e):
            try:
                self.tree.event_generate(ev, x=self._x0 + e.x, y=self._y0 + e.y, state=e.state)
            except tk.TclError:
                pass
            return "break"

        def _wheel(self, e):
            w = getattr(self.table, "wheel", None)
            if w is not None:
                return w(e)
            up = getattr(e, "num", 0) == 4 or getattr(e, "delta", 0) > 0
            self.tree.yview_scroll(-3 if up else 3, "units")
            return "break"

        def setup(self, key, bold, tint):
            self.key, self.bold, self.tint = key, bold, tint
            self.layout()

        def _font(self):
            if not self.bold:
                return FONT
            k = (FONT.actual("family"), FONT.actual("size"))
            if k not in self._fonts:
                import tkinter.font as tkfont
                self._fonts[k] = tkfont.Font(root=self.tree, family=k[0], size=k[1], weight="bold")
            return self._fonts[k]

        def layout(self):
            tree, key = self.tree, self.key
            try:
                cols = list(tree["displaycolumns"])
                if not cols or cols[0] == "#all":
                    cols = list(tree["columns"])
                if key is None or key not in cols or not tree.winfo_ismapped():
                    self.place_forget()
                    return
                widths = [int(tree.column(c, "width")) for c in cols]
                off = tree.xview()[0] * sum(widths)
                i = cols.index(key)
                x0, w = int(round(sum(widths[:i]) - off)), widths[i]
                H, W = tree.winfo_height(), tree.winfo_width()
                hh = _header_h(tree)
                if x0 + w <= 0 or x0 >= W or H <= hh + 2 or w < 6:
                    self.place_forget()
                    return
                self._x0, self._y0 = x0, hh
                self.place(x=x0, y=hh, width=w - 1, height=H - hh)
                self.redraw(w - 1, hh)
            except tk.TclError:
                return

        _trunc = {}
        _twc = {}

        def _tw(self, txt, font):
            """Textbreite in Pixeln (gemerkt)."""
            key = (txt, str(font))
            w = self._twc.get(key)
            if w is None:
                if len(self._twc) > 20000:
                    self._twc.clear()
                w = self._twc[key] = font.measure(txt)
            return w

        def _fit(self, txt, maxw, font):
            """Text auf die Spaltenbreite kuerzen (Ergebnis gemerkt - Messen ist beim Scrollen der teuerste Teil)."""
            key = (txt, maxw, str(font))
            r = self._trunc.get(key)
            if r is None:
                r = txt
                if font.measure(r) > maxw:
                    while len(r) > 1 and font.measure(r + "…") > maxw:
                        r = r[:-1]
                    r += "…"
                if len(self._trunc) > 50000:
                    self._trunc.clear()
                self._trunc[key] = r
            return r

        def _slot(self, n):
            """Canvas-Elemente einer Zeile (werden wiederverwendet statt jedes Mal neu angelegt)."""
            pool = self.__dict__.setdefault("_pool", [])
            while len(pool) <= n:
                pool.append({"r": self.create_rectangle(0, 0, 0, 0, fill=C["panel"], outline=""),
                             "t": self.create_text(0, 0, text="", anchor="w"), "m": self.create_text(0, 0, text="", anchor="w"),
                             "i": [], "st": None})
            return pool[n]

        def redraw(self, W, hh):
            tree = self.tree
            font = self._font()
            sel = getattr(self.table, "_selset", None)
            if sel is None:
                sel = set(tree.selection())
            anchor = str(tree.column(self.key, "anchor"))
            iid = tree.identify_row(hh + 1)
            tagcol = {}
            H = max(self.winfo_height(), tree.winfo_height() - hh) + hh     # frisch platziert: Hoehe des Treeviews nehmen
            icon_col = self.key is not None and self.key == getattr(self.table, "icon_col", None)
            rowrecs = getattr(self.table, "_rowrec", {})
            markf = getattr(self.table, "col_mark", None)
            n = 0
            while iid and n < 200:
                bb = tree.bbox(iid, self.key)
                if not bb:
                    break
                _x, y, _w, h = bb
                tags = tree.item(iid, "tags")
                bg, fg = C["panel"], C["fg"]
                for t in tags:
                    if t not in tagcol:
                        try:
                            tagcol[t] = (str(tree.tag_configure(t, "background")), str(tree.tag_configure(t, "foreground")))
                        except tk.TclError:
                            tagcol[t] = ("", "")
                    tb, tf = tagcol[t]
                    if tb:
                        bg = tb
                    if tf:
                        fg = tf
                if iid in sel:
                    bg, fg = C["accent"], "#ffffff"
                elif self.tint:
                    bg = _blend(bg, C["accent"], 0.11)
                txt = str(tree.set(iid, self.key))
                maxw = W - 14
                icons, lead = [], []
                if icon_col:
                    rowrec = rowrecs.get(iid)
                    if rowrec is not None and not iid.startswith("g"):    # graue Treffer aus alten Scans: Platz fuer den Hinweis
                        icons, lead = self.table.row_icons(rowrec, h)
                if lead and anchor != "w":                 # CC nur bei linksbuendigem Namen direkt hinter den Text
                    icons, lead = lead + icons, []
                W_txt = W
                isz = max(12, h - 4)
                mk = None
                if markf is not None and not iid.startswith("g"):
                    rr = rowrecs.get(iid)
                    mk = markf(rr, self.key) if rr is not None else None
                mw = self._tw(mk[0], font) + 8 if mk else 0
                if icons or lead:
                    tail_w = sum(ph.width() + 3 for ph in icons)
                    room = tail_w + sum(ph.width() + 3 for ph in lead) + 2
                    maxw -= room
                    W_txt = W - tail_w - 2
                maxw -= mw
                txt = self._fit(txt, maxw, font)
                yt = y - hh
                state = (yt, h, W, bg, fg, txt, str(font), anchor, tuple(str(p) for p in icons), tuple(str(p) for p in lead), mk)
                sl = self._slot(n)
                if sl["st"] != state:                      # nur aendern, was sich geaendert hat
                    self.coords(sl["r"], 0, yt, W, yt + h)
                    self.itemconfigure(sl["r"], fill=bg, state="normal")
                    if anchor == "e":
                        x, an = W_txt - 7, "e"
                    elif anchor == "center":
                        x, an = W_txt / 2, "center"
                    else:
                        x, an = 7, "w"
                    self.coords(sl["t"], x, yt + h / 2)
                    self.itemconfigure(sl["t"], text=txt, fill=fg, font=font, anchor=an, state="normal")
                    lx = 7 + self._tw(txt, font) + 4               # hinter dem Text (bei linksbuendigem Text)
                    if mk:
                        if mk[2] == "after" and an == "w":
                            mx, man = lx, "w"
                            lx += mw - 4
                        elif an == "e":
                            mx, man = 6, "w"                   # Zahlen rechts: Pfeil an den linken Rand
                        else:
                            mx, man = W_txt - 6, "e"
                        self.coords(sl["m"], mx, yt + h / 2)
                        self.itemconfigure(sl["m"], text=mk[0], fill=mk[1], font=font, anchor=man, state="normal")
                    else:
                        self.itemconfigure(sl["m"], state="hidden")
                    pos, xr = [], W - 2
                    for ph in reversed(icons):             # rechtsbuendig (mit Pillow ein Bild fuer alle Symbole der Zeile)
                        xr -= ph.width() + 3
                        pos.append((xr, ph))
                    if lead:                               # direkt hinter dem Namen (Content Creator)
                        for ph in lead:
                            pos.append((lx, ph))
                            lx += ph.width() + 3
                    items = sl["i"]                        # Bild-Elemente wiederverwenden statt loeschen/neu anlegen
                    while len(items) < len(pos):
                        items.append(self.create_image(0, 0, anchor="w"))
                    for it, (ix, ph) in zip(items, pos):
                        self.coords(it, ix, yt + h / 2)
                        self.itemconfigure(it, image=ph, state="normal")
                    for it in items[len(pos):]:
                        self.itemconfigure(it, state="hidden")
                    sl["st"] = state
                n += 1
                if y > H:
                    break
                iid = tree.next(iid)
            for sl in self.__dict__.get("_pool", [])[n:]:            # uebrige Zeilen ausblenden
                if sl["st"] is not None:
                    self.itemconfigure(sl["r"], state="hidden")
                    self.itemconfigure(sl["t"], state="hidden")
                    self.itemconfigure(sl["m"], state="hidden")
                    for it in sl["i"]:
                        self.itemconfigure(it, state="hidden")
                    sl["st"] = None
            for fr in getattr(getattr(self.table, "grid", None), "lines", []):   # Trennlinien bleiben sichtbar (liegen ueber der Spalte)
                fr.lift()

    class SqOverlay(ColOverlay):
        """Zeichnet eine Kaestchen-Spalte (Festung, Runen, Pets, Portal, Rahmen) ueber den Treeview; Maus zeigt den Wert."""

        def __init__(self, table):
            super().__init__(table)
            self._cells = []
            self._tw_ = None
            self.bind("<Motion>", self._motion, add="+")
            self.bind("<Leave>", lambda e: self._tip_hide(), add="+")

        def _tip_hide(self):
            if self._tw_ is not None:
                try:
                    self._tw_.destroy()
                except tk.TclError:
                    pass
                self._tw_ = None

        def _motion(self, e):
            hit = None
            for x0, y0, x1, y1, tip in self._cells:
                if x0 - 1 <= e.x <= x1 + 1 and y0 - 3 <= e.y <= y1 + 3:
                    hit = tip
                    break
            if hit is None:
                self._tip_hide()
                return
            if self._tw_ is not None and getattr(self._tw_, "_txt", None) == hit:
                self._tw_.wm_geometry("+%d+%d" % (e.x_root + 14, e.y_root + 16))
                return
            self._tip_hide()
            try:
                self._tw_ = tw = tk.Toplevel(self)
                tw._txt = hit
                tw.wm_overrideredirect(True)
                tw.wm_geometry("+%d+%d" % (e.x_root + 14, e.y_root + 16))
                tk.Label(tw, text=tkstr(hit), bg=C["panel2"], fg=C["fg"], font=FONT, relief="solid", bd=1, padx=6, pady=3).pack()
            except tk.TclError:
                self._tw_ = None

        def redraw(self, W, hh):
            tree = self.tree
            self.delete("all")
            self._cells = []
            sel = getattr(self.table, "_selset", None)
            if sel is None:
                sel = set(tree.selection())
            rowrecs = getattr(self.table, "_rowrec", {})
            iid = tree.identify_row(hh + 1)
            H = max(self.winfo_height(), tree.winfo_height() - hh) + hh
            n = 0
            while iid and n < 200:
                bb = tree.bbox(iid, self.key)
                if not bb:
                    break
                _x, y, _w, h = bb
                yt = y - hh
                bg = C["panel"]
                for t in tree.item(iid, "tags"):
                    try:
                        tb = str(tree.tag_configure(t, "background"))
                    except tk.TclError:
                        tb = ""
                    if tb:
                        bg = tb
                if iid in sel:
                    bg = C["accent"]
                self.create_rectangle(0, yt, W, yt + h, fill=bg, outline="")
                rec = rowrecs.get(iid)
                cells = sq_cells(self.key, rec) if rec is not None and not iid.startswith("g") else []
                x = 6
                sh = max(9, min(15, h - 8))
                for code, tip, el in cells:
                    y0 = yt + (h - sh) / 2
                    col = SQ_COL.get(code) or ""
                    if code == "f0":
                        self.create_rectangle(x, y0, x + 10, y0 + sh, outline="#8a929c", fill="")
                    else:
                        self.create_rectangle(x, y0, x + 10, y0 + sh, outline="", fill=col)
                        if el == "now":
                            self.create_rectangle(x - 1, y0 - 1, x + 11, y0 + sh + 1, outline="#ffffff", width=1)
                        elif el:
                            self.create_rectangle(x, y0 + sh - 3, x + 10, y0 + sh, outline="", fill=el)
                    self._cells.append((x, y0, x + 10, y0 + sh, tip))
                    x += 13
                n += 1
                if y > H:
                    break
                iid = tree.next(iid)
            for fr in getattr(getattr(self.table, "grid", None), "lines", []):
                fr.lift()

    class ScanBar(ttk.Frame):
        """Scan-Auswahl eines Reiters (wie im Reiter Vergleich): welcher Scan gezeigt wird (neu) und womit verglichen wird (alt).
        Jeder Reiter merkt sich sein eigenes Paar; die Δ-Spalten, Zuwachs-Eintraege und Zu-/Abgaenge rechnen damit."""
        A_NONE = "kein Vergleich"

        def __init__(self, master, app, key):
            super().__init__(master)
            self.app, self.key = app, key
            self.dirty = True
            self._map, self._cur, self._auto = {}, "", ""
            ttk.Label(self, text="Scan (neu):").pack(side="left")
            self.vb = tk.StringVar()
            self.cbb = ttk.Combobox(self, textvariable=self.vb, state="readonly", width=50)
            self.cbb.pack(side="left", padx=(4, 14))
            ttk.Label(self, text="Vergleich mit (alt):").pack(side="left")
            self.va = tk.StringVar()
            self.cba = ttk.Combobox(self, textvariable=self.va, state="readonly", width=50)
            self.cba.pack(side="left", padx=4)
            self.info = ttk.Label(self, text="", style="Dim.TLabel")
            self.info.pack(side="left", padx=10)
            self.cbb.bind("<<ComboboxSelected>>", lambda e: self._picked("b"))
            self.cba.bind("<<ComboboxSelected>>", lambda e: self._picked("a"))
            Tip(self.cbb, "Welcher Scan in diesem Reiter gezeigt wird. Standard: die aktuell geladenen Daten. "
                          "Jeder Reiter (Bestenliste, Ehrenhalle, Gilde) merkt sich seine eigene Auswahl.")
            Tip(self.cba, "Womit verglichen wird (Δ Level, Δ XP, Δ Base, Zuwachs der Gilden, Zu- und Abgänge). "
                          "„automatisch“ nimmt immer den letzten Scan vor dem gezeigten Scan.")
            app.scan_bars.append(self)

        def refresh(self):
            self.dirty = False
            app = self.app
            ents = [e for e in app.lib_entries() if os.path.exists(e["path"])]
            labs, self._map, by_key = [], {}, {}
            for e in ents:
                lab = tkstr(app.scan_label(e))
                if lab in self._map:
                    lab += " [%s]" % os.path.basename(os.path.dirname(e["path"]))
                self._map[lab] = e["key"]
                by_key[e["key"]] = lab
                labs.append(lab)
            eb, ea, auto = app.resolve_pair(self.key)
            n = len(app.sources)
            self._cur = tkstr("Aktuell geladen: %s%s" % (fmt_ts(app.cur_ts(), any(x.get("time") for x in app.sources))
                                                         if app.sources else "noch nichts",
                                                         " (%d Dateien)" % n if n > 1 else ""))
            self.cbb.configure(values=[self._cur] + labs)
            self.vb.set(self._cur if eb is None else by_key.get(eb["key"], self._cur))
            b_ts = eb.get("ts", 0) if eb is not None else app.cur_ts()
            prev = app.previous_entry(b_ts)
            self._auto = tkstr("automatisch: vorheriger Scan (%s)" % fmt_ts(prev["ts"], prev.get("time", True))
                               if prev else "automatisch: vorheriger Scan (keiner vorhanden)")
            self.cba.configure(values=[self._auto, self.A_NONE] + labs)
            a = app.tab_scan_cfg(self.key).get("a") or "auto"
            if a == "auto":
                self.va.set(self._auto)
            elif a == "none":
                self.va.set(self.A_NONE)
            else:
                self.va.set(by_key.get(a, "(Datei nicht mehr vorhanden)"))
            try:
                v = app.view(self.key) if app.data or eb is not None else None
            except Exception:
                v = None
            if v is None:
                self.info.configure(text="")
            elif v["warn"]:
                self.info.configure(text=v["warn"])
            elif v["ea"] is not None:
                days = (v["b_ts"] - v["a_ts"]) / 86400000.0
                self.info.configure(text=tkstr("%s · %s Spieler in beiden Scans" % (app._span(days), _group(v["pairs"]))))
            else:
                self.info.configure(text="ohne Vergleich (Δ-Spalten leer)")

        def _picked(self, which):
            if which == "b":
                v = self.vb.get()
                val = "" if v == self._cur else self._map.get(v, "")
            else:
                v = self.va.get()
                val = "auto" if v == self._auto else ("none" if v == self.A_NONE else self._map.get(v, "auto"))
            self.app.set_tab_scan(self.key, which, val)
            self.refresh()


    class FormDialog(tk.Toplevel):
        """Kleines Formular: Beschriftungen + Eingabefelder -> self.result (Liste) oder None."""

        def __init__(self, master, title, labels, values):
            super().__init__(master)
            self.title(title)
            self.configure(bg=C["bg"])
            self.transient(master)
            self.result = None
            self.vars = []
            body = ttk.Frame(self, padding=14)
            body.pack(fill="both", expand=True)
            for i, (lab, val) in enumerate(zip(labels, values)):
                ttk.Label(body, text=lab).grid(row=i, column=0, sticky="w", pady=4, padx=(0, 10))
                v = tk.StringVar(value=str(val))
                ttk.Entry(body, textvariable=v, width=28).grid(row=i, column=1, pady=4)
                self.vars.append(v)
            bt = ttk.Frame(body)
            bt.grid(row=len(labels), column=0, columnspan=2, sticky="e", pady=(10, 0))
            ttk.Button(bt, text="Abbrechen", command=self.destroy).pack(side="right")
            ttk.Button(bt, text="OK", style="Accent.TButton", command=self._ok).pack(side="right", padx=8)
            self.bind("<Return>", lambda e: self._ok())
            self.grab_set()
            self.wait_window(self)

        def _ok(self):
            self.result = [v.get().strip() for v in self.vars]
            self.destroy()

    class TableEditor(ttk.Frame):
        """Bearbeitbare Tabelle (Hinzufuegen / Bearbeiten / Loeschen)."""

        def __init__(self, master, title, columns, widths, get_rows, set_rows, hint=""):
            super().__init__(master)
            self.columns, self.get_rows, self.set_rows = columns, get_rows, set_rows
            ttk.Label(self, text=title, style="Head.TLabel").pack(anchor="w")
            if hint:
                ttk.Label(self, text=hint, style="Dim.TLabel", wraplength=420, justify="left").pack(anchor="w")
            box = ttk.Frame(self, style="Panel.TFrame")
            box.pack(fill="both", expand=True, pady=4)
            self.tree = ttk.Treeview(box, columns=columns, show="headings", height=9, selectmode="browse")
            for c, w in zip(columns, widths):
                self.tree.heading(c, text=c)
                self.tree.column(c, width=w, anchor="w")
            attach_scroll(box, self.tree)
            self.tree.pack(side="left", fill="both", expand=True)
            self.tree.bind("<Double-Button-1>", lambda e: self.edit())
            bt = ttk.Frame(self)
            bt.pack(fill="x")
            ttk.Button(bt, text="Hinzufügen", command=self.add).pack(side="left")
            ttk.Button(bt, text="Bearbeiten", command=self.edit).pack(side="left", padx=4)
            ttk.Button(bt, text="Löschen", command=self.delete).pack(side="left")
            self.load()

        def load(self):
            self.tree.delete(*self.tree.get_children())
            for row in self.get_rows():
                self.tree.insert("", "end", values=[tkstr(x) for x in row])

        def _rows(self):
            return [list(self.tree.item(i)["values"]) for i in self.tree.get_children()]

        def _commit(self, rows):
            try:
                self.set_rows(rows)
            except Exception as e:
                messagebox.showerror(APP_NAME, "Ungültige Eingabe: %s" % e)
            self.load()

        def add(self):
            dlg = FormDialog(self, "Hinzufügen", self.columns, [""] * len(self.columns))
            if dlg.result and dlg.result[0]:
                rows = [r for r in self._rows() if str(r[0]) != dlg.result[0]] + [dlg.result]
                self._commit(rows)

        def edit(self):
            sel = self.tree.selection()
            if not sel:
                return
            cur = list(self.tree.item(sel[0])["values"])
            dlg = FormDialog(self, "Bearbeiten", self.columns, cur)
            if dlg.result and dlg.result[0]:
                rows = [r for r in self._rows() if str(r[0]) not in (str(cur[0]), dlg.result[0])] + [dlg.result]
                self._commit(rows)

        def delete(self):
            sel = self.tree.selection()
            if sel:
                self.tree.delete(sel[0])
                self._commit(self._rows())

    class GroupEditor(TableEditor):
        """Wie TableEditor, aber die Reihenfolge bleibt beim Bearbeiten erhalten und laesst sich verschieben."""

        def edit(self):
            sel = self.tree.selection()
            if not sel:
                return
            items = list(self.tree.get_children())
            pos = items.index(sel[0])
            cur = list(self.tree.item(sel[0])["values"])
            dlg = FormDialog(self, "Bearbeiten", self.columns, cur)
            if dlg.result and dlg.result[0]:
                rows = self._rows()
                rows[pos] = dlg.result
                self._commit(rows)

        def add(self):
            dlg = FormDialog(self, "Hinzufügen", self.columns, [""] * len(self.columns))
            if dlg.result and dlg.result[0]:
                self._commit(self._rows() + [dlg.result])

        def move(self, d):
            sel = self.tree.selection()
            if not sel:
                return
            items = list(self.tree.get_children())
            i = items.index(sel[0])
            j = i + d
            if not 0 <= j < len(items):
                return
            rows = self._rows()
            rows[i], rows[j] = rows[j], rows[i]
            self._commit(rows)
            self.tree.selection_set(self.tree.get_children()[j])


    # ==================================================================================
    #  4.3 Diagramme und Trend (Entwicklung, Zuwachs-Rechner)
    # ==================================================================================
    SERIES_COLORS = ["#5865f2", "#f0b232", "#23a559", "#f23f43", "#eb459e", "#00b0f4", "#b48cf2", "#e67e22",
                     "#9be564", "#26d0c2", "#c9cdfb", "#ff8a80"]

    class LineChart(tk.Canvas):
        """Liniendiagramm (Zeit auf der x-Achse) mit mehreren Linien, Legende, Zuwachs auf der Linie und Hover-Info."""

        def __init__(self, master, height=300, **kw):
            super().__init__(master, bg=C["panel"], highlightthickness=0, height=height, **kw)
            self.series, self.mode, self.marks, self._geo = [], "abs", [], None
            self.show_values, self.show_delta = True, True
            self.offsets = {}                                   # frei verschobene Zahlen: Schluessel -> (dx, dy)
            self._lblkeys, self._drag = {}, None
            self.bind("<Configure>", lambda e: self.redraw())
            self.bind("<Motion>", self._motion)
            self.bind("<Leave>", lambda e: self.delete("tip"))

        def set_series(self, series, mode="abs", marks=()):
            """series = [{name, color, pts=[(ts, wert)], fmt}] ; mode = abs | pct ; marks = hervorgehobene Zeitpunkte."""
            self.series, self.mode, self.marks = series, mode, list(marks)
            self.redraw()

        @staticmethod
        def _nice(lo, hi, n=5):
            span = hi - lo
            if span <= 1e-9:
                pad = max(1.0, abs(hi) * 0.05)
                lo, hi, span = lo - pad, hi + pad, 2 * pad
            raw = span / (n - 1)
            mag = 10 ** math.floor(math.log10(raw))
            step = next(m * mag for m in (1, 2, 2.5, 5, 10) if raw <= m * mag * 1.0000001)
            return math.floor(lo / step) * step, math.ceil(hi / step) * step, step

        def reset_offsets(self):
            self.offsets = {}
            self.redraw()

        def _label(self, x, y, txt, color, key, font=None):
            """Zahl mit dezentem Hintergrund; mit der Maus verschiebbar (Doppelklick = zurueck)."""
            dx, dy = self.offsets.get(key, (0, 0))
            n = len(self._lblkeys)
            tag = "L%d" % n
            self._lblkeys[tag] = key
            t = self.create_text(x + dx, y + dy, text=txt, fill=color, font=font or FONT, tags=("lbl", tag))
            bb = self.bbox(t)
            r = self.create_rectangle(bb[0] - 3, bb[1] - 1, bb[2] + 3, bb[3] + 1, fill=C["panel"], outline="", tags=("lbl", tag))
            self.tag_lower(r, t)

        def _lbl_tag(self):
            cur = self.find_withtag("current")
            if not cur:
                return None
            return next((t for t in self.gettags(cur[0]) if t.startswith("L") and t[1:].isdigit()), None)

        def _lbl_press(self, e):
            tg = self._lbl_tag()
            self._drag = (tg, e.x, e.y) if tg else None
            self.delete("tip")

        def _lbl_drag(self, e):
            if not self._drag:
                return
            tg, lx, ly = self._drag
            dx, dy = e.x - lx, e.y - ly
            self.move(tg, dx, dy)
            key = self._lblkeys.get(tg)
            ox, oy = self.offsets.get(key, (0, 0))
            self.offsets[key] = (ox + dx, oy + dy)
            self._drag = (tg, e.x, e.y)

        def _lbl_reset(self, _e):
            tg = self._lbl_tag()
            if tg and self._lblkeys.get(tg) in self.offsets:
                del self.offsets[self._lblkeys[tg]]
                self.redraw()

        def _yvals(self, s):
            pts = s["pts"]
            if self.mode == "pct":
                base = pts[0][1]
                if not base:
                    return None
                return [(v - base) * 100.0 / abs(base) for _t, v in pts]
            return [v for _t, v in pts]

        @staticmethod
        def _sgn(s, d):
            return ("+" if d > 0 else "") + s["fmt"](d)

        def redraw(self):
            self.delete("all")
            self._geo = None
            self._lblkeys = {}
            w, h = self.winfo_width(), self.winfo_height()
            if w < 160 or h < 100:
                return
            ser, ys = [], []
            for s in self.series:
                if s["pts"]:
                    y = self._yvals(s)
                    if y is not None:
                        ser.append(s)
                        ys.append(y)
            L, R, Bm = 96, 26, 40
            if not ser:
                self.create_text(w / 2, h / 2, text="Keine Daten für diese Auswahl", fill=C["dim"], font=FONT)
                return
            if len(ser) > 1:                                   # Legende
                x, yy = L, 10
                for s in ser:
                    if s.get("nolegend"):                      # z.B. Prognose-Linien bei vielen Spielern
                        continue
                    nm = tkstr(s["name"])
                    tw = FONT.measure(nm)
                    if x + tw + 30 > w - R and x > L:
                        x, yy = L, yy + 18
                    self.create_rectangle(x, yy + 2, x + 12, yy + 14, fill=s["color"], outline="")
                    self.create_text(x + 18, yy + 8, text=nm, anchor="w", fill=C["fg"], font=FONT)
                    x += tw + 40
                T = yy + 32
            else:
                self.create_text(L, 14, text=tkstr(ser[0]["name"]), anchor="w", fill=ser[0]["color"], font=FONT_HEAD)
                T = 34
            allv = [v for y in ys for v in y]
            start, end, step = self._nice(min(allv), max(allv))
            x0, x1, y0, y1 = L, w - R, T, h - Bm
            if y1 - y0 < 40:
                return
            Y = lambda v: y1 - (v - start) / (end - start) * (y1 - y0)
            axis = (lambda v: "%s %%" % fmt_num(round(v, 1), signed=True)) if self.mode == "pct" else (
                (lambda v: ser[0]["fmt"](round(v, 2))) if len(ser) == 1 else (lambda v: fmt_num(round(v, 2))))
            v = start
            while v <= end + step * 0.001:
                yv = Y(v)
                self.create_line(x0, yv, x1, yv, fill="#3b3d44")
                self.create_text(x0 - 8, yv, text=tkstr(axis(v)), anchor="e", fill=C["dim"], font=FONT)
                v += step
            tss = sorted({t for s in ser for t, _v in s["pts"]})
            t0, t1 = tss[0], tss[-1]
            if len(tss) == 1:
                X = lambda t: (x0 + x1) / 2
            else:
                X = lambda t: x0 + 20 + (t - t0) / (t1 - t0) * (x1 - x0 - 40)
            last_d = -1e9
            for t in tss:                                      # Datum unten
                x = X(t)
                dt = fmt_ts(t, False)
                dw = FONT.measure(dt)
                if x - dw / 2 - last_d > 12:
                    self.create_text(x, y1 + 16, text=dt, fill=C["dim"], font=FONT)
                    last_d = x + dw / 2
            for t in self.marks:                               # gewaehlte Scans
                if t0 <= t <= t1:
                    self.create_line(X(t), y0, X(t), y1, fill="#f0b232", dash=(5, 3), width=2)
            single = len(ser) == 1
            for s, y in zip(ser, ys):
                xy = [(X(t), Y(val)) for (t, _v), val in zip(s["pts"], y)]
                if len(xy) > 1:
                    if s.get("dash"):
                        self.create_line(*[c for p in xy for c in p], fill=s["color"], width=2, dash=s["dash"])
                    else:
                        self.create_line(*[c for p in xy for c in p], fill=s["color"], width=2)
                last_v = -1e9
                for i, (x, yv) in enumerate(xy):
                    if s.get("hollow"):
                        self.create_oval(x - 4, yv - 4, x + 4, yv + 4, fill=C["panel"], outline=s["color"], width=2)
                    else:
                        self.create_oval(x - 4, yv - 4, x + 4, yv + 4, fill=s["color"], outline=C["panel"])
                    if self.show_values:                       # Wert ueber dem Punkt
                        txt = tkstr(s["fmt"](s["pts"][i][1]))
                        tw = FONT.measure(txt)
                        if not single or x - tw / 2 - last_v > 10 or (s["name"], "v", s["pts"][i][0]) in self.offsets:
                            self._label(x, yv - 13, txt, s["color"] if not single else C["fg"], (s["name"], "v", s["pts"][i][0]))
                            last_v = x + tw / 2
                    if i and self.show_delta:                  # Zuwachs auf der Linie
                        d = s["pts"][i][1] - s["pts"][i - 1][1]
                        txt = tkstr(self._sgn(s, d))
                        tw = FONT.measure(txt)
                        px, py = xy[i - 1]
                        key = (s["name"], "d", s["pts"][i][0])
                        if x - px >= tw + 10 or key in self.offsets:
                            self._label((x + px) / 2, (yv + py) / 2 + 13, txt, s["color"], key, FONT_HEAD)
            self.tag_bind("lbl", "<ButtonPress-1>", self._lbl_press)
            self.tag_bind("lbl", "<B1-Motion>", self._lbl_drag)
            self.tag_bind("lbl", "<Double-Button-1>", self._lbl_reset)
            self.tag_bind("lbl", "<Enter>", lambda e: self.configure(cursor="fleur"))
            self.tag_bind("lbl", "<Leave>", lambda e: self.configure(cursor=""))
            self._geo = {"x0": x0, "x1": x1, "y0": y0, "y1": y1, "xs": [(X(t), t) for t in tss], "ser": ser}

        def _motion(self, e):
            self.delete("tip")
            if self._lbl_tag():
                return
            g = self._geo
            if not g or not (g["x0"] - 12 <= e.x <= g["x1"] + 12 and g["y0"] - 6 <= e.y <= g["y1"] + 6):
                return
            x, ts = min(g["xs"], key=lambda p: abs(p[0] - e.x))
            self.create_line(x, g["y0"], x, g["y1"], fill="#6b6e78", dash=(2, 3), tags="tip")
            lines = [(fmt_ts(ts, True), C["dim"])]
            for s in g["ser"]:
                pts = s["pts"]
                idx = next((i for i, (t, _v) in enumerate(pts) if t == ts), None)
                if idx is None:
                    continue
                txt = "%s: %s" % (s["name"], s["fmt"](pts[idx][1]))
                if idx:
                    txt += "   (%s zum Scan davor)" % self._sgn(s, pts[idx][1] - pts[idx - 1][1])
                lines.append((txt, s["color"]))
            lh = FONT.metrics("linespace") + 3
            bw = max(FONT.measure(tkstr(t)) for t, _c in lines) + 20
            bh = lh * len(lines) + 12
            bx = x + 14 if x + 14 + bw < self.winfo_width() - 4 else x - 14 - bw
            by = g["y0"] + 4
            self.create_rectangle(bx, by, bx + bw, by + bh, fill=C["panel2"], outline="#5a5d66", tags="tip")
            for i, (t, c) in enumerate(lines):
                self.create_text(bx + 10, by + 8 + i * lh, text=tkstr(t), anchor="nw", fill=c, font=FONT, tags="tip")

    class ChartPanel(ttk.Frame):
        """Diagramm + Mehrfachauswahl der Werte (farbige Liste = Legende) + Darstellung (absolut / Prozent)."""
        MODES = ["Absolute Werte", "Veränderung in % seit dem ersten Scan"]

        def __init__(self, master, metrics, default, height=300):
            super().__init__(master)
            self.metrics = metrics                            # [(key, Bezeichnung, kind)]
            self.items = []                                    # [(Bibliothekseintrag, Datensatz)], aelteste zuerst
            self.marks = []
            self._touched = False
            right = ttk.Frame(self)
            right.pack(side="right", fill="y", padx=(8, 0))
            ttk.Label(right, text="Werte (Mehrfachauswahl)").pack(anchor="w")
            lf = ttk.Frame(right, style="Panel.TFrame")
            lf.pack(fill="both", expand=True, pady=(2, 4))
            self.lb = tk.Listbox(lf, selectmode="multiple", exportselection=False, activestyle="none", height=8, width=30,
                                 bg=C["panel"], fg=C["fg"], highlightthickness=0, borderwidth=0, font=FONT)
            attach_scroll(lf, self.lb)
            self.lb.pack(side="left", fill="both", expand=True)
            for i, (k, lab, _kind) in enumerate(metrics):
                self.lb.insert("end", tkstr(lab))
                col = SERIES_COLORS[i % len(SERIES_COLORS)]
                self.lb.itemconfigure(i, foreground=col, selectbackground=col, selectforeground="#15161a")
                if k in default:
                    self.lb.selection_set(i)
            self.lb.bind("<<ListboxSelect>>", self._changed)
            self.mode = tk.StringVar(value=self.MODES[0])
            cb = ttk.Combobox(right, textvariable=self.mode, values=self.MODES, state="readonly", width=28)
            cb.pack(fill="x")
            cb.bind("<<ComboboxSelected>>", lambda e: self._mode_picked())
            self.chart = LineChart(self, height=height)
            self.v_values = tk.BooleanVar(value=True)
            self.v_delta = tk.BooleanVar(value=True)
            for txt, var in (("Werte an den Punkten", self.v_values), ("Zuwachs auf der Linie", self.v_delta)):
                ttk.Checkbutton(right, text=txt, variable=var, command=self._flags_picked).pack(anchor="w", pady=(4, 0))
            ttk.Button(right, text="Zahlen zurücksetzen", command=self.chart.reset_offsets).pack(fill="x", pady=(6, 0))
            ttk.Label(right, text="Zahlen lassen sich mit der Maus verschieben (Doppelklick = zurück). Maus über dem "
                                  "Diagramm zeigt alle Werte eines Scans.", style="Dim.TLabel", wraplength=230,
                      justify="left").pack(anchor="w", pady=(4, 0))
            self.chart.pack(side="left", fill="both", expand=True)
            self._flags_touched = False
            self._last = set(self.lb.curselection())

        def _mode_picked(self):
            self._touched = True
            self.redraw()

        def _flags_picked(self):
            self._flags_touched = True
            self.redraw()

        def _changed(self, _e=None):
            sel = set(self.lb.curselection())
            if not sel:                                        # mindestens ein Wert
                sel = self._last or {0}
                for i in sel:
                    self.lb.selection_set(i)
            if not self._touched:                              # bei mehreren Werten automatisch in Prozent
                self.mode.set(self.MODES[1] if len(sel) > 1 else self.MODES[0])
            self._last = set(sel)
            if not self._flags_touched:                        # Standard: viele Linien = weniger Zahlen
                self.v_values.set(len(sel) == 1)
                self.v_delta.set(len(sel) <= 3)
            self.redraw()

        def set_items(self, items, marks=()):
            self.items, self.marks = items, list(marks)
            self.redraw()

        def redraw(self):
            series = []
            for i in sorted(self.lb.curselection()):
                k, lab, kind = self.metrics[i]
                pts = [(e["ts"], r[k]) for e, r in self.items if r.get(k) is not None]
                fmt = (lambda v: fmt_num(v) + "%") if kind == "pct" else fmt_num
                series.append({"name": lab, "color": SERIES_COLORS[i % len(SERIES_COLORS)], "pts": pts, "fmt": fmt})
            self.chart.show_values, self.chart.show_delta = bool(self.v_values.get()), bool(self.v_delta.get())
            self.chart.set_series(series, "pct" if self.mode.get() == self.MODES[1] else "abs", self.marks)


    def trend_line(pts):
        """Lineare Ausgleichsgerade durch [(Zeit in ms, Wert)] -> {slope (je Tag), t_last, v_last, n, t_first} oder None."""
        pp = [(t / 86400000.0, float(v)) for t, v in pts if v is not None and t]
        if len(pp) < 2:
            return None
        n = float(len(pp))
        mx = sum(x for x, _y in pp) / n
        my = sum(y for _x, y in pp) / n
        sxx = sum((x - mx) ** 2 for x, _y in pp)
        if sxx <= 1e-9:
            return None
        slope = sum((x - mx) * (y - my) for x, y in pp) / sxx
        tl, vl = max(pp)
        return {"slope": slope, "t_last": tl, "v_last": vl, "n": len(pp), "t_first": min(pp)[0]}

    def trend_at(tr, day):
        """Wert der Prognose am Tag 'day' (Tage seit 1970), ausgehend vom letzten echten Wert."""
        return tr["v_last"] + tr["slope"] * (day - tr["t_last"])

    def overtake_text(na, ta, nb, tb, label):
        """Satz zum Ueberholen fuer einen Wert (ta, tb = Trends von Spieler A und B)."""
        if ta is None or tb is None:
            return "%s: zu wenige Scans für eine Prognose." % label
        t0 = max(ta["t_last"], tb["t_last"])
        va, vb = trend_at(ta, t0), trend_at(tb, t0)
        ds = ta["slope"] - tb["slope"]

        def when(days):
            d = datetime.date.fromtimestamp(0) + datetime.timedelta(days=t0 + days)
            return "in etwa %s Tagen (um den %s)" % (_group(max(1, int(round(days)))), d.strftime("%d.%m.%Y"))
        fmt = (lambda v: fmt_num(round(v, 1))) if label == "Level" else (lambda v: fmt_num(round(v)))
        if va >= vb:
            if ds >= 0:
                return "%s: %s liegt vorne (%s) und baut den Vorsprung aus (%s pro Tag)." % (
                    label, na, fmt(va - vb), fmt_num(round(ds, 2) if abs(ds) < 100 else round(ds), signed=True))
            return "%s: %s holt %s %s ein (Vorsprung jetzt %s)." % (label, nb, na, when((va - vb) / -ds), fmt(va - vb))
        if ds <= 0:
            return "%s: %s holt %s bei diesem Tempo nicht ein – der Abstand (%s) wächst um %s pro Tag." % (
                label, na, nb, fmt(vb - va), fmt_num(round(-ds, 2) if abs(ds) < 100 else round(-ds)))
        return "%s: %s holt %s %s ein (Abstand jetzt %s)." % (label, na, nb, when((vb - va) / ds), fmt(vb - va))


    # ==================================================================================
    #  4.4 Dialoge: Hilfe, JSON-Zuordnung, Spalten, Gilden- und Serverauswahl, Gilde suchen,
    #  Entwicklung eines Spielers / einer Gilde ueber alle Scans
