    class InfoDialog(tk.Toplevel):
        """Info & Hilfe: jeder Abschnitt zum Auf- und Zuklappen, Suche ueber alle Texte."""

        def __init__(self, master):
            super().__init__(master)
            self.title("Info & Hilfe")
            self.configure(bg=C["bg"])
            self.geometry("1000x740")
            self.transient(master)
            hd = ttk.Frame(self)
            hd.pack(fill="x", padx=14, pady=(12, 4))
            ttk.Label(hd, text="Info & Hilfe", style="Head.TLabel").pack(side="left")
            ttk.Button(hd, text="Alle zuklappen", command=lambda: self.all(False)).pack(side="right")
            ttk.Button(hd, text="Alle aufklappen", command=lambda: self.all(True)).pack(side="right", padx=6)
            sr = ttk.Frame(self)
            sr.pack(fill="x", padx=14, pady=(0, 6))
            ttk.Label(sr, text="Suchen:").pack(side="left")
            self.q = tk.StringVar()
            qe = ttk.Entry(sr, textvariable=self.q, width=36)
            qe.pack(side="left", padx=6)
            self.hits = ttk.Label(sr, text="Klick auf eine Überschrift klappt sie auf oder zu.", style="Dim.TLabel")
            self.hits.pack(side="left", padx=6)
            self.q.trace_add("write", lambda *a: self._search_soon())
            qe.bind("<Return>", lambda e: self._next_hit())
            f = ttk.Frame(self, style="Panel.TFrame")
            f.pack(fill="both", expand=True, padx=14, pady=(0, 6))
            t = tk.Text(f, wrap="word", font=FONT, cursor="arrow")
            style_text(t)
            attach_scroll(f, t)
            t.pack(side="left", fill="both", expand=True)
            self.t = t
            t.tag_configure("h", font=FONT_HEAD, foreground="#c9cdfb", spacing1=10, spacing3=3)
            t.tag_configure("hit", background="#6b5313", foreground="#ffffff")
            tabs = (210, 470)
            t.tag_configure("th", font=FONT_HEAD, foreground="#c9cdfb", tabs=tabs, lmargin2=tabs[1], background=C["panel2"],
                            spacing1=3, spacing3=3)
            t.tag_configure("r0", tabs=tabs, lmargin2=tabs[1], background=C["panel"], spacing1=2, spacing3=2)
            t.tag_configure("r1", tabs=tabs, lmargin2=tabs[1], background="#33353b", spacing1=2, spacing3=2)
            t.tag_configure("code", font=MONO, foreground="#dbe0ff")
            self.n = 0
            for head, body in HELP:
                self._head(head)
                t.insert("end", body + "\n", (self._b(),))
            for head, cols, rows, note in HELP_TABLES:
                self._head(head)
                bt = self._b()
                if note:
                    t.insert("end", note + "\n", (bt,))
                t.insert("end", "\n" + "\t".join(cols) + "\n", ("th", bt))
                for i, r in enumerate(rows):
                    tag = "r%d" % (i % 2)
                    t.insert("end", tkstr(r[0]), (tag, "code", bt))
                    t.insert("end", tkstr("\t%s\t%s\n" % (r[1], r[2])), (tag, bt))
            self.open = [False] * self.n
            for i in range(self.n):
                t.tag_configure("b%d" % i, elide=True)
            t.configure(state="disabled")
            self._sa = None
            self._hit_i = 0
            ttk.Button(self, text="Schließen", command=self.destroy).pack(anchor="e", padx=14, pady=(0, 12))
            self.bind("<Escape>", lambda e: self.destroy())
            qe.focus_set()

        def _head(self, head):
            i = self.n
            self.n += 1
            tg = "hd%d" % i
            self.t.insert("end", "+  " + head + "\n", ("h", tg))
            self.t.tag_bind(tg, "<Button-1>", lambda e, i=i: self.toggle(i))
            self.t.tag_bind(tg, "<Enter>", lambda e: self.t.configure(cursor="hand2"))
            self.t.tag_bind(tg, "<Leave>", lambda e: self.t.configure(cursor="arrow"))

        def _b(self):
            return "b%d" % (self.n - 1)

        def toggle(self, i, on=None):
            on = (not self.open[i]) if on is None else bool(on)
            if on == self.open[i]:
                return
            self.open[i] = on
            t = self.t
            t.configure(state="normal")
            t.tag_configure("b%d" % i, elide=not on)
            st = t.tag_ranges("hd%d" % i)[0]
            t.delete(st, "%s+1c" % st)
            t.insert(st, "–" if on else "+", ("h", "hd%d" % i))
            t.configure(state="disabled")

        def all(self, on):
            for i in range(self.n):
                self.toggle(i, on)

        def _search_soon(self):
            if self._sa:
                self.after_cancel(self._sa)
            self._sa = self.after(250, self._search)

        def _search(self):
            self._sa = None
            t = self.t
            t.tag_remove("hit", "1.0", "end")
            q = self.q.get().strip()
            if not q:
                self.hits.configure(text="Klick auf eine Überschrift klappt sie auf oder zu.")
                return
            ql = q.lower()
            secs = 0
            for i in range(self.n):
                a = t.tag_ranges("hd%d" % i)[0]
                nx = t.tag_ranges("hd%d" % (i + 1))
                b = nx[0] if nx else "end"
                found = ql in t.get(a, b).lower()
                secs += 1 if found else 0
                self.toggle(i, found)
            cnt, pos = 0, "1.0"
            while True:
                pos = t.search(q, pos, stopindex="end", nocase=True)      # nur sichtbare (aufgeklappte) Abschnitte
                if not pos:
                    break
                end = "%s+%dc" % (pos, len(q))
                t.tag_add("hit", pos, end)
                cnt += 1
                pos = end
            self._hit_i = 0
            self.hits.configure(text=("%d Treffer in %d Abschnitt%s · Enter = nächster Treffer" % (cnt, secs, "" if secs == 1 else "en"))
                                if cnt else "Nichts gefunden.")
            self._next_hit()

        def _next_hit(self):
            r = self.t.tag_ranges("hit")
            if not r:
                return
            k = (self._hit_i % (len(r) // 2)) * 2
            self.t.see(r[k])
            self._hit_i += 1


    class MappingDialog(tk.Toplevel):
        """Ordnet JSON-Felder den Programmfeldern zu."""

        def __init__(self, master, keys, sample, mapping):
            super().__init__(master)
            self.title("JSON-Felder zuordnen")
            self.configure(bg=C["bg"])
            self.result = None
            self.transient(master)
            ttk.Label(self, text="Welches JSON-Feld gehört zu welcher Spalte?", style="Head.TLabel").pack(
                anchor="w", padx=14, pady=(12, 2))
            ttk.Label(self, text="„Name“ ist Pflicht. Nicht vorhandene Felder auf „—“ lassen.",
                      style="Dim.TLabel").pack(anchor="w", padx=14)
            box = ttk.Frame(self)
            box.pack(fill="both", expand=True, padx=14, pady=10)
            canvas = tk.Canvas(box, bg=C["bg"], highlightthickness=0, width=640, height=440)
            vs = ttk.Scrollbar(box, orient="vertical", command=canvas.yview)
            inner = ttk.Frame(canvas)
            inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
            canvas.create_window((0, 0), window=inner, anchor="nw")
            canvas.configure(yscrollcommand=vs.set)
            canvas.pack(side="left", fill="both", expand=True)
            vs.pack(side="right", fill="y")
            self.vars = {}
            self.sample = sample
            choices = ["—"] + list(keys)
            for r, f in enumerate(FIELDS):
                ttk.Label(inner, text=f.label).grid(row=r, column=0, sticky="w", padx=(0, 10), pady=2)
                v = tk.StringVar(value=mapping.get(f.key, "—"))
                cb = ttk.Combobox(inner, textvariable=v, values=choices, state="readonly", width=32)
                cb.grid(row=r, column=1, pady=2)
                lab = ttk.Label(inner, text="", style="Dim.TLabel", width=24)
                lab.grid(row=r, column=2, padx=8, sticky="w")
                self.vars[f.key] = (v, lab)
                v.trace_add("write", lambda *a, k=f.key: self._sample(k))
                self._sample(f.key)
            bt = ttk.Frame(self)
            bt.pack(fill="x", padx=14, pady=(0, 12))
            ttk.Button(bt, text="Abbrechen", command=self.destroy).pack(side="right")
            ttk.Button(bt, text="Übernehmen", style="Accent.TButton", command=self._ok).pack(side="right", padx=8)
            self.grab_set()
            self.wait_window(self)

        def _sample(self, k):
            v, lab = self.vars[k]
            key = v.get()
            lab.configure(text=tkstr(str(self.sample.get(key, ""))[:24]) if key != "—" else "")

        def _ok(self):
            m = {k: v.get() for k, (v, _) in self.vars.items() if v.get() != "—"}
            if "name" not in m:
                messagebox.showwarning(APP_NAME, "Bitte mindestens das Feld „Name“ zuordnen.", parent=self)
                return
            self.result = m
            self.destroy()


    class ColumnsDialog(tk.Toplevel):
        """Spalten der Tabelle waehlen und ordnen: links verfuegbare (nach Gruppen), rechts angezeigte."""

        def __init__(self, app, table):
            super().__init__(app)
            self.table = table
            self.title("Spalten der Tabelle")
            self.configure(bg=C["bg"])
            self.transient(app)
            self.geometry("820x600")
            ttk.Label(self, text="Welche Spalten sollen in der Tabelle stehen?", style="Head.TLabel").pack(
                anchor="w", padx=14, pady=(12, 0))
            ttk.Label(self, text="Links: verfügbare Spalten (Doppelklick = hinzufügen). Rechts: angezeigte Spalten "
                                 "in Reihenfolge (Doppelklick = entfernen).", style="Dim.TLabel").pack(anchor="w", padx=14, pady=(0, 8))
            body = ttk.Frame(self)
            body.pack(fill="both", expand=True, padx=14)
            body.columnconfigure(0, weight=1, uniform="a")
            body.columnconfigure(2, weight=1, uniform="a")
            body.rowconfigure(1, weight=1)
            ttk.Label(body, text="Verfügbar").grid(row=0, column=0, sticky="w")
            ttk.Label(body, text="Angezeigt (von links nach rechts)").grid(row=0, column=2, sticky="w")
            lf = ttk.Frame(body, style="Panel.TFrame")
            lf.grid(row=1, column=0, sticky="nsew")
            self.avail = ttk.Treeview(lf, show="tree", selectmode="extended")
            attach_scroll(lf, self.avail)
            self.avail.pack(side="left", fill="both", expand=True)
            mid = ttk.Frame(body)
            mid.grid(row=1, column=1, padx=8)
            ttk.Button(mid, text="Hinzufügen >", command=self._add).pack(fill="x", pady=2)
            ttk.Button(mid, text="< Entfernen", command=self._remove).pack(fill="x", pady=2)
            ttk.Separator(mid).pack(fill="x", pady=8)
            ttk.Button(mid, text="Hoch", command=lambda: self._move(-1)).pack(fill="x", pady=2)
            ttk.Button(mid, text="Runter", command=lambda: self._move(1)).pack(fill="x", pady=2)
            rf = ttk.Frame(body, style="Panel.TFrame")
            rf.grid(row=1, column=2, sticky="nsew")
            self.shown = tk.Listbox(rf, selectmode="extended", activestyle="none", exportselection=False,
                                    bg=C["panel"], fg=C["fg"], selectbackground=C["accent"], selectforeground="#ffffff",
                                    highlightthickness=0, borderwidth=0, font=FONT)
            attach_scroll(rf, self.shown)
            self.shown.pack(side="left", fill="both", expand=True)
            bot = ttk.Frame(self)
            bot.pack(fill="x", padx=14, pady=12)
            ttk.Button(bot, text="Standard-Spalten", command=self._default).pack(side="left")
            ttk.Button(bot, text="Alle Spalten", command=self._all).pack(side="left", padx=6)
            ttk.Button(bot, text="Schließen", style="Accent.TButton", command=self.destroy).pack(side="right")
            self.avail.bind("<Double-1>", lambda e: self.after_idle(self._add))
            self.shown.bind("<Double-1>", lambda e: self._remove())
            self._keys = list(table._cols())
            self._fill()

        def _fill(self, select=()):
            self.avail.delete(*self.avail.get_children())
            hidden = [k for k in self.table.all_keys if k not in self._keys]
            for gname, ks in self.table.grouped(hidden):
                g = self.avail.insert("", "end", text=tkstr(gname), open=True, tags=("grp",))
                for k in ks:
                    self.avail.insert(g, "end", iid=k, text=tkstr(FIELD_MAP[k].label))
            self.shown.delete(0, "end")
            for k in self._keys:
                self.shown.insert("end", tkstr(FIELD_MAP[k].label))
            for i in select:
                if 0 <= i < len(self._keys):
                    self.shown.selection_set(i)
            self.table.set_cols(self._keys)

        def _add(self):
            new = [i for i in self.avail.selection() if i in FIELD_MAP]
            if not new:
                return
            start = len(self._keys)
            self._keys += new
            self._fill(range(start, len(self._keys)))

        def _remove(self):
            idx = set(self.shown.curselection())
            if not idx:
                return
            keep = [k for i, k in enumerate(self._keys) if i not in idx]
            if not keep:
                return
            self._keys = keep
            self._fill()

        def _move(self, d):
            idx = sorted(self.shown.curselection())
            if not idx:
                return
            ks = self._keys
            if d < 0:
                if idx[0] == 0:
                    return
                for i in idx:
                    ks[i - 1], ks[i] = ks[i], ks[i - 1]
                sel = [i - 1 for i in idx]
            else:
                if idx[-1] == len(ks) - 1:
                    return
                for i in reversed(idx):
                    ks[i + 1], ks[i] = ks[i], ks[i + 1]
                sel = [i + 1 for i in idx]
            self._fill(sel)

        def _default(self):
            self._keys = [k for k in self.table.default_cols if k in FIELD_MAP]
            self._fill()

        def _all(self):
            self._keys = list(self.table.all_keys)
            self._fill()


    class GuildPicker(tk.Toplevel):
        """Gildenauswahl mit Suche (mehrere Begriffe mit Komma) und Mehrfachauswahl: nur die gewaehlten Gilden zaehlen."""

        def __init__(self, app):
            super().__init__(app)
            self.app = app
            self.title("Gilden für die Listen wählen")
            self.configure(bg=C["bg"])
            self.transient(app)
            self.geometry("660x700+%d+%d" % (app.winfo_rootx() + 90, app.winfo_rooty() + 50))
            self.keys, self.vis, self.sel, self._busy, self._after = [], [], set(), False, None
            self.sort = tk.StringVar(value=app.cfg.d.get("pick_sort_g", "name"))
            ttk.Label(self, text="Suche nach Gildenname oder Server – mehrere Begriffe mit Komma trennen (z. B. endgegner, alpha, f8). "
                                 "Klick auf eine Gilde = an/aus, mehrere sind möglich. Es zählen nur die gewählten Gilden – "
                                 "überall im Programm (Bestenliste, Ehrenhalle, Gilden, Vergleich).",
                      style="Dim.TLabel", wraplength=630, justify="left").pack(anchor="w", padx=12, pady=(10, 4))
            fr0 = ttk.Frame(self)
            fr0.pack(fill="x", padx=12)
            ttk.Label(fr0, text="Suche:").pack(side="left")
            self.q = tk.StringVar()
            self.entry = ttk.Entry(fr0, textvariable=self.q)
            self.entry.pack(side="left", fill="x", expand=True, padx=6)
            self.q.trace_add("write", lambda *a: self.fill())
            bb = ttk.Frame(self)
            bb.pack(fill="x", padx=12, pady=(8, 2))
            ttk.Button(bb, text="Alle Treffer wählen", command=lambda: self.bulk("all")).pack(side="left")
            ttk.Button(bb, text="Treffer abwählen", command=lambda: self.bulk("none")).pack(side="left", padx=4)
            ttk.Button(bb, text="Treffer umkehren", command=lambda: self.bulk("inv")).pack(side="left")
            bb2 = ttk.Frame(self)
            bb2.pack(fill="x", padx=12, pady=(0, 6))
            ttk.Button(bb2, text="Keine Gilde", command=self.none_all).pack(side="left")
            ttk.Button(bb2, text="Alle Gilden (Filter aus)", command=self.all_all).pack(side="left", padx=4)
            _pick_sort_bar(self, self.sort, self._resort).pack(fill="x", padx=12, pady=(2, 6))
            fr = ttk.Frame(self)
            fr.pack(fill="both", expand=True, padx=12)
            self.lb = tk.Listbox(fr, selectmode="multiple", exportselection=False, bg=C["field"], fg=C["fg"], selectbackground=C["accent"],
                                 selectforeground="#ffffff", relief="flat", highlightthickness=0, font=FONT, activestyle="none")
            attach_scroll(fr, self.lb)
            self.lb.pack(side="left", fill="both", expand=True)
            self.lb.bind("<<ListboxSelect>>", self._changed)
            self.info = ttk.Label(self, text="", style="Dim.TLabel", wraplength=630, justify="left")
            self.info.pack(anchor="w", padx=12, pady=(6, 0))
            ttk.Button(self, text="Schließen", command=self.destroy).pack(anchor="e", padx=12, pady=8)
            self.reload()
            self.entry.focus_set()

        def _order(self, idx):
            srt = self.sort.get()
            name = lambda k: (idx[k][0].lower(), natural_key(idx[k][1]))
            if srt == "level":
                return sorted(idx, key=lambda k: (-(idx[k][3] / idx[k][4]) if idx[k][4] else 1e18, name(k)))
            if srt == "base":
                return sorted(idx, key=lambda k: (-(idx[k][5] / idx[k][6]) if idx[k][6] else 1e18, name(k)))
            if srt == "n":
                return sorted(idx, key=lambda k: (-idx[k][2], name(k)))
            return sorted(idx, key=name)

        def _resort(self):
            self.app.cfg.d["pick_sort_g"] = self.sort.get()
            self.app.save_soon()
            self.keys = self._order(self.idx)
            self.lb.yview_moveto(0)
            self.fill()

        def reload(self):
            if self._busy:
                return
            idx = self.app.guild_index()
            self.idx = idx
            self.keys = self._order(idx)
            ks = set(self.keys)
            self.sel = set(self.keys) if self.app.guild_all else (set(self.app.guild_sel) & ks)
            self.fill()

        def fill(self):
            self._busy = True
            try:
                y = self.lb.yview()[0]
                terms = parse_terms(self.q.get())
                self.vis = [k for k in self.keys if match_terms(terms, self.idx[k][0], self.idx[k][1])]
                self.lb.delete(0, "end")
                for i, k in enumerate(self.vis):
                    g, srv, n, ls, ln, bs, bn = self.idx[k]
                    self.lb.insert("end", tkstr("%s   ·   %s   ·   %s Spieler   ·   Ø Level %s   ·   Ø Base %s" % (
                        g, srv, _group(n), _avg_txt(ls, ln), _avg_txt(bs, bn, True))))
                    if k in self.sel:
                        self.lb.selection_set(i)
                self.lb.yview_moveto(y)
                self._info()
            finally:
                self._busy = False

        def _info(self):
            n, tot = len(self.sel), len(self.keys)
            txt = "%s von %s Gilden gewählt · %s Treffer in der Suche" % (_group(n), _group(tot), _group(len(self.vis)))
            if n == tot and tot:
                txt += "\nAktuell zählen alle Gilden. Für eine Auswahl zuerst „Keine Gilde“ klicken, dann suchen und Gilden wählen."
            self.info.configure(text=tkstr(txt))

        def _changed(self, _e=None):
            if self._busy:
                return
            chosen = {self.vis[i] for i in self.lb.curselection()}
            for k in self.vis:
                (self.sel.add if k in chosen else self.sel.discard)(k)
            self._info()
            self._later()

        def bulk(self, what):
            for k in self.vis:
                if what == "all":
                    self.sel.add(k)
                elif what == "none":
                    self.sel.discard(k)
                else:
                    (self.sel.discard if k in self.sel else self.sel.add)(k)
            self.fill()
            self._later()

        def none_all(self):
            self.sel = set()
            self.fill()
            self._later()

        def all_all(self):
            self.sel = set(self.keys)
            self.fill()
            self._later()

        def _later(self):
            if self._after:
                self.after_cancel(self._after)
            self._after = self.after(350, self._apply)

        def _apply(self):
            self._after = None
            self._busy = True
            try:
                self.app.set_guilds(set(self.sel), set(self.keys))
            finally:
                self._busy = False
            self._info()

    class ServerPicker(tk.Toplevel):
        """Serverauswahl mit Mehrfachauswahl: nur die gewaehlten Server werden fuer die Listen beruecksichtigt."""

        def __init__(self, app):
            super().__init__(app)
            self.app = app
            self.title("Server für die Listen wählen")
            self.configure(bg=C["bg"])
            self.transient(app)
            self.geometry("560x600+%d+%d" % (app.winfo_rootx() + 80, app.winfo_rooty() + 60))
            self.keys, self.disp, self.cnt, self.vis, self.sel, self._busy = [], {}, {}, [], set(), False
            self.sums = {}
            self.sort = tk.StringVar(value=app.cfg.d.get("pick_sort_s", "name"))
            ttk.Label(self, text="Klick = Server an/aus (mehrere möglich). Es zählen nur die gewählten Server – überall im Programm.",
                      style="Dim.TLabel", wraplength=530, justify="left").pack(anchor="w", padx=12, pady=(10, 4))
            fr0 = ttk.Frame(self)
            fr0.pack(fill="x", padx=12)
            ttk.Label(fr0, text="Filter:").pack(side="left")
            self.q = tk.StringVar()
            ttk.Entry(fr0, textvariable=self.q, width=16).pack(side="left", padx=6)
            self.q.trace_add("write", lambda *a: self.fill())
            bb = ttk.Frame(self)
            bb.pack(fill="x", padx=12, pady=6)
            ttk.Button(bb, text="Alle", command=lambda: self.bulk("all")).pack(side="left")
            ttk.Button(bb, text="Keine", command=lambda: self.bulk("none")).pack(side="left", padx=4)
            ttk.Button(bb, text="Umkehren", command=lambda: self.bulk("inv")).pack(side="left")
            _pick_sort_bar(self, self.sort, self._resort).pack(fill="x", padx=12, pady=(0, 6))
            fr = ttk.Frame(self)
            fr.pack(fill="both", expand=True, padx=12)
            self.lb = tk.Listbox(fr, selectmode="multiple", exportselection=False, bg=C["field"], fg=C["fg"], selectbackground=C["accent"],
                                 selectforeground="#ffffff", relief="flat", highlightthickness=0, font=FONT, activestyle="none")
            attach_scroll(fr, self.lb)
            self.lb.pack(side="left", fill="both", expand=True)
            self.lb.bind("<<ListboxSelect>>", self._changed)
            self.info = ttk.Label(self, text="", style="Dim.TLabel")
            self.info.pack(anchor="w", padx=12, pady=(6, 0))
            ttk.Button(self, text="Schließen", command=self.destroy).pack(anchor="e", padx=12, pady=8)
            self.reload()

        def reload(self):
            if self._busy:
                return
            cnt, disp, sums = Counter(), {}, {}
            for p in self.app.data:
                k = p["_srv"]
                cnt[k] += 1
                disp[k] = p["_srv_disp"]
                sm = sums.setdefault(k, [0.0, 0, 0.0, 0])
                if p.get("level") is not None:
                    sm[0] += p["level"]
                    sm[1] += 1
                if p.get("base_sum") is not None:
                    sm[2] += p["base_sum"]
                    sm[3] += 1
            self.cnt, self.disp, self.sums = cnt, disp, sums
            self.keys = self._order()
            self.sel = set(self.keys) if self.app.server_all else (set(self.app.server_sel) & set(self.keys))
            self.fill()

        def fill(self):
            self._busy = True
            try:
                y = self.lb.yview()[0]
                q = self.q.get().strip().lower()
                self.vis = [k for k in self.keys if not q or q in self.disp[k].lower()]
                self.lb.delete(0, "end")
                for i, k in enumerate(self.vis):
                    sm = self.sums.get(k, [0, 0, 0, 0])
                    self.lb.insert("end", tkstr("%s   ·   %s Spieler   ·   Ø Level %s   ·   Ø Base %s" % (
                        self.disp[k], _group(self.cnt[k]), _avg_txt(sm[0], sm[1]), _avg_txt(sm[2], sm[3], True))))
                    if k in self.sel:
                        self.lb.selection_set(i)
                self.lb.yview_moveto(y)
                self.info.configure(text="%d von %d Servern gewählt" % (len(self.sel), len(self.keys)))
            finally:
                self._busy = False

        def _changed(self, _e=None):
            if self._busy:
                return
            chosen = {self.vis[i] for i in self.lb.curselection()}
            for k in self.vis:
                (self.sel.add if k in chosen else self.sel.discard)(k)
            self._apply()

        def bulk(self, what):
            for k in self.vis:
                if what == "all":
                    self.sel.add(k)
                elif what == "none":
                    self.sel.discard(k)
                else:
                    (self.sel.discard if k in self.sel else self.sel.add)(k)
            self.fill()
            self._apply()

        def _order(self):
            srt, sm = self.sort.get(), self.sums
            if srt == "level":
                return sorted(self.cnt, key=lambda k: (-(sm[k][0] / sm[k][1]) if sm[k][1] else 1e18, natural_key(k)))
            if srt == "base":
                return sorted(self.cnt, key=lambda k: (-(sm[k][2] / sm[k][3]) if sm[k][3] else 1e18, natural_key(k)))
            if srt == "n":
                return sorted(self.cnt, key=lambda k: (-self.cnt[k], natural_key(k)))
            return sorted(self.cnt, key=natural_key)

        def _resort(self):
            self.app.cfg.d["pick_sort_s"] = self.sort.get()
            self.app.save_soon()
            self.keys = self._order()
            self.lb.yview_moveto(0)
            self.fill()

        def _apply(self):
            self._busy = True
            try:
                self.app.set_servers(set(self.sel), set(self.keys))
            finally:
                self._busy = False
            self.info.configure(text="%d von %d Servern gewählt" % (len(self.sel), len(self.keys)))


    class GuildPickDialog(tk.Toplevel):
        """Gilde suchen: Server waehlen, Name eintippen (auch unter tausenden Gilden schnell zu finden)."""

        def __init__(self, app, title, button, guilds, on_pick, marks=None, own=None, quick=False):
            super().__init__(app)
            self.app, self.on_pick, self.marks, self.own = app, on_pick, marks or set(), own
            self.guilds = [g for g in guilds if g.get("g_name")]
            self.title(title)
            self.configure(bg=C["bg"])
            self.transient(app)
            try:
                cw, lh = FONT.measure("0"), FONT.metrics("linespace")
            except Exception:
                cw, lh = 8, 18
            self.geometry("%dx%d" % (min(max(960, cw * 128), app.winfo_screenwidth() - 60),
                                     min(max(560, lh * 30), app.winfo_screenheight() - 90)))
            self.minsize(min(760, cw * 90), min(420, lh * 18))
            f = ttk.Frame(self, padding=14)
            f.pack(fill="both", expand=True)
            bb = ttk.Frame(f)                                  # Knoepfe zuerst unten anlegen: bleiben immer sichtbar
            bb.pack(side="bottom", fill="x", pady=(10, 0))
            srvs = sorted({str(g.get("g_server") or "") for g in self.guilds}, key=natural_key)
            ttk.Label(f, text=tkstr("Gilde suchen (%s Gilden auf %d Servern)" % (_group(len(self.guilds)), len(srvs))), style="Head.TLabel").pack(anchor="w")
            r1 = ttk.Frame(f)
            r1.pack(fill="x", pady=(10, 6))
            ttk.Label(r1, text="Server:").pack(side="left")
            self.srv = tk.StringVar(value="alle")
            pre = own[0] if own else ""
            for g in self.guilds:
                if own and g.get("_srv") == own[0]:
                    pre = str(g.get("g_server"))
                    break
            if pre in srvs:
                self.srv.set(pre)
            cb = ttk.Combobox(r1, textvariable=self.srv, values=["alle"] + srvs, width=16, state="readonly")
            cb.pack(side="left", padx=6)
            cb.bind("<<ComboboxSelected>>", lambda e: self.fill())
            ttk.Label(r1, text="Name enthält:").pack(side="left", padx=(14, 0))
            self.q = tk.StringVar()
            en = ttk.Entry(r1, textvariable=self.q, width=28)
            en.pack(side="left", padx=6)
            self.q.trace_add("write", lambda *a: self.fill())
            ttk.Label(r1, text="(leer = alle Gilden des Servers, nach Ehre)", style="Dim.TLabel").pack(side="left")
            box = ttk.Frame(f, style="Panel.TFrame")
            box.pack(fill="both", expand=True)
            sc = max(1.0, cw / 8.0)
            cols = (("g", "Gilde", 260, "w"), ("s", "Server", 150, "w"), ("rk", "Ehre-Rang", 100, "e"), ("m", "Mitgl.", 75, "e"),
                    ("l", "Ø Level", 85, "e"), ("r", "Raids", 75, "e"), ("b", "Σ Base", 140, "e"))
            cols = tuple((c, t, int(w * sc), a) for c, t, w, a in cols)
            self.tv = ttk.Treeview(box, columns=[c[0] for c in cols], show="headings", height=6, selectmode="extended")
            self._heads = {c: t for c, t, _w, _a in cols}
            self._srt = None                                   # (Spalte, absteigend) – None = Server, dann Ehre-Rang
            self._srt2 = None                                  # 2. Sortierung (Rechtsklick auf die Ueberschrift)
            for c, t, w, a in cols:
                self.tv.heading(c, text=t, command=lambda c=c: self._sort_by(c))
                self.tv.column(c, width=w, anchor=a, stretch=c == "g")
            for ev in ("<Button-3>", "<Button-2>"):
                self.tv.bind(ev, self._head_right)
            attach_scroll(box, self.tv)
            self.tv.pack(side="left", fill="both", expand=True)
            self.tv.tag_configure("own", foreground=C["accent"])
            self.tv.bind("<Double-Button-1>", lambda e: self.pick())
            self._picked = []                                  # gewaehlte Gilden - bleiben auch beim Wechsel von Server / Suche
            self.tv.bind("<<TreeviewSelect>>", self._sel_changed, add="+")
            self.lbl = ttk.Label(bb, text="", style="Dim.TLabel")
            self.lbl.pack(side="left")
            ttk.Button(bb, text="Schließen", command=self.destroy).pack(side="right")
            ttk.Button(bb, text=button, style="Accent.TButton", command=self.pick).pack(side="right", padx=6)
            self.v_quick, self.v_qname = tk.BooleanVar(value=False), tk.StringVar()
            if quick:                                          # Meine Gilde: Auswahl gleich als Schnellzugriff merken
                qf = ttk.Frame(bb)
                qf.pack(side="right", padx=(0, 14))
                ttk.Checkbutton(qf, text="als Schnellzugriff speichern:", variable=self.v_quick).pack(side="left")
                ttk.Entry(qf, textvariable=self.v_qname, width=18).pack(side="left", padx=4)
            self._rows = {}
            self.fill()
            en.focus_set()

        SORTK = {"g": "g_name", "s": "g_server", "rk": "g_rank", "m": "g_members", "l": "g_level_avg", "r": "g_raids", "b": "gs_base_sum"}

        def _sort_by(self, col):
            old = self._srt
            desc0 = col in ("m", "l", "r", "b")                 # Zahlen zuerst absteigend, Namen/Rang aufsteigend
            self._srt = (col, not old[1]) if old and old[0] == col else (col, desc0)
            if self._srt2 and self._srt2[0] == col:
                self._srt2 = None
            self._heads_now()
            self.fill()

        def _heads_now(self):
            for c, t in self._heads.items():
                mark = ""
                if self._srt and c == self._srt[0]:
                    mark = " ▼" if self._srt[1] else " ▲"
                elif self._srt2 and c == self._srt2[0]:
                    mark = " \u00b2▼" if self._srt2[1] else " \u00b2▲"
                self.tv.heading(c, text=t + mark)

        def _head_right(self, e):
            if self.tv.identify_region(e.x, e.y) != "heading":
                return None
            try:
                col = self.tv["columns"][int(self.tv.identify_column(e.x)[1:]) - 1]
            except (ValueError, IndexError):
                return None
            self._srt2 = sort2_cycle(self._srt2, col, self._srt[0] if self._srt else None, col in ("m", "l", "r", "b"))
            self._heads_now()
            self.fill()
            return "break"

        def _gval(self, col):
            k = self.SORTK[col]
            if col == "g":
                return lambda g: str(g.get(k) or "").lower()
            if col == "s":
                return lambda g: srv_sort_key(str(g.get(k) or ""))
            return lambda g: g.get(k)

        def fill(self):
            sv, q = self.srv.get(), self.q.get().strip().lower()
            gl = [g for g in self.guilds if (sv == "alle" or str(g.get("g_server")) == sv) and (not q or q in str(g["g_name"]).lower())]
            gl.sort(key=lambda g: (srv_sort_key(str(g.get("g_server") or "")), g.get("g_rank") or 99999, str(g["g_name"]).lower()))
            if self._srt2 and (not self._srt or self._srt2[0] != self._srt[0]):
                gl = sort_rows(gl, self._gval(self._srt2[0]), self._srt2[1])
            if self._srt:
                col, desc = self._srt
                gl = sort_rows(gl, self._gval(col), desc)            # ohne Wert immer ans Ende
            self.tv.delete(*self.tv.get_children())
            self._rows = {}
            ownset = set()
            if self.own:
                ownset = ({tuple(x) for x in self.own} if isinstance(self.own[0], (list, tuple)) else {tuple(self.own)})
            for i, g in enumerate(gl[:600]):
                key = (g.get("_srv"), g["g_name"])
                mark = "★ " if key in ownset else ("☑ " if key in self.marks else "")
                iid = "g%d" % i
                self._rows[iid] = key
                f = lambda k, d=0: "–" if g.get(k) is None else (_group(int(round(g[k]))) if d == 0 else ("%.1f" % g[k]).replace(".", ","))
                self.tv.insert("", "end", iid=iid, values=[tkstr(mark + str(g["g_name"])), tkstr(str(g.get("g_server") or "")),
                                                           "#%d" % int(g["g_rank"]) if g.get("g_rank") else "–", f("g_members"), f("g_level_avg", 1),
                                                           f("g_raids"), f("gs_base_sum")], tags=("own",) if mark == "★ " else ())
            self._lbl_base = "%d Treffer%s · ★ = deine Gilde · ☑ = schon Rivale · Klick auf eine Überschrift sortiert" % (
                len(gl), " (die ersten 600)" if len(gl) > 600 else "")
            if not hasattr(self, "_srvname"):
                self._srvname = {(g.get("_srv"), g["g_name"]): str(g.get("g_server") or "") for g in self.guilds}
            again = [iid for iid, k in self._rows.items() if k in set(getattr(self, "_picked", []))]
            if again:
                self.tv.selection_set(again)                   # schon gewaehlte Gilden bleiben markiert
            self._pick_lbl() if hasattr(self, "_picked") else self.lbl.configure(text=tkstr(self._lbl_base))

        def _sel_changed(self, _e=None):
            vis = set(self._rows.values())
            sel = [self._rows[i] for i in self.tv.selection() if i in self._rows]
            keep = [k for k in self._picked if k not in vis or k in sel]
            self._picked = keep + [k for k in sel if k not in keep]
            self._pick_lbl()

        def _pick_lbl(self):
            if not self._picked:
                self.lbl.configure(text=tkstr(self._lbl_base))
                return
            names = ", ".join("%s (%s)" % (k[1], self._srvname.get(k, k[0])) for k in self._picked[:4])
            self.lbl.configure(text=tkstr("%d gewählt: %s%s · Strg + Klick = weitere, auch nach Wechsel des Servers" % (
                len(self._picked), names, " …" if len(self._picked) > 4 else "")))

        def pick(self):
            keys = list(self._picked) or [self._rows[i] for i in self.tv.selection() if i in self._rows]
            if keys:
                self._picked = []
                self.on_pick(keys)
                try:
                    self.fill()
                except tk.TclError:
                    pass


    class ColsPickDialog(tk.Toplevel):
        """Spalten waehlen und ordnen wie in der Online-Liste (⚙ › Spalten): Haken = zeigen, ▲ ▼ = Reihenfolge.
        Oben die angezeigten Spalten (von links nach rechts), darunter die weiteren."""

        def __init__(self, app, title, cols, active, on_ok, default=None):
            super().__init__(app)
            self.title(title)
            self.configure(bg=C["bg"])
            self.transient(app)
            self.labels = dict(cols)
            self.base = [k for k, _l in cols]
            self.on = [k for k in active if k in self.labels]
            self.default, self.on_ok = default, on_ok
            try:
                lh = FONT.metrics("linespace")
            except Exception:
                lh = 18
            self.geometry("%dx%d" % (max(640, FONT.measure("0") * 80), min(max(420, (len(cols) + 6) * (lh + 10)),
                                                                             app.winfo_screenheight() - 120)))
            f = ttk.Frame(self, padding=14)
            f.pack(fill="both", expand=True)
            ttk.Label(f, text="Haken = Spalte zeigen · ▲ ▼ = Reihenfolge (oben = links)", style="Dim.TLabel").pack(anchor="w", pady=(0, 8))
            bb = ttk.Frame(f)                                  # Knoepfe zuerst unten: bleiben immer sichtbar
            bb.pack(side="bottom", fill="x", pady=(10, 0))
            ttk.Button(bb, text="Alle", command=lambda: self._set_all(True)).pack(side="left")
            ttk.Button(bb, text="Keine", command=lambda: self._set_all(False)).pack(side="left", padx=4)
            if default:
                ttk.Button(bb, text="Standard", command=self._std).pack(side="left")
            ttk.Button(bb, text="Abbrechen", command=self.destroy).pack(side="right")
            ttk.Button(bb, text="Übernehmen", style="Accent.TButton", command=self._ok).pack(side="right", padx=6)
            self.sf = ScrollFrame(f)
            self.sf.pack(fill="both", expand=True)
            self._build()

        def _build(self):
            inner = self.sf.inner
            for w in inner.winfo_children():
                w.destroy()
            row = 0
            ttk.Label(inner, text="Angezeigt (von links nach rechts)", style="Dim.TLabel").grid(row=row, column=0, sticky="w", pady=(0, 2))
            row += 1
            for i, k in enumerate(self.on):
                v = tk.BooleanVar(value=True)
                ttk.Checkbutton(inner, text=tkstr(self.labels[k]), variable=v,
                                command=lambda k=k: self._toggle(k)).grid(row=row, column=0, sticky="w", padx=(0, 18))
                ttk.Button(inner, text="▲", width=3, command=lambda i=i: self._move(i, -1),
                           state="normal" if i > 0 else "disabled").grid(row=row, column=1)
                ttk.Button(inner, text="▼", width=3, command=lambda i=i: self._move(i, 1),
                           state="normal" if i < len(self.on) - 1 else "disabled").grid(row=row, column=2, padx=(2, 0))
                inner.__dict__.setdefault("_vars", []).append(v)
                row += 1
            rest = [k for k in self.base if k not in self.on]
            if rest:
                ttk.Label(inner, text="Weitere Spalten", style="Dim.TLabel").grid(row=row, column=0, sticky="w", pady=(10, 2))
                row += 1
            for k in rest:
                v = tk.BooleanVar(value=False)
                ttk.Checkbutton(inner, text=tkstr(self.labels[k]), variable=v,
                                command=lambda k=k: self._toggle(k)).grid(row=row, column=0, sticky="w")
                inner.__dict__.setdefault("_vars", []).append(v)
                row += 1
            self.sf.canvas.yview_moveto(0) if not getattr(self, "_built", False) else None
            self._built = True

        def _toggle(self, k):
            if k in self.on:
                self.on.remove(k)
            else:
                self.on.append(k)
            self._build()

        def _move(self, i, d):
            j = i + d
            if 0 <= j < len(self.on):
                self.on[i], self.on[j] = self.on[j], self.on[i]
                self._build()

        def _set_all(self, on):
            self.on = list(self.on) + [k for k in self.base if k not in self.on] if on else []
            self._build()

        def _std(self):
            self.on = [k for k in self.default if k in self.labels]
            self._build()

        def _ok(self):
            self.on_ok(list(self.on))
            self.destroy()


    class _ScanLoader:
        """Liest nacheinander alle Scans der Bibliothek (mit Anzeige des Fortschritts) und sammelt je Scan einen Datensatz."""

        def _load_start(self):
            self.ents = self.app.history_entries()
            self.items = []                      # [(Bibliothekseintrag, Datensatz)], aelteste zuerst
            self._i = 0
            self.after(30, self._load_step)

        def _load_step(self):
            try:
                if not self.winfo_exists():
                    return
            except tk.TclError:
                return
            if self._i >= len(self.ents):
                self.status.configure(text=tkstr("%d Scan(s) ausgewertet." % len(self.items)))
                self._items_changed(True)
                return
            e = self.ents[self._i]
            self._i += 1
            self.status.configure(text=tkstr("Lade Scan %d von %d: %s …" % (self._i, len(self.ents), e["name"])))
            try:
                recs, groups = self.app.scan_data(e)
                it = self.extract(recs, groups)
            except Exception:
                it = None
            if it is not None:
                self.items.append((e, it))
                self._items_changed(False)
            self.after(15, self._load_step)

    def _delta(cur, prev, first):
        """(Anzeige, Rohwert) des Zuwachses zum vorherigen Scan."""
        if first:
            return ("", None)
        if cur is None or prev is None:
            return ("–", None)
        return (fmt_num(cur - prev, signed=True), cur - prev)

    def _cmp_summary(items, brief, full, picks):
        """Zusammenfassung: Standard = erster gegen letzter Scan; bei zwei angeklickten Scans nur diese beiden."""
        if not items:
            return ""
        prefix = ""
        if picks and len(picks) >= 2:
            a, b = sorted(picks[:2], key=lambda i: items[i][0]["ts"])
            (e0, r0), (e1, r1) = items[a], items[b]
            days = max(0.0, (e1["ts"] - e0["ts"]) / 86400000.0)
            cells = []
            for k, lab, per_day in full:
                x, y = r0.get(k), r1.get(k)
                if x is None or y is None:
                    continue
                t = "%s: %s → %s  (%s" % (lab, fmt_value(k, r0), fmt_value(k, r1), fmt_num(y - x, signed=True))
                if x:
                    t += ", %s %%" % fmt_num(round((y - x) * 100.0 / x, 1), signed=True)
                if per_day and days >= 1:
                    t += ", Ø %s/Tag" % fmt_num(round((y - x) / days), signed=True)
                cells.append(t + ")")
            lines = ["      |      ".join(cells[i:i + 2]) for i in range(0, len(cells), 2)]
            return "Vergleich der gewählten Scans %s  →  %s  (%d Tage):\n%s" % (
                fmt_ts(e0["ts"], e0["time"]), fmt_ts(e1["ts"], e1["time"]), round(days), "\n".join(lines))
        if picks:
            prefix = "Ein Scan gewählt (%s) – klicke einen zweiten Scan an, um nur diese beiden zu vergleichen.\n" % \
                     fmt_ts(items[picks[0]][0]["ts"], items[picks[0]][0]["time"])
        if len(items) == 1:
            return prefix + "Nur ein Scan gefunden. Für eine Entwicklung weitere Scans laden (Tab „Dateien“ = Bibliothek)."
        (e0, r0), (e1, r1) = items[0], items[-1]
        days = max(0.0, (e1["ts"] - e0["ts"]) / 86400000.0)
        parts = []
        for k, lab, per_day in brief:
            a, b = r0.get(k), r1.get(k)
            if a is None or b is None:
                continue
            t = "%s %s" % (lab, fmt_num(b - a, signed=True))
            if a:
                t += " (%s %%)" % fmt_num(round((b - a) * 100.0 / a, 1), signed=True)
            if per_day and days >= 1:
                t += ", Ø %s pro Tag" % fmt_num(round((b - a) / days), signed=True)
            parts.append(t)
        return prefix + "Ältester bis neuester Scan: %s bis %s (%d Scans, %d Tage):  %s" % (
            fmt_ts(e0["ts"], False), fmt_ts(e1["ts"], False), len(items), round(days), "   |   ".join(parts))

    class _HistTable(ttk.Frame):
        """Sortierbare Tabelle mit Zebrastreifen. cols = [(id, Titel, Breite, Ausrichtung)]; Zeilen = Liste von (Anzeige, Sortwert).
        on_pick: Klick waehlt/entwaehlt Zeilen (max. max_pick), z.B. zwei Scans zum Vergleich."""

        def __init__(self, master, cols, rownum=False, on_dbl=None, on_pick=None, max_pick=2, sort=(0, True), multi=False):
            super().__init__(master, style="Panel.TFrame")
            self.cols, self.rownum, self.on_pick, self.max_pick, self.sort = cols, rownum, on_pick, max_pick, sort
            ids = (["_n"] if rownum else []) + [c[0] for c in cols]
            self.tree = ttk.Treeview(self, columns=ids, show="headings",
                                     selectmode="none" if on_pick else ("extended" if multi else "browse"))
            _vs, self._hs = attach_scroll(self, self.tree, horizontal=True)
            self.tree.pack(side="left", fill="both", expand=True)
            self.tree.tag_configure("alt", background="#33353b")
            self.grid = GridLines(self.tree, self._hs)
            if rownum:
                self.tree.heading("_n", text="#", anchor="center")
                self.tree.column("_n", width=52, anchor="center", stretch=False)
            for i, (cid, title, w, a) in enumerate(cols):
                self.tree.heading(cid, text=tkstr(title), anchor=a, command=lambda k=i: self._sort_by(k))
                self.tree.column(cid, width=w, anchor=a, stretch=False)
            self.sort2 = None
            for ev in ("<Button-3>", "<Button-2>"):                # Rechtsklick auf die Ueberschrift = 2. Sortierung
                self.tree.bind(ev, self._head_right, add="+")
            self.rows, self.objs, self.picked = [], [], []
            if on_dbl:
                self.tree.bind("<Double-Button-1>", lambda e: self._dbl(e, on_dbl))
            if on_pick:
                self.tree.bind("<Button-1>", self._click)

        def _dbl(self, e, cb):
            if self.tree.identify_region(e.x, e.y) == "cell":
                iid = self.tree.identify_row(e.y)
                if iid and self.objs[int(iid[1:])] is not None:
                    cb(self.objs[int(iid[1:])])

        def _click(self, e):
            if self.tree.identify_region(e.x, e.y) != "cell":
                return None
            iid = self.tree.identify_row(e.y)
            if not iid:
                return "break"
            i = int(iid[1:])
            if i in self.picked:
                self.picked.remove(i)
            else:
                self.picked.append(i)
                if len(self.picked) > self.max_pick:
                    self.picked.pop(0)
            self._apply_sel()
            self.on_pick(list(self.picked))
            return "break"

        def clear_picks(self):
            self.picked = []
            self._apply_sel()
            if self.on_pick:
                self.on_pick([])

        def _apply_sel(self):
            self.tree.selection_set([("r%d" % i) for i in self.picked if i < len(self.rows)])

        def _desc0(self, k):
            first = next((r[k][1] for r in self.rows if r[k][1] is not None), None)
            return not isinstance(first, str)

        def _sort_by(self, k):
            if self.sort[0] == k:
                self.sort = (k, not self.sort[1])
            else:
                self.sort = (k, self._desc0(k))
            if self.sort2 and self.sort2[0] == k:
                self.sort2 = None
            self.render()

        def _head_right(self, e):
            if self.tree.identify_region(e.x, e.y) != "heading":
                return None
            try:
                n = int(self.tree.identify_column(e.x)[1:]) - 1 - (1 if self.rownum else 0)
            except ValueError:
                return None
            if not 0 <= n < len(self.cols):
                return None
            self.sort2 = sort2_cycle(self.sort2, n, self.sort[0], self._desc0(n))
            self.render()
            return "break"

        def set_sort(self, k, desc):
            self.sort = (k, desc)
            self.render()

        def set_cols(self, cols, sort=None):
            """Spalten neu setzen (z.B. nach "Spalten waehlen"); sort = (Spalten-Nr., absteigend)."""
            self.cols = cols
            ids = (["_n"] if self.rownum else []) + [c[0] for c in cols]
            self.tree.configure(columns=ids)
            if self.rownum:
                self.tree.heading("_n", text="#", anchor="center")
                self.tree.column("_n", width=52, anchor="center", stretch=False)
            for i, (cid, title, w, a) in enumerate(cols):
                self.tree.heading(cid, text=tkstr(title), anchor=a, command=lambda k=i: self._sort_by(k))
                self.tree.column(cid, width=w, anchor=a, stretch=False)
            self.sort2 = None
            self.sort = sort if sort else (min(self.sort[0], max(0, len(cols) - 1)), self.sort[1])

        def set_rows(self, rows, objs=None):
            self.rows = rows
            self.objs = objs or [None] * len(rows)
            self.picked = [i for i in self.picked if i < len(rows)]
            self.render()

        def render(self):
            k, desc = self.sort
            order = list(range(len(self.rows)))
            s2 = self.sort2
            if s2 and s2[0] != k and s2[0] < len(self.cols):
                order = sort_rows(order, lambda i: self.rows[i][s2[0]][1], s2[1])
            if k < len(self.cols):
                order = sort_rows(order, lambda i: self.rows[i][k][1], desc)
            self.tree.delete(*self.tree.get_children())
            for pos, i in enumerate(order):
                vals = ([pos + 1] if self.rownum else []) + [tkstr(c[0]) for c in self.rows[i]]
                self.tree.insert("", "end", iid="r%d" % i, values=vals, tags=("alt",) if pos % 2 else ())
            for i, (cid, title, _w, _a) in enumerate(self.cols):
                mark = ((" v" if desc else " ^") if i == k else
                        ((" \u00b2v" if s2[1] else " \u00b2^") if s2 and i == s2[0] else ""))
                self.tree.heading(cid, text=tkstr(title + mark))
            self._apply_sel()
            self.grid.schedule()

    class _ScanTableMixin:
        """Gemeinsame Bedienung der Scan-Tabelle: Reihenfolge, Auswahl zweier Scans."""

        def _scan_controls(self, parent):
            bar = ttk.Frame(parent)
            bar.pack(fill="x", padx=8, pady=(0, 4))
            ttk.Label(bar, text="Reihenfolge:").pack(side="left")
            self.order = tk.StringVar(value="Neueste oben")
            cb = ttk.Combobox(bar, textvariable=self.order, values=["Neueste oben", "Älteste oben"], state="readonly", width=14)
            cb.pack(side="left", padx=6)
            cb.bind("<<ComboboxSelected>>", lambda e: self.table.set_sort(0, self.order.get() == "Neueste oben"))
            ttk.Button(bar, text="Alle Scans vergleichen", command=lambda: self.table.clear_picks()).pack(side="left", padx=4)
            ttk.Label(bar, text="Klicke zwei Scans an = nur diese beiden werden verglichen (nochmal klicken = abwählen). "
                                "Klick auf eine Überschrift sortiert.", style="Dim.TLabel").pack(side="left", padx=8)

        def _picked(self, picks):
            self.picks = picks
            self._refresh_compare()

        def _refresh_compare(self):
            marks = [self.items[i][0]["ts"] for i in self.picks if i < len(self.items)] if self.picks else []
            self.panel.set_items(self.items, marks)
            self.summary.configure(text=tkstr(_cmp_summary(self.items, self.BRIEF, self.FULL, self.picks) if self.items else
                                              ("" if not getattr(self, "_done", False) else self.EMPTY)))

    class TwinDialog(tk.Toplevel):
        """Spieler mit genau gleichem Aussehen wie rec (Rechtsklick > Gleiches Aussehen)."""

        def __init__(self, app, rec, twins, on_open):
            super().__init__(app)
            self.title(tkstr("Gleiches Aussehen: %s (%s)" % (rec["name"], rec.get("_srv_disp", ""))))
            self.configure(bg=C["bg"])
            self.transient(app)
            self.geometry("720x380")
            ttk.Label(self, text=tkstr("Gleiches Aussehen wie %s (%s)" % (rec["name"], rec.get("_srv_disp", ""))),
                      style="Head.TLabel").pack(anchor="w", padx=14, pady=(12, 0))
            ttk.Label(self, text="Rasse, Geschlecht und alle Gesichtsteile samt Farben sind gleich – über alle geladenen "
                                 "Server. Doppelklick = Entwicklung.", style="Dim.TLabel").pack(anchor="w", padx=14)
            self.app, self.rec, self.twins = app, rec, list(twins)
            ccr = ttk.Frame(self)
            ccr.pack(fill="x", padx=14, pady=(6, 0))
            self.v_cc = tk.BooleanVar(value=bool(app.cfg.d.get("tw_cc", False)))
            cb_cc = ttk.Checkbutton(ccr, text="Avatar-Bilder mitzählen (CC und Avatar)", variable=self.v_cc, command=self._cc_changed)
            cb_cc.pack(side="left")
            try:
                pool_ = app.view("table")["players"]
            except Exception:
                pool_ = list(twins) + [rec]
            Tip(cb_cc, "Spieler mit Spezial-Bild (Content Creator oder Avatar-Bild) mitzählen.\n" + special_counts_text(pool_))
            self.cc_info = ttk.Label(ccr, text="", style="Dim.TLabel")
            self.cc_info.pack(side="left", padx=10)
            box = ttk.Frame(self, style="Panel.TFrame")
            box.pack(fill="both", expand=True, padx=14, pady=8)
            cols = (("name", "Name", 200), ("srv", "Server", 90), ("guild", "Gilde", 200), ("level", "Level", 70),
                    ("bs", "Base Sum", 100), ("cc", "Bild", 70))
            tv = ttk.Treeview(box, columns=[c[0] for c in cols], show="headings", selectmode="browse")
            for k, lab, w in cols:
                tv.heading(k, text=lab)
                tv.column(k, width=w, anchor="e" if k in ("level", "bs") else ("center" if k == "cc" else "w"))
            attach_scroll(box, tv)
            tv.pack(side="left", fill="both", expand=True)
            self.tv = tv
            self.recs = {}
            self._fill()
            tv.bind("<Double-Button-1>", lambda e: on_open(self.recs[tv.focus()]) if tv.focus() in self.recs else None)
            ttk.Button(self, text="Schließen", command=self.destroy).pack(anchor="e", padx=14, pady=(0, 12))
            self.bind("<Escape>", lambda e: self.destroy())

        def _fill(self):
            tv = self.tv
            tv.delete(*tv.get_children())
            self.recs = {}
            cc = bool(self.v_cc.get())
            shown = [r for r in self.twins if cc or not is_special(r)]
            for r in [self.rec] + shown:
                iid = tv.insert("", "end", values=(tkstr(r.get("name") or ""), tkstr(r.get("_srv_disp") or ""),
                                                   tkstr(r.get("guild") or "–"), fmt_value("level", r), fmt_value("base_sum", r),
                                                   "CC" if r.get("creator") is True else ("Avatar" if is_avatar(r) else "")))
                self.recs[iid] = r
            hid = len(self.twins) - len(shown)
            self.cc_info.configure(text=("%d mit Avatar-Bild / CC ausgeblendet" % hid) if hid else "")

        def _cc_changed(self):
            self.app.cfg.d["tw_cc"] = bool(self.v_cc.get())
            self.app.save_soon()
            self._fill()


