            ttk.Label(f, text=tkstr(msg or os.path.basename(files[0])), style="Dim.TLabel", wraplength=520, justify="left").pack(anchor="w", pady=(2, 10))
            self.v_open = tk.BooleanVar(value=bool(d.get("png_open", True)))
            self.v_clip = tk.BooleanVar(value=bool(d.get("png_clip", True)) and sys.platform.startswith("win"))
            self.v_never = tk.BooleanVar(value=False)
