    class _PickDialog(tk.Toplevel):
        """Kleine Auswahlliste mit Suchfeld: on_pick(index_in_items) wird bei Doppelklick / OK aufgerufen."""

        def __init__(self, master, title, hint, items, on_pick):
            super().__init__(master)
            self.title(title)
            self.configure(bg=C["bg"])
            self.transient(master.winfo_toplevel())
            self.items, self.on_pick, self.vis = items, on_pick, []
            ttk.Label(self, text=tkstr(hint), style="Dim.TLabel", wraplength=460, justify="left").pack(anchor="w", padx=12, pady=(10, 4))
            self.q = tk.StringVar()
            e = ttk.Entry(self, textvariable=self.q, width=40)
            e.pack(fill="x", padx=12)
            self.q.trace_add("write", lambda *a: self.fill())
            fr = ttk.Frame(self)
            fr.pack(fill="both", expand=True, padx=12, pady=8)
            self.lb = tk.Listbox(fr, height=14, width=60, bg=C["field"], fg=C["fg"], selectbackground=C["accent"], relief="flat",
                                 highlightthickness=0, font=FONT, exportselection=False)
            attach_scroll(fr, self.lb)
            self.lb.pack(side="left", fill="both", expand=True)
            self.lb.bind("<Double-Button-1>", lambda ev: self.ok())
            bb = ttk.Frame(self)
            bb.pack(fill="x", padx=12, pady=(0, 10))
            ttk.Button(bb, text="Abbrechen", command=self.destroy).pack(side="right")
            ttk.Button(bb, text="Auswählen", style="Accent.TButton", command=self.ok).pack(side="right", padx=6)
            self.fill()
            e.focus_set()
            self.grab_set()

        def fill(self):
            q = norm_name(self.q.get())
            self.lb.delete(0, "end")
            self.vis = [i for i, it in enumerate(self.items) if not q or q in norm_name(it)][:400]
            for i in self.vis:
                self.lb.insert("end", tkstr(self.items[i]))
            if self.vis:
                self.lb.selection_set(0)

        def ok(self):
            s = self.lb.curselection()
            if s:
                i = self.vis[s[0]]
                self.destroy()
                self.on_pick(i)

    class MergeAltDialog(tk.Toplevel):
        """Alternativen zu einem Spieler des neuen Servers ansehen, einen anderen alten Spieler waehlen oder von Hand suchen."""

        def __init__(self, tab, row):
            super().__init__(tab)
            self.tab, self.row, self.items = tab, row, []
            new = row["new"]
            self.title("Zuordnung prüfen – %s" % new["name"])
            self.configure(bg=C["bg"])
            self.transient(tab.winfo_toplevel())
            self.geometry("1000x520")
            ttk.Label(self, text=tkstr("Neu: %s  ·  %s  ·  Gilde %s  ·  Level %s" % (
                new["name"], new["_srv_disp"], new.get("guild") or "–", fmt_num(new.get("level")))), style="Head.TLabel").pack(
                anchor="w", padx=12, pady=(10, 2))
            ttk.Label(self, text="Doppelklick oder „Diesen zuordnen“ übernimmt einen alten Spieler. Mit der Suche findest du auch Spieler, "
                                 "die anders heißen. „Keiner“ heißt: dieser Spieler hat keinen Vorgänger.", style="Dim.TLabel",
                      wraplength=960, justify="left").pack(anchor="w", padx=12)
            sb = ttk.Frame(self)
            sb.pack(fill="x", padx=12, pady=6)
            ttk.Label(sb, text="Suche unter den alten Spielern:").pack(side="left")
            self.q = tk.StringVar()
            ttk.Entry(sb, textvariable=self.q, width=28).pack(side="left", padx=6)
            self.q.trace_add("write", lambda *a: self.fill())
            fr = ttk.Frame(self)
            fr.pack(fill="both", expand=True, padx=12)
            cols = ("score", "srv", "name", "guild", "level", "why")
            self.tree = ttk.Treeview(fr, columns=cols, show="headings", selectmode="browse")
            for c, t, w, a in (("score", "Punkte", 60, "e"), ("srv", "Alter Server", 90, "w"), ("name", "Name", 160, "w"),
                               ("guild", "Gilde", 200, "w"), ("level", "Level", 60, "e"), ("why", "Begründung", 380, "w")):
                self.tree.heading(c, text=t, anchor=a)
                self.tree.column(c, width=w, anchor=a)
            attach_scroll(fr, self.tree)
            self.tree.pack(side="left", fill="both", expand=True)
            self.tree.bind("<Double-Button-1>", lambda ev: self.pick())
            self.grid = GridLines(self.tree)
            bb = ttk.Frame(self)
            bb.pack(fill="x", padx=12, pady=10)
            ttk.Button(bb, text="Schließen", command=self.destroy).pack(side="right")
            ttk.Button(bb, text="Keiner (kein Vorgänger)", command=self.none).pack(side="right", padx=6)
            ttk.Button(bb, text="Diesen zuordnen", style="Accent.TButton", command=self.pick).pack(side="right")
            self.fill()

        def fill(self):
            q = norm_name(self.q.get())
            new = self.row["new"]
            if not q:
                self.items = list(self.row["cands"])
            else:
                nn = norm_name(new["name"])
                res = []
                for o in self.tab.old_recs:
                    on = o.get("_nn") or norm_name(o["name"])
                    if q in on or q in norm_name(o.get("guild") or ""):
                        import difflib
                        sim = 1.0 if on == nn else difflib.SequenceMatcher(None, nn, on).ratio()
                        pts, why = merge_score(new, o, sim)
                        res.append((pts, o, why))
                    if len(res) > 600:
                        break
                res.sort(key=lambda t: -t[0])
                self.items = res[:200]
            self.tree.delete(*self.tree.get_children())
            for i, (pts, o, why) in enumerate(self.items):
                self.tree.insert("", "end", iid=str(i), values=[pts, o["_srv_disp"], tkstr(o["name"]), tkstr(o.get("guild") or ""),
                                                                 fmt_num(o.get("level")), tkstr(" · ".join(why))])
            kids = self.tree.get_children()
            if kids:
                self.tree.selection_set(kids[0])
            self.grid.schedule()

        def pick(self):
            s = self.tree.selection()
            if s and self.tab.assign(self.row, self.items[int(s[0])]):
                self.destroy()

        def none(self):
            self.tab.assign(self.row, None)
            self.destroy()


    class PlausDialog(tk.Toplevel):
        """Auffaelligkeiten im neuen Scan (nur zur Kontrolle - die Daten bleiben unveraendert)."""

        def __init__(self, app, src, prev, rows, info):
            super().__init__(app)
            self.app = app
            self.title(tkstr("Auffälligkeiten im neuen Scan (%s)" % fmt_ts(src.get("ts"), False)))
            self.configure(bg=C["bg"])
            self.transient(app)
            ttk.Label(self, text=tkstr("%d Auffälligkeiten in %s bei %s Spielern (verglichen mit dem Scan davor nach Datum: %s). "
                                       "Die Daten bleiben unverändert – nur zur Kontrolle." % (
                                           len(rows), src.get("name"), _group(len(src.get("recs") or [])), fmt_ts(prev.get("ts"), False))),
                      wraplength=860, justify="left").pack(fill="x", padx=12, pady=(10, 6))
            fr = ttk.Frame(self)
            fr.pack(fill="both", expand=True, padx=12)
            tv = ttk.Treeview(fr, columns=("a", "s", "v", "h"), show="headings", height=min(16, max(4, len(rows))))
            for c_, t_, w_ in (("a", "Art", 190), ("s", "Spieler", 220), ("v", "vorher → jetzt", 190), ("h", "Hinweis", 330)):
                tv.heading(c_, text=t_)
                tv.column(c_, width=w_, anchor="w")
            for tag, col in (("r", "#ff8a80"), ("y", "#ffd27a"), ("g", "#9fd3a8")):
                tv.tag_configure(tag, foreground=col)
            for x in rows[:2000]:
                tv.insert("", "end", values=[tkstr(v) for v in x[1:]], tags=(x[0],))
            attach_scroll(fr, tv)
            tv.pack(side="left", fill="both", expand=True)
            self.v_red = tk.BooleanVar(value=bool(app.cfg.d.get("plaus_red_only")))
            ttk.Checkbutton(self, text="Diesen Hinweis nur bei roten Auffälligkeiten zeigen", variable=self.v_red,
                            command=self._red).pack(anchor="w", padx=12, pady=(8, 0))
            bb = ttk.Frame(self)
            bb.pack(fill="x", padx=12, pady=10)
            ttk.Button(bb, text="OK", style="Accent.TButton", command=self.destroy).pack(side="right")
            ttk.Button(bb, text="Liste kopieren", command=lambda: self._copy(rows)).pack(side="right", padx=8)
            self.bind("<Escape>", lambda e: self.destroy())

        def _red(self):
            self.app.cfg.d["plaus_red_only"] = bool(self.v_red.get())
            self.app.save_soon()

        def _copy(self, rows):
            self.clipboard_clear()
            self.clipboard_append("\n".join(" · ".join(x[1:]) for x in rows))
            self.app.set_status("%d Auffälligkeiten in der Zwischenablage." % len(rows))

    class MergeTab(ttk.Frame):
        """Server-Zusammenlegung: Spieler und Gilden von alten Servern dem neuen Server zuordnen (halbautomatisch, mit Pruefung)."""
        STATUS_ORDER = {"sicher": 0, "manuell": 1, "prüfen": 2, "unsicher": 3, "kein freier Kandidat": 4}
        FILTERS = ["Alle Treffer", "Nur sichere", "Nur zu prüfende (prüfen / unsicher)", "Nur angehakte", "Nur nicht angehakte"]

        def __init__(self, master, app):
            super().__init__(master)
            self.app = app
            self.dirty = True
            self.rows, self.grows, self.old_recs, self.new_recs, self._raw = [], [], [], [], []
            self.srv_keys = []
            self.psort = (None, False)
            self._gsig = None
            ttk.Label(self, text=tkstr(
                "Nach einer Server-Zusammenlegung bekommen Spieler eine neue ID (und manchmal einen neuen Gildennamen). Hier ordnest du "
                "die Spieler der alten Server dem neuen Server zu – erst wird vorgeschlagen (Name, Level, Base, Klasse, Gilde; aus JSON zusätzlich "
                "Aussehen des Avatars, Beschreibung und Ursprungsserver, damit auch Umbenannte gefunden werden), dann prüfst du "
                "alles von Hand. Erst „Speichern“ übernimmt die Zuordnung; danach laufen Entwicklung, Δ-Spalten und Zu-/Abgänge über "
                "die Zusammenlegung hinweg."), style="Dim.TLabel", wraplength=1300, justify="left").pack(fill="x", padx=12, pady=(8, 4))
            top = ttk.Frame(self)
            top.pack(fill="x", padx=12, pady=4)
            left = ttk.Frame(top)
            left.pack(side="left")
            ttk.Label(left, text="Alte Server (Klick = an/aus, mehrere möglich):").pack(anchor="w")
            lf = ttk.Frame(left)
            lf.pack(anchor="w")
            self.lb_old = tk.Listbox(lf, selectmode="multiple", exportselection=False, height=6, width=24, bg=C["field"], fg=C["fg"],
                                     selectbackground=C["accent"], relief="flat", highlightthickness=0, font=FONT)
            attach_scroll(lf, self.lb_old)
            self.lb_old.pack(side="left")
            mid = ttk.Frame(top)
            mid.pack(side="left", padx=24, anchor="n")
            ttk.Label(mid, text="Neuer Server:").pack(anchor="w")
            self.cb_new = ttk.Combobox(mid, state="readonly", width=22)
            self.cb_new.pack(anchor="w", pady=(0, 6))
            self.fuzzy = tk.BooleanVar(value=True)
            ttk.Checkbutton(mid, text="auch ähnliche Namen suchen (etwas langsamer)", variable=self.fuzzy).pack(anchor="w")
            sr = ttk.Frame(mid)
            sr.pack(anchor="w", pady=(4, 0))
            ttk.Label(sr, text="ab Ähnlichkeit").pack(side="left")
            self.sim = tk.StringVar(value="85")
            ttk.Spinbox(sr, from_=70, to=100, increment=5, width=4, textvariable=self.sim).pack(side="left", padx=4)
            ttk.Label(sr, text="%").pack(side="left")
            right = ttk.Frame(top)
            right.pack(side="left", anchor="n")
            ttk.Button(right, text="Kandidaten suchen", style="Accent.TButton", command=self.search).pack(anchor="w")
            self.info = ttk.Label(right, text="", style="Dim.TLabel", wraplength=560, justify="left")
            self.info.pack(anchor="w", pady=(8, 0))

            self.inner = ttk.Notebook(self)
            self.inner.pack(fill="both", expand=True, padx=10, pady=(8, 4))
            self.p1, self.p2, self.p3 = ttk.Frame(self.inner), ttk.Frame(self.inner), ttk.Frame(self.inner)
            self.inner.add(self.p1, text="  1 · Spieler prüfen  ")
            self.inner.add(self.p2, text="  2 · Gilden prüfen  ")
            self.inner.add(self.p3, text="  Gespeicherte Zusammenlegungen  ")
            self.inner.bind("<<NotebookTabChanged>>", lambda e: self._inner_changed())
            self._build_players()
            self._build_guilds()
            self._build_saved()
            bot = ttk.Frame(self)
            bot.pack(fill="x", padx=12, pady=(0, 8))
            self.save_btn = ttk.Button(bot, text="Zusammenlegung speichern …", style="Accent.TButton", command=self.save)
            self.save_btn.pack(side="left")
            self.sel_lbl = ttk.Label(bot, text="", style="Dim.TLabel")
            self.sel_lbl.pack(side="left", padx=12)

        # ---- Aufbau der drei Bereiche
        def _tree(self, parent, cols, height=10):
            fr = ttk.Frame(parent, style="Panel.TFrame")
            fr.pack(fill="both", expand=True, padx=6, pady=(0, 6))
            tr = ttk.Treeview(fr, columns=[c[0] for c in cols], show="headings", selectmode="extended", height=height)
            for c, t, w, a in cols:
                tr.heading(c, text=t, anchor="center" if a == "center" else a)
                tr.column(c, width=w, anchor=a, stretch=False)
            _vs, hs = attach_scroll(fr, tr, horizontal=True)
            tr.pack(side="left", fill="both", expand=True)
            tr.tag_configure("sicher", foreground="#3ba55d")
            tr.tag_configure("manuell", foreground="#5865f2")
            tr.tag_configure("prüfen", foreground=C["warn"])
            tr.tag_configure("unsicher", foreground=C["err"])
            tr.tag_configure("kein freier Kandidat", foreground=C["dim"])
            return tr, GridLines(tr, hs)

        def _build_players(self):
            bar = ttk.Frame(self.p1)
            bar.pack(fill="x", padx=6, pady=6)
            ttk.Label(bar, text="Anzeigen:").pack(side="left")
            self.flt = tk.StringVar(value=self.FILTERS[0])
            fc = ttk.Combobox(bar, textvariable=self.flt, values=self.FILTERS, width=34, state="readonly")
            fc.pack(side="left", padx=6)
            fc.bind("<<ComboboxSelected>>", lambda e: self._fill())
            ttk.Label(bar, text="Suche:").pack(side="left", padx=(12, 2))
            self.mq = tk.StringVar()
            me = ttk.Entry(bar, textvariable=self.mq, width=22)
            me.pack(side="left")
            Tip(me, "Spieler- oder Gildennamen (neu oder alt), mehrere mit Komma trennen. „Alle angezeigten anhaken“ wirkt nur auf die Treffer.")
            self._mq_after = None
            self.mq.trace_add("write", lambda *a: self._mq_changed())
            ttk.Button(bar, text="Sichere anhaken", command=lambda: self._bulk("safe")).pack(side="left", padx=(12, 2))
            ttk.Button(bar, text="Alle angezeigten anhaken", command=lambda: self._bulk("all")).pack(side="left", padx=2)
            ttk.Button(bar, text="Alle abwählen", command=lambda: self._bulk("none")).pack(side="left", padx=2)
            ttk.Button(bar, text="Alternativen / von Hand …", command=self.open_alt).pack(side="right")
            ttk.Label(self.p1, text="Klick auf ☐ / ☑ oder Leertaste = an/aus · Doppelklick = Alternativen ansehen oder von Hand zuordnen · "
                                    "grün = sicher, gelb = bitte prüfen, rot = unsicher, blau = von Hand.",
                      style="Dim.TLabel").pack(anchor="w", padx=8)
            self.ptree, self.pgrid = self._tree(self.p1, [
                ("chk", "✓", 44, "center"), ("status", "Status", 80, "w"), ("score", "Punkte", 60, "e"),
                ("n_name", "Neuer Spieler", 150, "w"), ("n_guild", "Gilde (neu)", 170, "w"), ("n_lvl", "Level", 58, "e"),
                ("o_srv", "Alter Server", 84, "w"), ("o_name", "Alter Spieler", 150, "w"), ("o_guild", "Gilde (alt)", 170, "w"),
                ("o_lvl", "Level", 58, "e"), ("dlv", "Δ Level", 62, "e"), ("why", "Begründung", 460, "w")], height=12)
            sortable = {"status": "status", "score": "score", "n_name": "n_name", "n_guild": "n_guild", "n_lvl": "n_lvl",
                        "o_srv": "o_srv", "o_name": "o_name", "o_guild": "o_guild", "o_lvl": "o_lvl", "dlv": "dlv", "chk": "chk"}
            for c in sortable:
                self.ptree.heading(c, command=lambda c=c: self._psort(c))
            self.psort2 = None
            for ev in ("<Button-3>", "<Button-2>"):                # Rechtsklick auf die Ueberschrift = 2. Sortierung
                self.ptree.bind(ev, self._phead_right)
            self.ptree.bind("<Button-1>", self._click, add="+")
            self.ptree.bind("<space>", self._space)
            self.ptree.bind("<Double-Button-1>", lambda e: self.open_alt() if self.ptree.identify_region(e.x, e.y) == "cell" and
                            self.ptree.identify_column(e.x) != "#1" else None)
            self.ptree.bind("<<TreeviewSelect>>", lambda e: None)

        def _build_guilds(self):
            self.gq = tk.StringVar()
            bar = ttk.Frame(self.p2)
            bar.pack(fill="x", padx=6, pady=6)
            ttk.Label(bar, text=tkstr("Aus den angehakten Spielern abgeleitet: welche alte Gilde ist auf dem neuen Server welche Gilde? "
                                      "Klick auf ☐ / ☑ = an/aus, Doppelklick = andere neue Gilde wählen."), style="Dim.TLabel").pack(side="left")
            ttk.Button(bar, text="Neu berechnen", command=lambda: self.ensure_guilds(True)).pack(side="right")
            ge = ttk.Entry(bar, textvariable=self.gq, width=20)
            ge.pack(side="right", padx=(0, 10))
            ttk.Label(bar, text="Suche:").pack(side="right", padx=(10, 2))
            Tip(ge, "Gildennamen (alt oder neu), mehrere mit Komma trennen.")
            self._gq_after = None
            self.gq.trace_add("write", lambda *a: self._gq_changed())
            self.gtree, self.ggrid = self._tree(self.p2, [
                ("chk", "✓", 44, "center"), ("o_srv", "Alter Server", 90, "w"), ("o_name", "Alte Gilde", 220, "w"),
                ("n_srv", "Neuer Server", 90, "w"), ("n_name", "Neue Gilde", 220, "w"), ("votes", "gemeinsame Spieler", 130, "e"),
                ("share", "Anteil der alten Gilde", 150, "e"), ("note", "Hinweis", 320, "w")], height=12)
            self.gtree.bind("<Button-1>", self._gclick, add="+")
            self.gtree.bind("<space>", self._gspace)
            self.gtree.bind("<Double-Button-1>", lambda e: self._gpick_new() if self.gtree.identify_region(e.x, e.y) == "cell" and
                            self.gtree.identify_column(e.x) != "#1" else None)

        def _build_saved(self):
            self.stree, self.sgrid = self._tree(self.p3, [
                ("date", "Gespeichert", 140, "w"), ("old", "Alte Server", 260, "w"), ("new", "Neuer Server", 100, "w"),
                ("np", "Spieler", 80, "e"), ("ng", "Gilden", 80, "e")], height=4)
            self.stree.configure(selectmode="browse")
            self.stree.bind("<<TreeviewSelect>>", lambda e: self._fill_links())
            bar = ttk.Frame(self.p3)
            bar.pack(fill="x", padx=6, pady=(0, 4))
            ttk.Button(bar, text="Ganze Zusammenlegung löschen (rückgängig)", command=self.delete_saved).pack(side="left")
            ttk.Label(bar, text="Darunter kannst du auch einzelne Zuordnungen entfernen.", style="Dim.TLabel").pack(side="left", padx=10)
            self.v_hide = tk.BooleanVar(value=bool(self.app.cfg.d.get("hide_fused", True)))
            ttk.Checkbutton(bar, text="Fusionierte alte Server in allen Listen ausblenden", variable=self.v_hide,
                            command=self._hide_toggled).pack(side="right")
            bar2 = ttk.Frame(self.p3)
            bar2.pack(fill="x", padx=6, pady=(4, 2))
            ttk.Label(bar2, text="Zuordnungen der gewählten Zusammenlegung – Suche (mehrere mit Komma):").pack(side="left")
            self.lq = tk.StringVar()
            ttk.Entry(bar2, textvariable=self.lq, width=26).pack(side="left", padx=6)
            self.lq.trace_add("write", lambda *a: self._fill_links())
            ttk.Button(bar2, text="Ausgewählte Zuordnungen entfernen", command=self.delete_links).pack(side="right")
            self.ltree, self.lgrid = self._tree(self.p3, [
                ("typ", "Art", 70, "w"), ("o_srv", "Alter Server", 90, "w"), ("o_name", "Alter Name", 210, "w"),
                ("n_srv", "Neuer Server", 90, "w"), ("n_name", "Neuer Name", 210, "w")], height=8)
            self._link_idx = {}

        # ---- Daten
        def refresh(self):
            self.dirty = False
            app = self.app
            raw = merge_dedupe([r for x in app.sources for r in x["recs"]], canon=False) if app.sources else []
            self._raw = raw
            cnt, disp = Counter(), {}
            for r in raw:
                cnt[r["_srv"]] += 1
                disp[r["_srv"]] = r["_srv_disp"]
            keep = {self.srv_keys[i] for i in self.lb_old.curselection() if i < len(self.srv_keys)}
            new_prev = self._new_key()
            self.srv_keys = sorted(cnt, key=natural_key)
            self.lb_old.delete(0, "end")
            fz = self.app.fused_keys()
            for k in self.srv_keys:
                self.lb_old.insert("end", tkstr("%s   (%s Spieler)%s" % (disp[k], _group(cnt[k]), "  – fusioniert" if k in fz else "")))
            for i, k in enumerate(self.srv_keys):
                if k in keep:
                    self.lb_old.selection_set(i)
            self.cb_new.configure(values=[tkstr(disp[k]) for k in self.srv_keys])
            self._disp = disp
            if new_prev in disp:
                self.cb_new.set(tkstr(disp[new_prev]))
            elif not self.cb_new.get() and self.srv_keys:
                # der Server mit dem neuesten Scan ist meist der neue
                self.cb_new.set(tkstr(disp[max(self.srv_keys, key=lambda k: max((r.get("_ts") or 0) for r in raw if r["_srv"] == k))]))
            self._fill_saved()
            self._update_sel_label()
            if not raw:
                self.info.configure(text="Noch keine Daten geladen – oben Datei(en) laden (alter und neuer Scan).")

        def preset(self, olds, new_k):
            """Alte Server und neuen Server waehlen und Kandidaten suchen (Vorschlag nach einer erkannten Fusion)."""
            self.refresh()
            self.lb_old.selection_clear(0, "end")
            for i, k in enumerate(self.srv_keys):
                if k in olds:
                    self.lb_old.selection_set(i)
            if new_k in getattr(self, "_disp", {}):
                self.cb_new.set(tkstr(self._disp[new_k]))
            self.search()

        def _new_key(self):
            v = self.cb_new.get()
            for k, d in getattr(self, "_disp", {}).items():
                if tkstr(d) == v:
                    return k
            return None

        def search(self):
            new_k = self._new_key()
            olds = [self.srv_keys[i] for i in self.lb_old.curselection() if i < len(self.srv_keys)]
            if not self._raw or not new_k or not olds:
                messagebox.showinfo(APP_NAME, "Bitte alte Server auswählen und den neuen Server wählen.")
                return
            if new_k in olds:
                messagebox.showinfo(APP_NAME, "Der neue Server darf nicht zugleich ein alter Server sein.")
                return
            try:
                sim = max(0.7, min(1.0, int(self.sim.get()) / 100.0))
            except ValueError:
                sim = 0.85
            self.app.config(cursor="watch")
            self.app.set_status("Suche Kandidaten …")
            self.app.update_idletasks()
            try:
                done_old = set(_ALIAS["p"])
                self.old_recs = [r for r in self._raw if r["_srv"] in olds and (r["_srv"], r["name"].lower()) not in done_old]
                self.new_recs = [r for r in self._raw if r["_srv"] == new_k]
                komp = {}
                try:                                              # Kompensation: so viele Level mehr sind beim alten Server zu erwarten
                    plan = self.app.komp_plan_now()
                    lpm = float(str(self.app.cfg.d.get("komp_level_per_month", 2)).replace(",", "."))
                    for k in olds:
                        if k in plan and not plan[k].get("fused") and plan[k].get("months"):
                            komp[k] = int(math.floor(float(plan[k]["months"]) * lpm + 1e-9))
                except Exception:
                    komp = {}
                rows = find_merge_candidates(self.old_recs, self.new_recs, fuzzy=bool(self.fuzzy.get()), min_sim=sim, komp=komp)
            finally:
                self.app.config(cursor="")
            for r in rows:
                r["sel"] = r["cands"][r["choice"]] if r.get("choice") is not None else None
                r["checked"] = r["status"] == "sicher"
            self.rows = rows
            self.old_keys = olds
            self.new_key = new_k
            cnt = Counter(r["status"] for r in rows)
            self.info.configure(text=tkstr(
                "%s: %s Spieler · alte Server: %s Spieler · Treffer: %d (sicher %d, prüfen %d, unsicher %d) · ohne Treffer: %s. "
                "Sichere Treffer sind schon angehakt – bitte trotzdem kurz durchsehen." % (
                    self._disp.get(new_k, new_k), _group(len(self.new_recs)), _group(len(self.old_recs)), len(rows), cnt["sicher"],
                    cnt["prüfen"], cnt["unsicher"], _group(len(self.new_recs) - len(rows)))))
            self._gsig = None
            self.grows = []
            self._fill()
            self._fill_g()
            self.inner.select(self.p1)
            self.app.set_status("%d Kandidaten gefunden." % len(rows))

        # ---- Spielertabelle
        def _vals(self, r):
            n, sel = r["new"], r.get("sel")
            o = sel[1] if sel else None
            return {"chk": 1 if r.get("checked") else 0, "status": self.STATUS_ORDER.get(r["status"], 9),
                    "score": sel[0] if sel else -1, "n_name": n["name"].lower(), "n_guild": (n.get("guild") or "").lower(),
                    "n_lvl": n.get("level") or 0, "o_srv": natural_key(o["_srv_disp"]) if o else [],
                    "o_name": o["name"].lower() if o else "", "o_guild": (o.get("guild") or "").lower() if o else "",
                    "o_lvl": (o.get("level") or 0) if o else 0,
                    "dlv": ((n.get("level") or 0) - (o.get("level") or 0)) if o else -10 ** 9}

        def _mq_changed(self):
            if self._mq_after:
                self.after_cancel(self._mq_after)
            self._mq_after = self.after(300, self._fill)

        def _gq_changed(self):
            if self._gq_after:
                self.after_cancel(self._gq_after)
            self._gq_after = self.after(300, self._fill_g)

        def _visible(self):
            f = self.flt.get()
            terms = parse_terms(self.mq.get())
            out = []
            for i, r in enumerate(self.rows):
                if f == self.FILTERS[1] and r["status"] != "sicher":
                    continue
                if f == self.FILTERS[2] and r["status"] not in ("prüfen", "unsicher"):
                    continue
                if f == self.FILTERS[3] and not r.get("checked"):
                    continue
                if f == self.FILTERS[4] and r.get("checked"):
                    continue
                if terms:
                    n, sel = r["new"], r.get("sel")
                    o = sel[1] if sel else None
                    if not match_terms(terms, n["name"], n.get("guild"), o["name"] if o else "", o.get("guild") if o else ""):
                        continue
                out.append(i)
            col, desc = self.psort
            s2 = getattr(self, "psort2", None)
            if s2 and s2[0] != col:
                out = sort_rows(out, lambda i: self._vals(self.rows[i])[s2[0]], s2[1])
            if col:
                out = sort_rows(out, lambda i: self._vals(self.rows[i])[col], desc)
            return out

        def _phead_right(self, e):
            if self.ptree.identify_region(e.x, e.y) != "heading":
                return None
            try:
                col = self.ptree["columns"][int(self.ptree.identify_column(e.x)[1:]) - 1]
            except (ValueError, IndexError):
                return None
            if col in ("why",):
                return "break"
            self.psort2 = sort2_cycle(self.psort2, col, self.psort[0], col in ("score", "n_lvl", "o_lvl", "dlv", "chk"))
            self._fill()
            return "break"

        def _fill(self):
            tr = self.ptree
            tr.delete(*tr.get_children())
            for i in self._visible():
                r = self.rows[i]
                n, sel = r["new"], r.get("sel")
                o = sel[1] if sel else None
                tr.insert("", "end", iid=str(i), tags=(r["status"],), values=[
                    "☑" if r.get("checked") else "☐", r["status"], sel[0] if sel else "", tkstr(n["name"]), tkstr(n.get("guild") or ""),
                    fmt_num(n.get("level")), o["_srv_disp"] if o else "", tkstr(o["name"]) if o else "",
                    tkstr(o.get("guild") or "") if o else "", fmt_num(o.get("level")) if o else "",
                    fmt_num((n.get("level") or 0) - (o.get("level") or 0), True) if o and n.get("level") is not None and o.get("level") is not None else "",
                    tkstr(" · ".join(sel[2])) if sel else "kein alter Spieler zugeordnet"])
            self.pgrid.schedule()
            self._update_sel_label()

        def _psort(self, col):
            c, d = self.psort
            self.psort = (col, not d) if c == col else (col, col in ("score", "n_lvl", "o_lvl", "dlv", "chk"))
            self._fill()

        def _set_checked(self, i, val):
            r = self.rows[i]
            r["checked"] = bool(val) and r.get("sel") is not None
            self.ptree.set(str(i), "chk", "☑" if r["checked"] else "☐")

        def _click(self, e):
            if self.ptree.identify_region(e.x, e.y) == "cell" and self.ptree.identify_column(e.x) == "#1":
                iid = self.ptree.identify_row(e.y)
                if iid:
                    self._set_checked(int(iid), not self.rows[int(iid)].get("checked"))
                    self._update_sel_label()
                    return "break"

        def _space(self, e):
            for iid in self.ptree.selection():
                self._set_checked(int(iid), not self.rows[int(iid)].get("checked"))
            self._update_sel_label()
            return "break"

        def _bulk(self, what):
            for i in self._visible():
                r = self.rows[i]
                if what == "safe":
                    if r["status"] == "sicher":
                        r["checked"] = True
                elif what == "all":
                    r["checked"] = r.get("sel") is not None
                else:
                    r["checked"] = False
            self._fill()

        def open_alt(self):
            s = self.ptree.selection()
            if not s:
                messagebox.showinfo(APP_NAME, "Bitte zuerst eine Zeile auswählen.")
                return
            MergeAltDialog(self, self.rows[int(s[0])])

        def assign(self, row, item):
            """item = (Punkte, alter Spieler, Begruendung) oder None. False, wenn abgebrochen."""
            if item is None:
                row["sel"], row["checked"], row["status"] = None, False, "kein freier Kandidat"
                self._fill()
                return True
            o = item[1]
            for r in self.rows:
                if r is not row and r.get("sel") and r["sel"][1] is o:
                    if not messagebox.askyesno(APP_NAME, "Der alte Spieler „%s“ (%s) ist schon „%s“ zugeordnet.\n\nDie andere Zuordnung aufheben "
                                               "und ihn stattdessen „%s“ zuordnen?" % (o["name"], o["_srv_disp"], r["new"]["name"], row["new"]["name"])):
                        return False
                    r["sel"], r["checked"], r["status"] = None, False, "kein freier Kandidat"
            row["sel"], row["checked"], row["status"] = item, True, "manuell"
            self._fill()
            return True

        def _update_sel_label(self):
            n = sum(1 for r in self.rows if r.get("checked"))
            g = sum(1 for r in self.grows if r.get("checked"))
            self.sel_lbl.configure(text=tkstr("%d Spieler und %d Gilden zum Speichern vorgemerkt." % (n, g) if self.rows else
                                              "Noch keine Kandidaten – oben alte und neuen Server wählen und „Kandidaten suchen“ drücken."))

        # ---- Gilden
        def _links(self):
            return [(r["sel"][1], r["new"]) for r in self.rows if r.get("checked") and r.get("sel")]

        def ensure_guilds(self, force=False):
            links = self._links()
            sig = tuple(sorted((id(o), id(n)) for o, n in links))
            if not force and sig == self._gsig:
                return
            self._gsig = sig
            props = guild_link_proposals(links, self.old_recs, self.new_recs)
            self.grows = []
            for p in props:
                og, ng = p["old"], p["new"]
                same = og[2].lower() == ng[2].lower()
                sfx = re.sub(r"\s*\([^()]*\)\s*$", "", ng[2]).strip().lower() == og[2].strip().lower()
                note = "Name gleich" if same else ("Name gleich + Server-Zusatz" if sfx else (
                    "Name fast gleich" if norm_name(og[2]) == norm_name(ng[2]) else "andere Bezeichnung"))
                if p["share"] < 0.5:
                    note += " · nur %d von %d Spielern" % (p["votes"], p["old_n"])
                if p.get("byname") and p["share"] < 0.5:
                    note += " (Gildenname zählt)"
                self.grows.append({"old": og, "new": ng, "votes": p["votes"], "old_n": p["old_n"], "share": p["share"],
                                   "note": note, "checked": bool(p.get("byname")) or p["share"] >= 0.5 or p["votes"] >= 3})
            self._fill_g()

        def _fill_g(self):
            tr = self.gtree
            tr.delete(*tr.get_children())
            gterms = parse_terms(self.gq.get())
            for i, g in enumerate(self.grows):
                if gterms and not match_terms(gterms, g["old"][2], g["new"][2], g["old"][1], g["new"][1]):
                    continue
                tr.insert("", "end", iid=str(i), tags=("sicher" if g["share"] >= 0.5 else "prüfen",), values=[
                    "☑" if g["checked"] else "☐", g["old"][1], tkstr(g["old"][2]), g["new"][1], tkstr(g["new"][2]), g["votes"],
                    "%d %%  (%d von %d)" % (round(g["share"] * 100), g["votes"], g["old_n"]), tkstr(g["note"])])
            self.ggrid.schedule()
            self._update_sel_label()

        def _inner_changed(self):
            try:
                if self.inner.select() == str(self.p2) and self.rows:
                    self.ensure_guilds()
            except tk.TclError:
                pass

        def _gclick(self, e):
            if self.gtree.identify_region(e.x, e.y) == "cell" and self.gtree.identify_column(e.x) == "#1":
                iid = self.gtree.identify_row(e.y)
                if iid:
                    g = self.grows[int(iid)]
                    g["checked"] = not g["checked"]
                    self.gtree.set(iid, "chk", "☑" if g["checked"] else "☐")
                    self._update_sel_label()
                    return "break"

        def _gspace(self, e):
            for iid in self.gtree.selection():
                g = self.grows[int(iid)]
                g["checked"] = not g["checked"]
                self.gtree.set(iid, "chk", "☑" if g["checked"] else "☐")
            self._update_sel_label()
            return "break"

        def _gpick_new(self):
            s = self.gtree.selection()
            if not s:
                return
            g = self.grows[int(s[0])]
            names = {}
            for r in self.new_recs:
                if r.get("guild"):
                    names.setdefault(r["guild"].lower(), r["guild"])
            items = sorted(names.values(), key=str.lower)

            def pick(i):
                g["new"] = (g["new"][0], g["new"][1], items[i])
                g["note"] = "von Hand gewählt"
                g["checked"] = True
                self._fill_g()
            _PickDialog(self, "Neue Gilde wählen", "Welche Gilde auf dem neuen Server ist die Nachfolgerin von „%s“?" % g["old"][2], items, pick)

        # ---- Speichern / Gespeichertes
        def save(self):
            if not self.rows:
                messagebox.showinfo(APP_NAME, "Es gibt noch nichts zu speichern – erst Kandidaten suchen und prüfen.")
                return
            self.ensure_guilds()
            links = self._links()
            if not links:
                messagebox.showinfo(APP_NAME, "Es ist kein Spieler angehakt.")
                return
            gl = [g for g in self.grows if g["checked"]]
            m = {"id": int(time.time()), "date": datetime.datetime.now().strftime("%d.%m.%Y %H:%M"),
                 "old": [self._disp.get(k, k) for k in self.old_keys], "new": self._disp.get(self.new_key, self.new_key),
                 "players": [[o["_srv"], o["name"], n["_srv"], n["name"]] for o, n in links],
                 "guilds": [[g["old"][0], g["old"][2], g["new"][0], g["new"][2]] for g in gl]}
            if not messagebox.askyesno(APP_NAME, "%d Spieler und %d Gilden von %s nach %s zusammenlegen?\n\nDanach werden sie in Entwicklung, "
                                       "Δ-Vergleich und Zu-/Abgängen als dieselben Spieler bzw. Gilden behandelt. Rückgängig machen kannst du das "
                                       "unter „Gespeicherte Zusammenlegungen“." % (len(links), len(gl), ", ".join(m["old"]), m["new"])):
                return
            self.app.cfg.d.setdefault("merges", []).append(m)
            self._apply(m_saved=len(links))
            self.rows, self.grows, self._gsig = [], [], None
            self._fill()
            self._fill_g()
            self.info.configure(text=tkstr("Gespeichert: %d Spieler, %d Gilden." % (len(links), len(gl))))
            self.inner.select(self.p3)

        def _apply(self, m_saved=0):
            self.app.apply_merges()
            self.refresh()

        def _fill_saved(self):
            tr = self.stree
            tr.delete(*tr.get_children())
            for i, m in enumerate(self.app.cfg.d.get("merges", [])):
                tr.insert("", "end", iid=str(i), values=[m.get("date", ""), tkstr(", ".join(m.get("old", []))), tkstr(m.get("new", "")),
                                                          len(m.get("players", [])), len(m.get("guilds", []))])
            self.sgrid.schedule()

        def _hide_toggled(self):
            self.app.cfg.d["hide_fused"] = bool(self.v_hide.get())
            self.app.after_data_changed()
            self.refresh()

        def _cur_merge(self):
            s = self.stree.selection()
            ms = self.app.cfg.d.get("merges", [])
            return (int(s[0]), ms[int(s[0])]) if s and int(s[0]) < len(ms) else (None, None)

        def _fill_links(self):
            tr = self.ltree
            tr.delete(*tr.get_children())
            self._link_idx = {}
            _i, m = self._cur_merge()
            if m is None:
                return
            qs = [norm_name(t) for t in parse_terms(self.lq.get())]
            n = 0
            for kind, key, lst in (("Spieler", "players", m.get("players", [])), ("Gilde", "guilds", m.get("guilds", []))):
                for j, (os_, on, ns, nn) in enumerate(lst):
                    if qs and not any(q in norm_name(on) or q in norm_name(nn) for q in qs):
                        continue
                    iid = "l%d" % n
                    n += 1
                    self._link_idx[iid] = (key, j)
                    tr.insert("", "end", iid=iid, values=[kind, os_.upper(), tkstr(on), ns.upper(), tkstr(nn)])
                    if n >= 5000:
                        break
            self.lgrid.schedule()

        def delete_links(self):
            mi, m = self._cur_merge()
            sel = self.ltree.selection()
            if m is None or not sel:
                messagebox.showinfo(APP_NAME, "Bitte links oben eine Zusammenlegung wählen und unten die Zuordnungen markieren, "
                                              "die entfernt werden sollen (Strg/Umschalt = mehrere).")
                return
            if not messagebox.askyesno(APP_NAME, "%d Zuordnung(en) entfernen?\n\nDie betroffenen Spieler/Gilden gelten danach wieder "
                                       "als getrennt (alter Server und neuer Server)." % len(sel)):
                return
            drop = {}
            for iid in sel:
                key, j = self._link_idx[iid]
                drop.setdefault(key, set()).add(j)
            for key, js in drop.items():
                m[key] = [x for j, x in enumerate(m.get(key, [])) if j not in js]
            ms = self.app.cfg.d["merges"]
            if not m.get("players") and not m.get("guilds"):
                del ms[mi]
                mi = None
            self._apply()
            if mi is not None and self.stree.exists(str(mi)):
                self.stree.selection_set(str(mi))
            self._fill_links()

        def delete_saved(self):
            s = self.stree.selection()
            if not s:
                messagebox.showinfo(APP_NAME, "Bitte eine Zusammenlegung in der Liste auswählen.")
                return
            ms = self.app.cfg.d.get("merges", [])
            m = ms[int(s[0])]
            if not messagebox.askyesno(APP_NAME, "Die Zusammenlegung %s → %s (%d Spieler, %d Gilden) löschen?" % (
                    ", ".join(m.get("old", [])), m.get("new", ""), len(m.get("players", [])), len(m.get("guilds", [])))):
                return
            del ms[int(s[0])]
            self._apply()


    # ==================================================================================
    #  5.8 Reiter „Kompensation“: Level- und Base-Bonus fuer spaeter gestartete Server
    # ==================================================================================
    DEFAULT_KOMP_COLS = ["komp_server", "name", "level", "level_k", "base_k", "komp_bonus"]
    DEFAULT_KOMP_GCOLS = ["komp_server", "g_name", "kg_members", "kg_level_avg", "kg_level_k_avg", "kg_base_k_sum",
                          "kg_bonus_sum", "kg_bonus_avg"]

    def _gkey(r):
        return r.get("_komp_g") or (9999, 9)

    class KompTable(TableTab):
        """Tabellen im Reiter Kompensation (Spieler / Gilden) - Aufbau und Bedienung wie Ehrenhalle und Gilden-Tabelle."""
        GROUPS_K = [("Gilde", ["komp_server", "g_server", "g_name", "komp_group", "kg_members"]),
                    ("Level", ["kg_level_avg", "kg_level_k_avg"]),
                    ("Base & Bonus", ["kg_base_sum", "kg_base_k_sum", "kg_bonus_sum", "kg_bonus_avg"])]

        def __init__(self, master, app, host, mode, count_parent=None):
            self.host = host
            super().__init__(master, app, mode=mode, count_parent=count_parent)

        def _init_mode(self, mode):
            if mode == "kguild":
                self.is_guild = True
                self.all_keys = ["komp_server", "g_server", "g_name", "komp_group"] + [f.key for f in KFIELDS]
                self.default_cols = list(DEFAULT_KOMP_GCOLS)
                self.cfg_cols, self.cfg_limit = "komp_guild_cols", "komp_guild_limit"
                self.groups = self.GROUPS_K
                self.unit = "Gilden"
                self.bold_key, self.icon_col = "g_name", None
                self.png_title, self.csv_name = "Kompensation Gilden", "Kompensation_Gilden.csv"
                self.search_label = "Suche (Gilde / Server):"
                names = {"komp_server": "Server", "g_name": "Gildenname"}
            else:
                self.is_guild = False
                self.all_keys = [f.key for f in FIELDS]
                self.default_cols = list(DEFAULT_KOMP_COLS)
                self.cfg_cols, self.cfg_limit = "komp_cols", "komp_limit"
                self.groups = self.GROUPS
                self.unit = "Spielern"
                self.bold_key, self.icon_col = "name", "name"
                self.png_title, self.csv_name = "Kompensation Spieler", "Kompensation_Spieler.csv"
                self.search_label = "Suche (Name / Gilde / Server):"
                names = {"komp_server": "Server", "name": "Spieler"}
            self.sort_key, self.sort_desc = None, True
            self.scan_key = None
            cn = self.app.cfg.d.setdefault("col_names", {})
            if mode not in cn:
                cn[mode] = dict(names)

        def _source(self):
            return self.host.rows(self.mode)

        def _match(self, terms, p):
            if self.is_guild:
                return match_terms(terms, p["name"], p.get("_srv_disp"), p.get("komp_server"))
            return match_terms(terms, p["name"], p.get("guild"), p.get("_srv_disp"), p.get("komp_server"))

        def _show_detail(self, rec):
            if not self.is_guild:
                PlayerDialog(self.app, rec)
                return
            low = rec["name"].lower()
            for g in self.app.guilds_all():
                if g["_srv"] == rec["_srv"] and g["name"].lower() == low:
                    GuildDialog(self.app, g)
                    return
            messagebox.showinfo(APP_NAME, "Zu dieser Gilde gibt es keine Gilden-Daten im Scan.", parent=self)

    class KompTab(ttk.Frame):
        """Reiter Kompensation: spaeter gestartete Server bekommen Level- und Base-Bonus (Spieler- und Gildenliste)."""
        MODES = [("round", "auf halbe Monate gerundet (wie die sf-tools-Formel)"), ("exact", "exakt aus dem Startdatum")]

        def __init__(self, master, app):
            super().__init__(master)
            self.app = app
            self.dirty = True
            self._cache = None
            bar = ttk.Frame(self)
            bar.pack(fill="x", padx=10, pady=(8, 0))
            self.btn = {}
            for key, txt in (("players", "Spieler"), ("guilds", "Gilden")):
                b = ttk.Button(bar, text=txt, width=12, command=lambda k=key: self.show(k))
                b.pack(side="left", padx=(0, 4))
                self.btn[key] = b
            ttk.Label(bar, text="Fusionsgruppe:").pack(side="left", padx=(16, 4))
            self.group = tk.StringVar(value=eu_names(app.cfg.d.get("komp_group", "alle")))
            self.gcb = ttk.Combobox(bar, textvariable=self.group, state="readonly", width=22, values=["alle"])
            self.gcb.pack(side="left")
            self.gcb.bind("<<ComboboxSelected>>", lambda e: self._group_changed())
            Tip(self.gcb, "Server werden jedes Halbjahr zusammengelegt (Jan–Jun, Jul–Dez). Kompensiert wird innerhalb einer "
                          "Gruppe: der erste Server des Halbjahres ist der Bezug (0 Monate).")
            ttk.Label(bar, text="Monate:").pack(side="left", padx=(16, 4))
            self.mode = tk.StringVar()
            self.mcb = ttk.Combobox(bar, textvariable=self.mode, state="readonly", width=44, values=[t for _k, t in self.MODES])
            self.mcb.pack(side="left")
            self.mcb.bind("<<ComboboxSelected>>", lambda e: self._mode_changed())
            Tip(self.mcb, "Gerundet: Tage seit dem ersten Server des Halbjahres ÷ 30,44, auf halbe Monate gerundet "
                          "(ergibt für EU6–EU8 genau 1,5 / 3 / 4,5 wie die Formel). Exakt: ohne Runden (z. B. 1,38).")
            ttk.Button(bar, text="Serverliste & Startdaten …", command=self.open_servers).pack(side="right")
            bar2 = ttk.Frame(self)
            bar2.pack(fill="x", padx=10, pady=(6, 0))
            self.cyc = tk.BooleanVar(value=(app.cfg.d.get("komp_cycle") is not False))
            cyc = ttk.Checkbutton(bar2, text="Halbjahres-Zyklus", variable=self.cyc, command=self._cycle_changed)
            cyc.pack(side="left", padx=(0, 6))
            Tip(cyc, "An (Standard): kompensiert wird je Halbjahr (Jan–Jun, Jul–Dez), Bezug ist der erste Server des Halbjahres.\n"
                     "Aus: kein Halbjahr – alle Server ab dem gewählten Bezugsserver zählen zusammen, Monate ab dessen Start. "
                     "Ältere (noch nicht fusionierte) Server bekommen dann nichts. Der Fusionsplan der Online-Liste bleibt je Halbjahr.")
            ttk.Label(bar2, text="Bezug:").pack(side="left")
            self.ref = tk.StringVar()
            self.rcb = ttk.Combobox(bar2, textvariable=self.ref, state="readonly", width=8)
            self.rcb.pack(side="left", padx=(4, 16))
            self.rcb.bind("<<ComboboxSelected>>", lambda e: self._ref_changed())
            Tip(self.rcb, "Bezugsserver ohne Halbjahres-Zyklus: bekommt 0 Monate, alle später gestarteten Server werden an ihm gemessen.")
            ttk.Label(bar2, text="Goldkurve:").pack(side="left")
            self.curve = tk.StringVar()
            self.ccb = ttk.Combobox(bar2, textvariable=self.curve, state="readonly", width=38, values=[t for _k, t in KOMP_CURVES])
            self.ccb.pack(side="left", padx=(4, 0))
            self.ccb.bind("<<ComboboxSelected>>", lambda e: self._curve_changed())
            Tip(self.ccb, "Neu (Standard): bis Level 556 wie die Goldkurve des Spiels, danach je Level nur noch 12,8 / 25,6 / 38,4 Stats "
                          "(Server 1,5 / 3 / 4,5 Monate später gestartet) – so wurde F28 kompensiert. Alt: die Goldkurve ohne Knick "
                          "(sf-tools-Formel), ab Level 557 deutlich mehr.")
            self.info = ttk.Label(bar2, text="", style="Dim.TLabel")
            self.info.pack(side="right")
            self.body = ttk.Frame(self)
            self.body.pack(fill="both", expand=True)
            self.players = KompTable(self.body, app, self, "kplayer", count_parent=bar2)
            self.guilds = KompTable(self.body, app, self, "kguild", count_parent=bar2)
            self.view = None
            self.load_from_cfg()
            v = app.cfg.d.get("komp_view")
            self.show(v if v in ("players", "guilds") else "players")

        def load_from_cfg(self):
            m = self.app.cfg.d.get("komp_mode", "round")
            self.mode.set(dict(self.MODES).get(m, self.MODES[0][1]))
            self.curve.set(dict(KOMP_CURVES).get(self.app.cfg.d.get("komp_curve", "new"), KOMP_CURVES[0][1]))
            self.group.set(eu_names(self.app.cfg.d.get("komp_group", "alle")))
            self._fill_ref()

        def _fill_ref(self):
            d = self.app.cfg.d
            sv = [x for x in (d.get("komp_servers") or default_komp_servers()) if not x.get("fused") and parse_day(x.get("start"))]
            sv.sort(key=lambda x: parse_day(x.get("start")))
            names = [eu_names(x.get("name")) for x in sv]
            self.rcb.configure(values=names)
            cur = eu_names(d.get("komp_ref") or "")
            self.ref.set(cur if cur in names else (names[0] if names else ""))
            self.cyc.set((d.get("komp_cycle") is not False))
            self.rcb.configure(state="disabled" if self.cyc.get() else "readonly")

        def _cycle_changed(self):
            on = bool(self.cyc.get())
            self.rcb.configure(state="disabled" if on else "readonly")
            self.app.cfg.d["komp_cycle"] = on
            if not on and not self.app.cfg.d.get("komp_ref"):
                self.app.cfg.d["komp_ref"] = self.ref.get()
            self.app.komp_changed("komp_cycle")

        def _ref_changed(self):
            if self.ref.get() != self.app.cfg.d.get("komp_ref"):
                self.app.cfg.d["komp_ref"] = self.ref.get()
                self.app.komp_changed("komp_ref")

        def _current(self):
            return self.players if self.view == "players" else self.guilds

        def show(self, view):
            self.view = view
            for w in (self.players, self.guilds):
                w.pack_forget()
                w.count.pack_forget()
            cur = self._current()
            cur.pack(fill="both", expand=True)
            cur.count.pack(side="left", padx=14)
            for k, b in self.btn.items():
                b.configure(style="Accent.TButton" if k == view else "TButton")
            self.app.cfg.d["komp_view"] = view
            self.app.save_soon()
            self.after(30, self.refresh_view)

        def refresh_view(self):
            t = self._current()
            if getattr(t, "dirty", True):
                self.app.config(cursor="watch")
                self.app.update_idletasks()
                try:
                    t.refresh()
                finally:
                    self.app.config(cursor="")

        def _all(self):
            key = (id(self.app.data), len(self.app.data), getattr(self.app, "komp_version", 0), self.group.get())
            if self._cache and self._cache[0] == key:
                return self._cache[1], self._cache[2]
            recs = [r for r in self.app.data if r.get("komp_bonus") is not None]
            g = self.group.get()
            if g and g != "alle":
                recs = [r for r in recs if r.get("komp_group") == g]
            recs.sort(key=lambda r: (_gkey(r), natural_key(r["komp_server"]), -r["komp_bonus"],
                                     -(r.get("base_k") or 0), (r["name"] or "").lower()))
            guilds = komp_guilds(recs)
            guilds.sort(key=lambda x: (_gkey(x), natural_key(x["komp_server"]),
                                       -x["kg_bonus_sum"], -(x.get("kg_base_k_sum") or 0)))
            self._cache = (key, recs, guilds)
            return recs, guilds

        def rows(self, mode):
            recs, guilds = self._all()
            return guilds if mode == "kguild" else recs

        def refresh(self):
            self.dirty = False
            self.players.dirty = self.guilds.dirty = True
            allk = [r for r in self.app.data if r.get("komp_bonus") is not None]
            groups = [lab for _g, lab in sorted({(_gkey(r), r["komp_group"]) for r in allk})]
            self.gcb.configure(values=["alle"] + groups)
            if self.group.get() not in (["alle"] + groups):
                self.group.set("alle")
            recs, guilds = self._all()
            srv = sorted({r["komp_server"] for r in recs}, key=natural_key)
            if not self.app.data:
                txt = "Noch keine Daten geladen."
            elif not allk:
                txt = "Keine Spieler von Servern aus der Kompensations-Liste in den geladenen Daten (Serverliste & Startdaten …)."
            else:
                txt = "%s Spieler, %s Gilden auf %d Servern (%s) · unabhängig von der Serverauswahl" % (
                    _group(len(recs)), _group(len(guilds)), len(srv), ", ".join(srv[:8]) + (" …" if len(srv) > 8 else ""))
            try:
                lpm = float(str(self.app.cfg.d.get("komp_level_per_month", 2)).replace(",", "."))
            except ValueError:
                lpm = 2.0
            cyc = "je Halbjahr" if self.app.cfg.d.get("komp_cycle") is not False else "ohne Zyklus, ab %s" % (self.ref.get() or "–")
            txt = "Level-Bonus: %s je Monat · Monate: %s · %s   ·   %s" % (
                fmt_num(lpm), "exakt" if self.app.cfg.d.get("komp_mode", "round") == "exact" else "gerundet", cyc, txt)
            self.info.configure(text=tkstr(txt))
            self.refresh_view()

        def _group_changed(self):
            self.app.cfg.d["komp_group"] = self.group.get()
            self.app.save_soon()
            self.players.dirty = self.guilds.dirty = True
            self.refresh()

        def _mode_changed(self):
            key = {t: k for k, t in self.MODES}.get(self.mode.get(), "round")
            if key != self.app.cfg.d.get("komp_mode", "round"):
                self.app.cfg.d["komp_mode"] = key
                self.app.komp_changed("komp_mode")

        def _curve_changed(self):
            key = {t: k for k, t in KOMP_CURVES}.get(self.curve.get(), "new")
            if key != self.app.cfg.d.get("komp_curve", "new"):
                self.app.cfg.d["komp_curve"] = key
                self.app.komp_changed("komp_curve")

        def open_servers(self):
            KompServerDialog(self.app)

    class KompServerDialog(tk.Toplevel):
        """Serverliste der Kompensation bearbeiten: Startdaten, Kuerzel im Programm, Herkunfts-Nummer, bereits fusioniert."""
        COLS = [("name", "Server", 70), ("key", "Kürzel", 65), ("start", "Start", 100), ("group", "Halbjahr", 125),
                ("fgroup", "Fusionsgruppe", 150), ("ref", "Bezug", 65), ("mr", "Monate (gerundet)", 140),
                ("me", "Monate (exakt)", 120), ("origin", "Herkunfts-Nr.", 110), ("fused", "Status", 140),
                ("n", "Spieler im Scan", 150)]

        def __init__(self, app):
            super().__init__(app)
            self.app = app
            self.title("Kompensation – Serverliste & Startdaten")
            self.configure(bg=C["bg"])
            self.transient(app)
            self.geometry("1330x720+%d+%d" % (app.winfo_rootx() + 30, app.winfo_rooty() + 40))
            ttk.Label(self, text="Serverliste der Kompensation", style="Head.TLabel").pack(anchor="w", padx=14, pady=(12, 0))
            ttk.Label(self, text="Alle Server eines Halbjahres (Januar–Juni bzw. Juli–Dezember) werden zusammengelegt. Der erste Server "
                                 "des Halbjahres ist der Bezug (0 Monate), alle späteren bekommen Level- und Base-Bonus für die "
                                 "Monate Rückstand. Nach einer Fusion rechnet das Programm über den Herkunftsserver weiter (Herkunfts-Nr. "
                                 "aus dem Scan) – aber nur nach der ersten Fusion.", style="Dim.TLabel", wraplength=1120,
                      justify="left").pack(anchor="w", padx=14, pady=(2, 8))
            fr = ttk.Frame(self)
            fr.pack(fill="both", expand=True, padx=14)
            self.tree = ttk.Treeview(fr, columns=[c for c, _t, _w in self.COLS], show="headings", selectmode="browse")
            for c, t, w in self.COLS:
                self.tree.heading(c, text=t)
                self.tree.column(c, width=w, anchor="w" if c in ("name", "key", "group", "fgroup", "fused") else "center",
                                 stretch=False)
            attach_scroll(fr, self.tree)
            self.tree.pack(side="left", fill="both", expand=True)
            self.tree.bind("<<TreeviewSelect>>", lambda e: self._pick())
            form = ttk.LabelFrame(self, text=" Eintrag bearbeiten ", padding=8)
            form.pack(fill="x", padx=14, pady=8)
            self.v = {}
            for i, (k, lab, w) in enumerate((("name", "Server:", 10), ("key", "Kürzel im Programm:", 10),
                                             ("start", "Start (TT.MM.JJJJ):", 12), ("origin", "Herkunfts-Nr.:", 8))):
                ttk.Label(form, text=lab).grid(row=0, column=i * 2, sticky="w", padx=(0 if i == 0 else 12, 4))
                v = tk.StringVar()
                ttk.Entry(form, textvariable=v, width=w).grid(row=0, column=i * 2 + 1, sticky="w")
                self.v[k] = v
            self.fused = tk.BooleanVar()
            ttk.Checkbutton(form, text="bereits fusioniert (nur über Herkunft)", variable=self.fused).grid(row=0, column=8, padx=12)
            bf = ttk.Frame(form)
            bf.grid(row=1, column=0, columnspan=9, sticky="w", pady=(8, 0))
            ttk.Button(bf, text="Übernehmen", style="Accent.TButton", command=self._apply).pack(side="left")
            ttk.Button(bf, text="Neuer Server", command=self._new).pack(side="left", padx=6)
            ttk.Button(bf, text="Löschen", command=self._delete).pack(side="left")
            ttk.Button(bf, text="Standardliste wiederherstellen", command=self._defaults).pack(side="left", padx=(18, 0))
            ttk.Label(bf, text="Level-Bonus je Monat:").pack(side="left", padx=(24, 4))
            self.lpm = tk.StringVar(value=str(app.cfg.d.get("komp_level_per_month", 2)))
            ttk.Spinbox(bf, from_=0, to=20, increment=0.5, width=5, textvariable=self.lpm, command=self._lpm).pack(side="left")
            self.lpm.trace_add("write", lambda *a: self._lpm())
            ttk.Label(form, text="Kürzel = Servername im Programm (EU5 → s5, AM1 → am1). Startdatum unbekannt (z. B. EU31)? Feld leer "
                                 "lassen – der Server bekommt dann keine Kompensation, bis das Datum eingetragen ist.",
                      style="Dim.TLabel").grid(row=2, column=0, columnspan=9, sticky="w", pady=(6, 0))
            nf = ttk.Frame(form)
            nf.grid(row=3, column=0, columnspan=9, sticky="w", pady=(8, 0))
            ttk.Label(nf, text="Nächste Fusion wird F").pack(side="left")
            self.nextf = tk.StringVar(value=str(app.cfg.d.get("komp_next_f") or ""))
            ttk.Entry(nf, textvariable=self.nextf, width=5).pack(side="left", padx=4)
            self.nextf_lbl = ttk.Label(nf, text="", style="Dim.TLabel")
            self.nextf_lbl.pack(side="left", padx=6)
            self.nextf.trace_add("write", lambda *a: self._nextf())
            self._nextf(save=False)
            bot = ttk.Frame(self)
            bot.pack(fill="x", padx=14, pady=(0, 12))
            ttk.Button(bot, text="Schließen", command=self.destroy).pack(side="right")
            self.sel = None
            self._fill()

        def _servers(self):
            return self.app.cfg.d.setdefault("komp_servers", default_komp_servers())

        def _nextf(self, save=True):
            """Nummer der naechsten Fusionswelt (leer = automatisch) - fuer die Knoepfe "F29 …" in der Online-Liste."""
            txt = self.nextf.get().strip().lstrip("Ff")
            if save:
                if txt and not txt.isdigit():
                    return
                self.app.cfg.d["komp_next_f"] = txt
                self.app.save_soon()
            n, auto = self.app.next_fusion_no()
            fz = self.app.fusion_forecast()
            plan = ", ".join("%s = %s" % (f["n"], f["l"]) for f in fz[:4]) + (" …" if len(fz) > 4 else "")
            self.nextf_lbl.configure(text=tkstr(("leer = automatisch (höchste F-Welt im Scan + 1 → F%d)" % n if auto and n else
                                                 "leer = automatisch (höchste F-Welt im Scan + 1)" if auto else "eigene Nummer") +
                                                ((" · Online-Liste: " + plan) if plan else "")))

        def _fill(self, keep=None):
            self.tree.delete(*self.tree.get_children())
            d = self.app.cfg.d
            cyc, ref = (d.get("komp_cycle") is not False), d.get("komp_ref")
            plan_r = komp_plan(self._servers(), "round", cyc, ref)
            plan_e = komp_plan(self._servers(), "exact", cyc, ref)
            cnt = Counter(r["_srv"] for r in self.app.data)
            cntk = Counter(r["komp_server"] for r in self.app.data if r.get("komp_server"))
            for i, sv in enumerate(self._servers()):
                key = str(sv.get("key") or komp_key_of(sv.get("name"))).lower()
                pr, pe = plan_r.get(key), plan_e.get(key)
                n = cnt.get(key, 0)
                if sv.get("fused"):
                    st = "bereits fusioniert"
                elif not pr:
                    st = "vor dem Bezugsserver – keine" if parse_day(sv.get("start")) else "Startdatum fehlt"
                else:
                    st = "aktiv"
                kn = eu_names(sv.get("name"))
                ns = _group(n) if n else ("über Herkunft: %s" % _group(cntk.get(kn, 0)) if cntk.get(kn) else "–")
                self.tree.insert("", "end", iid=str(i), values=[
                    kn, key, sv.get("start", ""), pr["half_label"] if pr else "–",
                    pr["group_label"] if pr else "–", pr["ref"] if pr else "–",
                    fmt_num(pr["months"]) if pr else "–", fmt_num(round(pe["months"], 2)) if pe else "–",
                    sv.get("origin") or "", st, ns])
            if keep is not None and self.tree.exists(str(keep)):
                self.tree.selection_set(str(keep))
                self.tree.see(str(keep))

        def _pick(self):
            sel = self.tree.selection()
            if not sel:
                return
            self.sel = int(sel[0])
            sv = self._servers()[self.sel]
            self.v["name"].set(sv.get("name", ""))
            self.v["key"].set(sv.get("key", ""))
            self.v["start"].set(sv.get("start", ""))
            self.v["origin"].set(str(sv.get("origin") or ""))
            self.fused.set(bool(sv.get("fused")))

        def _changed(self, keep=None):
            self.app.komp_changed("komp_servers")
            self._fill(keep)

        def _apply(self):
            name = self.v["name"].get().strip()
            if not name:
                return
            start = self.v["start"].get().strip()
            if start and parse_day(start) is None:
                messagebox.showerror(APP_NAME, "Datum nicht lesbar – bitte als TT.MM.JJJJ eingeben, z. B. 07.07.2023.", parent=self)
                return
            o = self.v["origin"].get().strip()
            if o and not o.isdigit():
                messagebox.showerror(APP_NAME, "Die Herkunfts-Nr. ist eine ganze Zahl (z. B. 466) oder bleibt leer.", parent=self)
                return
            sv = {"name": name, "key": (self.v["key"].get().strip() or komp_key_of(name)).lower(), "start": start,
                  "origin": int(o) if o else None, "fused": bool(self.fused.get())}
            lst = self._servers()
            if self.sel is not None and 0 <= self.sel < len(lst):
                lst[self.sel] = sv
                keep = self.sel
            else:
                lst.append(sv)
                keep = len(lst) - 1
            self.sel = keep
            self._changed(keep)

        def _new(self):
            self.sel = None
            self.tree.selection_remove(*self.tree.selection())
            for v in self.v.values():
                v.set("")
            self.fused.set(False)

        def _delete(self):
            if self.sel is None:
                return
            lst = self._servers()
            if 0 <= self.sel < len(lst) and messagebox.askyesno(APP_NAME, "Server „%s“ aus der Liste löschen?" % lst[self.sel].get("name"),
                                                                 parent=self):
                del lst[self.sel]
                self.sel = None
                self._changed()

        def _defaults(self):
            if messagebox.askyesno(APP_NAME, "Die Serverliste auf den Standard zurücksetzen (EU1–EU31, AM1)?\n"
                                   "Eigene Änderungen an dieser Liste gehen verloren.", parent=self):
                self.app.cfg.d["komp_servers"] = default_komp_servers()
                self.sel = None
                self._changed()

        def _lpm(self):
            try:
                v = float(str(self.lpm.get()).replace(",", "."))
            except ValueError:
                return
            if v != float(self.app.cfg.d.get("komp_level_per_month", 2)):
                self.app.cfg.d["komp_level_per_month"] = v
                self.app.komp_changed("komp_level_per_month")


