    def web_head_split(items):
        """Kopfzeile: bis zum ersten "rechtsbuendig" links neben dem Titel, ab dort rechts. Aeltere Anordnungen ohne
        "rechtsbuendig" im Kopf: alle Knoepfe rechts (wie bisher)."""
        idx = next((n for n, x in enumerate(items) if x.get("right")), None)
        if idx is None:
            idx = next((n for n, x in enumerate(items) if x.get("b") not in WEB_TEXTB), len(items))
        return idx
