    class TabsDialog(tk.Toplevel):
        """Reiter der Spaltenauswahl online verwalten: neu, umbenennen, Reihenfolge, loeschen."""

        def __init__(self, tab):
            super().__init__(tab)
            self.tab = tab
            self.title("Reiter verwalten")
            self.configure(bg=C["bg"])
            self.transient(tab)
            ttk.Label(self, text="Reiter der Spaltenauswahl online (⚙ › Spalten)", style="Head.TLabel").pack(anchor="w", padx=14, pady=(12, 0))
            ttk.Label(self, text="Leere Reiter erscheinen online nicht. „Allgemein“ und „Sonstiges“ lassen sich umbenennen, aber nicht "
                                 "löschen. Spalten eines gelöschten Reiters kommen nach „Sonstiges“. Ein umbenannter Reiter heißt in "
                                 "allen Sprachen so.", style="Dim.TLabel", wraplength=520, justify="left").pack(anchor="w", padx=14)
            f = ttk.Frame(self)
            f.pack(fill="both", expand=True, padx=14, pady=8)
            self.lb = tk.Listbox(f, height=10, width=34, bg=C["panel"], fg=C["fg"], highlightthickness=0, borderwidth=0, font=FONT,
                                 activestyle="none", exportselection=False)
            self.lb.pack(side="left", fill="both", expand=True)
            bb = ttk.Frame(f)
            bb.pack(side="left", fill="y", padx=(10, 0))
            for txt, cmd in (("Neuer Reiter …", self._new), ("Umbenennen …", self._ren), ("▲ nach oben", lambda: self._mv(-1)),
                             ("▼ nach unten", lambda: self._mv(1)), ("Löschen", self._del), ("Vorgabe", self._reset)):
                ttk.Button(bb, text=txt, width=18, command=cmd).pack(fill="x", pady=2)
            ttk.Button(self, text="Schließen", command=self.destroy).pack(anchor="e", padx=14, pady=(0, 12))
            self.bind("<Escape>", lambda e: self.destroy())
            self._fill()

        def _tabs(self):
            return [list(x) for x in self.tab.web().tabs()]

        def _save(self, tabs, sel=None):
            self.tab.c["ctabs"] = tabs
            self.tab.changed(reload_cols=True)
            self._fill(sel)

        def _fill(self, sel=None):
            self.lb.delete(0, "end")
            for i, lab in self._tabs():
                self.lb.insert("end", tkstr(lab))
            if sel is not None:
                self.lb.selection_set(sel)
                self.lb.see(sel)

        def _cur(self):
            s = self.lb.curselection()
            return s[0] if s else None

        def _new(self):
            if self.tab._tab_new() is not None:
                self._fill(len(self._tabs()) - 1)

        def _ren(self):
            i = self._cur()
            if i is None:
                return
            tabs = self._tabs()
            dlg = FormDialog(self, "Reiter umbenennen", ["Neuer Name:"], [tabs[i][1]])
            name = (dlg.result or [""])[0].strip()
            if name:
                tabs[i][1] = name
                self._save(tabs, i)

        def _mv(self, d):
            i = self._cur()
            tabs = self._tabs()
            if i is None or not 0 <= i + d < len(tabs):
                return
            tabs[i], tabs[i + d] = tabs[i + d], tabs[i]
            self._save(tabs, i + d)

        def _del(self):
            i = self._cur()
            tabs = self._tabs()
            if i is None or tabs[i][0] in ("all", "misc"):
                self.tab.app.set_status("„Allgemein“ und „Sonstiges“ lassen sich nicht löschen.")
                return
            gone = tabs.pop(i)[0]
            w = self.tab.web()
            for mode_key in [k for k in list(self.tab.c) if k.startswith("cols_")]:
                for e in (self.tab.c.get(mode_key) or {}).values():
                    if isinstance(e, dict) and e.get("tab") == gone:
                        e["tab"] = "misc"
            self._save(tabs, max(0, i - 1))

        def _reset(self):
            self.tab.c.pop("ctabs", None)
            for mode_key in [k for k in list(self.tab.c) if k.startswith("cols_")]:
                for e in (self.tab.c.get(mode_key) or {}).values():
                    if isinstance(e, dict):
                        e.pop("tab", None)
            self.tab.changed(reload_cols=True)
            self._fill()


    class LivePreview:
        """Kleiner Web-Server nur auf diesem PC (127.0.0.1): zeigt die Vorschau der Online-Liste; die Seite fragt jede Sekunde
        nach einer neuen Fassung und laedt sich dann von selbst neu. Nichts geht ins Internet."""

        POLL = ('<script>(function(){var v=%d,f=%d;'
                'function msg(t){var m=document.createElement("div");m.textContent=t;m.style.cssText="position:fixed;left:50%%;top:18px;'
                'transform:translateX(-50%%);z-index:100;background:#b3261e;color:#fff;font:600 14px/1.35 system-ui,sans-serif;'
                'padding:8px 14px;border-radius:8px;box-shadow:0 6px 20px rgba(0,0,0,.4)";document.body.appendChild(m);'
                'setTimeout(function(){m.remove();},3500);}'
                'function fl(sel){var el=null;try{el=document.querySelector(sel);}catch(e){}'
                'if(!el||!el.getClientRects().length){msg("Diese Stelle ist gerade nicht zu sehen (ausgeblendet oder nur in bestimmten F\u00e4llen sichtbar).");return;}'
                'el.scrollIntoView({block:"center"});setTimeout(function(){var r=el.getBoundingClientRect(),b=document.createElement("div");'
                'b.style.cssText="position:fixed;z-index:100;pointer-events:none;border:4px solid #ff2d78;border-radius:10px;'
                'box-shadow:0 0 0 4px rgba(255,45,120,.35),0 0 24px rgba(255,45,120,.8);left:"+(r.left-8)+"px;top:"+(r.top-8)+"px;'
                'width:"+(r.width+16)+"px;height:"+(r.height+16)+"px";document.body.appendChild(b);var n=0;'
                'var iv=setInterval(function(){b.style.opacity=(++n%%2)?"0.15":"1";if(n>=6){clearInterval(iv);b.remove();}},320);},250);}'
                'setInterval(function(){fetch("/v",{cache:"no-store"}).then(function(r){'
                'return r.text();}).then(function(x){var p=x.split("|");if(+p[0]!==v){location.reload();return;}'
                'if(p[1]&&+p[1]!==f){f=+p[1];fl(p.slice(2).join("|"));}}).catch(function(){});},1000);})();</script>'
                '<div style="position:fixed;left:10px;bottom:10px;z-index:99;background:#5865f2;color:#fff;font:600 12px/1.3 '
                'system-ui,sans-serif;padding:5px 9px;border-radius:7px;opacity:.9;pointer-events:none">Live-Vorschau · '
                'lädt nach jeder Änderung im Programm neu</div>')

        ERRJS = ('<script>(function(){var sent={},n=0;function rep(m){m=String(m||"").slice(0,300);if(!m||sent[m])return;sent[m]=1;n++;'
                 'try{fetch("/err?m="+encodeURIComponent(m),{cache:"no-store"});}catch(e){}}'
                 'window.addEventListener("error",function(e){rep((e.message||"Fehler")+(e.lineno?" – Zeile "+e.lineno:""));});'
                 'window.addEventListener("unhandledrejection",function(e){rep("Promise: "+((e.reason&&e.reason.message)||e.reason));});'
                 'setTimeout(function(){var b=document.getElementById("boot");if(b&&!b.hidden&&/err/.test(b.className))'
                 'rep(b.textContent.split(".")[0]);else if(!n){try{fetch("/ok",{cache:"no-store"});}catch(e){}}},5000);})();</script>')

        def __init__(self):
            self.err, self.err_t = "", ""
            self.srv, self.port, self.ver, self.page = None, 0, 0, b""
            self.flash_n, self.flash_sel = 0, ""                # "Auf der Seite zeigen": Zaehler und Stelle (CSS-Auswahl)

        def running(self):
            return self.srv is not None

        def start(self):
            import http.server
            import threading
            lp = self

            class Handler(http.server.BaseHTTPRequestHandler):
                def do_GET(self):
                    if self.path.startswith("/err") or self.path.startswith("/ok"):
                        if self.path.startswith("/ok"):
                            lp.err = ""
                        else:
                            import urllib.parse
                            q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                            m = (q.get("m") or [""])[0][:400]
                            if m and m not in lp.err:
                                lp.err = (lp.err + " · " if lp.err else "") + m
                            lp.err_t = datetime.datetime.now().strftime("%H:%M:%S")
                        body, ctype = b"ok", "text/plain; charset=utf-8"
                    elif self.path.startswith("/v"):
                        body, ctype = ("%d|%d|%s" % (lp.ver, lp.flash_n, lp.flash_sel)).encode("utf-8"), "text/plain; charset=utf-8"
                    else:
                        body, ctype = lp.page, "text/html; charset=utf-8"
                    self.send_response(200)
                    self.send_header("Content-Type", ctype)
                    self.send_header("Cache-Control", "no-store")
                    self.send_header("Content-Length", str(len(body)))
                    self.end_headers()
                    try:
                        self.wfile.write(body)
                    except Exception:
                        pass

                def log_message(self, *a):
                    pass

            self.srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Handler)
            self.port = self.srv.server_address[1]
            threading.Thread(target=self.srv.serve_forever, daemon=True).start()
            return "http://127.0.0.1:%d/" % self.port

        def update(self, html):
            self.ver += 1
            self.err = ""
            html = html.replace("<body>", "<body>" + self.ERRJS, 1)
            tail = self.POLL % (self.ver, self.flash_n)
            i_ = html.rfind("</body>")
            html = html[:i_] + tail + html[i_:] if i_ >= 0 else html + tail
            self.page = html.encode("utf-8")

        def flash(self, sel):
            self.flash_sel = sel
            self.flash_n += 1

        def stop(self):
            if self.srv is not None:
                try:
                    self.srv.shutdown()
                    self.srv.server_close()
                except Exception:
                    pass
            self.srv = None

