    # ---- Enter-Taste automatisch (Windows): Tastendruecke an das Fenster, das vorne ist
    VK_F = {"F%d" % i: 0x6F + i for i in range(1, 13)}

    class WinKeys:
        """Windows-Teil: Enter druecken, globale Tastenkuerzel (RegisterHotKey), eigenes Fenster vorne?"""

        def __init__(self, root):
            import ctypes
            self.ct = ctypes
            self.u32 = ctypes.windll.user32
            self.k32 = ctypes.windll.kernel32
            self.root = root
            self._tid = None
            self._th = None

        def press_enter(self):
            u = self.u32
            u.keybd_event(0x0D, 0x1C, 0, 0)
            time.sleep(0.02)
            u.keybd_event(0x0D, 0x1C, 2, 0)

        def own_window_front(self):
            try:
                fg = self.u32.GetForegroundWindow()
                me = self.u32.GetAncestor(self.root.winfo_id(), 2)
                return bool(fg) and fg == me
            except Exception:
                return False

        def hotkeys_start(self, keys, q):
            """keys = {Id: VK}; gedrueckt -> q.put(("hk", Id))."""
            import threading
            import ctypes.wintypes as wt
            self.hotkeys_stop()
            ct, u, k = self.ct, self.u32, self.k32
            ok = {}

            def run():
                self._tid = k.GetCurrentThreadId()
                for hid, vk in keys.items():
                    ok[hid] = bool(u.RegisterHotKey(None, hid, 0x4000, vk))
                q.put(("hkreg", dict(ok)))
                msg = wt.MSG()
                while u.GetMessageW(ct.byref(msg), None, 0, 0) > 0:
                    if msg.message == 0x0312:
                        q.put(("hk", int(msg.wParam)))
                for hid in keys:
                    u.UnregisterHotKey(None, hid)
            self._th = threading.Thread(target=run, daemon=True)
            self._th.start()

        def hotkeys_stop(self):
            if self._tid:
                try:
                    self.u32.PostThreadMessageW(self._tid, 0x0012, 0, 0)
                except Exception:
                    pass
            if self._th is not None:
                self._th.join(0.5)
            self._tid, self._th = None, None


    class EnterBot:
        """Drueckt Enter im Abstand (Sekunden) plus Zufall, bis Anzahl erreicht oder gestoppt. Meldungen ueber eine Warteschlange."""

        def __init__(self, keys, q):
            import threading
            self.keys, self.q = keys, q
            self.stop_ev = threading.Event()
            self.th = None
            self.count = 0

        def running(self):
            return self.th is not None and self.th.is_alive()

        def start(self, interval, rnd, n, countdown=5):
            import threading
            import random
            if self.running():
                return
            self.stop_ev.clear()
            self.count = 0

            def run():
                for s_ in range(int(countdown), 0, -1):
                    self.q.put(("cd", s_))
                    if self.stop_ev.wait(1.0):
                        self.q.put(("end", "gestoppt"))
                        return
                while not self.stop_ev.is_set():
                    if n and self.count >= n:
                        self.q.put(("end", "fertig"))
                        return
                    if self.keys.own_window_front():
                        self.q.put(("front", self.count))
                    else:
                        self.keys.press_enter()
                        self.count += 1
                        self.q.put(("press", self.count))
                    if self.stop_ev.wait(max(0.05, interval + random.uniform(0, max(0.0, rnd)))):
                        break
                self.q.put(("end", "gestoppt"))
            self.th = threading.Thread(target=run, daemon=True)
            self.th.start()

        def stop(self):
            self.stop_ev.set()


    class CanvasTable(ttk.Frame):
        """Tabelle auf einer Zeichenflaeche: Spaltenbreite passt sich dem Inhalt an, Klick auf die Ueberschrift sortiert,
        Rechtsklick auf die Ueberschrift blendet Spalten aus und ein, farbige Zahlen, Balken (Quote), aufklappbare Zeilen.
        cols = [(Schluessel, Titel, Ausrichtung "w"/"e", Art "text"/"num"/"quote")];
        Zeile = {"id", "cells": {Schluessel: (Text, Sortierwert, Farbe|None)}, "kids": [...], "dim": bool, "obj": ...}"""
        PADX = 9
        IND = 18

        def __init__(self, master, cols, cfg=None, on_dbl=None, sort=None, bar_w=80, height=None, on_ctx=None):
            super().__init__(master, style="Panel.TFrame")
            self.cols, self.cfg, self.on_dbl, self.bar_w = list(cols), (cfg if cfg is not None else {}), on_dbl, bar_w
            self.on_ctx = on_ctx
            self.hidden = set(self.cfg.get("hidden") or [])
            srt = self.cfg.get("sort") or sort or [None, True]
            self.sort = (srt[0], bool(srt[1]))
            s2 = self.cfg.get("sort2")
            self.sort2 = (s2[0], bool(s2[1])) if s2 else None
            self.rows, self.flat, self.opened, self.sel = [], [], set(self.cfg.get("open") or []), None
            import tkinter.font as tkfont
            self.f_body = FONT
            self.f_head = tkfont.Font(root=self, family=FONT.actual("family"), size=FONT.actual("size"), weight="bold")
            self.rh = self.f_body.metrics("linespace") + 8
            self.hh = self.f_head.metrics("linespace") + 10
            inner = ttk.Frame(self, style="Panel.TFrame")
            vs = ttk.Scrollbar(self, orient="vertical", command=lambda *a: self.cv.yview(*a))
            hs = ttk.Scrollbar(self, orient="horizontal", command=self._xv)
            vs.pack(side="right", fill="y")
            hs.pack(side="bottom", fill="x")
            inner.pack(side="left", fill="both", expand=True)
            self.hc = tk.Canvas(inner, height=self.hh, bg=C["panel2"], highlightthickness=0)
            self.hc.pack(fill="x")
            self.cv = tk.Canvas(inner, bg=C["panel"], highlightthickness=0, height=height or 200)
            self.cv.pack(fill="both", expand=True)
            self._hs = hs

            def xs(a, b):
                hs.set(a, b)
                self.hc.xview_moveto(a)
            self.cv.configure(yscrollcommand=vs.set, xscrollcommand=xs)
            self.hc.bind("<Button-1>", self._head_click)
            for ev in ("<Button-3>", "<Button-2>"):                # Rechtsklick = 2. Sortierung, Strg + Rechtsklick = Spalten-Menue
                self.hc.bind(ev, self._head_right)
            self.cv.bind("<Button-1>", self._click)
            self.cv.bind("<Double-Button-1>", self._dbl)
            for ev in ("<Button-3>", "<Button-2>"):
                self.cv.bind(ev, self._ctx)
            for w in (self.cv, self.hc):
                for ev in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
                    w.bind(ev, self._wheel)

        def _xv(self, *a):
            self.cv.xview(*a)
            self.hc.xview(*a)

        def _wheel(self, e):
            up = getattr(e, "num", 0) == 4 or getattr(e, "delta", 0) > 0
            if e.state & 0x0001:
                self.cv.xview_scroll(-3 if up else 3, "units")
            else:
                self.cv.yview_scroll(-3 if up else 3, "units")
            return "break"

        def _save(self):
            self.cfg["hidden"] = sorted(self.hidden)
            self.cfg["sort"] = list(self.sort)
            self.cfg["sort2"] = list(self.sort2) if self.sort2 else None
            self.cfg["open"] = sorted(self.opened)

        def _arrow(self, k):
            if self.sort[0] == k:
                return " v" if self.sort[1] else " ^"
            if self.sort2 and self.sort2[0] == k:
                return " \u00b2v" if self.sort2[1] else " \u00b2^"
            return ""

        def _head_right(self, e):
            if e.state & 0x0004:
                return self._head_menu(e)
            i = self._col_at(e.x)
            if i is None:
                return
            k, kind = self._vis()[i][0], self._vis()[i][3]
            self.sort2 = sort2_cycle(self.sort2, k, self.sort[0], kind != "text")
            self._save()
            self.render()

        def set_rows(self, rows):
            self.rows = rows
            self.render()

        def _vis(self):
            return [c for i, c in enumerate(self.cols) if i == 0 or c[0] not in self.hidden]

        def _sorted(self, rows):
            out = list(rows)
            val = lambda k: (lambda r: (r["cells"].get(k) or ("", None))[1] if len(r["cells"].get(k) or ()) > 1 else None)
            if self.sort2 and self.sort2[0] != self.sort[0]:
                out = sort_rows(out, val(self.sort2[0]), self.sort2[1])
            k, desc = self.sort
            if k is None:
                return out
            return sort_rows(out, val(k), desc)

        def render(self):
            flat = []
            for r in self._sorted(self.rows):
                flat.append((0, r))
                if r.get("kids") and r["id"] in self.opened:
                    flat.extend((1, k_) for k_ in self._sorted(r["kids"]))
            self.flat = flat
            tree = any(r.get("kids") for r in self.rows)
            cols = self._vis()
            mb, mh = self.f_body.measure, self.f_head.measure
            ws = []
            for i, (k, t, a, kind) in enumerate(cols):
                arrow = self._arrow(k)
                w = mh(t + arrow)
                for lvl, r in flat:
                    txt = (r["cells"].get(k) or ("",))[0]
                    w = max(w, mb(str(txt)) + ((self.IND * (1 + lvl)) if (i == 0 and tree) else 0) + (self.bar_w + 8 if kind == "quote" else 0))
                ws.append(w + 2 * self.PADX)
            self.widths = ws
            tot = sum(ws)
            hc, cv = self.hc, self.cv
            hc.delete("all")
            cv.delete("all")
            x = 0
            for i, (k, t, a, kind) in enumerate(cols):
                arrow = self._arrow(k)
                tx = x + self.PADX if a == "w" else x + ws[i] - self.PADX
                hc.create_text(tx, self.hh // 2, text=tkstr(t + arrow), anchor=a, font=self.f_head, fill="#c9cdfb")
                x += ws[i]
                hc.create_line(x - 1, 4, x - 1, self.hh - 4, fill=GRID_COLOR)
            hc.configure(scrollregion=(0, 0, max(tot, 1), self.hh))
            rh = self.rh
            for n, (lvl, r) in enumerate(flat):
                y = n * rh
                bg = C["sel"] if self.sel == r["id"] else ("#33353b" if n % 2 else C["panel"])
                cv.create_rectangle(0, y, tot, y + rh, fill=bg, outline="")
                x = 0
                for i, (k, t, a, kind) in enumerate(cols):
                    cell = r["cells"].get(k) or ("", None, None)
                    txt, sv = cell[0], (cell[1] if len(cell) > 1 else None)
                    col = C["dim"] if r.get("dim") else ((cell[2] if len(cell) > 2 else None) or C["fg"])
                    x0 = x
                    if i == 0 and tree:
                        x0 += self.IND * lvl
                        if lvl == 0 and r.get("kids"):
                            cv.create_text(x0 + self.PADX, y + rh // 2, text="–" if r["id"] in self.opened else "+",
                                           anchor="w", font=self.f_head, fill=C["accent"], tags=("tg",))
                        x0 += self.IND
                    if kind == "quote" and isinstance(sv, (int, float)):
                        bx = x0 + self.PADX
                        cv.create_rectangle(bx, y + rh // 2 - 4, bx + self.bar_w, y + rh // 2 + 4, fill="#5a2a2a", outline="")
                        cv.create_rectangle(bx, y + rh // 2 - 4, bx + int(self.bar_w * max(0.0, min(1.0, sv))), y + rh // 2 + 4,
                                            fill=C["ok"], outline="")
                        cv.create_text(bx + self.bar_w + 6, y + rh // 2, text=tkstr(txt), anchor="w", font=self.f_body, fill=col)
                    else:
                        tx = x0 + self.PADX if a == "w" else x + ws[i] - self.PADX
                        cv.create_text(tx, y + rh // 2, text=tkstr(str(txt)), anchor=a, font=self.f_body, fill=col)
                    x += ws[i]
            cv.configure(scrollregion=(0, 0, max(tot, 1), max(len(flat) * rh, 1)))

        def _col_at(self, x):
            cx = self.hc.canvasx(x)
            acc = 0
            for i, w in enumerate(self.widths):
                if acc <= cx < acc + w:
                    return i
                acc += w
            return None

        def _head_click(self, e):
            i = self._col_at(e.x)
            if i is None:
                return
            k = self._vis()[i][0]
            self.sort = (k, not self.sort[1]) if self.sort[0] == k else (k, self._vis()[i][3] != "text")
            if self.sort2 and self.sort2[0] == k:
                self.sort2 = None
            self._save()
            self.render()

        def _head_menu(self, e):
            m = tk.Menu(self, tearoff=0, font=FONT)
            for i, (k, t, a, kind) in enumerate(self.cols):
                if i == 0:
                    continue
                v = tk.BooleanVar(value=k not in self.hidden)
                m.add_checkbutton(label=tkstr(t), variable=v, command=lambda k=k: self._toggle_col(k))
                m.__dict__.setdefault("_vars", []).append(v)
            m.add_separator()
            m.add_command(label="Alle Spalten zeigen", command=self._show_all)
            m.tk_popup(e.x_root, e.y_root)

        def _toggle_col(self, k):
            if k in self.hidden:
                self.hidden.discard(k)
            else:
                self.hidden.add(k)
            self._save()
            self.render()

        def _show_all(self):
            self.hidden.clear()
            self._save()
            self.render()

        def _row_at(self, y):
            n = int(self.cv.canvasy(y) // self.rh)
            return self.flat[n] if 0 <= n < len(self.flat) else (None, None)

        def _click(self, e):
            lvl, r = self._row_at(e.y)
            if r is None:
                return
            self.sel = r["id"]
            x = self.cv.canvasx(e.x)
            if lvl == 0 and r.get("kids") and x < self.IND + 2 * self.PADX:
                self.opened.symmetric_difference_update({r["id"]})
                self._save()
            self.render()

        def _dbl(self, e):
            lvl, r = self._row_at(e.y)
            if r is not None and self.on_dbl:
                self.on_dbl(r, lvl)

        def _ctx(self, e):
            lvl, r = self._row_at(e.y)
            if r is not None and self.on_ctx:
                self.sel = r["id"]
                self.render()
                self.on_ctx(r, lvl, e)


    WIN_C, LOSS_C = "#57d98b", "#ff6b6b"

    def fight_cells(t, label, n_opp=None):
        """Zellen einer Zeile der Kampf-Tabelle aus den Summen t."""
        mio = lambda x: ("%s Mio" % _group(int(round(x / 1e6))), x) if x else ("–", None)
        n = t.get("kaempfe", 0)
        if not n:
            return {"cls": (label, label.lower(), None), "n": (0, 0, None)}
        q = t["siege"] / float(n)
        at, bt = t["a_treffer"], t["b_treffer"]
        c = {"cls": (label, label.lower(), None), "n": (n, n, None), "w": (t["siege"], t["siege"], WIN_C),
             "l": (n - t["siege"], n - t["siege"], LOSS_C), "q": ("%d %%" % round(100 * q), q, WIN_C if q >= 0.5 else LOSS_C),
             "am": mio(at and t["a_schaden"] / at), "ax": mio(t["a_max"]), "bm": mio(bt and t["b_schaden"] / bt), "bx": mio(t["b_max"]),
             "ad": mio(t["a_schaden_eff"] / n), "bd": mio(t["b_schaden_eff"] / n),
             "ak": ("%d %%" % round(100.0 * t["a_krit"] / at), t["a_krit"] / float(at)) if at else ("–", None),
             "bk": ("%d %%" % round(100.0 * t["b_krit"] / bt), t["b_krit"] / float(bt)) if bt else ("–", None),
             "bl": (t["a_geblockt"], t["a_geblockt"]), "ev": (t["a_ausgewichen"], t["a_ausgewichen"]),
             "rv": ("%d×" % t["a_wiederbelebt"], t["a_wiederbelebt"])}
        if n_opp is not None:
            c["og"] = (n_opp, n_opp)
        return {k: tuple(v) + (None,) * (3 - len(v)) for k, v in c.items()}


    class FightTab(ttk.Frame):
        """Kampf-Auswertung (nur im Programm): Kaempfe aus HAR-Dateien je Gegner-Klasse, dazu die automatische Enter-Taste."""
        COLS = (("cls", "Klasse / Gegner", "w", "text"), ("og", "Gegner", "e", "num"), ("n", "Kämpfe", "e", "num"),
                ("w", "Siege", "e", "num"), ("l", "Niederl.", "e", "num"), ("q", "Sieg-Quote", "w", "quote"),
                ("am", "dein Ø Treffer", "e", "num"), ("ax", "dein höchster", "e", "num"), ("bm", "sein Ø Treffer", "e", "num"),
                ("bx", "sein höchster", "e", "num"), ("ad", "dein Schaden je Kampf", "e", "num"), ("bd", "sein Schaden je Kampf", "e", "num"),
                ("ak", "deine Krits", "e", "num"), ("bk", "seine Krits", "e", "num"), ("bl", "geblockt", "e", "num"),
                ("ev", "ausgewichen", "e", "num"), ("rv", "wiederbelebt", "e", "num"))

        def __init__(self, master, app):
            super().__init__(master, padding=(12, 8))
            import queue
            self.app = app
            self.dirty = True
            self.q = queue.Queue()
            self.c = app.cfg.d.setdefault("bot", {})
            self.keys = None
            if sys.platform == "win32":
                try:
                    self.keys = WinKeys(app)
                except Exception:
                    self.keys = None
            self.bot = EnterBot(self.keys, self.q) if self.keys else None
            top = ttk.Frame(self)
            top.pack(fill="x")
            top.columnconfigure(0, weight=1)
            top.columnconfigure(1, weight=1)
            lf = ttk.LabelFrame(top, text=" Kämpfe aus HAR-Dateien ", padding=8)
            lf.grid(row=0, column=0, sticky="nsew", padx=(0, 8))
            br = ttk.Frame(lf)
            br.pack(fill="x")
            ttk.Button(br, text="HAR-Dateien laden …", style="Accent.TButton", command=self.load_hars).pack(side="left")
            ttk.Button(br, text="Liste leeren", command=self.clear).pack(side="left", padx=6)
            ttk.Button(br, text="CSV speichern …", command=self.save_csv).pack(side="left")
            self.sum_lbl = ttk.Label(lf, text="", style="Dim.TLabel", wraplength=620, justify="left")
            self.sum_lbl.pack(anchor="w", pady=(6, 4))
            fb = ttk.Frame(lf, style="Panel.TFrame")
            fb.pack(fill="both", expand=True)
            self.t_files = ttk.Treeview(fb, columns=("f", "t", "n", "new"), show="headings", height=4, selectmode="none")
            for c_, t_, w_ in (("f", "Datei", 240), ("t", "aufgenommen", 130), ("n", "Kämpfe", 70), ("new", "neu", 60)):
                self.t_files.heading(c_, text=t_)
                self.t_files.column(c_, width=w_, anchor="w" if c_ in ("f", "t") else "e")
            attach_scroll(fb, self.t_files)
            self.t_files.pack(side="left", fill="both", expand=True)
            rf = ttk.LabelFrame(top, text=" Enter-Taste automatisch (nur Beta-Server) ", padding=8)
            rf.grid(row=0, column=1, sticky="nsew")
            r1 = ttk.Frame(rf)
            r1.pack(fill="x")
            self.v_iv = tk.StringVar(value=str(self.c.get("iv", 0.5)).replace(".", ","))
            self.v_rnd = tk.StringVar(value=str(self.c.get("rnd", 0.2)).replace(".", ","))
            self.v_n = tk.StringVar(value=str(self.c.get("n", 1000)))
            for lab, var, w_, tip in (("Abstand", self.v_iv, 6, "Sekunden zwischen zwei Tastendrücken"),
                                      ("Sekunden · dazu zufällig bis", self.v_rnd, 6, "So viele Sekunden kommen zufällig dazu (0 = immer gleich)"),
                                      ("s · Anzahl", self.v_n, 7, "Nach so vielen Tastendrücken hört es auf (0 = ohne Ende)")):
                ttk.Label(r1, text=lab).pack(side="left", padx=(0, 4))
                e_ = ttk.Spinbox(r1, from_=0, to=100000, increment=0.1 if var is not self.v_n else 50, textvariable=var, width=w_)
                e_.pack(side="left", padx=(0, 8))
                Tip(e_, tip)
            ttk.Label(r1, text="(0 = ohne Ende)", style="Dim.TLabel").pack(side="left")
            r2 = ttk.Frame(rf)
            r2.pack(fill="x", pady=(6, 0))
            self.v_ks = tk.StringVar(value=self.c.get("k_start", "F7"))
            self.v_ke = tk.StringVar(value=self.c.get("k_stop", "F8"))
            ttk.Label(r2, text="Start mit").pack(side="left")
            ttk.Combobox(r2, textvariable=self.v_ks, values=list(VK_F), state="readonly", width=5).pack(side="left", padx=4)
            ttk.Label(r2, text="· Stopp / Not-Aus mit").pack(side="left")
            ttk.Combobox(r2, textvariable=self.v_ke, values=list(VK_F), state="readonly", width=5).pack(side="left", padx=4)
            self.v_hk = tk.BooleanVar(value=bool(self.c.get("hk", True)))
            ttk.Checkbutton(r2, text="Tastenkürzel an", variable=self.v_hk, command=self._hk_changed).pack(side="left", padx=(10, 0))
            for v_ in (self.v_ks, self.v_ke):
                v_.trace_add("write", lambda *a: self._hk_changed())
            r3 = ttk.Frame(rf)
            r3.pack(fill="x", pady=(8, 0))
            self.b_start = ttk.Button(r3, text="Start (in 5 s)", style="Accent.TButton", command=self.start)
            self.b_start.pack(side="left")
            ttk.Button(r3, text="Stopp", command=self.stop).pack(side="left", padx=6)
            self.st_lbl = ttk.Label(rf, text="", font=FONT_HEAD)
            self.st_lbl.pack(anchor="w", pady=(8, 0))
            self.hint = ttk.Label(rf, text="", style="Dim.TLabel", wraplength=620, justify="left")
            self.hint.pack(anchor="w", pady=(4, 0))
            # Ergebnis
            res = ttk.LabelFrame(self, text=" Ergebnis je Gegner-Klasse ", padding=8)
            res.pack(fill="both", expand=True, pady=(10, 0))
            rb = ttk.Frame(res)
            rb.pack(fill="x", pady=(0, 6))
            ttk.Label(rb, text="Dein Charakter:").pack(side="left")
            self.v_me = tk.StringVar()
            self.cb_me = ttk.Combobox(rb, textvariable=self.v_me, state="readonly", width=28)
            self.cb_me.pack(side="left", padx=6)
            self.cb_me.bind("<<ComboboxSelected>>", lambda e: self.show())
            self.v_showhid = tk.BooleanVar(value=bool(self.c.get("show_hidden", False)))
            ttk.Checkbutton(rb, text="ausgeblendete Spieler zeigen", variable=self.v_showhid,
                            command=lambda: (self.c.__setitem__("show_hidden", bool(self.v_showhid.get())), self.show())).pack(side="left", padx=(4, 0))
            ttk.Label(rb, text="+ vor der Klasse = ihre Gegner · Rechtsklick auf einen Gegner = ausblenden oder „nur diesen zählen“ – "
                               "die Klasse rechnet dann nur mit den gezeigten Spielern · Doppelklick = Kämpfe · Klick auf die Überschrift "
                               "sortiert, Rechtsklick = 2. Sortierung, Strg + Rechtsklick blendet Spalten aus",
                      style="Dim.TLabel", wraplength=820, justify="left").pack(side="left", padx=10)
            self.table = CanvasTable(res, self.COLS, cfg=self.c.setdefault("table", {}), on_dbl=self._open_class, sort=["n", True],
                                     on_ctx=self._row_menu)
            self.table.pack(fill="both", expand=True)
            self._poll()
            self._idle_text()
            if self.keys and self.v_hk.get():
                self.after(300, self._hk_changed)
            self.bind("<Destroy>", self._destroyed, add="+")

        # ---------------------------------------------------------------- Daten
        def _mine(self):
            name = self.v_me.get()
            fs = self.app.fights.fights
            return [f for f in fs if not name or "%s" % f["a"]["name"] == name.split("  (")[0]]

        def refresh(self):
            self.dirty = False
            fs = self.app.fights.fights
            cnt = Counter(f["a"]["name"] for f in fs)
            names = ["%s  (%d Kämpfe)" % (n, c_) for n, c_ in cnt.most_common()]
            self.cb_me.configure(values=names)
            if names and self.v_me.get() not in names:
                cur = self.v_me.get().split("  (")[0]
                self.v_me.set(next((x for x in names if x.split("  (")[0] == cur), names[0]))
            self.t_files.delete(*self.t_files.get_children())
            for x in reversed(self.app.fights.files):
                self.t_files.insert("", "end", values=(tkstr(x.get("name", "")), fmt_ts(x.get("t0") or 0, True) if x.get("t0") else "",
                                                       x.get("n", 0), x.get("new", 0)))
            self.sum_lbl.configure(text="Zusammen: %s Kämpfe aus %d Datei(en) · doppelte Kämpfe werden nur einmal gezählt · "
                                        "die Kämpfe bleiben gespeichert, auch nach dem Neustart." % (_group(len(fs)), len(self.app.fights.files)))
            self.show()

        def _hidden(self):
            return set(self.c.get("hide_opp") or [])

        @staticmethod
        def _okey(f):
            return "%d|%s" % (int(f["b"].get("cls") or 0), f["b"]["name"])

        def _visible(self, fights):
            hid = self._hidden()
            return [f for f in fights if self._okey(f) not in hid]

        def show(self):
            mine = self._mine()
            hid = self._hidden()
            by = {}
            for f in mine:
                by.setdefault(int(f["b"].get("cls") or 0), []).append(f)
            rows = []
            for cid in sorted(set(CLASSES) | set(by)):
                name = CLASSES.get(cid, ("Klasse %d" % cid,))[0]
                fs = by.get(cid) or []
                opp = {}
                for f in fs:                                   # jeder Gegner-Name nur einmal
                    opp.setdefault(f["b"]["name"], []).append(f)
                kids, vis = [], []
                for nm, fl in opp.items():
                    key = "%d|%s" % (cid, nm)
                    if key in hid:
                        if self.v_showhid.get():
                            kids.append({"id": "o" + key, "cells": dict(fight_cells(fight_agg(fl), nm + "  (ausgeblendet)")), "obj": fl,
                                         "dim": True, "okey": key})
                        continue
                    vis.extend(fl)
                    kids.append({"id": "o" + key, "cells": fight_cells(fight_agg(fl), nm), "obj": fl, "okey": key})
                n_vis = sum(1 for nm in opp if "%d|%s" % (cid, nm) not in hid)
                cells = fight_cells(fight_agg(vis), name, n_vis if fs else None)
                if fs and n_vis < len(opp):
                    cells["og"] = ("%d von %d" % (n_vis, len(opp)), n_vis, "#f0b232")
                rows.append({"id": "c%d" % cid, "cells": cells, "kids": kids, "dim": not vis, "obj": vis, "cid": cid})
            self.table.set_rows(rows)

        def _set_hidden(self, hid):
            self.c["hide_opp"] = sorted(hid)
            self.app.save_soon()
            self.show()

        def _row_menu(self, row, lvl, e):
            m = tk.Menu(self, tearoff=0, font=FONT)
            hid = self._hidden()
            if lvl == 1 and row.get("okey"):
                key = row["okey"]
                cid = key.split("|", 1)[0]
                same = {"%s|%s" % (cid, f["b"]["name"]) for f in self._mine() if str(int(f["b"].get("cls") or 0)) == cid}
                if key in hid:
                    m.add_command(label="Spieler wieder einblenden", command=lambda: self._set_hidden(hid - {key}))
                else:
                    m.add_command(label="Spieler ausblenden", command=lambda: self._set_hidden(hid | {key}))
                m.add_command(label="Nur diesen Spieler zählen (andere dieser Klasse ausblenden)",
                              command=lambda: self._set_hidden((hid | same) - {key}))
                m.add_command(label="Alle Spieler dieser Klasse einblenden", command=lambda: self._set_hidden(hid - same))
            elif lvl == 0 and row.get("cid") is not None:
                cid = str(row["cid"])
                same = {"%s|%s" % (cid, f["b"]["name"]) for f in self._mine() if str(int(f["b"].get("cls") or 0)) == cid}
                m.add_command(label="Alle Spieler dieser Klasse einblenden", command=lambda: self._set_hidden(hid - same),
                              state="normal" if hid & same else "disabled")
            m.add_separator()
            m.add_command(label="Alle ausgeblendeten Spieler einblenden", command=lambda: self._set_hidden(set()),
                          state="normal" if hid else "disabled")
            m.tk_popup(e.x_root, e.y_root)

        def load_hars(self):
            paths = filedialog.askopenfilenames(parent=self, title="HAR-Dateien mit Kämpfen laden",
                                                initialdir=self.app.cfg.d.get("last_dir") or None,
                                                filetypes=[("HAR", "*.har"), ("Alle Dateien", "*.*")])
            if not paths:
                return
            tot = new = 0
            self.config(cursor="watch")
            self.update_idletasks()
            try:
                for p in paths:
                    try:
                        x = har_extract(p)
                    except Exception as ex:
                        messagebox.showerror(APP_NAME, "%s:\n%s" % (os.path.basename(p), ex), parent=self)
                        continue
                    tot += len(x["fights"])
                    new += self.app.fights.add(x["fights"], os.path.basename(p), x["info"].get("t0", 0))
            finally:
                self.config(cursor="")
            self.app.cfg.d["last_dir"] = os.path.dirname(paths[0])
            self.refresh()
            self.app.set_status("%d Kämpfe gelesen, davon %d neu." % (tot, new))

        def clear(self):
            if messagebox.askyesno(APP_NAME, "Alle gesammelten Kämpfe löschen?", parent=self):
                self.app.fights.clear()
                self.refresh()

        def save_csv(self):
            fs = self._visible(self._mine())
            if not fs:
                return
            p = filedialog.asksaveasfilename(parent=self, defaultextension=".csv", initialfile="Kaempfe.csv",
                                             initialdir=self.app.cfg.d.get("last_dir") or None, filetypes=[("CSV", "*.csv")])
            if not p:
                return
            with open(p, "w", encoding="utf-8-sig", newline="") as fh:
                w = csv.writer(fh, delimiter=";")
                w.writerow(["Zeit", "Du", "Gegner", "Klasse Gegner", "Ergebnis", "Aktionen", "Dein Schaden", "Sein Schaden",
                            "Deine Treffer", "Deine Krits", "Seine Treffer", "Seine Krits", "geblockt", "ausgewichen", "wiederbelebt", "Ehre", "Gold"])
                for f in fs:
                    a, b = fight_side_stats(f)
                    w.writerow([fmt_ts(f.get("ts") or 0, True), f["a"]["name"], f["b"]["name"],
                                CLASSES.get(int(f["b"].get("cls") or 0), ("?",))[0], "Sieg" if f.get("win") else "Niederlage",
                                len(f["acts"]), a["schaden_eff"], b["schaden_eff"], a["treffer"], a["krit"], b["treffer"], b["krit"],
                                a["geblockt"], a["ausgewichen"], a["wiederbelebt"], f.get("honor", 0), f.get("gold", 0)])
            self.app.set_status("Gespeichert: " + p)

        def _open_class(self, row, lvl):
            fs = row.get("obj") or []
            if fs:
                FightClassDialog(self.app, row["cells"]["cls"][0], fs)

        # ---------------------------------------------------------------- Enter-Taste
        def _num(self, var, dflt):
            try:
                return float(str(var.get()).replace(",", "."))
            except ValueError:
                return dflt

        def _idle_text(self):
            if not self.keys:
                self.st_lbl.configure(text="Nur unter Windows verfügbar.")
                self.hint.configure(text="Die Enter-Taste funktioniert nur unter Windows.")
                self.b_start.configure(state="disabled")
                return
            ks, ke = self.v_ks.get(), self.v_ke.get()
            self.st_lbl.configure(text="Bereit")
            self.hint.configure(text=("%s startet (nach 5 Sekunden), %s stoppt sofort – auch wenn das Spiel vorne ist. " % (ks, ke) if self.v_hk.get()
                                      else "Tastenkürzel sind aus – nur die Knöpfe hier. ") +
                                "Die Taste geht an das Fenster, das vorne ist; ist dieses Programm vorne, wird nicht gedrückt. "
                                "Für die Auswertung im Browser F12 › Netzwerk mit „Log beibehalten“ offen lassen und danach „Alle als HAR speichern“.")

        def _hk_changed(self):
            self.c.update(k_start=self.v_ks.get(), k_stop=self.v_ke.get(), hk=bool(self.v_hk.get()))
            self.app.save_soon()
            if not self.keys:
                return
            self.keys.hotkeys_stop()
            if self.v_hk.get() and self.v_ks.get() != self.v_ke.get():
                self.keys.hotkeys_start({1: VK_F[self.v_ks.get()], 2: VK_F[self.v_ke.get()]}, self.q)
            if not (self.bot and self.bot.running()):
                self._idle_text()

        def start(self):
            if not self.bot or self.bot.running():
                return
            iv, rnd, n = self._num(self.v_iv, 0.5), self._num(self.v_rnd, 0.2), int(self._num(self.v_n, 1000))
            self.c.update(iv=iv, rnd=rnd, n=n)
            self.app.save_soon()
            self.bot.start(max(0.05, iv), max(0.0, rnd), max(0, n))

        def stop(self):
            if self.bot:
                self.bot.stop()

        def _poll(self):
            try:
                while True:
                    kind, val = self.q.get_nowait()
                    n = int(self._num(self.v_n, 0))
                    if kind == "hk":
                        if val == 1:
                            self.start()
                        elif val == 2:
                            self.stop()
                    elif kind == "hkreg":
                        bad = [k for k, ok in val.items() if not ok]
                        if bad:
                            self.hint.configure(text="Tastenkürzel %s ist schon von einem anderen Programm belegt – bitte eine andere Taste wählen."
                                                % " / ".join(self.v_ks.get() if b_ == 1 else self.v_ke.get() for b_ in bad))
                    elif kind == "cd":
                        self.st_lbl.configure(text="Start in %d s – jetzt das Spiel-Fenster nach vorn holen (%s = Stopp)" % (val, self.v_ke.get()))
                    elif kind == "press":
                        self.st_lbl.configure(text="%s%s gedrückt · %s = Stopp" % (_group(val), (" / " + _group(n)) if n else "", self.v_ke.get()))
                    elif kind == "front":
                        self.st_lbl.configure(text="%s gedrückt · Pause: dieses Programm ist vorne – Spiel-Fenster nach vorn holen" % _group(val))
                    elif kind == "end":
                        cnt = self.bot.count if self.bot else 0
                        self.st_lbl.configure(text="%s: %s Mal Enter gedrückt" % ("Fertig" if val == "fertig" else "Gestoppt", _group(cnt)))
            except Exception:
                pass
            try:
                self.after(80, self._poll)
            except tk.TclError:
                pass

        def _destroyed(self, e):
            if e.widget is self:
                if self.bot:
                    self.bot.stop()
                if self.keys:
                    self.keys.hotkeys_stop()


    class FightClassDialog(tk.Toplevel):
        """Alle Gegner einer Klasse (oder ein Gegner) und ihre Kaempfe."""

