    class FightDialog(tk.Toplevel):
        """Ein Kampf: Verlauf der Lebensenergie und jede Aktion."""

        def __init__(self, app, f):
            super().__init__(app)
            self.f = f
            a, b = f["a"], f["b"]
            self.title(tkstr("Kampf: %s gegen %s" % (a["name"], b["name"])))
            self.configure(bg=C["bg"])
            self.transient(app)
            self.geometry("1000x720")
            ttk.Label(self, text=tkstr("%s gegen %s (%s) – %s · %s" % (a["name"], b["name"], CLASSES.get(int(b.get("cls") or 0), ("?",))[0],
                                                                       "Sieg" if f.get("win") else "Niederlage", fmt_ts(f.get("ts") or 0, True))),
                      style="Head.TLabel").pack(anchor="w", padx=14, pady=(12, 4))
            self.cv = tk.Canvas(self, height=220, bg=C["panel"], highlightthickness=0)
            self.cv.pack(fill="x", padx=14)
            self.cv.bind("<Configure>", lambda e: self._draw())
            cols = (("i", "#", "e", "num"), ("w", "Wer", "w", "text"), ("t", "Art", "w", "text"), ("d", "Abwehr", "w", "text"),
                    ("s", "Schaden", "e", "num"), ("o", "eigene LE", "e", "num"), ("ha", "LE " + a["name"], "e", "num"),
                    ("hb", "LE " + b["name"], "e", "num"))
            rows = []
            for i, (w, typ, dfn, dmg, selfd, ha, hb, rev) in enumerate(f["acts"], 1):
                own = ("wiederbelebt" if rev else ("−" + _group(selfd) if selfd > 0 else ("+" + _group(-selfd) if selfd < 0 else "")))
                krit = typ in (1, 101)
                rows.append({"id": i, "cells": {
                    "i": (i, i, None), "w": (a["name"] if w == 0 else b["name"], w, "#f0b232" if w == 0 else "#7fb8ff"),
                    "t": (FIGHT_ATT.get(typ, "Art %d" % typ), typ, "#ff9f43" if krit else None), "d": (FIGHT_DEF.get(dfn, str(dfn)), dfn, C["dim"]),
                    "s": (_group(dmg) if dmg else "", dmg, "#ff9f43" if krit and dmg else None),
                    "o": (own, -selfd if not rev else 0, WIN_C if (rev or selfd < 0) else (LOSS_C if selfd > 0 else None)),
                    "ha": (_group(max(0, ha)), ha, None), "hb": (_group(max(0, hb)), hb, None)}})
            tb = CanvasTable(self, cols, cfg=app.cfg.d.setdefault("bot", {}).setdefault("t_acts", {}), sort=["i", False])
            tb.pack(fill="both", expand=True, padx=14, pady=10)
            tb.set_rows(rows)
            self.bind("<Escape>", lambda e: self.destroy())

        def _draw(self):
            cv, f = self.cv, self.f
            cv.delete("all")
            w, h = cv.winfo_width(), cv.winfo_height()
            acts = f["acts"]
            if w < 50 or not acts:
                return
            pts = [(f["a"]["hp"], f["b"]["hp"])] + [(x[5], x[6]) for x in acts]
            mx = max(max(p) for p in pts) or 1
            left, top, bot = 12, 26, h - 14
            step = (w - 2 * left) / float(max(1, len(pts) - 1))
            for k, col in ((0, "#f0b232"), (1, "#7fb8ff")):
                xy = []
                for i, p_ in enumerate(pts):
                    xy += [left + i * step, bot - (bot - top) * max(0, p_[k]) / float(mx)]
                if len(xy) >= 4:
                    cv.create_line(*xy, fill=col, width=2)
            for i, x in enumerate(acts, 1):
                if x[0] == 0 and x[1] in (1, 101) and x[3] > 0:
                    yy = bot - (bot - top) * max(0, x[6]) / float(mx)
                    cv.create_oval(left + i * step - 3, yy - 3, left + i * step + 3, yy + 3, fill="#ff6b6b", outline="")
            cv.create_text(left, 8, anchor="nw", fill=C["fg"], font=FONT,
                           text=tkstr("Lebensenergie nach jeder Aktion:  gelb = %s · blau = %s · rot = dein Krit" % (f["a"]["name"], f["b"]["name"])))


    class VisitsTab(ttk.Frame):
        """Besucher der Online-Liste (GoatCounter) - nur fuer dich, mit deinem geheimen Schluessel."""
        RANGES = ((1, "Heute"), (7, "7 Tage"), (30, "30 Tage"))

        def __init__(self, master, app):
            super().__init__(master, padding=(12, 8))
            self.app = app
            self.dirty = True
            self.data = None
            self._th = None
            top = ttk.Frame(self)
            top.pack(fill="x")
            ttk.Label(top, text="Besucher der Online-Liste", style="Head.TLabel").pack(side="left")
            self.rbtn = {}
            for d, lab in self.RANGES:
                b = ttk.Button(top, text=lab, width=8, command=lambda d=d: self.set_range(d))
                b.pack(side="left", padx=(14 if d == 1 else 2, 0))
                self.rbtn[d] = b
            ttk.Button(top, text="Aktualisieren", command=self.fetch).pack(side="left", padx=(12, 0))
            self.stamp = ttk.Label(top, text="", style="Dim.TLabel")
            self.stamp.pack(side="left", padx=12)
            self.msg = ttk.Label(self, text="", style="Dim.TLabel", wraplength=1200, justify="left")
            self.msg.pack(fill="x", pady=(6, 2))
            kp = ttk.Frame(self)
            kp.pack(fill="x", pady=(4, 8))
            self.kpi = {}
            for k, lab in (("visitors", "Besucher"), ("events", "Klicks (Ereignisse)"), ("today", "Besucher heute"),
                           ("peak", "meister Ansturm")):
                box = tk.Frame(kp, bg=C["panel"], padx=16, pady=8)
                box.pack(side="left", padx=(0, 10))
                v = tk.Label(box, text="–", bg=C["panel"], fg=C["fg"], font=(FAM[0], 18, "bold"))
                v.pack(anchor="w")
                tk.Label(box, text=lab, bg=C["panel"], fg=C["dim"], font=FONT).pack(anchor="w")
                self.kpi[k] = v
            ch = ttk.Frame(self)
            ch.pack(fill="x")
            self.cv_h = tk.Canvas(ch, height=180, bg=C["panel"], highlightthickness=0)
            self.cv_h.pack(side="left", fill="x", expand=True, padx=(0, 8))
            self.cv_d = tk.Canvas(ch, height=180, bg=C["panel"], highlightthickness=0)
            self.cv_d.pack(side="left", fill="x", expand=True)
            for cv in (self.cv_h, self.cv_d):
                cv.bind("<Configure>", lambda e: self._draw(), add="+")
            tb = ttk.Frame(self)
            tb.pack(fill="both", expand=True, pady=(10, 0))
            self.t_pages = self._table(tb, "Seiten & geöffnete Links", "Seite / Link")
            self.t_ev = self._table(tb, "Angeklickt", "Was")
            self._range_btns()

        def _table(self, parent, title, col):
            fr = ttk.Frame(parent)
            fr.pack(side="left", fill="both", expand=True, padx=(0, 8))
            ttk.Label(fr, text=title, style="Head.TLabel").pack(anchor="w")
            box = ttk.Frame(fr, style="Panel.TFrame")
            box.pack(fill="both", expand=True, pady=(4, 0))
            tv = ttk.Treeview(box, columns=("n",), show="tree headings", selectmode="browse", height=8)
            tv.heading("#0", text=col)
            tv.heading("n", text="Besucher")
            tv.column("#0", width=420, anchor="w")
            tv.column("n", width=90, anchor="e", stretch=False)
            attach_scroll(box, tv)
            tv.pack(side="left", fill="both", expand=True)
            return tv

        def _days(self):
            try:
                d = int(self.app.cfg.d.get("gc_days", 7))
            except (TypeError, ValueError):
                d = 7
            return d if d in (1, 7, 30) else 7

        def _range_btns(self):
            for d, b in self.rbtn.items():
                b.configure(style="Accent.TButton" if d == self._days() else "TButton")

        def set_range(self, d):
            self.app.cfg.d["gc_days"] = d
            self.app.save_soon()
            self._range_btns()
            self.fetch()

        def refresh(self):
            self.dirty = False
            if self.data is None:
                self.fetch()

        def fetch(self):
            d = self.app.cfg.d
            acc = gc_account((d.get("html_export") or {}).get("gc_account"))
            key = str(d.get("gc_key") or "").strip()
            if not acc or not key:
                self.msg.configure(text="Noch nicht eingerichtet: Im Reiter „Online-Liste“ › „Besucher-Statistik“ Konto-Name und geheimen "
                                        "Schlüssel eintragen und „Besucher zählen“ anhaken. Danach die Seite neu speichern und hochladen.",
                                   foreground=C["warn"])
                return
            if self._th is not None and self._th.is_alive():
                return
            import threading
            days = self._days()
            box = {}

            def work():
                try:
                    box["r"] = gc_fetch(acc, key, days)
                except Exception as ex:
                    box["e"] = str(ex)

            self.msg.configure(text="Lade die Zahlen von %s.goatcounter.com …" % acc, foreground=C["dim"])
            self._th = threading.Thread(target=work, daemon=True)
            self._th.start()

            def poll():
                if self._th.is_alive():
                    self.after(150, poll)
                    return
                if "e" in box:
                    self.msg.configure(text="Nicht geklappt: " + box["e"], foreground=C["warn"])
                    return
                self.data = box["r"]
                self.stamp.configure(text="Stand %s" % datetime.datetime.now().strftime("%d.%m.%Y %H:%M"))
                self.msg.configure(text="", foreground=C["dim"])
                self.show()
            poll()

        def show(self):
            r = self.data
            if not r:
                return
            self.kpi["visitors"].configure(text=_group(r["visitors"]))
            self.kpi["events"].configure(text=_group(r["events"]))
            self.kpi["today"].configure(text=_group(r["today"]))
            pk = r["peak"]
            self.kpi["peak"].configure(text=("%d–%d Uhr" % (pk, pk + 1)) if pk is not None else "–")
            for tv in (self.t_pages, self.t_ev):
                tv.delete(*tv.get_children())
            for path, n in r["pages"]:
                self.t_pages.insert("", "end", text=tkstr(path or "/"), values=(_group(n),))
            groups = {}
            for path, n in r["events_list"]:
                head, sep, rest = path.partition(": ")
                groups.setdefault(head if sep else path, []).append((rest if sep else "", n))
            for head, items in sorted(groups.items(), key=lambda kv: -sum(n for _x, n in kv[1])):
                tot = sum(n for _x, n in items)
                kids = [(x, n) for x, n in items if x]
                pid = self.t_ev.insert("", "end", text=tkstr(head), values=(_group(tot),), open=False)
                for x, n in kids:
                    self.t_ev.insert(pid, "end", text=tkstr(x), values=(_group(n),))
            self._draw()

        def _bars(self, cv, title, labels, vals, every=1):
            cv.delete("all")
            w, h = cv.winfo_width(), cv.winfo_height()
            if w < 50:
                return
            cv.create_text(10, 8, anchor="nw", text=title, fill=C["fg"], font=FONT)
            n = len(vals)
            if not n:
                return
            top, bot, left = 32, h - 22, 10
            mx = max(vals) or 1
            bw = (w - 2 * left) / float(n)
            for i, v in enumerate(vals):
                x0 = left + i * bw + 1
                y0 = bot - (bot - top) * v / float(mx)
                cv.create_rectangle(x0, y0, x0 + max(1, bw - 2), bot, fill=C["accent"], outline="")
                if v and n <= 31:
                    cv.create_text(x0 + bw / 2 - 1, y0 - 2, anchor="s", text=_group(v), fill=C["dim"], font=(FAM[0], 7))
                if i % every == 0:
                    cv.create_text(x0 + bw / 2 - 1, bot + 3, anchor="n", text=labels[i], fill=C["dim"], font=(FAM[0], 8))
            cv.create_line(left, bot, w - left, bot, fill=GRID_COLOR)

        def _draw(self):
            r = self.data
            if not r:
                return
            self._bars(self.cv_h, "Besucher nach Uhrzeit", [str(i) for i in range(24)], r["hourly"], 3)
            days = sorted(r["daily"])
            if not days:
                start = datetime.date.today() - datetime.timedelta(days=r["days"] - 1)
                days = [(start + datetime.timedelta(days=i)).strftime("%Y-%m-%d") for i in range(r["days"])]
            labs = ["%s.%s." % (d[8:10], d[5:7]) for d in days]
            self._bars(self.cv_d, "Besucher je Tag", labs, [r["daily"].get(d, 0) for d in days], 1 if len(days) <= 10 else 5)


    class OnlineTab(ttk.Frame):
        SECS = ["Texte", "Spalten & Überschriften", "Knöpfe & Anordnung", "Server-Knöpfe", "Zuwachs & Top-Performer",
                "Aussehen (Start-Einstellung)", "Schnellsuche", "Profil, Gilden & Rivalen", "Meine Gilde", "Einstellungen der Besucher (⚙)",
                "Besucher-Statistik"]
        PAGES = [("player", "Ehrenhalle (Spieler)"), ("guild", "Gilden-Tabelle"), ("kplayer", "Kompensation (Spieler)"),
                 ("kguild", "Kompensation (Gilden)"), ("oplayer", "Eigene Scans (Spieler)"), ("oguild", "Eigene Scans (Gilden)")]

        def __init__(self, master, app):
            super().__init__(master, padding=(12, 8))
            self.app = app
            self.dirty = True
            self._loading = True
            self._prev_after = None
            self.live = LivePreview()
            self.c = app.cfg.d.setdefault("html_export", {})
            top = ttk.Frame(self)
            top.grid(row=0, column=0, columnspan=2, sticky="ew")
            ttk.Label(top, text="Online-Liste (Web-Seite)", style="Head.TLabel").pack(side="left")
            ttk.Button(top, text="Web-Seite (HTML) speichern …", style="Accent.TButton", command=self._export).pack(side="right")
            self.live_btn = ttk.Button(top, text="Live-Vorschau im Browser", command=self._live_toggle)
            self.live_btn.pack(side="right", padx=8)
            Tip(self.live_btn, "Öffnet die Seite in deinem Browser (so viele Zeilen wie bei „Vorschau-Zeilen“ eingestellt). Nach jeder Änderung "
                               "hier lädt sie sich nach etwa einer Sekunde von selbst neu. Läuft nur auf diesem PC (127.0.0.1).")
            self.live_lbl = ttk.Label(top, text="", style="Dim.TLabel")
            self.live_lbl.pack(side="right", padx=8)
            self.live_err = tk.Frame(top, bg="#5a1a17")              # Fehler der Seite (von der Live-Vorschau gemeldet)
            self.live_err_l = tk.Label(self.live_err, text="", bg="#5a1a17", fg="#ffd7d3", anchor="w", justify="left", font=FONT,
                                       padx=8, pady=3)
            self.live_err_l.pack(side="left", fill="x", expand=True)
            ttk.Button(self.live_err, text="Details kopieren", command=self._live_err_copy).pack(side="right", padx=4, pady=2)
            self._live_err_shown = ""
            self.v_lrows = tk.StringVar(value=str(self.c.get("live_rows", 150)))
            lr = ttk.Frame(top)
            lr.pack(side="right", padx=(0, 4))
            ttk.Label(lr, text="Vorschau-Zeilen:").pack(side="left")
            sp = ttk.Spinbox(lr, from_=0, to=100000, increment=50, width=7, textvariable=self.v_lrows)
            sp.pack(side="left", padx=4)
            Tip(sp, "So viele Zeilen zeigt die Live-Vorschau (0 = alle; viele Zeilen machen die Vorschau langsamer). "
                    "Die gespeicherte Web-Seite enthält immer alle Zeilen nach „Welche Zeilen kommen in die Liste?“.")
            self.v_lrows.trace_add("write", lambda *a: self._num("live_rows", self.v_lrows, 0, self.c))
            ttk.Label(self, text="Alle Einstellungen der Web-Seite an einem Ort. Der Knopf „Web-Seite (HTML) …“ in Ehrenhalle, "
                                 "Gilde und Kompensation fragt danach nur noch nach der Art der Seite und dem Speicherort.",
                      style="Dim.TLabel").grid(row=1, column=0, columnspan=2, sticky="w", pady=(0, 6))
            pf = ttk.Frame(self)
            pf.grid(row=2, column=0, columnspan=2, sticky="w", pady=(0, 8))
            ttk.Label(pf, text="Seite:").pack(side="left")
            self.page = tk.StringVar(value=self.PAGES[0][1])
            self.page_cb = ttk.Combobox(pf, textvariable=self.page, state="readonly", width=26, values=[t for _k, t in self.PAGES])
            self.page_cb.pack(side="left", padx=6)
            self.page_cb.bind("<<ComboboxSelected>>", lambda e: self._page_changed())
            ttk.Label(pf, text="(Überschrift und Spalten gelten je Seite, alles andere für alle Seiten)", style="Dim.TLabel").pack(side="left", padx=6)
            tf = ttk.LabelFrame(self, text=" Welche Zeilen kommen in die Liste? ", padding=(10, 6))
            tf.grid(row=3, column=0, columnspan=2, sticky="ew", pady=(0, 8))
            self.v_topmode = tk.StringVar(value="top")
            self.v_topn = tk.StringVar(value="200")
            ttk.Radiobutton(tf, text="alle Zeilen", value="all", variable=self.v_topmode, command=self._topmode).pack(side="left")
            ttk.Radiobutton(tf, text="nur wer unter den Top", value="top", variable=self.v_topmode, command=self._topmode).pack(side="left", padx=(16, 4))
            self.sp_topn = ttk.Spinbox(tf, from_=10, to=100000, increment=50, width=8, textvariable=self.v_topn)
            self.sp_topn.pack(side="left")
            ttk.Label(tf, text="einer Top-Liste ist").pack(side="left", padx=(4, 0))
            self.top_info = ttk.Label(tf, text="", style="Dim.TLabel", wraplength=900, justify="left")
            self.top_info.pack(side="left", padx=(14, 0))
            self.v_topn.trace_add("write", lambda *a: self._topmode())
            self.columnconfigure(1, weight=1)
            self.rowconfigure(4, weight=1)
            self.nav = tk.Listbox(self, width=26, activestyle="none", exportselection=False, bg=C["panel"], fg=C["fg"],
                                  selectbackground=C["accent"], selectforeground="#ffffff", highlightthickness=0, relief="flat",
                                  font=FONT)
            for sname in self.SECS:
                self.nav.insert("end", "  " + sname)
            self.nav.grid(row=4, column=0, sticky="ns", padx=(0, 12))
            self.nav.bind("<<ListboxSelect>>", lambda e: self._sec_changed())
            self.body = ttk.Frame(self)
            self.body.grid(row=4, column=1, sticky="nsew")
            self.body.columnconfigure(0, weight=1)
            self.body.rowconfigure(0, weight=1)
            self.frames = {}
            for sname, build in zip(self.SECS, (self._b_texts, self._b_cols, self._b_layout, self._b_servers, self._b_gain,
                                                self._b_look, self._b_quick, self._b_prof, self._b_mg, self._b_visit, self._b_stats)):
                f = ttk.Frame(self.body, padding=(4, 0))
                f.grid(row=0, column=0, sticky="nsew")
                self.frames[sname] = f
                build(f)
            self.nav.selection_set(0)
            self._sec_changed()
            self._loading = False

        # ---------------------------------------------------------------- Hilfen
        def table(self):
            key = dict((t, k) for k, t in self.PAGES).get(self.page.get(), "player")
            if key in ("oplayer", "oguild"):                     # Reiter "Eigene Scans" der Seite: nur Spalten, keine Zeilen
                own = self.app.__dict__.setdefault("_own_tables", {})
                if key not in own:
                    own[key] = OwnTable(self.app, key == "oguild")
                return own[key]
            if key == "guild":
                return self.app.tab_guild.table
            if key == "kplayer":
                return self.app.tab_komp.players
            if key == "kguild":
                return self.app.tab_komp.guilds
            return self.app.tab_table

        def web(self):
            return WebPage(self.app, self.table())

        def _ready(self):
            """Gewaehlte Tabelle mit aktuellen Zeilen (Reiter, die gerade nicht sichtbar sind, rechnen erst bei Bedarf)."""
            t = self.table()
            if isinstance(t, OwnTable):                          # Eigene Scans stecken in der Spieler-Seite
                t = self.app.tab_table
            host = {"guild": self.app.tab_guild, "kplayer": self.app.tab_komp, "kguild": self.app.tab_komp}.get(t.mode)
            if host is not None and getattr(host, "dirty", False):
                host.refresh()
            if getattr(t, "dirty", False) or not getattr(t, "_all_rows", None):
                t.refresh()
            return t

        def show_for(self, table):
            for k, t in self.PAGES:
                if getattr(table, "mode", None) == k:
                    self.page.set(t)
            self._page_changed()

        def changed(self, reload_cols=False):
            """Eine Einstellung wurde geaendert: speichern und die Live-Vorschau neu bauen."""
            if self._loading:
                return
            self.app.save_soon()
            if reload_cols:
                self._fill_cols()
            self._live_soon()

        def _sec_changed(self):
            sel = self.nav.curselection()
            name = self.SECS[sel[0]] if sel else self.SECS[0]
            self.frames[name].tkraise()
            if name == "Knöpfe & Anordnung":
                self._draw_layout()
            if name == "Server-Knöpfe":
                self._groups_status()

        def _page_changed(self):
            self._loading = True
            self.v_title.set(self.web().title())
            self._loading = False
            own = isinstance(self.table(), OwnTable)
            for w in self.sp_topn.master.winfo_children():     # "Welche Zeilen …" gilt hier nicht (immer alle Zeilen der Datei)
                try:
                    w.configure(state="disabled" if own else "normal")
                except tk.TclError:
                    pass
            if not own:
                self._topmode()
            self._fill_cols()
            self._live_soon()

        def refresh(self):
            self.dirty = True                     # bei jedem Oeffnen neu laden (Werte teilen sich Einstellungen & Tabellen)
            self._loading = True
            try:
                self.v_title.set(self.web().title())
                self._load_values()
            finally:
                self._loading = False
            self._fill_cols()
            self._fill_texts()
            self._fill_layout()
            self._groups_status()
            self._fill_vis()

        def _export(self):
            HtmlExportDialog(self.app, self._ready())

        # ---------------------------------------------------------------- Texte
        def _b_texts(self, f):
            g = ttk.Frame(f)
            g.pack(fill="x")
            g.columnconfigure(1, weight=1)
            ttk.Label(g, text="Überschrift:").grid(row=0, column=0, sticky="w", pady=3)
            self.v_title = tk.StringVar()
            et = ttk.Entry(g, textvariable=self.v_title, width=44)
            et.grid(row=0, column=1, sticky="ew", padx=6)
            Tip(et, "Gilt für die oben gewählte Seite (Ehrenhalle, Gilden-Tabelle …).")
            self.v_title.trace_add("write", lambda *a: self._set_title())
            self._pos_lbl = {}
            for r, b in ((0, "title"), (1, "sub"), (3, "foot")):     # Stelle auf der Seite + Pfeile + Zeigen
                pf = ttk.Frame(g)
                pf.grid(row=r, column=2, sticky="w", padx=(8, 0))
                self._pos_lbl[b] = ttk.Label(pf, text="", width=12, foreground=C["accent"])
                self._pos_lbl[b].pack(side="left")
                self._arrows(pf, b)
                ttk.Button(pf, text="Zeigen", width=6, command=lambda b=b: self._show(WEB_SEL[b])).pack(side="left", padx=(6, 0))
            ttk.Label(g, text="Untertitel:").grid(row=1, column=0, sticky="w", pady=3)
            sf = ttk.Frame(g)
            sf.grid(row=1, column=1, sticky="ew", padx=6)
            self.v_submode = tk.StringVar(value="auto")
            rk = ttk.Radiobutton(sf, text="keiner", value="auto", variable=self.v_submode,
                            command=lambda: self._set("sub_mode", self.v_submode.get()))
            rk.pack(side="left")
            Tip(rk, "Kein Untertitel – der Zeitraum der Scans steht dann im „i“.")
            ttk.Radiobutton(sf, text="eigener Text:", value="own", variable=self.v_submode,
                            command=lambda: self._set("sub_mode", self.v_submode.get())).pack(side="left", padx=(12, 4))
            self.v_sub = tk.StringVar()
            ttk.Entry(sf, textvariable=self.v_sub, width=20).pack(side="left", fill="x", expand=True)
            self.v_sub.trace_add("write", lambda *a: self._set("sub_own", self.v_sub.get()))
            ttk.Label(g, text="Hinweis im „i“:").grid(row=2, column=0, sticky="w", pady=3)
            self.v_note = tk.StringVar()
            en = ttk.Entry(g, textvariable=self.v_note, width=44)
            en.grid(row=2, column=1, sticky="ew", padx=6)
            Tip(en, "Ein neuer Hinweis öffnet das „i“ bei jedem Betrachter einmal von selbst.")
            self.v_note.trace_add("write", lambda *a: self._set("note", self.v_note.get()))
            nf = ttk.Frame(g)
            nf.grid(row=2, column=2, sticky="w", padx=(8, 0))
            ttk.Label(nf, text="im „i“", width=12, style="Dim.TLabel").pack(side="left")
            ttk.Button(nf, text="Zeigen", width=6, command=lambda: self._show(WEB_SEL["hinfo"])).pack(side="left", padx=(0, 0))
            ttk.Label(g, text="Fußzeile:").grid(row=3, column=0, sticky="w", pady=3)
            self.v_foot = tk.StringVar()
            ttk.Entry(g, textvariable=self.v_foot, width=44).grid(row=3, column=1, sticky="ew", padx=6)
            self.v_foot.trace_add("write", lambda *a: self._set("foot", self.v_foot.get()))
            ttk.Label(g, text="leer = „Erstellt am {datum}.“ · Platzhalter: {datum} {scan} {scan1} {scan2} {spieler}",
                      style="Dim.TLabel").grid(row=4, column=1, columnspan=2, sticky="w", padx=6)
            ttk.Label(f, text="Weitere Texte der Seite – leer = Standardtext in der Sprache des Besuchers; dein Text gilt für alle "
                              "Sprachen. Doppelklick = ändern.", style="Dim.TLabel").pack(anchor="w", pady=(12, 4))
            box = ttk.Frame(f, style="Panel.TFrame")
            box.pack(fill="both", expand=True)
            self.t_tx = ttk.Treeview(box, columns=("where", "std", "own"), show="headings", height=6, selectmode="browse")
            for c, t, w in (("where", "Stelle auf der Seite", 320), ("std", "Standard (Deutsch)", 420), ("own", "Dein Text", 360)):
                self.t_tx.heading(c, text=t)
                self.t_tx.column(c, width=w, anchor="w")
            attach_scroll(box, self.t_tx)
            self.t_tx.pack(side="left", fill="both", expand=True)
            self.t_tx.tag_configure("own", foreground=C["accent"])
            self.t_tx.bind("<Double-Button-1>", lambda e: self._tx_edit())
            self.t_tx.bind("<<TreeviewSelect>>", lambda e: self._fill_pos())
            bf = ttk.Frame(f)
            bf.pack(fill="x", pady=6)
            ttk.Button(bf, text="Text ändern …", command=self._tx_edit).pack(side="left")
            ttk.Button(bf, text="Standard", command=self._tx_clear).pack(side="left", padx=6)
            ttk.Button(bf, text="Auf der Seite zeigen", command=self._tx_show).pack(side="left", padx=(18, 6))
            self._tx_pos = ttk.Label(bf, text="", foreground=C["accent"])
            self._tx_pos.pack(side="left", padx=(6, 6))
            self._arrows(bf, None)
            ttk.Label(bf, text="Pfeile verschieben das Element, zu dem der Text gehört", style="Dim.TLabel").pack(side="left", padx=8)

        def _set(self, key, val):
            if self._loading:
                return
            self.c[key] = val
            self.changed()

        def _set_title(self):
            if self._loading:
                return
            t = self.table()
            self.c["title_" + t.mode] = self.v_title.get()
            if t.mode == "player":
                self.c["title"] = self.v_title.get()
            self.changed()

        def _fill_texts(self):
            tx = self.c.get("tx") or {}
            self.t_tx.delete(*self.t_tx.get_children())
            for k, where, std in WEB_TX:
                own = str(tx.get(k) or "")
                self.t_tx.insert("", "end", iid=k, values=[tkstr(where), tkstr(std), tkstr(own)], tags=("own",) if own else ())

        def _tx_edit(self):
            sel = self.t_tx.selection()
            if not sel:
                return
            k = sel[0]
            where = dict((a, b) for a, b, _c in WEB_TX).get(k, k)
            dlg = FormDialog(self, "Text ändern", [where + ":"], [str((self.c.get("tx") or {}).get(k) or "")])
            if dlg.result is None:
                return
            tx = self.c.setdefault("tx", {})
            if dlg.result[0].strip():
                tx[k] = dlg.result[0].strip()
            else:
                tx.pop(k, None)
            self._fill_texts()
            self.t_tx.selection_set(k)
            self.changed()

        def _tx_key_block(self):
            sel = self.t_tx.selection() if hasattr(self, "t_tx") else ()
            return TX_BLOCK.get(sel[0]) if sel else None

        def _tx_show(self):
            sel = self.t_tx.selection()
            if not sel:
                self.app.set_status("Bitte zuerst einen Text in der Liste auswählen.")
                return
            k = sel[0]
            self._show(TX_SEL.get(k) or WEB_SEL.get(TX_BLOCK.get(k, ""), ""))

        def _arrows(self, parent, block):
            """Pfeile ◀ ▲ ▼ ▶ fuer einen Baustein (block=None: der Baustein des gewaehlten Textes)."""
            get = (lambda: block) if block else self._tx_key_block

            def go(fn, d):
                b = get()
                if not b:
                    self.app.set_status("Dieser Text gehört zu keinem verschiebbaren Element (er erscheint an seiner festen Stelle).")
                    return
                fn(d, b)
            for txt, fn, d in (("◀", self._lay_move, -1), ("▲", self._lay_row, -1), ("▼", self._lay_row, 1), ("▶", self._lay_move, 1)):
                ttk.Button(parent, text=txt, width=2, command=lambda fn=fn, d=d: go(fn, d)).pack(side="left", padx=1)

        def _pos_text(self, b, short=False):
            """"Kopf, Platz 1" / "Zeile 2, Platz 3" / "unten, Platz 1" – wo ein Baustein steht (kurz: "Zeile 2 · 3")."""
            lay = sorted(self._layout(), key=lambda x: x.get("r", 1))
            x = next((y for y in lay if y["b"] == b), None)
            if x is None:
                return ""
            if x.get("on") is False:
                return "ausgeblendet"
            r = x.get("r", 1)
            row = [y["b"] for y in lay if y.get("r", 1) == r and y.get("on") is not False]
            return ("%s · %d" if short else "%s, Platz %d") % (web_row_name(r), row.index(b) + 1)

        def _fill_pos(self):
            for b, lbl in getattr(self, "_pos_lbl", {}).items():
                lbl.configure(text=self._pos_text(b, short=True))
            if hasattr(self, "_tx_pos"):
                b = self._tx_key_block()
                sel = self.t_tx.selection()
                self._tx_pos.configure(text=("Stelle: " + self._pos_text(b)) if b else ("keine feste Stelle" if sel else ""))

        def _show(self, sel):
            """Stelle in der Live-Vorschau aufleuchten lassen (startet die Vorschau, falls sie noch nicht laeuft)."""
            if not sel:
                self.app.set_status("Dieser Text hat keine feste Stelle auf der Seite.")
                return
            if not self.live.running():
                self._live_toggle()
                if self.live.running():
                    self.after(3500, lambda: self.live.flash(sel))
                return
            self.live.flash(sel)

        def _tx_clear(self):
            sel = self.t_tx.selection()
            if sel:
                (self.c.get("tx") or {}).pop(sel[0], None)
                self._fill_texts()
                self.changed()

        # ---------------------------------------------------------------- Spalten & Ueberschriften
        def _b_cols(self, f):
            ttk.Label(f, text="Spalten der Seite in der Reihenfolge der Tabelle. Klick auf ☑/☐ schaltet um. Online = die Spalte kommt in "
                              "die Seite (☐ = gar nicht, auch nicht in den Einstellungen der Seite) · Anfangs an = sofort sichtbar (☐ = erst "
                              "ausgeblendet, jeder Besucher kann sie unter ⚙ › Spalten einschalten) · Top-Liste = wer dort unter den Top X "
                              "ist, kommt in die Datei · Rang-Marke = Platz neben dem Wert · Knopf oben = Listen-Knopf über der Tabelle · "
                              "Zuwachs = grüne/rote Zahl im Vergleich (☐ = nur die nackte Zahl, z. B. für Base Ratio). "
                              "Spalten, die du in der Tabelle entfernst, fehlen auch online.",
                      style="Dim.TLabel", wraplength=1150, justify="left").grid(row=0, column=0, columnspan=2, sticky="w")
            box = ttk.Frame(f, style="Panel.TFrame")
            box.grid(row=1, column=0, sticky="nsew", pady=(6, 6))
            f.columnconfigure(0, weight=1)
            f.rowconfigure(1, weight=1)
            cols = ("show", "vis", "prog", "web", "top", "mark", "btn", "gain", "tab")
            self.t_cols = ttk.Treeview(box, columns=cols, show="headings", height=6, selectmode="browse")
            for c, t, w, a in (("show", "Online", 70, "center"), ("vis", "Anfangs an", 90, "center"), ("prog", "Spalte im Programm", 230, "w"),
                               ("web", "Überschrift online", 230, "w"), ("top", "Top-Liste", 90, "center"),
                               ("mark", "Rang-Marke", 100, "center"), ("btn", "Knopf oben", 100, "center"),
                               ("gain", "Zuwachs", 90, "center"), ("tab", "Reiter online", 130, "w")):
                self.t_cols.heading(c, text=t)
                self.t_cols.column(c, width=w, anchor=a, stretch=(a == "w"))
            attach_scroll(box, self.t_cols)
            self.t_cols.pack(side="left", fill="both", expand=True)
            self.t_cols.tag_configure("own", foreground=C["accent"])
            self.t_cols.bind("<Button-1>", self._cols_click)
            self.t_cols.bind("<Double-Button-1>", lambda e: self._col_rename() if self.t_cols.identify_column(e.x) in ("#3", "#4") else None)
            bb = ttk.Frame(f)
            bb.grid(row=1, column=1, sticky="n", padx=(10, 0), pady=(6, 0))
            for txt, cmd in (("▲ nach oben", lambda: self._col_move(-1)), ("▼ nach unten", lambda: self._col_move(1)),
                             ("Überschrift ändern …", self._col_rename), ("Original-Überschrift", self._col_orig),
                             ("Spalten wählen …", self._cols_dialog), ("Reiter verwalten …", self._tabs_dialog)):
                ttk.Button(bb, text=txt, width=22, command=cmd).pack(fill="x", pady=2)
            of = ttk.Frame(f)
            of.grid(row=2, column=0, columnspan=2, sticky="w")
            ttk.Label(of, text="Top-Liste = zählt für „Welche Zeilen kommen in die Liste?“ (oben)   ·   Namen höchstens").pack(side="left")
            self.v_nw = tk.StringVar()
            ttk.Spinbox(of, from_=6, to=60, width=5, textvariable=self.v_nw).pack(side="left", padx=6)
            ttk.Label(of, text="Zeichen, Gilden höchstens").pack(side="left")
            self.v_gw = tk.StringVar()
            ttk.Spinbox(of, from_=6, to=60, width=5, textvariable=self.v_gw).pack(side="left", padx=6)
            ttk.Label(of, text="Zeichen (länger → „…“, die Maus zeigt alles)", style="Dim.TLabel").pack(side="left")
            self.v_nw.trace_add("write", lambda *a: self._num("web_nw", self.v_nw, 4, self.app.cfg.d))
            self.v_gw.trace_add("write", lambda *a: self._num("web_gw", self.v_gw, 4, self.app.cfg.d))
            ttk.Label(f, text="Blau = eigene Überschrift (gilt für alle Sprachen). XP bekommt nie eine Rang-Marke. Server, Gilde und "
                              "Klasse bleiben intern für Suche und Server-Knöpfe, auch wenn sie nicht online sind.",
                      style="Dim.TLabel").grid(row=3, column=0, columnspan=2, sticky="w", pady=(6, 0))

        def _topmode(self):
            """Alle Zeilen oder nur wer in mindestens einer Top-Liste unter den Top X ist (top_n = 0 heisst alle)."""
            try:
                self.sp_topn.configure(state="normal" if self.v_topmode.get() == "top" else "disabled")
            except (AttributeError, tk.TclError):
                pass
            if self._loading:
                return
            try:
                n = int(float(str(self.v_topn.get()).replace(".", "").replace(",", ".")))
            except ValueError:
                return
            if self.v_topmode.get() == "all":
                self.c["top_n"] = 0
            elif n >= 1:
                self.c["top_n"] = n
                self.c["top_last"] = n
            self._top_info()
            self.changed()

        def _top_info(self):
            lab = getattr(self, "top_info", None)
            if lab is None:
                return
            try:
                w = self.web()
                cc = w.col_conf()
                tops = [w.label(k, cc) for k, e in cc.items() if e.get("top") and e.get("show")]
            except Exception:
                tops = []
            if self.v_topmode.get() == "all":
                txt = ("Alle Zeilen der Tabelle bzw. alle Spieler der gewählten Scans und Gilden. Mit allen Spielern "
                       "(ohne Gilden-Filter) wird die Datei groß.")
            elif tops:
                txt = "Top-Listen: %s (Haken „Top-Liste“ unter Spalten & Überschriften)." % ", ".join(tops)
            else:
                txt = "Noch keine Spalte hat den Haken „Top-Liste“ (Spalten & Überschriften) – dann kommen alle Zeilen hinein."
            lab.configure(text=tkstr(txt))

        def _num(self, key, var, lo, store):
            if self._loading:
                return
            try:
                v = int(float(str(var.get()).replace(".", "").replace(",", ".")))
            except ValueError:
                return
            if v >= lo:
                store[key] = v
                self.changed()

        def _fill_cols(self):
            if not hasattr(self, "t_cols"):
                return
            self._top_info()
            keep = self.t_cols.selection()
            self.t_cols.delete(*self.t_cols.get_children())
            try:
                w = self.web()
                cc = w.col_conf()
            except Exception:
                return
            Y, N, X = "☑", "☐", "–"
            tabn = dict(w.tabs())
            for k, e in cc.items():
                num = FIELD_MAP[k].kind in ("num", "pct") and e["show"]
                lab = w.label(k, cc).replace("{x}", gain_x_text(GAIN_X)) if e["show"] else "(nicht online)"
                self.t_cols.insert("", "end", iid=k, tags=("own",) if e["label"] else (), values=[
                    Y if e["show"] else N, ((Y if e["vis"] else N) if e["show"] and k not in ("name", "g_name") else X),
                    tkstr(w.table.label(k)), tkstr(lab),
                    (Y if e["top"] else N) if num else X, (Y if e["mark"] else N) if num and k != "xp" else X,
                    (Y if e["btn"] else N) if num else X, (Y if e["gain"] else N) if e["show"] and w.gain_ok(k) else X,
                    tkstr(tabn.get(e["tab"], e["tab"]) + " ▾") if e["show"] and k not in ("name", "g_name") else X])
            for k in keep:
                if self.t_cols.exists(k):
                    self.t_cols.selection_set(k)

        def _cols_click(self, e):
            if self.t_cols.identify_region(e.x, e.y) != "cell":
                return
            k = self.t_cols.identify_row(e.y)
            col = self.t_cols.identify_column(e.x)
            what = {"#1": "show", "#2": "vis", "#5": "top", "#6": "mark", "#7": "btn", "#8": "gain", "#9": "tab"}.get(col)
            if not k or not what:
                return
            if what == "tab":                                  # Reiter online: Liste zum Auswaehlen
                w0 = self.web()
                e0 = w0.col_conf().get(k) or {}
                if not e0.get("show") or k in ("name", "g_name"):
                    return "break"
                self.t_cols.selection_set(k)
                m = tk.Menu(self, tearoff=0, font=FONT)
                self._tabvar = tk.StringVar(value=e0.get("tab"))
                for tid, lab in w0.tabs():
                    m.add_radiobutton(label=tkstr(lab), value=tid, variable=self._tabvar,
                                      command=lambda tid=tid: (w0.set_col(k, tab=tid), self.changed(reload_cols=True)))
                m.add_separator()
                m.add_command(label="Neuer Reiter …", command=lambda: self._tab_new(k))
                m.add_command(label="Reiter verwalten …", command=self._tabs_dialog)
                try:
                    m.tk_popup(e.x_root, e.y_root)
                finally:
                    m.grab_release()
                return "break"
            w = self.web()
            cc = w.col_conf()
            if k not in cc:
                return
            num = FIELD_MAP[k].kind in ("num", "pct") and cc[k]["show"]
            if what == "gain":
                if not (cc[k]["show"] and w.gain_ok(k)):
                    return
            elif what == "vis":
                if not cc[k]["show"] or k in ("name", "g_name"):
                    return
            elif what != "show" and not num or (what == "mark" and k == "xp"):
                return
            if what == "show" and k in ("name", "g_name"):
                return
            w.set_col(k, **{what: not cc[k][what]})
            self.t_cols.selection_set(k)
            self.changed(reload_cols=True)
            return "break"

        def _tab_new(self, key=None):
            w = self.web()
            dlg = FormDialog(self, "Neuer Reiter", ["Name des neuen Reiters (online in ⚙ › Spalten):"], [""])
            name = (dlg.result or [""])[0].strip()
            if not name:
                return None
            tabs = w.tabs()
            n = 1
            while any(i == "t%d" % n for i, _l in tabs):
                n += 1
            tid = "t%d" % n
            self.c["ctabs"] = [list(x) for x in tabs] + [[tid, name]]
            if key:
                w.set_col(key, tab=tid)
            self.changed(reload_cols=True)
            return tid

        def _tabs_dialog(self):
            TabsDialog(self)

        def _sel_col(self):
            sel = self.t_cols.selection()
            return sel[0] if sel else None

        def _col_rename(self):
            k = self._sel_col()
            if not k:
                return
            w = self.web()
            dlg = FormDialog(self, "Überschrift online", ["Überschrift für „%s“ (leer = Standard):" % w.table.label(k)],
                             [w.col_conf().get(k, {}).get("label", "")])
            if dlg.result is None:
                return
            w.set_col(k, label=dlg.result[0].strip())
            self.changed(reload_cols=True)

        def _col_orig(self):
            k = self._sel_col()
            if k:
                self.web().set_col(k, label="")
                self.changed(reload_cols=True)

        def _col_move(self, d):
            k = self._sel_col()
            t = self.table()
            cols = list(t._cols())
            if not k or k not in cols:
                return
            i = cols.index(k)
            j = i + d
            if not 0 <= j < len(cols):
                return
            cols[i], cols[j] = cols[j], cols[i]
            t.set_cols(cols)
            self.t_cols.selection_set(k)
            self.changed(reload_cols=True)

        def _cols_dialog(self):
            t = self.table()
            t.open_columns()
            self.after(500, self._wait_cols)

        def _wait_cols(self):
            try:
                if any(isinstance(w, ColumnsDialog) and w.winfo_exists() for w in self.app.winfo_children()):
                    self.after(400, self._wait_cols)
                    return
            except tk.TclError:
                return
            self.changed(reload_cols=True)

        # ---------------------------------------------------------------- Knoepfe & Anordnung
        def _b_layout(self, f):
            ttk.Label(f, text="Was steht wo auf der Seite? Element wählen und mit den Pfeilen verschieben: ▲▼ = andere Zeile, ◀▶ = weiter "
                              "vorne/hinten – rechts siehst du die Anordnung. „Kopf“ = die Zeile mit dem Titel: bis zum ersten „rechtsbündig“ "
                              "steht alles links neben dem Titel, ab dort rechts. „unten“ = unter der Tabelle. Leere Zeilen verschwinden "
                              "auf der Seite von selbst.",
                      style="Dim.TLabel", wraplength=1100, justify="left").grid(
                row=0, column=0, columnspan=3, sticky="w")
            box = ttk.Frame(f, style="Panel.TFrame")
            box.grid(row=1, column=0, sticky="nsw", pady=(6, 6))
            self.t_lay = ttk.Treeview(box, columns=("r", "el", "on", "right", "gap"), show="headings", height=11, selectmode="browse")
            for c, t, w, a in (("r", "Zeile", 55, "center"), ("el", "Element", 280, "w"), ("on", "Zeigen", 70, "center"),
                               ("right", "rechts", 65, "center"), ("gap", "Abstand", 75, "center")):
                self.t_lay.heading(c, text=t)
                self.t_lay.column(c, width=w, anchor=a, stretch=False)
            attach_scroll(box, self.t_lay)
            self.t_lay.pack(side="left", fill="y")
            self.t_lay.bind("<<TreeviewSelect>>", lambda e: self._draw_layout())
            bb = ttk.Frame(f)
            bb.grid(row=1, column=1, sticky="n", padx=10, pady=(6, 0))
            pad = ttk.Frame(bb)
            pad.pack(pady=(0, 4))
            for (r, cc, txt, cmd) in ((0, 1, "▲", lambda: self._lay_row(-1)), (1, 0, "◀", lambda: self._lay_move(-1)),
                                      (1, 1, "▼", lambda: self._lay_row(1)), (1, 2, "▶", lambda: self._lay_move(1))):
                ttk.Button(pad, text=txt, width=3, command=cmd).grid(row=r, column=cc, padx=1, pady=1)
            for txt, cmd in (("zeigen / ausblenden", lambda: self._lay_flag("on")), ("rechtsbündig", lambda: self._lay_flag("right")),
                             ("Abstand davor", lambda: self._lay_flag("gap")), ("Auf der Seite zeigen", self._lay_show),
                             ("Standard", self._lay_default)):
                ttk.Button(bb, text=txt, width=20, command=cmd).pack(fill="x", pady=2)
            self.cv_lay = tk.Canvas(f, width=520, height=330, bg=C["bg"], highlightthickness=1, highlightbackground=C["panel2"])
            self.cv_lay.grid(row=1, column=2, sticky="nsew", pady=(6, 0))
            f.columnconfigure(2, weight=1)
            self.cv_lay.bind("<Configure>", lambda e: self._draw_layout())
            pf = ttk.LabelFrame(f, text=" Im Programm ", padding=8)
            pf.grid(row=2, column=0, columnspan=3, sticky="ew", pady=(8, 0))
            ttk.Label(pf, text="Anzeige „252 Spieler · 1 Datei(en)“:").pack(side="left")
            self.v_cpos = tk.StringVar()
            cb = ttk.Combobox(pf, textvariable=self.v_cpos, state="readonly", width=28, values=[t for _k, t in COUNT_POS])
            cb.pack(side="left", padx=6)
            cb.bind("<<ComboboxSelected>>", lambda e: self._cpos_changed())
            ttk.Label(pf, text="(gilt für das Programm selbst, nicht für die Web-Seite)", style="Dim.TLabel").pack(side="left")

        def _layout(self):
            lay = [dict(x) for x in (self.c.get("layout") or WEB_LAYOUT_DEFAULT)]
            have = {x.get("b") for x in lay}
            if "riv" not in have:                            # neuer Baustein (Paket 4): direkt hinter das Suchfeld
                i = next((n for n, x in enumerate(lay) if x.get("b") == "search"), None)
                if i is not None:
                    lay.insert(i + 1, {"b": "riv", "r": lay[i].get("r", 2)})
                    have.add("riv")
            if "rks" not in have:                            # neu: Top-Marken alle | angezeigte hinter die Spaltensuche
                i = next((n for b in ("colf", "search", "reset") for n, x in enumerate(lay)
                          if x.get("b") == b and x.get("on", True) is not False), None)
                if i is not None:
                    lay.insert(i + 1, {"b": "rks", "r": lay[i].get("r", 2)})
                else:
                    lay.append({"b": "rks", "r": 2})
                have.add("rks")
            if "title" not in have:                          # neu (Schritt 2): Ueberschrift und Untertitel als Bausteine im Kopf
                lay.insert(0, {"b": "title", "r": 0})
                have.add("title")
            if "sub" not in have:
                i = next(n for n, x in enumerate(lay) if x.get("b") == "title")
                lay.insert(i + 1, {"b": "sub", "r": lay[i].get("r", 0)})
                have.add("sub")
            for b in WEB_HEAD:                                # neu: Kopfzeile (fruehere Anordnungen: Knoepfe wie bisher oben)
                if b not in have:
                    lay.append({"b": b, "r": 0})
                    have.add(b)
            if "foot" not in have:
                lay.append({"b": "foot", "r": WEB_BELOW})
                have.add("foot")
            for b, _n in WEB_BLOCKS:
                if b not in have:
                    lay.append({"b": b, "r": min(9, max([x.get("r", 1) for x in lay if x.get("r", 1) < WEB_BELOW] or [1]) + 1), "on": False})
            return [x for x in lay if x.get("b") in dict(WEB_BLOCKS)]

        def _lay_save(self, lay, keep=None):
            self.c["layout"] = lay
            self._fill_layout(keep)
            self.changed()

        def _fill_layout(self, keep=None):
            if not hasattr(self, "t_lay"):
                return
            keep = keep or (self.t_lay.selection()[0] if self.t_lay.selection() else None)
            self.t_lay.delete(*self.t_lay.get_children())
            names = dict(WEB_BLOCKS)
            lay = sorted(self._layout(), key=lambda x: x.get("r", 1))
            for x in lay:
                self.t_lay.insert("", "end", iid=x["b"], values=[web_row_name(x.get("r", 1)).replace("Zeile ", ""), tkstr(names[x["b"]]),
                                                                 "☐" if x.get("on") is False else "☑",
                                                                 "☑" if x.get("right") else "", "☑" if x.get("gap") else ""])
            if keep and self.t_lay.exists(keep):
                self.t_lay.selection_set(keep)
                self.t_lay.see(keep)
            self._draw_layout()
            self._fill_pos()

        def _lay_sel(self):
            sel = self.t_lay.selection()
            return sel[0] if sel else None

        def _lay_move(self, d, b=None):
            """◀ / ▶: innerhalb der Zeile weiter nach vorne / hinten."""
            b = b or self._lay_sel()
            if not b:
                return
            lay = sorted(self._layout(), key=lambda x: x.get("r", 1))
            i = next(n for n, x in enumerate(lay) if x["b"] == b)
            j = i + d
            if 0 <= j < len(lay) and lay[j].get("r", 1) == lay[i].get("r", 1):
                lay[i], lay[j] = lay[j], lay[i]
                self._lay_save(lay, b)

        def _lay_row(self, d, b=None):
            """▲ / ▼: eine Zeile hoeher / tiefer. Unter der letzten Zeile kommt "unten" (unter der Tabelle); von dort geht ▲
            in eine neue Zeile direkt ueber der Tabelle."""
            b = b or self._lay_sel()
            if not b:
                return
            lay = sorted(self._layout(), key=lambda x: x.get("r", 1))
            x = next(y for y in lay if y["b"] == b)
            r = int(x.get("r", 1))
            mx = max([int(y.get("r", 1)) for y in lay if y is not x and y.get("on") is not False and int(y.get("r", 1)) < WEB_BELOW] or [0])
            last = min(9, mx + 1)
            if d < 0:
                nr = r if r == 0 else (last if r >= WEB_BELOW else r - 1)
            else:
                nr = WEB_BELOW if r >= WEB_BELOW or r + 1 > last else r + 1
            if nr == r:
                return
            lay.remove(x)
            x["r"] = nr
            if d < 0:                                           # nach oben: ans Ende der Zeile darueber
                pos = max([n + 1 for n, y in enumerate(lay) if int(y.get("r", 1)) <= nr] or [0])
            else:                                               # nach unten: an den Anfang der Zeile darunter
                pos = min([n for n, y in enumerate(lay) if int(y.get("r", 1)) >= nr] or [len(lay)])
            lay.insert(pos, x)
            self._lay_save(sorted(lay, key=lambda y: y.get("r", 1)), b)

        def _lay_flag(self, key):
            b = self._lay_sel()
            if not b:
                return
            if key == "on" and b in WEB_NOHIDE:
                self.app.set_status("Die Überschrift und der Knopf Einstellungen lassen sich nicht ausblenden.")
                return
            lay = self._layout()
            for x in lay:
                if x["b"] == b:
                    if key == "on":
                        x["on"] = x.get("on") is False
                    else:
                        x[key] = 0 if x.get(key) else 1
            self._lay_save(lay, b)

        def _lay_show(self):
            b = self._lay_sel()
            if not b:
                self.app.set_status("Bitte zuerst ein Element in der Liste auswählen.")
                return
            self._show(WEB_SEL.get(b, ""))

        def _lay_default(self):
            self.c.pop("layout", None)
            self._fill_layout()
            self.changed()

        def _draw_layout(self):
            cv = getattr(self, "cv_lay", None)
            if cv is None:
                return
            cv.delete("all")
            cv.create_text(10, 8, text="Vorschau der Anordnung", anchor="nw", fill=C["dim"])
            names = {"scan": "Scan Alt → Neu", "dsort": "Nach Zuwachs ▲▼", "gone": "Alte Einträge", "cmp": "Vergleich", "riv": "Rivalen",
                     "gain": "gesamt | Tag | Woche | X", "search": "Suchfeld", "lists": "Alle | Level …", "colf": "Spaltensuche", "rks": "# alle | angezeigte",
                     "reset": "Zurücksetzen", "quick": "Schnellsuche ✦", "servers": "Server ▾", "count": "214 von 214 Spieler",
                     "hrk": "#", "hlang": "DE ▾", "hset": "⚙ Einstellungen", "hinfo": "i", "title": "Titel  Spieler | Gilden",
                     "sub": "Untertitel", "foot": "Fußzeile (Erstellt am …)"}
            widths = {"scan": 150, "search": 130, "gain": 150, "count": 130, "lists": 100, "quick": 100, "servers": 70, "rks": 130,
                      "hrk": 30, "hlang": 50, "hset": 110, "hinfo": 30, "title": 170, "foot": 170, "dsort": 110}
            sel = self._lay_sel()
            W = max(300, cv.winfo_width() - 4)
            rows = {}
            for x in sorted(self._layout(), key=lambda x: x.get("r", 1)):
                if x.get("on") is not False:
                    rows.setdefault(x.get("r", 1), []).append(x)

            def wd(i):
                return (W - 20) if i["b"] == "sub" else widths.get(i["b"], 88) + (16 if i.get("gap") else 0)

            def draw_row(items, y, idx):
                """Elemente von links nach rechts (zu lang = naechste Zeile); ab idx rechtsbuendig. Gibt das neue y zurueck."""
                lines, cur, xw = [], [], 10
                for n, i in enumerate(items):
                    w_ = wd(i)
                    if cur and (xw + w_ > W - 10 or i["b"] == "sub" or cur[-1][1]["b"] == "sub"):
                        lines.append(cur)
                        cur, xw = [], 10
                    cur.append((n, i, w_))
                    xw += w_ + 6
                if cur:
                    lines.append(cur)
                for ln in lines:
                    x0 = 10
                    right = [e for e in ln if e[0] >= idx]
                    xr = W - 8 - sum(e[2] + 6 for e in right) + 6
                    for n, i, w_ in ln:
                        if n >= idx:
                            x0 = max(x0, xr)
                            xr = -1
                        gx = 16 if i.get("gap") else 0
                        self._lay_box(cv, x0 + gx, y, w_ - gx, names[i["b"]], i["b"] == sel)
                        x0 += w_ + 6
                    y += 32
                return y
            y = 30
            head = rows.pop(0, [])
            if head:                                            # Kopf: links neben dem Titel (untereinander umbrechend) | rechts
                idx = web_head_split(head)
                left, right = head[:idx], head[idx:]
                rw = sum(widths.get(i["b"], 88) + 6 for i in right)
                xr = W - 8 - rw + 6
                for i in right:
                    w_ = widths.get(i["b"], 88)
                    self._lay_box(cv, xr, y, w_, names[i["b"]], i["b"] == sel)
                    xr += w_ + 6
                x0, y0 = 10, y
                for i in left:
                    w_ = (W - rw - 30) if i["b"] == "sub" else widths.get(i["b"], 88)
                    if x0 > 10 and (x0 + w_ > W - rw - 14 or i["b"] == "sub"):
                        x0, y0 = 10, y0 + 32
                    self._lay_box(cv, x0, y0, w_, names[i["b"]], i["b"] == sel)
                    x0 += w_ + 6
                    if i["b"] == "sub":
                        x0, y0 = 10, y0 + 32
                y = max(y + 32, y0 + (32 if x0 > 10 else 0)) + 6
            below = [rows.pop(r) for r in sorted([r for r in rows if r >= WEB_BELOW])]
            for r in sorted(rows):
                items = rows[r]
                box = any(i["b"] in ("scan", "dsort", "gone", "cmp") for i in items)
                idx = next((n for n, i in enumerate(items) if i.get("right")), len(items))
                top = y
                y = draw_row(items, y, idx)
                if box:
                    cv.create_rectangle(4, top - 5, W - 2, y - 2, outline=C["dim"], dash=(3, 3))
                    cv.tag_lower(cv.find_all()[-1])
                y += 10
            cv.create_rectangle(10, y, W - 8, y + 44, outline=C["dim"], fill=C["panel"])
            cv.create_text(18, y + 8, text="Tabelle", anchor="nw", fill=C["dim"])
            y += 54
            for items in below:
                idx = next((n for n, i in enumerate(items) if i.get("right")), len(items))
                y = draw_row(items, y, idx) + 6
            if y > int(cv.cget("height")):
                cv.configure(height=y)

        def _lay_box(self, cv, x, y, w, txt, sel):
            cv.create_rectangle(x, y, x + w, y + 26, outline=C["accent"] if sel else C["dim"], width=2 if sel else 1, fill=C["panel2"])
            cv.create_text(x + 5, y + 13, text=txt, anchor="w", fill=C["accent"] if sel else C["fg"])

        def _cpos_changed(self):
            k = dict((t, k) for k, t in COUNT_POS).get(self.v_cpos.get(), "top")
            self.app.cfg.d["count_pos"] = k
            self.app.apply_count_pos()
            self.app.save_soon()

        # ---------------------------------------------------------------- Server-Knoepfe
        def _b_servers(self, f):
            sfr = ScrollFrame(f)                                 # scrollbar, damit bei kleinem Fenster nichts abgeschnitten ist
            sfr.pack(fill="both", expand=True)
            f = sfr.inner
            self.t_groups = GroupEditor(
                f, "Server-Knöpfe der Online-Liste (und Schnellauswahl im Reiter Server)", ["Name", "Server"], [220, 520],
                self._get_groups, self._set_groups,
                "Server mit Komma trennen. * = beliebig (f* = alle F-Welten), eu5-8 = EU5 bis EU8, sonst der Name wie im Reiter "
                "Server (z. B. f8, eu12, am1, maerwynn). Die Reihenfolge hier ist die Reihenfolge der Knöpfe. Spielerzahlen "
                "zeigt die Seite nicht an.")
            self.t_groups.grid(row=0, column=0, sticky="nsew")
            self.t_groups.tree.configure(height=5)
            for w in self.t_groups.winfo_children():
                if isinstance(w, ttk.Label) and str(w.cget("wraplength")) == "420":
                    w.configure(wraplength=760)
            f.columnconfigure(0, weight=1)
            f.rowconfigure(0, weight=1)
            gb = ttk.Frame(f)
            gb.grid(row=0, column=1, sticky="n", padx=12)
            ttk.Button(gb, text="Hoch", command=lambda: self.t_groups.move(-1)).pack(fill="x")
            ttk.Button(gb, text="Runter", command=lambda: self.t_groups.move(1)).pack(fill="x", pady=4)
            ttk.Button(gb, text="Standard", command=self._groups_default).pack(fill="x", pady=(12, 0))
            self.grp_lbl = ttk.Label(gb, text="", style="Dim.TLabel", wraplength=260, justify="left")
            self.grp_lbl.pack(anchor="w", pady=(10, 0))
            ff = ttk.LabelFrame(f, text=" Kommende Fusionen ", padding=8)
            ff.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(10, 0))
            self.v_fzb = tk.BooleanVar(value=True)
            ttk.Checkbutton(ff, text="Im Fenster „EU-Server“ je kommender Fusion einen Knopf zeigen (F29 = EU5–EU8 …, laut "
                                     "Fusionsplan im Reiter Kompensation)", variable=self.v_fzb,
                            command=lambda: self._set_d("web_fusion_btns", bool(self.v_fzb.get()))).grid(row=0, column=0, columnspan=3, sticky="w")
            self.v_kpc = tk.BooleanVar(value=True)
            ttk.Checkbutton(ff, text="Ist eine kommende Fusion gewählt: Spalten „Komp. Level“ und „Komp. Stats“ zeigen (Stand heute, "
                                     "Formel aus dem Reiter Kompensation)", variable=self.v_kpc,
                            command=lambda: self._set_d("web_komp_cols", bool(self.v_kpc.get()))).grid(row=2, column=0, columnspan=3, sticky="w", pady=(6, 0))
            ttk.Label(ff, text="Nächste Fusion wird F").grid(row=1, column=0, sticky="w", pady=(6, 0))
            self.v_nextf = tk.StringVar()
            ttk.Entry(ff, textvariable=self.v_nextf, width=5).grid(row=1, column=1, sticky="w", padx=4, pady=(6, 0))
            self.v_nextf.trace_add("write", lambda *a: self._nextf())
            self.nextf_lbl = ttk.Label(ff, text="", style="Dim.TLabel")
            self.nextf_lbl.grid(row=1, column=2, sticky="w", padx=6, pady=(6, 0))
            sm = ttk.LabelFrame(f, text=" Server-Knöpfe auf der Seite ", padding=8)
            sm.grid(row=2, column=0, columnspan=2, sticky="ew", pady=(10, 0))
            self.v_srvmode = tk.StringVar(value="row")
            ttk.Radiobutton(sm, text="nebeneinander", value="row", variable=self.v_srvmode,
                            command=lambda: self._set("srv_mode", self.v_srvmode.get())).pack(side="left")
            ttk.Radiobutton(sm, text="als Liste beim Darüberfahren (ein Knopf „Server ▾“)", value="pop", variable=self.v_srvmode,
                            command=lambda: self._set("srv_mode", self.v_srvmode.get())).pack(side="left", padx=16)
            ttk.Label(sm, text="unabhängig von der Schnellsuche", style="Dim.TLabel").pack(side="left", padx=8)

        def _set_d(self, key, val):
            if self._loading:
                return
            self.app.cfg.d[key] = val
            self.changed()

        def _get_groups(self):
            return [[str(g[0]), str(g[1])] for g in self.app.cfg.d.get("server_groups") or [] if len(g) >= 2]

        def _set_groups(self, rows):
            self.app.cfg.d["server_groups"] = [[str(r[0]).strip(), str(r[1]).strip()] for r in rows if str(r[0]).strip()]
            self.app.save_soon()
            self._groups_status()
            self.app.groups_changed()
            self._live_soon()

        def _groups_default(self):
            self._set_groups([list(x) for x in DEFAULT_SERVER_GROUPS])
            self.t_groups.load()

        def _groups_status(self):
            known = self.app.known_servers()
            parts = []
            for name, pat in self._get_groups():
                n = sum(1 for sid, disp in known if server_pattern_match(pat, sid, disp))
                parts.append("%s: %d" % (name, n))
            self.grp_lbl.configure(text=tkstr(("Geladene Server je Gruppe – " + ", ".join(parts)) if known and parts else ""))
            self._nextf(save=False)

        def _nextf(self, save=True):
            txt = self.v_nextf.get().strip().lstrip("Ff")
            if save and not self._loading:
                if txt and not txt.isdigit():
                    return
                self.app.cfg.d["komp_next_f"] = txt
                self.changed()
            n, auto = self.app.next_fusion_no()
            fz = self.app.fusion_forecast()
            plan = ", ".join("%s = %s" % (x["n"], x["l"]) for x in fz[:4]) + (" …" if len(fz) > 4 else "")
            self.nextf_lbl.configure(text=tkstr(("leer = automatisch (höchste F-Welt im Scan + 1 → F%d)" % n if auto and n else
                                                 "leer = automatisch (höchste F-Welt im Scan + 1)" if auto else "eigene Nummer") +
                                                ((" · " + plan) if plan else "")))

        # ---------------------------------------------------------------- Zuwachs & Top-Performer
        def _b_gain(self, f):
            g = ttk.Frame(f)
            g.pack(fill="x")
            ttk.Label(g, text="Zuwachs „pro X Tage“: X =").grid(row=0, column=0, sticky="w")
            self.v_gx = tk.StringVar()
            ttk.Spinbox(g, from_=2, to=365, width=6, textvariable=self.v_gx).grid(row=0, column=1, padx=6, sticky="w")
            ttk.Label(g, text="Tage (Vorgabe – jeder Besucher kann es auf der Seite ändern; gilt auch in Ehrenhalle und Gilden)",
                      style="Dim.TLabel").grid(row=0, column=2, sticky="w")
            ttk.Label(g, text="Top-Performer ✦ ab dem").grid(row=1, column=0, sticky="w", pady=(8, 0))
            self.v_tp = tk.StringVar()
            ttk.Spinbox(g, from_=1.2, to=10, increment=0.1, width=6, textvariable=self.v_tp).grid(row=1, column=1, padx=6, sticky="w", pady=(8, 0))
            ttk.Label(g, text="-fachen Durchschnitt des Δ Base der aktiven Spieler (auch in Ehrenhalle und Aufsteiger)",
                      style="Dim.TLabel").grid(row=1, column=2, sticky="w", pady=(8, 0))
            self.v_tpchip = tk.BooleanVar(value=True)
            ttk.Checkbutton(g, text="Knopf ✦ in der Schnellsuche (zeigt nur die Top-Performer; Erklärung per Maus)",
                            variable=self.v_tpchip, command=lambda: self._set("tp_chip", bool(self.v_tpchip.get()))).grid(
                row=2, column=0, columnspan=3, sticky="w", pady=(8, 0))
            ttk.Label(g, text="Top-Marken gold bis Platz").grid(row=3, column=0, sticky="w", pady=(8, 0))
            self.v_tm = tk.StringVar()
            ttk.Spinbox(g, from_=1, to=100000, increment=10, width=8, textvariable=self.v_tm).grid(row=3, column=1, padx=6, sticky="w", pady=(8, 0))
            ttk.Label(g, text="(Vorgabe; dahinter grau – Besucher wählen selbst Top 10 / 50 / 100 / eigene)", style="Dim.TLabel").grid(
                row=3, column=2, sticky="w", pady=(8, 0))
            ttk.Label(g, text="Vergleich Alt → Neu:").grid(row=4, column=0, sticky="w", pady=(8, 0))
            ttk.Label(g, text="beim Öffnen einer Seite mit mehreren Scans immer an", style="Dim.TLabel").grid(row=4, column=1, columnspan=2,
                                                                                                          sticky="w", padx=6, pady=(8, 0))
            self.v_gx.trace_add("write", lambda *a: self._gx())
            self.v_tp.trace_add("write", lambda *a: self._tpf())
            self.v_tm.trace_add("write", lambda *a: self._num("web_tm", self.v_tm, 1, self.app.cfg.d))

        def _gx(self):
            if self._loading:
                return
            try:
                x = float(str(self.v_gx.get()).replace(",", "."))
            except ValueError:
                return
            if 1 <= x <= 365:
                self.app.cfg.d["gain_x_days"] = int(x) if float(x).is_integer() else x
                set_gain_x(x)
                self.app.gain_x_changed()
                self.app.tab_settings.dirty = True
                self.changed()

        def _tpf(self):
            if self._loading:
                return
            try:
                v = float(str(self.v_tp.get()).replace(",", "."))
            except ValueError:
                return
            if v >= 1.0:
                self.app.cfg.d["stone_factor"] = v
                self.app.tab_table.dirty = self.app.tab_settings.dirty = True
                self.changed()

