        # ---------------------------------------------------------------- Live-Vorschau
        def _live_toggle(self):
            if self.live.running():
                self.live.stop()
                self.live_btn.configure(text="Live-Vorschau im Browser")
                self.live_lbl.configure(text="")
                return
            try:
                url = self.live.start()
            except Exception as ex:
                messagebox.showerror(APP_NAME, "Die Live-Vorschau konnte nicht starten: %s" % ex)
                return
            self._live_build()
            self.live_btn.configure(text="Live-Vorschau beenden")
            self.live_lbl.configure(text=tkstr("läuft: %s" % url))
            self.after(1500, self._live_err_poll)
            try:
                import webbrowser
                webbrowser.open(url)
            except Exception:
                pass

        def _live_err_copy(self):
            e = self._live_err_shown
            if not e:
                return
            self.clipboard_clear()
            self.clipboard_append("Fehler der Seite (Live-Vorschau, %s, %s): %s" % (self.live.err_t, APP_NAME, e))
            self.app.set_status("Fehler-Details in der Zwischenablage.")

        def _live_err_poll(self):
            """Fehler der Seite (von der Live-Vorschau gemeldet) rot unter der Kopfzeile zeigen."""
            try:
                if not self.winfo_exists():
                    return
            except tk.TclError:
                return
            e = self.live.err if self.live.running() else ""
            if e != self._live_err_shown:
                self._live_err_shown = e
                if e:
                    self.live_err_l.configure(text=tkstr("⚠ Die Vorschau meldet einen Fehler der Seite (%s): %s – die Seite wird so nicht "
                                                       "richtig angezeigt." % (self.live.err_t, e)))
                    self.live_err.pack(side="bottom", fill="x", pady=(6, 0), before=self.live_btn.master.winfo_children()[0])
                else:
                    self.live_err.pack_forget()
            if self.live.running():
                self.after(1000, self._live_err_poll)

        def _live_soon(self):
            if not self.live.running():
                return
            if self._prev_after:
                self.after_cancel(self._prev_after)
            self._prev_after = self.after(700, self._live_build)

        def _live_build(self):
            self._prev_after = None
            if not self.live.running():
                return
            try:
                self.config(cursor="watch")
                self.update_idletasks()
                try:
                    lim = max(0, int(self.c.get("live_rows", 150) or 0))
                except (TypeError, ValueError):
                    lim = 150
                t = self._ready()
                spec = WebPage(self.app, t).build("top", limit=lim or None)
                html = html_page(spec, level=1)                  # Vorschau: schnell packen
                tb_ = self.table()
                hs_ = ("#og" if tb_.is_guild else "#o") if isinstance(tb_, OwnTable) else ""
                html = html.replace("<body>", "<body><script>(function(){var h=%s;if(h?location.hash!==h:/^#(og?$|s=)/.test(location.hash))"
                                    "history.replaceState(null,'',location.pathname+h);})();</script>" % json.dumps(hs_), 1)
                n_all = len(getattr(t, "_all_rows", None) or [])
                if lim and n_all > lim:
                    i_ = html.rfind("</body>")
                    html = html[:i_] + ('<div style="position:fixed;right:10px;bottom:10px;z-index:99;background:#b7791f;'
                                        'color:#fff;font:600 12px/1.3 system-ui,sans-serif;padding:5px 9px;border-radius:7px;'
                                        'opacity:.95;pointer-events:none">Vorschau: nur die ersten %s von %s Zeilen · die gespeicherte '
                                        'Datei enthält alle (Einstellung „Vorschau-Zeilen“)</div>' % (_group(lim), _group(n_all))) + html[i_:]
            except Exception as ex:
                import html as _h
                html = ("<!doctype html><meta charset='utf-8'><body style='font:16px system-ui;padding:30px;background:#1b1e26;"
                        "color:#e9ebf1'><h2>Live-Vorschau</h2><p>%s</p></body>" % _h.escape(str(ex)))
            self.config(cursor="")
            self.live.update(html)
            self.live_lbl.configure(text=tkstr("läuft: http://127.0.0.1:%d/ · aktualisiert %s" % (
                self.live.port, datetime.datetime.now().strftime("%H:%M:%S"))))


