            ttk.Label(dsp, text="Gilt für das ganze Programm (Texte, Tabellen, Menüs) und wird sofort übernommen.",
                      style="Dim.TLabel").grid(row=1, column=0, columnspan=4, sticky="w", pady=(4, 0))
            self.v_pngask = tk.BooleanVar(value=app.cfg.d.get("png_ask", True) is not False)
            ttk.Checkbutton(dsp, text="Nach „Als Bild speichern“ fragen: Bild öffnen / in die Zwischenablage kopieren",
                            variable=self.v_pngask, command=self._pngask_changed).grid(row=2, column=0, columnspan=4, sticky="w", pady=(8, 0))

