            self.nb.add(self.tab_guild, text="  Gilde  ")
            self.nb.add(self.tab_servers, text="  Server  ")
            self.nb.add(self.tab_files, text="  Dateien  ")
            self.nb.add(self.tab_table, text="  Ehrenhalle  ")
            self.tab_settings = SettingsTab(self.nb, self)
            self.nb.add(self.tab_cmp, text="  Vergleich  ")
            self.nb.add(self.tab_merge, text="  Zusammenlegung  ")
            self.nb.add(self.tab_komp, text="  Kompensation  ")
